"use strict";
// Curated learning notes; examples are original practice, not quotations from exam papers.
const GSAT_EXAM_NOTEBOOK = {"version":"2.0","source":"self-authored","sourceLabel":"本站依學測閱讀、翻譯及寫作情境自行編寫；不是歷屆試題原句，也未以出題頻率排序。","entries":{"abandon":{"senses":[{"pos":"vt.","meaning":"放棄；遺棄","usage":"及物動詞，後接計畫、希望或被留下的人。"}],"collocations":[{"en":"abandon a plan","zh":"放棄計畫","note":""},{"en":"abandon hope","zh":"放棄希望","note":""},{"en":"abandon a pet","zh":"遺棄寵物","note":""},{"en":"abandon oneself to grief","zh":"沉浸於悲傷","note":"反身用法，語氣偏文學。"}],"synonyms":[{"en":"give up","zh":"放棄","note":"日常用語，亦可接動名詞。"},{"en":"desert","zh":"拋棄","note":"常強調背棄責任或離開人。"}],"idioms":[{"en":"throw in the towel","zh":"認輸；放棄","note":"較口語，常用於屢試失敗後。"}],"family":[{"word":"abandonment","pos":"n.","meaning":"放棄；遺棄"},{"word":"abandoned","pos":"adj.","meaning":"被遺棄的；廢棄的"}],"examples":[{"text":"Rather than abandon the project, the students revised their plan and asked local residents for advice.","translationZh":"學生們沒有放棄專題，而是修改計畫，向當地居民請教。","grammar":"rather than 後接原形動詞，與主句動作形成選擇。","writingTip":"適合寫遇到挫折後調整策略的經驗。","topic":"學習與解決問題","source":"self-authored"},{"text":"Families should never abandon their pets simply because caring for them becomes inconvenient.","translationZh":"家庭絕不應只因照顧寵物變得不方便，就遺棄牠們。","grammar":"because 引導原因子句，caring 為動名詞主詞。","writingTip":"可用於討論飼主責任與動物福利。","topic":"寵物與責任","source":"self-authored"}],"usageNote":"不可把 abandon 與 leave 完全互換；abandon 通常含不再照顧或徹底放棄的意思。"},"absorb":{"senses":[{"pos":"v.","meaning":"吸收液體、光或能量","usage":""},{"pos":"v.","meaning":"理解並吸收資訊","usage":""},{"pos":"v.","meaning":"使全神貫注","usage":""}],"collocations":[{"en":"absorb water","zh":"吸水","note":""},{"en":"absorb new information","zh":"吸收新資訊","note":""},{"en":"be absorbed in a book","zh":"專注於一本書","note":""},{"en":"absorb the cost","zh":"承擔成本","note":""}],"synonyms":[{"en":"soak up","zh":"吸收","note":"可指液體或比喻吸收知識"},{"en":"take in","zh":"理解","note":"take in information 強調接收理解"}],"idioms":[],"family":[{"word":"absorption","pos":"n.","meaning":"吸收；專注"},{"word":"absorbent","pos":"adj.","meaning":"能吸收的"},{"word":"absorbing","pos":"adj.","meaning":"引人入勝的"}],"usageNote":"be absorbed in + 名詞／V-ing；absorbing 描述事物有趣，absorbed 描述人的投入狀態。","examples":[{"text":"During the workshop, students absorbed new information more easily when they could connect each concept with an experience from daily life.","translationZh":"工作坊中，學生能把每個概念連結到日常經驗時，就更容易吸收新資訊。","source":"self-authored","grammar":"when 引導較易吸收資訊的條件；connect A with B。","writingTip":"把新概念連結個人經驗，說明有效學習方法。","topic":"知識吸收"},{"text":"I was so absorbed in the novel that I almost missed my stop on the way home from school.","translationZh":"放學回家途中，我太專注於小說，差點坐過站。","source":"self-authored","grammar":"so absorbed in + 名詞 + that 子句表示專注造成的結果。","writingTip":"可描寫太投入閱讀而差點錯過站的經驗。","topic":"閱讀投入"}]},"abstract":{"senses":[{"pos":"adj.","meaning":"抽象的","usage":""},{"pos":"n.","meaning":"文章或研究的摘要","usage":""},{"pos":"v.","meaning":"提取；摘錄","usage":""}],"collocations":[{"en":"an abstract idea","zh":"抽象概念","note":""},{"en":"abstract thinking","zh":"抽象思考","note":""},{"en":"the abstract of a paper","zh":"論文摘要","note":""},{"en":"abstract information from a report","zh":"從報告提取資料","note":""}],"synonyms":[{"en":"conceptual","zh":"概念性的","note":"conceptual 不一定難以理解"},{"en":"summary","zh":"摘要","note":"summary 適用各類內容，abstract 常見於研究論文"}],"idioms":[],"family":[{"word":"abstraction","pos":"n.","meaning":"抽象概念；抽象化"},{"word":"abstractly","pos":"adv.","meaning":"抽象地"}],"usageNote":"形容詞與名詞 abstract 重音常在首音節；動詞常在第二音節；不是所有摘要都必須稱 abstract。","examples":[{"text":"The teacher used coins and shopping examples to explain an abstract mathematical idea that many students had found difficult.","translationZh":"老師用硬幣和購物例子，解釋許多學生原本覺得困難的抽象數學概念。","source":"self-authored","grammar":"to explain 表目的；that many students had found 修飾 idea。","writingTip":"以具體例子如何改善抽象理解作為論點。","topic":"數學理解"},{"text":"Before reading the entire study, I checked its abstract to see whether the research question was relevant to my project.","translationZh":"閱讀整份研究前，我先看摘要，確認研究問題是否與我的專題相關。","source":"self-authored","grammar":"before reading 表時間；whether 引導摘要查核的問題。","writingTip":"描述先讀摘要來判斷研究與專題是否相關。","topic":"專題資料選擇"}]},"abundant":{"senses":[{"pos":"adj.","meaning":"大量的；豐富的","usage":""}],"collocations":[{"en":"abundant natural resources","zh":"豐富的天然資源","note":""},{"en":"an abundant supply of water","zh":"充足的供水","note":""},{"en":"abundant evidence","zh":"大量的證據","note":""},{"en":"abundant wildlife","zh":"豐富的野生動物","note":""}],"synonyms":[{"en":"plentiful","zh":"充足的","note":"常用於可取得的物資"},{"en":"ample","zh":"充分的","note":"ample time/space 強調足夠有餘"}],"idioms":[],"family":[{"word":"abundance","pos":"n.","meaning":"豐富；大量"},{"word":"abundantly","pos":"adv.","meaning":"大量地；充分地"}],"usageNote":"abundant + 名詞；in abundance 是「大量地」，不要寫 an abundant of。","examples":[{"text":"Although the island receives abundant rainfall, poor storage facilities can still leave communities short of water during the dry season.","translationZh":"雖然島上雨量豐沛，不良的儲水設施仍可能使社區在旱季缺水。","source":"self-authored","grammar":"although 引導資源豐富與仍缺水的對比。","writingTip":"可分析天然條件良好卻仍需基礎建設的原因。","topic":"水資源"},{"text":"The forest supports abundant wildlife, but visitors must stay on marked trails to avoid disturbing animals and damaging young plants.","translationZh":"森林孕育豐富的野生動物，但遊客必須留在標示步道上，避免干擾動物和傷害幼苗。","source":"self-authored","grammar":"to avoid + V-ing；disturbing/damaging 為平行動名詞。","writingTip":"說明保護豐富生態所需的遊客行為。","topic":"森林保育"}]},"accept":{"senses":[{"pos":"vt.","meaning":"接受；答應","usage":"可接邀請、建議、責任或事實。"}],"collocations":[{"en":"accept an invitation","zh":"接受邀請","note":""},{"en":"accept responsibility for","zh":"承擔……的責任","note":""},{"en":"accept the fact that","zh":"接受……這項事實","note":""},{"en":"accept someone as they are","zh":"接納某人原本的樣子","note":""}],"synonyms":[{"en":"receive","zh":"收到","note":"只表示取得，未必同意或接納。"},{"en":"embrace","zh":"欣然接受","note":"比 accept 更強調積極支持。"}],"idioms":[],"family":[{"word":"acceptance","pos":"n.","meaning":"接受；接納"},{"word":"acceptable","pos":"adj.","meaning":"可接受的"},{"word":"unacceptable","pos":"adj.","meaning":"無法接受的"}],"examples":[{"text":"Learning to accept criticism helped me improve my writing without losing confidence in myself.","translationZh":"學會接受批評，讓我能改進寫作，也不失去對自己的信心。","grammar":"Learning to accept criticism 為動名詞片語主詞。","writingTip":"可連結同儕回饋與個人成長。","topic":"學習與成長","source":"self-authored"},{"text":"Although the offer was attractive, she refused to accept a job that required dishonest behavior.","translationZh":"雖然條件很吸引人，她仍拒絕接受一份要求不誠實行為的工作。","grammar":"refuse to accept 接不定詞，that 引導限定關係子句。","writingTip":"適合討論工作選擇與誠信。","topic":"職涯與倫理","source":"self-authored"}],"usageNote":"accept 是動詞；except 通常表示「除了」，兩者拼字相近但功能不同。"},"access":{"senses":[{"pos":"n.","meaning":"取得或使用的機會；進入權","usage":"常接 to；不可數"},{"pos":"vt.","meaning":"存取；使用","usage":"直接接受詞，不加 to"}],"collocations":[{"en":"have access to clean water","zh":"有乾淨飲水可用","note":"access 為名詞"},{"en":"gain access to information","zh":"取得資訊","note":"常見閱讀搭配"},{"en":"access online resources","zh":"使用線上資源","note":"access 為動詞"},{"en":"limited access to healthcare","zh":"有限的醫療取得機會","note":"談社會差距"}],"synonyms":[{"en":"entry","zh":"進入","note":"著重進入場所"},{"en":"availability","zh":"可取得性","note":"談資源是否可用，不能直接取代動詞 access"}],"idioms":[],"family":[{"word":"accessible","pos":"adj.","meaning":"可取得的；可進入的"},{"word":"accessibility","pos":"n.","meaning":"可及性"}],"examples":[{"text":"Students in remote villages need access to reliable internet to complete their school assignments.","translationZh":"偏鄉學生需要可靠的網路，才能完成學校作業。","source":"self-authored","grammar":"need 後接不可數名詞 access；access to reliable internet 的 to 是介系詞；to complete 表目的。","writingTip":"談數位落差時，指出資源不足影響的是完成作業等具體需求。","topic":"education"},{"text":"Visitors can access the museum's digital collection without paying an entrance fee.","translationZh":"參觀者不用支付入場費，就能使用博物館的數位館藏。","source":"self-authored","grammar":"can 後接原形動詞 access，直接接受詞 collection；without paying 是 without + V-ing。","writingTip":"介紹免費文化資源時，可交代使用內容與省下的費用。","topic":"culture"}],"usageNote":"名詞 access 通常不可數；區分 access to information 與 access information。"},"accessible":{"senses":[{"pos":"adj.","meaning":"容易取得或使用的","usage":"常接 to + 使用者"},{"pos":"adj.","meaning":"可進入的；無障礙的","usage":"形容場所設計"},{"pos":"adj.","meaning":"容易理解的","usage":"形容文字或說明"}],"collocations":[{"en":"accessible to everyone","zh":"人人都能使用","note":"to 指使用者"},{"en":"wheelchair-accessible facilities","zh":"輪椅可使用的設施","note":"談無障礙設計"},{"en":"accessible information","zh":"容易理解的資訊","note":"談表達方式"},{"en":"make education accessible","zh":"讓教育容易取得","note":"make + 受詞 + 形容詞"}],"synonyms":[{"en":"available","zh":"可取得的","note":"著重供應情況"},{"en":"easy to understand","zh":"容易理解","note":"對應文章或說明的意思"}],"idioms":[],"family":[{"word":"access","pos":"n./vt.","meaning":"取得機會；存取"},{"word":"accessibility","pos":"n.","meaning":"可及性"},{"word":"inaccessible","pos":"adj.","meaning":"難以取得或進入的"}],"examples":[{"text":"The library made its entrance accessible to wheelchair users by adding a gentle ramp.","translationZh":"圖書館增設緩坡，讓輪椅使用者能順利進入。","source":"self-authored","grammar":"made its entrance accessible 是 make + 受詞 + 形容詞；to wheelchair users 指可使用者；by adding 表方法。","writingTip":"先寫增設緩坡這項措施，再說明輪椅使用者如何受益。","topic":"inclusion"},{"text":"A clear diagram can make complex scientific ideas accessible to younger readers.","translationZh":"清楚的圖解能讓年幼讀者理解複雜的科學概念。","source":"self-authored","grammar":"make complex scientific ideas accessible 是 make + 受詞 + 形容詞；to younger readers 指能理解內容的人。","writingTip":"談科普溝通時，提出圖解這項工具，並指出它幫助哪一群讀者。","topic":"science"}],"usageNote":"accessible 可指身體上的可進入、資源的可取得，也可指內容容易理解。"},"accompany":{"senses":[{"pos":"vt.","meaning":"陪同；伴隨","usage":"直接接人或事物，不加 with 表示陪同。"}],"collocations":[{"en":"accompany someone to school","zh":"陪某人去學校","note":""},{"en":"be accompanied by","zh":"由……陪同；伴隨著","note":""},{"en":"accompany a meal","zh":"搭配餐點","note":""},{"en":"accompany someone on the piano","zh":"以鋼琴為某人伴奏","note":""}],"synonyms":[{"en":"escort","zh":"護送；陪同","note":"常帶正式護送或保護意味。"},{"en":"go with","zh":"與……同行","note":"較口語，未必表示照顧。"}],"idioms":[],"family":[{"word":"accompaniment","pos":"n.","meaning":"伴奏；伴隨物"},{"word":"accompanist","pos":"n.","meaning":"伴奏者"}],"examples":[{"text":"My grandfather asked me to accompany him to the clinic because he found the online registration system confusing.","translationZh":"祖父請我陪他去診所，因為他覺得線上掛號系統很難懂。","grammar":"ask someone to V，find 受詞 adjective 描述感受。","writingTip":"可寫數位落差與世代互助。","topic":"高齡與科技","source":"self-authored"},{"text":"A rise in tourism is often accompanied by increased pressure on local transportation and housing.","translationZh":"觀光人數增加，往往伴隨著當地交通與住房壓力上升。","grammar":"be accompanied by 為被動搭配，by 後接伴隨現象。","writingTip":"適合分析發展帶來的連帶影響。","topic":"觀光與社區","source":"self-authored"}],"usageNote":"accompany 已包含「與……一起」，寫 accompany my friend，不寫 accompany with my friend。"},"accomplish":{"senses":[{"pos":"vt.","meaning":"完成；達成","usage":"常用於需要努力的任務或目標。"}],"collocations":[{"en":"accomplish a task","zh":"完成任務","note":""},{"en":"accomplish a goal","zh":"達成目標","note":""},{"en":"accomplish a great deal","zh":"完成許多事","note":""},{"en":"feel a sense of accomplishment","zh":"感到成就感","note":"名詞搭配，適合寫努力成果。"}],"synonyms":[{"en":"achieve","zh":"達成","note":"常接目標或成果，強調成功取得。"},{"en":"complete","zh":"完成","note":"較中性，強調進度結束。"}],"idioms":[],"family":[{"word":"accomplishment","pos":"n.","meaning":"成就；完成"},{"word":"accomplished","pos":"adj.","meaning":"技藝高超的"}],"examples":[{"text":"By dividing the work into smaller tasks, our team accomplished more than we had originally expected.","translationZh":"透過把工作分成較小的任務，我們團隊完成了比原先預期更多的事。","grammar":"By 後接動名詞，had expected 表示較早的預期。","writingTip":"可用於說明分工與時間管理。","topic":"團隊合作","source":"self-authored"},{"text":"She felt proud of what she had accomplished, even though the final result was far from perfect.","translationZh":"即使最後成果仍不完美，她依然為自己完成的事感到驕傲。","grammar":"what 引導名詞子句，even though 表讓步。","writingTip":"適合寫重視成長而非追求完美。","topic":"個人成長","source":"self-authored"}],"usageNote":"accomplished 作形容詞時指熟練或有造詣，不只表示某事完成了。"},"account":{"senses":[{"pos":"n.","meaning":"敘述；報告","usage":"a detailed account of an event。"},{"pos":"n.","meaning":"帳戶；帳目","usage":"a bank account；複數 accounts 可指帳目。"},{"pos":"vi.","meaning":"解釋；說明原因","usage":"account for the difference；for 不可省略。"},{"pos":"vi.","meaning":"占某比例","usage":"account for twenty percent of the total；不是解釋百分比的成因。"}],"collocations":[{"en":"give an account of an event","zh":"敘述事件","note":""},{"en":"open a bank account","zh":"開銀行帳戶","note":""},{"en":"account for the difference","zh":"解釋差異","note":""},{"en":"take costs into account","zh":"把成本納入考量","note":""}],"synonyms":[{"en":"report","zh":"報告","note":"account 強調事件敘述，不一定正式"},{"en":"explain","zh":"解釋","note":"只對應 account for 的「解釋原因」義；表占比時可用 make up，不能換成 explain。"}],"idioms":[{"en":"take into account","zh":"納入考量","note":"受詞可放在 take 和 into account 之間"}],"family":[{"word":"accountant","pos":"n.","meaning":"會計師"},{"word":"accountable","pos":"adj.","meaning":"應負責說明的"},{"word":"accountability","pos":"n.","meaning":"問責；責任"}],"usageNote":"account for 有「解釋」與「占」兩義；on account of 表示因為。","examples":[{"text":"When choosing a college, students should take living costs into account instead of focusing only on tuition and course rankings.","translationZh":"選大學時，學生應把生活費納入考量，而不只注意學費和課程排名。","source":"self-authored","grammar":"take + 生活費 + into account；instead of + V-ing。","writingTip":"評估大學時可加入排名以外的生活費考量。","topic":"升學選擇"},{"text":"The witness gave a detailed account of the accident, helping the police understand why the driver had suddenly changed direction.","translationZh":"目擊者詳細敘述事故，幫助警方了解駕駛為何突然轉向。","source":"self-authored","grammar":"gave an account of + 事故；helping 補充敘述的作用。","writingTip":"交代目擊者資訊如何幫助理解事件經過。","topic":"事故敘述"}]},"accurate":{"senses":[{"pos":"adj.","meaning":"正確的；精確的","usage":"形容資料、描述或測量結果與實際情況相符。"}],"collocations":[{"en":"accurate information","zh":"正確的資訊","note":""},{"en":"an accurate description of the event","zh":"對事件的準確描述","note":"of 接描述對象。"},{"en":"accurate measurements","zh":"精確的測量結果","note":""},{"en":"an accurate prediction","zh":"準確的預測","note":"預測是否準確須事後比對。"}],"synonyms":[{"en":"correct","zh":"正確的","note":"適用答案或資訊，不一定強調細節精確。"},{"en":"precise","zh":"精確的","note":"強調明確或細緻；測量很精細仍可能不準確。"}],"idioms":[],"family":[{"word":"accuracy","pos":"n.","meaning":"準確性"},{"word":"accurately","pos":"adv.","meaning":"準確地"},{"word":"inaccurate","pos":"adj.","meaning":"不正確的；不準確的"}],"usageNote":"accurate 指符合事實；precise 指精密或明確。報告數字時也應交代資料來源與測量方式。","examples":[{"text":"Before sharing the chart, we checked whether its figures gave an accurate picture of local recycling habits.","translationZh":"分享圖表前，我們檢查其中數字是否準確呈現當地的回收習慣。","grammar":"whether 引導檢查的內容；an accurate picture of 表準確呈現。","writingTip":"圖表作文可用 give an accurate picture of 說明資料是否反映現況。","topic":"圖表與查證","source":"self-authored"},{"text":"An accurate description of the missing bag helped station staff return it to its owner that afternoon.","translationZh":"對遺失提袋的準確描述，幫助車站人員在當天下午將它歸還失主。","grammar":"description of + 事物；help + 人 + 原形動詞 return。","writingTip":"用物品細節如何促成解決問題，取代籠統描述。","topic":"遺失物協尋","source":"self-authored"}]},"achieve":{"senses":[{"pos":"vt.","meaning":"達成；實現","usage":"常接目標、成果或某種水準。"}],"collocations":[{"en":"achieve a goal","zh":"達成目標","note":""},{"en":"achieve a balance between work and rest","zh":"在工作與休息間取得平衡","note":"between A and B。"},{"en":"achieve success","zh":"獲得成功","note":"success 在此不可數。"},{"en":"achieve better results","zh":"取得更好的成果","note":""}],"synonyms":[{"en":"accomplish","zh":"完成；達成","note":"常接任務或目標，強調完成。"},{"en":"attain","zh":"達到","note":"較正式，常接水準或目標。"}],"idioms":[],"family":[{"word":"achievement","pos":"n.","meaning":"成就；達成"},{"word":"achievable","pos":"adj.","meaning":"可以達成的"},{"word":"achiever","pos":"n.","meaning":"有成就的人"}],"usageNote":"achieve 後直接接目標；不寫 achieve to do。achievement 可數時指一項成就，不可數時指達成的過程。","examples":[{"text":"By setting smaller weekly goals, I achieved better results without feeling overwhelmed by the work ahead.","translationZh":"透過訂定較小的每週目標，我取得更好的成果，也未因眼前工作而感到不知所措。","grammar":"By + V-ing 表方法；without feeling 是介系詞接動名詞。","writingTip":"描寫大目標如何拆成每週可做的小行動。","topic":"目標管理","source":"self-authored"},{"text":"The team hopes to achieve a balance between attracting visitors and protecting the village from excessive development.","translationZh":"團隊希望在吸引遊客與保護村莊免於過度開發之間取得平衡。","grammar":"hope to V；between 後並列 attracting 與 protecting。","writingTip":"討論發展的取捨時，具體列出需要兼顧的兩端。","topic":"觀光與保育","source":"self-authored"}]},"acknowledge":{"senses":[{"pos":"vt.","meaning":"承認；確認收到；表達感謝","usage":"可接名詞、that 子句或動名詞。"}],"collocations":[{"en":"acknowledge a mistake","zh":"承認錯誤","note":""},{"en":"acknowledge receipt of","zh":"確認收到……","note":""},{"en":"acknowledge someone's contribution","zh":"肯定某人的貢獻","note":""},{"en":"acknowledge that","zh":"承認……","note":""}],"synonyms":[{"en":"admit","zh":"承認","note":"常承認令人不快或不利的事。"},{"en":"recognize","zh":"認可；意識到","note":"不一定公開表達承認。"}],"idioms":[],"family":[{"word":"acknowledgment","pos":"n.","meaning":"承認；致謝"},{"word":"acknowledged","pos":"adj.","meaning":"公認的"}],"examples":[{"text":"A responsible leader should acknowledge mistakes openly and explain how the team will prevent them from happening again.","translationZh":"負責任的領導者應公開承認錯誤，並說明團隊如何避免再次犯錯。","grammar":"prevent someone or something from V-ing，how 引導名詞子句。","writingTip":"適合討論領導力與承擔責任。","topic":"領導與責任","source":"self-authored"},{"text":"In her speech, she acknowledged the volunteers whose quiet efforts had made the community festival possible.","translationZh":"她在演說中感謝那些默默付出、讓社區節慶得以舉行的志工。","grammar":"whose 引導所有格關係子句，make 受詞 adjective。","writingTip":"可描述活動成功背後的協作。","topic":"社區與服務","source":"self-authored"}],"usageNote":"acknowledge receiving a message 只表示確認收到，不等於同意內容。"},"acquire":{"senses":[{"pos":"vt.","meaning":"取得；習得","usage":"常指經過時間、努力或購買而得到。"}],"collocations":[{"en":"acquire a skill","zh":"習得技能","note":""},{"en":"acquire knowledge","zh":"獲得知識","note":""},{"en":"acquire a taste for","zh":"逐漸喜歡上……","note":""},{"en":"acquire property","zh":"取得房產或財產","note":""}],"synonyms":[{"en":"gain","zh":"獲得","note":"常接經驗、支持或優勢，範圍較廣。"},{"en":"obtain","zh":"取得","note":"較正式，常指取得所需物品或資訊。"}],"idioms":[],"family":[{"word":"acquisition","pos":"n.","meaning":"取得；習得"},{"word":"acquired","pos":"adj.","meaning":"後天獲得的"}],"examples":[{"text":"Students acquire practical skills more effectively when they have opportunities to solve problems outside the classroom.","translationZh":"學生若有機會解決課堂外的問題，往往更能有效習得實用技能。","grammar":"when 引導情境子句，opportunities to V 表機會內容。","writingTip":"適合討論體驗學習的價值。","topic":"教育與實作","source":"self-authored"},{"text":"After living abroad for a year, he acquired a taste for foods he had once avoided.","translationZh":"在國外住了一年後，他逐漸喜歡上自己曾經避而不吃的食物。","grammar":"acquire a taste for 表逐漸養成喜好，had avoided 指更早經驗。","writingTip":"可寫文化交流如何改變偏好。","topic":"文化與飲食","source":"self-authored"}],"usageNote":"acquire knowledge 中 knowledge 通常不可數；不寫 acquire many knowledges。"},"adapt":{"senses":[{"pos":"vt.","meaning":"調整以適應","usage":"adapt oneself 或制度"},{"pos":"vi.","meaning":"適應","usage":"adapt to + 新環境"},{"pos":"vt.","meaning":"改編","usage":"adapt A from B"}],"collocations":[{"en":"adapt to climate change","zh":"適應氣候變遷","note":"to 為介系詞"},{"en":"adapt to a new environment","zh":"適應新環境","note":"談生活轉變"},{"en":"adapt a novel for the screen","zh":"將小說改編成電影","note":"for 指新用途"},{"en":"adapt teaching methods","zh":"調整教學方法","note":"動詞直接接受詞"}],"synonyms":[{"en":"adjust","zh":"調整；適應","note":"較常指小幅修正"},{"en":"modify","zh":"修改","note":"著重改動事物以符合需求"}],"idioms":[],"family":[{"word":"adaptation","pos":"n.","meaning":"適應；改編作品"},{"word":"adaptable","pos":"adj.","meaning":"能適應的"},{"word":"adaptive","pos":"adj.","meaning":"具有適應作用的"}],"examples":[{"text":"Farmers must adapt to changing rainfall patterns if they want to protect their crops.","translationZh":"農民若想保護作物，就必須適應改變中的降雨模式。","source":"self-authored","grammar":"adapt to + 名詞；if 引導條件子句","writingTip":"適合連結氣候影響與因應措施。","topic":"environment"},{"text":"The director adapted a local legend into a film that attracted viewers of all ages.","translationZh":"導演將一則地方傳說改編成電影，吸引了各年齡層的觀眾。","source":"self-authored","grammar":"adapt A into B；that 修飾 film","writingTip":"可用於文化傳承或媒體主題。","topic":"culture"}],"usageNote":"適應環境用 adapt to；改編作品可用 adapt A into B 或 adapt A for B。"},"address":{"senses":[{"pos":"n.","meaning":"地址；住址；電子郵件地址","usage":"a home / mailing / email address；可數名詞，不同種類的地址由前面的修飾語決定。"},{"pos":"n.","meaning":"演說；正式致詞","usage":"give / deliver an address；an opening address = 開幕致詞，語氣較正式。"},{"pos":"vt.","meaning":"向……說話；向……致詞","usage":"address the audience / a meeting；直接接聽眾或會議，不說 address to the audience。"},{"pos":"vt.","meaning":"處理；著手解決","usage":"address a problem / a concern / an issue；表示面對並採取處理行動，不保證問題已完全解決。"},{"pos":"vt.","meaning":"在……上寫收件地址；寄給","usage":"address an envelope to someone；to 在此引出收件人，不是演說的聽眾結構。"},{"pos":"vt.","meaning":"稱呼","usage":"address someone as + 稱謂，如 address the teacher as Ms. Lin；as 指使用的稱呼。"}],"collocations":[{"en":"a mailing address","zh":"郵寄地址","note":""},{"en":"address a problem","zh":"處理問題","note":""},{"en":"address the audience","zh":"向觀眾致詞","note":""},{"en":"an opening address","zh":"開幕致詞","note":""},{"en":"address an envelope to someone","zh":"在信封上寫給某人的收件地址","note":"address + 信封 + to + 收件人；與 address the audience 的直接受詞不同。"},{"en":"address someone as Ms. Lin","zh":"稱呼某人為林女士","note":"as 後接所用稱謂，可用於稱呼禮貌的情境。"}],"synonyms":[{"en":"tackle","zh":"處理","note":"tackle 強調積極著手難題"},{"en":"speech","zh":"演說","note":"address 作名詞通常較正式"}],"idioms":[],"family":[{"word":"addressee","pos":"n.","meaning":"收件人；受話者"},{"word":"addressable","pos":"adj.","meaning":"可處理或可定址的"}],"usageNote":"address a problem 是著手處理問題；address the audience 是向聽眾致詞，兩者直接接受詞。address a letter to someone 中 to 接收件人；address someone as + 稱謂 表稱呼。原字典的舉止、靈巧、求愛等較舊義保留於原釋義，現代學測寫作優先使用地址、致詞與處理問題等語義。","examples":[{"text":"Instead of blaming students for being late, the school addressed the problem by improving bus connections and opening the gate earlier.","translationZh":"學校沒有責怪學生遲到，而是改善公車接駁並提早開門來處理問題。","source":"self-authored","grammar":"by improving/opening 表處理問題的具體方法。","writingTip":"提出制度改善方案，而不只歸咎個人。","topic":"遲到問題"},{"text":"The speaker addressed the audience in simple language, explaining how small changes in daily habits could reduce household waste.","translationZh":"講者用淺白的語言向觀眾說明，日常習慣的小改變如何減少家庭垃圾。","source":"self-authored","grammar":"addressed the audience；how 引導演說說明的內容。","writingTip":"可描述用淺白語言說明日常行動的影響。","topic":"環保宣導"}]},"adjust":{"senses":[{"pos":"vt.","meaning":"調整","usage":"調整設備或計畫"},{"pos":"vi.","meaning":"適應","usage":"adjust to + 情境"}],"collocations":[{"en":"adjust the temperature","zh":"調整溫度","note":"接受詞"},{"en":"adjust to school life","zh":"適應校園生活","note":"to 為介系詞"},{"en":"adjust the schedule","zh":"調整行程","note":"因應變動"},{"en":"make minor adjustments","zh":"做小幅調整","note":"名詞搭配"}],"synonyms":[{"en":"adapt","zh":"適應","note":"通常含較大或較長期的改變"},{"en":"fine-tune","zh":"微調","note":"著重細部調整"}],"idioms":[],"family":[{"word":"adjustment","pos":"n.","meaning":"調整；適應"},{"word":"adjustable","pos":"adj.","meaning":"可調整的"}],"examples":[{"text":"We adjusted the meeting time so that students with long commutes could attend.","translationZh":"我們調整了開會時間，讓通勤路程較長的學生也能出席。","source":"self-authored","grammar":"adjusted 直接接受詞 the meeting time；so that 引導目的子句，說明調整後誰能出席。","writingTip":"討論公平安排時，寫出時程調整如何照顧通勤較久的學生。","topic":"school"},{"text":"It took my brother several weeks to adjust to living away from home.","translationZh":"哥哥花了幾週才適應離家生活。","source":"self-authored","grammar":"It took 人 + 時間 + to V 表花費時間；adjust to living 的 to 是介系詞，後接 V-ing。","writingTip":"寫離家經驗時，可用花費的時間呈現適應過程。","topic":"personal experience"}],"usageNote":"adjust to 的 to 是介系詞，後面接名詞或動名詞。"},"adopt":{"senses":[{"pos":"v.","meaning":"收養；認養","usage":""},{"pos":"v.","meaning":"採用做法或政策","usage":""}],"collocations":[{"en":"adopt a child","zh":"收養孩子","note":""},{"en":"adopt a rescue dog","zh":"認養獲救的狗","note":""},{"en":"adopt a new approach","zh":"採用新方法","note":""},{"en":"adopt a policy","zh":"採用政策","note":""}],"synonyms":[{"en":"take in","zh":"收留","note":"可能只是暫時安置"},{"en":"embrace","zh":"欣然接受","note":"用於思想或做法，不等於正式收養"}],"idioms":[],"family":[{"word":"adoption","pos":"n.","meaning":"收養；採用"},{"word":"adoptive","pos":"adj.","meaning":"收養的"},{"word":"adopted","pos":"adj.","meaning":"被收養的；被採用的"}],"usageNote":"adopt（採用／收養）與 adapt（適應／改編）拼字近但意義不同。","examples":[{"text":"Instead of buying a puppy, my family adopted an older dog whose gentle nature suited our quiet home.","translationZh":"我們家沒有買幼犬，而是認養一隻性情溫和、適合安靜家庭的老狗。","source":"self-authored","grammar":"instead of + V-ing；whose gentle nature 表示狗的性情。","writingTip":"可說明為何選擇認養適合家庭的動物。","topic":"寵物認養"},{"text":"To reduce food waste, the school adopted a policy that allows students to choose smaller portions and ask for more later.","translationZh":"為減少食物浪費，學校採用一項政策，讓學生先選小份量，之後再追加。","source":"self-authored","grammar":"adopted a policy；that allows 引導修飾 policy 的關係子句。","writingTip":"用份量選擇說明政策如何減少浪費。","topic":"午餐政策"}]},"advantage":{"senses":[{"pos":"n.","meaning":"優點；有利條件","usage":"可數"},{"pos":"n.","meaning":"優勢","usage":"advantage over + 對手"}],"collocations":[{"en":"have an advantage over rivals","zh":"比對手有優勢","note":"over 指比較對象"},{"en":"take advantage of opportunities","zh":"善用機會","note":"依受詞判斷語氣"},{"en":"competitive advantage","zh":"競爭優勢","note":"商業及科技主題"},{"en":"the advantages of public transport","zh":"大眾運輸的優點","note":"of 接事物"}],"synonyms":[{"en":"benefit","zh":"好處","note":"著重帶來的正面結果"},{"en":"strength","zh":"優勢；強項","note":"著重人或方案的長處"}],"idioms":[{"en":"get the upper hand","zh":"佔上風","note":"表示取得相對優勢，常指競爭情境。"}],"family":[{"word":"advantageous","pos":"adj.","meaning":"有利的"},{"word":"disadvantage","pos":"n.","meaning":"缺點；不利條件"}],"examples":[{"text":"One advantage of cycling to school is that it reduces both travel costs and carbon emissions.","translationZh":"騎自行車上學的一個優點，是能同時降低交通費與碳排放。","source":"self-authored","grammar":"One advantage of V-ing is that + 子句","writingTip":"適合比較交通選擇。","topic":"transport"},{"text":"Students who ask thoughtful questions often have an advantage over those who only memorize facts.","translationZh":"提出深入問題的學生，往往比只背誦事實的學生更有優勢。","source":"self-authored","grammar":"who ask thoughtful questions 修飾 Students；have an advantage over those 中 over 引出比較對象。","writingTip":"比較學習策略時，明確列出提問與死背兩種做法。","topic":"education"}],"usageNote":"take advantage of 機會表示善用；若受詞是弱勢的人，可能表示占便宜。"},"affect":{"senses":[{"pos":"v.","meaning":"影響","usage":""},{"pos":"v.","meaning":"使產生情緒反應","usage":""}],"collocations":[{"en":"affect one's health","zh":"影響健康","note":""},{"en":"affect daily life","zh":"影響日常生活","note":""},{"en":"be deeply affected by a story","zh":"深受故事感動","note":""},{"en":"adversely affect performance","zh":"對表現造成不利影響","note":""}],"synonyms":[{"en":"influence","zh":"影響","note":"常暗示對想法或行為的影響"},{"en":"impact","zh":"影響","note":"較強調顯著效果"}],"idioms":[],"family":[{"word":"affected","pos":"adj.","meaning":"受影響的；不自然做作的"},{"word":"affection","pos":"n.","meaning":"喜愛；感情"},{"word":"affective","pos":"adj.","meaning":"情感方面的"}],"usageNote":"affect 通常是動詞；effect 通常是名詞，have an effect on = affect。affection 與一般影響義不同。","examples":[{"text":"Lack of sleep can affect our ability to concentrate, making even familiar tasks feel more difficult than they usually do.","translationZh":"睡眠不足會影響專注能力，使熟悉的任務也比平常更難。","source":"self-authored","grammar":"affect + 受詞；making + 受詞 + 原形 feel 補充後果。","writingTip":"由睡眠不足延伸到執行日常任務的後果。","topic":"睡眠與專注"},{"text":"The documentary deeply affected me because it showed how a single act of kindness could change a stranger's difficult day.","translationZh":"那部紀錄片深深打動我，因為它呈現一個善意舉動如何改變陌生人難熬的一天。","source":"self-authored","grammar":"because 解釋被打動的原因；how 引導紀錄片呈現的內容。","writingTip":"用作品中的具體善意行動說明感動的來源。","topic":"紀錄片感受"}]},"afford":{"senses":[{"pos":"v.","meaning":"負擔得起","usage":""},{"pos":"v.","meaning":"有餘裕承受或提供","usage":""}],"collocations":[{"en":"afford to buy a house","zh":"買得起房子","note":""},{"en":"afford the cost","zh":"負擔得起費用","note":""},{"en":"cannot afford to waste time","zh":"沒有餘裕浪費時間","note":""},{"en":"afford an opportunity","zh":"提供機會","note":""}],"synonyms":[{"en":"pay for","zh":"支付","note":"pay for 只表示付款，不代表有餘裕"},{"en":"provide","zh":"提供","note":"afford opportunity 是正式用法"}],"idioms":[],"family":[{"word":"affordable","pos":"adj.","meaning":"價格負擔得起的"},{"word":"affordability","pos":"n.","meaning":"可負擔性"}],"usageNote":"can/cannot afford to + 原形動詞；不限金錢，也可指時間或風險。","examples":[{"text":"Many students cannot afford expensive private lessons, so free community programs can help make learning opportunities more widely available.","translationZh":"許多學生負擔不起昂貴的私人課程，因此免費社區課程有助更多人獲得學習機會。","source":"self-authored","grammar":"cannot afford + 費用；help make + 受詞 + 形容詞。","writingTip":"可分析免費社區課程如何回應費用障礙。","topic":"教育機會"},{"text":"With only two days left before the exhibition, our team could not afford to waste time arguing over minor details.","translationZh":"展覽前只剩兩天，我們小組沒有餘裕把時間浪費在爭論小細節上。","source":"self-authored","grammar":"cannot afford to waste；arguing 為 waste time 的動名詞補語。","writingTip":"時間吃緊時，用細節爭論與實際進度作取捨。","topic":"展覽準備"}]},"alternative":{"senses":[{"pos":"n.","meaning":"替代方案","usage":"alternative to + 名詞"},{"pos":"adj.","meaning":"替代的；非傳統的","usage":"放在名詞前"}],"collocations":[{"en":"an alternative to driving","zh":"開車以外的替代方式","note":"to 後接 V-ing"},{"en":"alternative energy sources","zh":"替代能源","note":"形容詞搭配"},{"en":"offer a practical alternative","zh":"提供可行替代方案","note":"a 表單一方案"},{"en":"consider other alternatives","zh":"考慮其他方案","note":"複數名詞"}],"synonyms":[{"en":"option","zh":"選項","note":"選擇範圍較廣，未必取代既有方案"},{"en":"substitute","zh":"替代物","note":"著重取代某個人或物"}],"idioms":[],"family":[{"word":"alternatively","pos":"adv.","meaning":"或者；作為另一選擇"}],"examples":[{"text":"Taking the bus offers a practical alternative to driving through the crowded city center.","translationZh":"搭公車是在擁擠市中心開車以外的可行選擇。","source":"self-authored","grammar":"Taking the bus 是 V-ing 片語作主詞；an alternative to driving 的 to 為介系詞。","writingTip":"提出替代交通方式時，點出它可取代的既有行為。","topic":"transport"},{"text":"The school proposed an alternative plan after heavy rain made the outdoor event impossible.","translationZh":"豪雨讓戶外活動無法進行後，學校提出了替代計畫。","source":"self-authored","grammar":"alternative 作形容詞修飾 plan；made the outdoor event impossible 是 make + 受詞 + 形容詞。","writingTip":"敘述活動遇雨時，可用替代計畫銜接困難與應變。","topic":"school"}],"usageNote":"名詞通常用 an alternative to；alternative 作形容詞時可直接修飾 plan、method、source。"},"ambition":{"senses":[{"pos":"n.","meaning":"抱負；雄心；志向","usage":"指追求成功的動力或想達成的目標。"}],"collocations":[{"en":"have an ambition to","zh":"懷有……的志向","note":""},{"en":"achieve an ambition","zh":"實現抱負","note":""},{"en":"career ambitions","zh":"職涯抱負","note":""},{"en":"be driven by ambition","zh":"受到雄心驅使","note":""}],"synonyms":[{"en":"aspiration","zh":"志向","note":"常指理想或期望，語氣較正面。"},{"en":"desire","zh":"渴望","note":"範圍更廣，不一定關於成就。"}],"idioms":[],"family":[{"word":"ambitious","pos":"adj.","meaning":"有雄心的；規模宏大的"},{"word":"ambitiously","pos":"adv.","meaning":"雄心勃勃地"}],"examples":[{"text":"Her ambition to become a doctor grew stronger after she volunteered at a rural health center.","translationZh":"她在偏鄉衛生中心當志工後，成為醫師的志向更加堅定。","grammar":"ambition to V 說明志向內容，after 後接完整子句。","writingTip":"適合連結服務經驗與職涯目標。","topic":"職涯與服務","source":"self-authored"},{"text":"Personal ambition can encourage hard work, but it should not come at the expense of others.","translationZh":"個人抱負能促使人努力，但不該以犧牲他人為代價。","grammar":"at the expense of 表以……為代價。","writingTip":"可討論競爭與道德的界線。","topic":"競爭與倫理","source":"self-authored"}],"usageNote":"ambition 可以是不可數的雄心，也可用 an ambition 表示一項具體志向。"},"amount":{"senses":[{"pos":"n.","meaning":"數量；總額","usage":""},{"pos":"v.","meaning":"總計；等同於","usage":""}],"collocations":[{"en":"a large amount of waste","zh":"大量垃圾","note":""},{"en":"the total amount of money","zh":"總金額","note":""},{"en":"amount to three hundred dollars","zh":"總計三百元","note":""},{"en":"amount to a serious problem","zh":"等同於嚴重問題","note":""}],"synonyms":[{"en":"quantity","zh":"數量","note":"quantity 可搭配可數與不可數名詞"},{"en":"total","zh":"總數","note":"強調加總結果"}],"idioms":[],"family":[{"word":"amount","pos":"n./v.","meaning":"總量；總計"}],"usageNote":"amount of + 不可數名詞；number of + 可數名詞複數。amount to 後接名詞。","examples":[{"text":"The amount of food thrown away each day surprised our class and inspired us to start a lunch-sharing project.","translationZh":"每天被丟棄的食物量讓我們班驚訝，也促使我們開始午餐分享計畫。","source":"self-authored","grammar":"thrown away 修飾 food；the amount of + 不可數名詞。","writingTip":"用數量帶來的驚訝銜接班級改善行動。","topic":"食物浪費"},{"text":"Although each purchase seemed inexpensive, the small payments amounted to a considerable expense by the end of the month.","translationZh":"雖然每次購買看似不貴，這些小額付款到月底卻累積成可觀支出。","source":"self-authored","grammar":"amounted to + 總額；although 引導單次便宜與總支出的對比。","writingTip":"分析小額支出累積成負擔的過程。","topic":"小額消費"}]},"analyze":{"senses":[{"pos":"vt.","meaning":"分析","usage":"把資料或問題拆開檢視，以理解其結構或原因。"}],"collocations":[{"en":"analyze the data","zh":"分析資料","note":""},{"en":"analyze the causes of a problem","zh":"分析問題的成因","note":""},{"en":"analyze survey results","zh":"分析調查結果","note":""},{"en":"analyze a text in detail","zh":"詳細分析文本","note":""}],"synonyms":[{"en":"examine","zh":"仔細檢視","note":"範圍較廣，未必拆解結構。"},{"en":"investigate","zh":"調查","note":"重點是查明事實或原因，不一定分析既有資料。"}],"idioms":[],"family":[{"word":"analysis","pos":"n.","meaning":"分析"},{"word":"analytical","pos":"adj.","meaning":"分析的；善於分析的"},{"word":"analyst","pos":"n.","meaning":"分析人員"}],"usageNote":"analyze 為美式拼字，analyse 為英式；analysis 的複數是 analyses，不能寫 analysises。","examples":[{"text":"We analyzed the survey results before deciding which changes would make the school library more welcoming.","translationZh":"決定哪些改變能讓校圖書館更親切之前，我們先分析了調查結果。","grammar":"before deciding 省略相同主詞；which 引導間接問句。","writingTip":"先寫分析資料，再寫依資料作決定的過程。","topic":"校園調查","source":"self-authored"},{"text":"Rather than blame one person, the group analyzed how unclear instructions had contributed to the misunderstanding.","translationZh":"小組沒有責怪一個人，而是分析不清楚的指示如何造成誤解。","grammar":"how 引導分析的內容；had contributed 表較早發生的原因。","writingTip":"人際衝突作文可分析流程問題，避免只歸咎個人。","topic":"合作反思","source":"self-authored"}]},"anticipate":{"senses":[{"pos":"vt.","meaning":"預期；預料","usage":"後接名詞、V-ing 或 that 子句，常含事先準備的意思。"}],"collocations":[{"en":"anticipate difficulties","zh":"預料困難","note":""},{"en":"anticipate a rise in demand","zh":"預期需求上升","note":""},{"en":"anticipate having to wait","zh":"預料會需要等候","note":"anticipate + V-ing。"},{"en":"anticipate the needs of visitors","zh":"預先考慮訪客需求","note":""}],"synonyms":[{"en":"expect","zh":"預期","note":"範圍較廣，expect 可接 to V，anticipate 通常不行。"},{"en":"foresee","zh":"預見","note":"強調事先看出將發生的情況。"}],"idioms":[],"family":[{"word":"anticipation","pos":"n.","meaning":"預期；期待"},{"word":"anticipated","pos":"adj.","meaning":"預期中的"},{"word":"unanticipated","pos":"adj.","meaning":"未預料到的"}],"usageNote":"用 anticipate doing 或 anticipate that，不寫 anticipate to do。可預期好事，也可預料困難。","examples":[{"text":"Because we anticipated heavy traffic, we left early and arrived at the interview with time to spare.","translationZh":"因為預料會塞車，我們提早出發，到達面試地點時還有充裕時間。","grammar":"Because 引導原因；with time to spare 表時間有餘裕。","writingTip":"敘述行前預判如何降低遲到的風險。","topic":"行程準備","source":"self-authored"},{"text":"The organizers anticipated having to answer questions about accessibility, so they prepared a clear map of the venue.","translationZh":"主辦人預料需要回答無障礙設施的問題，因此準備了清楚的場地圖。","grammar":"anticipated having to V 為動名詞受詞；so 連接準備的結果。","writingTip":"用具體準備呈現對不同使用者需求的考量。","topic":"活動規畫","source":"self-authored"}]},"anxiety":{"senses":[{"pos":"n.","meaning":"焦慮；憂慮","usage":"常作不可數名詞，特定憂慮可用複數 anxieties。"}],"collocations":[{"en":"experience anxiety","zh":"感到焦慮","note":""},{"en":"anxiety about the future","zh":"對未來的焦慮","note":""},{"en":"reduce anxiety","zh":"減輕焦慮","note":""},{"en":"anxiety over exam results","zh":"對考試結果的憂慮","note":""}],"synonyms":[{"en":"worry","zh":"擔心","note":"較日常，可作名詞或動詞。"},{"en":"unease","zh":"不安","note":"常較輕微或原因不明，不必等同焦慮症。"}],"idioms":[],"family":[{"word":"anxious","pos":"adj.","meaning":"焦慮的；急切想做的"},{"word":"anxiously","pos":"adv.","meaning":"焦慮地"}],"examples":[{"text":"Talking with a trusted teacher helped reduce my anxiety about choosing a university major.","translationZh":"與信任的老師談話，幫助我減輕了選擇大學科系的焦慮。","grammar":"anxiety about 後接名詞或動名詞，help 後可接原形。","writingTip":"適合寫求助與升學壓力。","topic":"升學與情緒","source":"self-authored"},{"text":"Constant exposure to alarming news may increase anxiety, especially when people feel unable to change the situation.","translationZh":"持續接觸令人不安的新聞，可能增加焦慮，尤其在人們覺得無力改變情況時。","grammar":"exposure to 為名詞搭配，feel unable to V 表無力。","writingTip":"可分析媒體使用對情緒的影響。","topic":"媒體與心理","source":"self-authored"}],"usageNote":"anxious about 多指擔心；anxious to V 有時指急切想做，須看語境。"},"apply":{"senses":[{"pos":"v.","meaning":"申請","usage":""},{"pos":"v.","meaning":"應用；適用","usage":""},{"pos":"v.","meaning":"塗抹","usage":""}],"collocations":[{"en":"apply for a scholarship","zh":"申請獎學金","note":""},{"en":"apply to a university","zh":"申請進入大學","note":""},{"en":"apply knowledge to practice","zh":"把知識應用於實務","note":""},{"en":"apply sunscreen","zh":"塗防曬乳","note":""}],"synonyms":[{"en":"request","zh":"請求","note":"request 不一定是正式申請"},{"en":"use","zh":"使用","note":"apply 強調把方法知識用於特定目的"}],"idioms":[],"family":[{"word":"application","pos":"n.","meaning":"申請；應用"},{"word":"applicant","pos":"n.","meaning":"申請者"},{"word":"applicable","pos":"adj.","meaning":"適用的"}],"usageNote":"apply for + 欲取得的職位或資源；apply to + 機構；apply A to B = 將 A 應用於 B。","examples":[{"text":"Students who apply for the scholarship must explain how their volunteer experience has shaped their plans for future study.","translationZh":"申請獎學金的學生必須說明，志工經驗如何影響他們未來的學習計畫。","source":"self-authored","grammar":"who apply for 修飾 students；how 子句說明經驗的影響。","writingTip":"申請類短文可把志工經驗連結未來計畫。","topic":"獎學金申請"},{"text":"By applying what we learned in science class to gardening, we discovered why some plants grew better in different soils.","translationZh":"把自然課學到的知識應用於園藝後，我們發現不同植物為何在不同土壤長得較好。","source":"self-authored","grammar":"applying A to B；what we learned 作 applying 的受詞。","writingTip":"可敘述如何把課堂知識用於日常實驗。","topic":"課堂實作"}]},"appreciate":{"senses":[{"pos":"vt.","meaning":"感激；欣賞；理解重要性","usage":"根據受詞判斷是感激、欣賞或理解。"},{"pos":"vi.","meaning":"增值","usage":"用於資產或貨幣價值上升。"}],"collocations":[{"en":"appreciate someone's help","zh":"感激某人的幫助","note":""},{"en":"appreciate the importance of","zh":"理解……的重要性","note":""},{"en":"appreciate being included","zh":"感激受到邀請或納入","note":""},{"en":"appreciate in value","zh":"增值","note":""}],"synonyms":[{"en":"value","zh":"珍視","note":"強調認為重要，不一定表示感謝。"},{"en":"be grateful for","zh":"感激……","note":"需用 for 接感激的事情。"}],"idioms":[],"family":[{"word":"appreciation","pos":"n.","meaning":"感激；欣賞；增值"},{"word":"appreciative","pos":"adj.","meaning":"感激的；欣賞的"}],"examples":[{"text":"I appreciate the time my classmates spent helping me understand a topic I had found difficult.","translationZh":"我很感激同學花時間幫我理解一個原本覺得困難的主題。","grammar":"spend time V-ing，兩個省略關係代名詞的限定子句。","writingTip":"可寫同儕互助與感恩。","topic":"學習與友誼","source":"self-authored"},{"text":"Visitors can better appreciate local traditions when guides explain the stories behind everyday customs.","translationZh":"導覽者若解說日常習俗背後的故事，遊客便能更深入欣賞在地傳統。","grammar":"when 引導條件情境，behind 表背後的原因或故事。","writingTip":"適合討論文化導覽與深度旅行。","topic":"文化與觀光","source":"self-authored"}],"usageNote":"appreciate 直接接事物或動名詞；感謝某人可寫 appreciate your help，不寫 appreciate you for help。"},"approach":{"senses":[{"pos":"n.","meaning":"方法；處理方式","usage":"approach to + 問題"},{"pos":"vi./vt.","meaning":"接近","usage":"時間或人物靠近"},{"pos":"vt.","meaning":"處理；著手解決","usage":"approach a problem"}],"collocations":[{"en":"an approach to problem solving","zh":"解決問題的方法","note":"to 為介系詞"},{"en":"adopt a practical approach","zh":"採取務實方法","note":"adopt 搭配"},{"en":"approach a difficult task","zh":"著手處理難題","note":"動詞直接接受詞"},{"en":"the approach of winter","zh":"冬天的到來","note":"名詞表接近"}],"synonyms":[{"en":"method","zh":"方法","note":"著重具體程序"},{"en":"draw near","zh":"接近","note":"對應接近的動詞義"}],"idioms":[],"family":[{"word":"approachable","pos":"adj.","meaning":"平易近人的；容易接近的"}],"examples":[{"text":"Our teacher adopted a different approach to explaining the experiment when several students looked confused.","translationZh":"幾位學生露出困惑神情時，老師採用了不同方式解釋實驗。","source":"self-authored","grammar":"approach to + V-ing","writingTip":"描述教學方法時交代改變的原因。","topic":"education"},{"text":"As the deadline approached, our team divided the remaining work into smaller tasks.","translationZh":"截止日期接近時，我們把剩餘工作分成較小的任務。","source":"self-authored","grammar":"As the deadline approached 是時間子句；approached 在此不及物；divided A into B 表分成。","writingTip":"寫時間壓力時，補上拆分工作的具體應對方式。","topic":"teamwork"}],"usageNote":"名詞 approach 後常接 to；動詞 approach 後直接接問題或人，不加 to。"},"appropriate":{"senses":[{"pos":"adj.","meaning":"合適的；恰當的","usage":"常接 for + 對象或情境。"},{"pos":"vt.","meaning":"撥用；挪用；擅自取用","usage":"較正式；須由受詞與語境判斷合法撥款或未經同意取用。"}],"collocations":[{"en":"appropriate for younger readers","zh":"適合年幼讀者","note":""},{"en":"take appropriate action","zh":"採取適當行動","note":""},{"en":"appropriate behavior","zh":"合宜的行為","note":""},{"en":"appropriate funds for repairs","zh":"撥款維修","note":"此處 appropriate 為動詞。"}],"synonyms":[{"en":"suitable","zh":"合適的","note":"對應形容詞義，常接 for。"},{"en":"allocate","zh":"分配；撥出","note":"對應資源撥用義，不包含擅取的負面意思。"}],"idioms":[],"family":[{"word":"appropriately","pos":"adv.","meaning":"適當地"},{"word":"inappropriate","pos":"adj.","meaning":"不適當的"},{"word":"appropriation","pos":"n.","meaning":"撥款；挪用"}],"usageNote":"形容詞與動詞拼字相同但尾音不同；閱讀時先依句型辨詞性。appropriate for 指適合對象，不是對所有人都有效。","examples":[{"text":"Teachers chose examples appropriate for younger readers without removing the important questions raised by the original article.","translationZh":"老師選擇適合年幼讀者的例子，同時保留原文提出的重要問題。","grammar":"appropriate for younger readers 後置修飾 examples；raised 為過去分詞。","writingTip":"說明簡化教材仍可保留值得討論的核心問題。","topic":"教材設計","source":"self-authored"},{"text":"The council voted to appropriate funds for repairing the footbridge after residents reported several damaged wooden boards.","translationZh":"居民通報數塊木板損壞後，議會表決撥款修復人行橋。","grammar":"voted to appropriate 為不定詞；funds for + V-ing 表資金用途。","writingTip":"公共建設作文可具體寫出問題、資金與修復行動。","topic":"公共設施","source":"self-authored"}]},"approve":{"senses":[{"pos":"vi.","meaning":"贊成；認可","usage":"approve of + 人、事物或 V-ing。"},{"pos":"vt.","meaning":"核准；批准","usage":"正式核准計畫或申請，直接接受詞。"}],"collocations":[{"en":"approve of a decision","zh":"贊成一項決定","note":"意見上的支持。"},{"en":"approve of sharing resources","zh":"贊成共享資源","note":"of 後接 V-ing。"},{"en":"approve a proposal","zh":"核准提案","note":"正式核准時不加 of。"},{"en":"receive official approval","zh":"獲得正式核准","note":"名詞搭配。"}],"synonyms":[{"en":"endorse","zh":"支持；背書","note":"常指公開表態支持，不必具有核准權。"},{"en":"authorize","zh":"授權；准許","note":"強調給予正式權限，通常需有權批准。"}],"idioms":[],"family":[{"word":"approval","pos":"n.","meaning":"同意；核准"},{"word":"approved","pos":"adj.","meaning":"已核准的"},{"word":"disapprove","pos":"vi.","meaning":"不贊成"}],"usageNote":"approve of the plan 表示贊成；approve the plan 表示核准。approval 通常不可數，具體核准文件等語境另有用法。","examples":[{"text":"Most parents approved of the new reading program because children could choose books that matched their interests.","translationZh":"多數家長贊成新的閱讀計畫，因為孩子能選擇符合興趣的書。","grammar":"approve of + 名詞；that matched their interests 修飾 books。","writingTip":"交代支持教育措施的具體理由。","topic":"閱讀計畫","source":"self-authored"},{"text":"The school approved our proposal only after we explained how volunteers would keep the playground safe.","translationZh":"直到我們說明志工會如何維持操場安全後，學校才核准提案。","grammar":"approved 直接接 proposal；how 引導安全措施的內容。","writingTip":"描述提案獲准前必須處理的實際條件。","topic":"校園提案","source":"self-authored"}]},"argue":{"senses":[{"pos":"vi.","meaning":"爭論；主張","usage":"argue with 人、about 事情、for 或 against 立場。"},{"pos":"vt.","meaning":"論證；主張","usage":"可接 that 子句。"}],"collocations":[{"en":"argue with someone","zh":"與某人爭論","note":""},{"en":"argue about money","zh":"為金錢爭吵","note":""},{"en":"argue in favor of","zh":"提出支持……的論點","note":""},{"en":"argue that","zh":"主張……","note":""}],"synonyms":[{"en":"dispute","zh":"爭議；質疑","note":"常聚焦某項說法的真實性。"},{"en":"claim","zh":"聲稱","note":"未必提出論證，可信度需依語境判斷。"}],"idioms":[],"family":[{"word":"argument","pos":"n.","meaning":"爭論；論點"},{"word":"arguable","pos":"adj.","meaning":"可爭辯的"},{"word":"arguably","pos":"adv.","meaning":"可以說是"}],"examples":[{"text":"Instead of arguing about who was responsible, we focused on repairing the damage and improving our procedures.","translationZh":"我們沒有爭論誰該負責，而是專注修復損害並改善流程。","grammar":"instead of 後接動名詞，who 引導名詞子句。","writingTip":"適合寫衝突後的合作解決方式。","topic":"合作與衝突","source":"self-authored"},{"text":"Some parents argue that schools should begin later so that teenagers can get enough sleep.","translationZh":"有些家長主張學校應較晚開始上課，好讓青少年睡眠充足。","grammar":"argue that 表提出立場，so that 表目的。","writingTip":"適合議論文引出一方觀點。","topic":"教育與健康","source":"self-authored"}],"usageNote":"argue 不一定指吵架；在議論文章中常指以理由支持某個立場。"},"arrange":{"senses":[{"pos":"vt.","meaning":"安排；整理","usage":"可接事物，但安排某人做事用 arrange for someone to V。"}],"collocations":[{"en":"arrange a meeting","zh":"安排會議","note":""},{"en":"arrange for someone to","zh":"安排某人……","note":""},{"en":"arrange flowers","zh":"插花；整理花卉","note":""},{"en":"arrange things in order","zh":"按順序整理物品","note":""}],"synonyms":[{"en":"organize","zh":"籌辦；整理","note":"可包括分工、規畫與執行。"},{"en":"schedule","zh":"排定時間","note":"更聚焦明確的日期或時段。"}],"idioms":[],"family":[{"word":"arrangement","pos":"n.","meaning":"安排；協議"},{"word":"rearrange","pos":"vt.","meaning":"重新安排；重新排列"}],"examples":[{"text":"The school arranged for a local artist to teach students how to reuse discarded materials creatively.","translationZh":"學校安排一位在地藝術家，教學生如何有創意地再利用廢棄材料。","grammar":"arrange for someone to V，how to V 表方法。","writingTip":"可寫社區資源與環境教育。","topic":"藝術與永續","source":"self-authored"},{"text":"Before the presentation, we arranged the chairs in a circle to encourage an open discussion.","translationZh":"簡報開始前，我們把椅子排成一圈，以鼓勵開放的討論。","grammar":"in a circle 描述排列方式，to V 表目的。","writingTip":"適合描述活動安排如何影響互動。","topic":"溝通與活動","source":"self-authored"}],"usageNote":"arrange a meeting with someone 正確；安排某人做事須加 for，不寫 arrange someone to go。"},"artificial":{"senses":[{"pos":"adj.","meaning":"人工製造的","usage":"與天然材料對比"},{"pos":"adj.","meaning":"刻意做作的","usage":"形容笑容或行為"}],"collocations":[{"en":"artificial intelligence","zh":"人工智慧","note":"科技用語"},{"en":"artificial lighting","zh":"人工照明","note":"建築與環境主題"},{"en":"artificial sweeteners","zh":"人工甜味劑","note":"食品主題"},{"en":"an artificial smile","zh":"做作的笑容","note":"描述表情"}],"synonyms":[{"en":"man-made","zh":"人造的","note":"適用材料或設施"},{"en":"insincere","zh":"不真誠的","note":"只對應表情或行為的意思"}],"idioms":[],"family":[{"word":"artificially","pos":"adv.","meaning":"人工地；不自然地"},{"word":"artificiality","pos":"n.","meaning":"人工性；不自然"}],"examples":[{"text":"Artificial lighting along the coast can confuse young sea turtles as they search for the ocean.","translationZh":"海岸的人工照明可能讓尋找海洋的幼龜迷失方向。","source":"self-authored","grammar":"artificial 作形容詞修飾 lighting；as they search for the ocean 引導同時發生的動作。","writingTip":"以人工照明干擾幼龜方向為例，說明人類活動如何影響動物。","topic":"wildlife"},{"text":"Although artificial sweeteners can reduce sugar intake, consumers should still examine the ingredients in processed foods.","translationZh":"雖然人工甜味劑能減少糖的攝取，消費者仍應檢查加工食品的成分。","source":"self-authored","grammar":"Although 引導讓步子句","writingTip":"可用於飲食選擇的審慎論述。","topic":"health"}],"usageNote":"artificial 不一定帶負面評價；artificial smile 則常含不自然或不真誠之意。"},"assess":{"senses":[{"pos":"vt.","meaning":"評估；判定","usage":"根據資料作判斷"}],"collocations":[{"en":"assess the damage","zh":"評估損害","note":"災害報導"},{"en":"assess the risks","zh":"評估風險","note":"決策前的步驟"},{"en":"assess student progress","zh":"評估學生進展","note":"教育情境"},{"en":"assess the effectiveness of a policy","zh":"評估政策成效","note":"of 說明成效對象"}],"synonyms":[{"en":"evaluate","zh":"評估","note":"常評價品質或效果"},{"en":"estimate","zh":"估計","note":"著重數量的大致判斷"}],"idioms":[],"family":[{"word":"assessment","pos":"n.","meaning":"評估"},{"word":"reassess","pos":"vt.","meaning":"重新評估"}],"examples":[{"text":"Before opening the hiking trail, officials assessed the damage caused by the recent storm.","translationZh":"步道開放前，官員評估了近日風暴造成的損害。","source":"self-authored","grammar":"caused by 為過去分詞片語修飾 damage","writingTip":"適合說明災後決策程序。","topic":"safety"},{"text":"Teachers can assess student progress through projects that show how knowledge is applied.","translationZh":"老師能透過呈現知識應用方式的專題，評估學生的學習進展。","source":"self-authored","grammar":"assess 直接接 student progress；that show 修飾 projects；how knowledge is applied 是間接問句，內含被動語態。","writingTip":"討論多元評量時，指出專題可呈現知識的實際應用。","topic":"education"}],"usageNote":"assess 著重有依據的評估；估計人數或價格時，estimate 往往更精確。"},"assume":{"senses":[{"pos":"v.","meaning":"假定；認為","usage":""},{"pos":"v.","meaning":"承擔職務或責任","usage":""}],"collocations":[{"en":"assume that someone knows","zh":"假定某人知道","note":""},{"en":"assume responsibility for a task","zh":"承擔任務責任","note":""},{"en":"assume the role of leader","zh":"擔任領導者","note":""},{"en":"make an assumption","zh":"作出假設","note":""}],"synonyms":[{"en":"suppose","zh":"假設","note":"常用於未經確定的推測"},{"en":"take on","zh":"承擔","note":"take on a role 接受角色或任務"}],"idioms":[],"family":[{"word":"assumption","pos":"n.","meaning":"假設；假定"},{"word":"assumed","pos":"adj.","meaning":"假定的；假裝的"}],"usageNote":"assume 不代表已證實；勿與 assure（使確信）混淆。","examples":[{"text":"We should not assume that everyone has reliable internet access simply because most of our classmates use smartphones every day.","translationZh":"我們不應只因多數同學每天使用智慧型手機，就假定每個人都有可靠的網路。","source":"self-authored","grammar":"assume that + 子句；simply because 表假設的單一依據。","writingTip":"可反思以身邊經驗推論所有人的偏誤。","topic":"網路可及性"},{"text":"When our team leader became ill, I assumed responsibility for organizing the meeting and making sure everyone understood the new schedule.","translationZh":"小組長生病時，我承擔安排會議的責任，並確保每個人都了解新進度。","source":"self-authored","grammar":"assumed responsibility for + V-ing；making sure 與 organizing 平行。","writingTip":"描寫接手任務時的安排與確認工作。","topic":"接手領導工作"}]},"assumption":{"senses":[{"pos":"n.","meaning":"假設；想當然的看法","usage":"尚未充分驗證的前提；不可直接當成事實。"},{"pos":"n.","meaning":"承擔；取得","usage":"較正式，如 assumption of responsibility。"}],"collocations":[{"en":"make an assumption about someone","zh":"對某人作出假設","note":""},{"en":"challenge an assumption","zh":"質疑一項假設","note":""},{"en":"based on the assumption that","zh":"基於……的假設","note":"that 子句解釋假設內容。"},{"en":"the assumption of responsibility","zh":"承擔責任","note":"另一個名詞義。"}],"synonyms":[{"en":"supposition","zh":"假定","note":"較正式，強調暫時相信但未證實。"},{"en":"premise","zh":"前提","note":"論證的起點，可能有證據，也可能只是先行接受。"}],"idioms":[],"family":[{"word":"assume","pos":"vt.","meaning":"假定；承擔"},{"word":"assumed","pos":"adj.","meaning":"假定的；假裝的"}],"usageNote":"assumption that + 子句表假設內容；assumption of + 職務或責任表承擔。不要把假設自動當作研究結論。","examples":[{"text":"Our plan was based on the assumption that every student had reliable internet access at home.","translationZh":"我們的計畫建立在每位學生家中都有可靠網路的假設上。","grammar":"based on 為被動搭配；that 子句說明 assumption 的內容。","writingTip":"可用來指出計畫忽略不同家庭資源的問題。","topic":"數位落差","source":"self-authored"},{"text":"Talking with older residents challenged my assumption that people of their generation were unwilling to learn new skills.","translationZh":"與年長居民交談，挑戰了我原以為那個世代不願學習新技能的看法。","grammar":"Talking 為動名詞主詞；that 子句補充假設內容。","writingTip":"寫個人經驗如何改變對某群體的刻板印象。","topic":"世代理解","source":"self-authored"}]},"atmosphere":{"senses":[{"pos":"n.","meaning":"大氣層","usage":"常用 the atmosphere"},{"pos":"n.","meaning":"氣氛","usage":"場所或情境的感受"}],"collocations":[{"en":"the Earth's atmosphere","zh":"地球的大氣層","note":"科學語境"},{"en":"a relaxed atmosphere","zh":"輕鬆的氣氛","note":"a 表某種氣氛"},{"en":"create a welcoming atmosphere","zh":"營造友善氣氛","note":"人際與空間"},{"en":"release gases into the atmosphere","zh":"將氣體排入大氣","note":"into 表進入"}],"synonyms":[{"en":"air","zh":"空氣","note":"只在特定大氣語境相近"},{"en":"ambience","zh":"氛圍","note":"著重場所帶給人的感覺"}],"idioms":[],"family":[{"word":"atmospheric","pos":"adj.","meaning":"大氣的；有氛圍的"}],"examples":[{"text":"The small bookstore creates a welcoming atmosphere by providing comfortable chairs and quiet reading corners.","translationZh":"這家小書店透過舒適座椅與安靜閱讀角，營造友善的氣氛。","source":"self-authored","grammar":"a welcoming atmosphere 是 create 的受詞；by providing 用 by + V-ing 說明營造方式。","writingTip":"描寫書店氣氛時，以座椅和閱讀角支持友善的感受。","topic":"community"},{"text":"Certain gases trap heat in the atmosphere and gradually raise the planet's average temperature.","translationZh":"某些氣體將熱困在大氣中，逐漸提高地球的平均溫度。","source":"self-authored","grammar":"in the atmosphere 是介系詞片語；trap 與 raise 共用主詞 Certain gases，表示兩項相關作用。","writingTip":"解釋暖化時，可先說熱被困住，再說平均溫度上升。","topic":"climate"}],"usageNote":"atmosphere 可指實體大氣，也可指抽象氣氛；依語境判讀。"},"attach":{"senses":[{"pos":"vt.","meaning":"附上；繫上","usage":"attach A to B，把 A 附加或固定到 B。"},{"pos":"vt.","meaning":"賦予；認為具有","usage":"attach importance to 重視。"}],"collocations":[{"en":"attach a file to an email","zh":"把檔案附在電子郵件中","note":""},{"en":"attach a label to a box","zh":"把標籤貼在箱子上","note":""},{"en":"attach importance to safety","zh":"重視安全","note":"importance 為不可數名詞。"},{"en":"be attached to a pet","zh":"依戀寵物","note":"attached 形容情感依附。"}],"synonyms":[{"en":"fasten","zh":"繫牢；固定","note":"只對應實物連接義，常強調牢固。"},{"en":"enclose","zh":"隨信附上","note":"通常指信函內附物；不等於所有 attach 用法。"}],"idioms":[],"family":[{"word":"attachment","pos":"n.","meaning":"附件；依戀"},{"word":"attached","pos":"adj.","meaning":"附加的；依戀的"},{"word":"detach","pos":"vt.","meaning":"拆下；分離"}],"usageNote":"attach A to B 的 to 是介系詞；be attached to 可指附在某物上，也可指情感依戀。","examples":[{"text":"Please attach a recent photo to your application so that volunteers can recognize you at the meeting point.","translationZh":"請在申請表附上近照，讓志工能在集合地點認出你。","grammar":"attach A to B；so that 引導附照片的目的。","writingTip":"寫活動通知時交代要求及其用途。","topic":"活動報名","source":"self-authored"},{"text":"Our club attaches great importance to safety, even when a shortcut would save time during an outdoor activity.","translationZh":"即使捷徑能在戶外活動中節省時間，我們社團仍非常重視安全。","grammar":"attach importance to + 名詞；even when 表即使在某情況下。","writingTip":"討論效率與安全時清楚表明優先考量。","topic":"戶外安全","source":"self-authored"}]},"attempt":{"senses":[{"pos":"n.","meaning":"嘗試","usage":"an attempt to V；可數名詞。"},{"pos":"vt.","meaning":"嘗試","usage":"attempt to V，語氣較正式。"}],"collocations":[{"en":"make an attempt to improve","zh":"嘗試改善","note":""},{"en":"attempt to solve a problem","zh":"嘗試解決問題","note":""},{"en":"a successful attempt","zh":"成功的嘗試","note":"attempt 本身不保證成功。"},{"en":"on the first attempt","zh":"第一次嘗試時","note":""}],"synonyms":[{"en":"try","zh":"嘗試","note":"較日常；try doing 也可指試用方法。"},{"en":"effort","zh":"努力；嘗試","note":"可強調付出的心力，不只是一次行動。"}],"idioms":[],"family":[{"word":"attempted","pos":"adj.","meaning":"企圖進行而未遂的"},{"word":"unattempted","pos":"adj.","meaning":"未嘗試過的"}],"usageNote":"attempt to do 並不保證做到；敘述成果時應另交代成功或失敗，不把嘗試直接寫成達成。","examples":[{"text":"My first attempt to explain the rules failed because I used terms that younger children did not understand.","translationZh":"我第一次嘗試解釋規則失敗了，因為用了年幼孩子不懂的詞。","grammar":"attempt to explain 修飾名詞；that 引導限定關係子句。","writingTip":"用失敗的具體原因引出後續調整。","topic":"教學經驗","source":"self-authored"},{"text":"The students attempted to reduce food waste by letting classmates order smaller portions and return for more if needed.","translationZh":"學生嘗試讓同學先點較小份量，必要時再添餐，以減少食物浪費。","grammar":"attempted to V；let + 人 + 原形 order 與 return。","writingTip":"環境作文可提出可操作的改善方式，並保留成效驗證空間。","topic":"惜食行動","source":"self-authored"}]},"attend":{"senses":[{"pos":"v.","meaning":"出席；上學","usage":""},{"pos":"v.","meaning":"照料；處理","usage":""}],"collocations":[{"en":"attend a lecture","zh":"出席講座","note":""},{"en":"attend school","zh":"上學","note":""},{"en":"attend to a patient","zh":"照料病人","note":""},{"en":"attend to a problem","zh":"處理問題","note":""}],"synonyms":[{"en":"be present at","zh":"出席","note":"強調到場"},{"en":"take care of","zh":"照顧","note":"對應 attend to，不能替代所有出席義"}],"idioms":[],"family":[{"word":"attendance","pos":"n.","meaning":"出席；出席率"},{"word":"attendant","pos":"n.","meaning":"服務人員"},{"word":"attentive","pos":"adj.","meaning":"注意的；體貼的"}],"usageNote":"attend + 活動不加 to；attend to + 人／事情表示照料或處理。","examples":[{"text":"Students attending the lecture were encouraged to ask questions and relate the speaker's ideas to problems in their own communities.","translationZh":"參加講座的學生受到鼓勵，提出問題並將講者觀點連結到自己社區的問題。","source":"self-authored","grammar":"attending 修飾 students；were encouraged to + 原形動詞。","writingTip":"說明講座如何連結社區問題。","topic":"講座學習"},{"text":"While the nurse attended to an injured passenger, other travelers made room and helped keep the crowded platform calm.","translationZh":"護理師照料受傷乘客時，其他旅客讓出空間，並協助擁擠的月台保持平靜。","source":"self-authored","grammar":"attended to + 病人；while 表同時的兩種行動。","writingTip":"描寫專業照護與其他旅客合作的現場。","topic":"月台互助"}]},"attention":{"senses":[{"pos":"n.","meaning":"注意；關注","usage":"一般不可數，常用 attention to。"},{"pos":"n.","meaning":"照顧；處理","usage":"如 medical attention 表醫療處置。"}],"collocations":[{"en":"pay attention to details","zh":"注意細節","note":"to 是介系詞。"},{"en":"draw attention to a problem","zh":"使人注意某個問題","note":""},{"en":"need medical attention","zh":"需要醫療處置","note":""},{"en":"capture the audience's attention","zh":"吸引觀眾注意","note":""}],"synonyms":[{"en":"notice","zh":"注意","note":"take notice of 句型不同，不宜直接逐字替換。"},{"en":"care","zh":"照料","note":"只對應處理或照顧義，不等於集中注意。"}],"idioms":[],"family":[{"word":"attentive","pos":"adj.","meaning":"專心的；體貼的"},{"word":"attentively","pos":"adv.","meaning":"專心地"},{"word":"inattention","pos":"n.","meaning":"不注意"}],"usageNote":"pay attention to + 名詞／V-ing；不是 pay attention on。注意力集中不保證理解，還需要檢查自己能否說明內容。","examples":[{"text":"Instead of checking my phone between every paragraph, I paid attention to how each idea connected with the next.","translationZh":"我沒有每讀完一段就看手機，而是注意各個想法如何銜接。","grammar":"Instead of + V-ing；pay attention to 後接 how 子句。","writingTip":"學習經驗可寫具體閱讀行為的改變。","topic":"專注閱讀","source":"self-authored"},{"text":"The photo exhibition drew attention to the challenges faced by families living far from hospitals and public transportation.","translationZh":"攝影展讓人注意住在遠離醫院與大眾運輸地區的家庭所面臨的挑戰。","grammar":"draw attention to + 名詞；faced 與 living 分別修飾 challenges、families。","writingTip":"以展覽或照片作為引發社會關注的具體媒介。","topic":"偏鄉生活","source":"self-authored"}]},"attitude":{"senses":[{"pos":"n.","meaning":"態度；看法","usage":"常搭配 toward 或 towards 表對象。"}],"collocations":[{"en":"a positive attitude","zh":"正面的態度","note":""},{"en":"an attitude toward learning","zh":"對學習的態度","note":""},{"en":"change one's attitude","zh":"改變態度","note":""},{"en":"adopt a different attitude","zh":"採取不同態度","note":""}],"synonyms":[{"en":"outlook","zh":"觀點；人生觀","note":"常指對未來或人生的整體看法。"},{"en":"mindset","zh":"思維模式","note":"強調影響行為的固定想法。"}],"idioms":[],"family":[{"word":"attitudinal","pos":"adj.","meaning":"態度的（較正式，常見於研究語境）"}],"examples":[{"text":"Her positive attitude helped the team remain hopeful when unexpected delays threatened the project.","translationZh":"當突如其來的延誤威脅到專案時，她積極的態度幫助團隊保持希望。","grammar":"help someone remain adjective，when 引導時間子句。","writingTip":"可寫逆境中影響團隊的力量。","topic":"團隊與韌性","source":"self-authored"},{"text":"People's attitudes toward secondhand goods may change as they become more aware of the environmental costs of consumption.","translationZh":"人們越了解消費造成的環境成本，對二手物品的態度就可能改變。","grammar":"as 表隨著，become aware of 表逐漸意識到。","writingTip":"適合分析觀念轉變與永續消費。","topic":"消費與環境","source":"self-authored"}],"usageNote":"attitude 與 altitude「海拔」拼字相近；toward 後接名詞，不接原形動詞。"},"attract":{"senses":[{"pos":"vt.","meaning":"吸引；引起","usage":"接人、注意力、投資等受詞。"}],"collocations":[{"en":"attract attention","zh":"吸引注意","note":""},{"en":"attract visitors","zh":"吸引遊客","note":""},{"en":"attract investment","zh":"吸引投資","note":""},{"en":"be attracted to","zh":"受到……吸引","note":""}],"synonyms":[{"en":"draw","zh":"吸引","note":"draw attention 常可替換 attract attention。"},{"en":"appeal to","zh":"對……有吸引力","note":"主詞通常是有吸引力的人事物。"}],"idioms":[],"family":[{"word":"attraction","pos":"n.","meaning":"吸引力；景點"},{"word":"attractive","pos":"adj.","meaning":"有吸引力的"},{"word":"attractively","pos":"adv.","meaning":"吸引人地"}],"examples":[{"text":"The small bookstore attracts visitors by offering reading groups and events that connect neighbors.","translationZh":"這家小書店透過舉辦讀書會和聯繫鄰里情感的活動，吸引訪客。","grammar":"by V-ing 表方法，that 引導限定關係子句。","writingTip":"可描述實體店家如何創造價值。","topic":"社區與閱讀","source":"self-authored"},{"text":"Advertisements often attract our attention with vivid images before we notice the product's actual usefulness.","translationZh":"廣告常先用鮮明的影像吸引我們注意，之後我們才留意產品是否真正實用。","grammar":"before 連接先後發生的動作，with 表手段。","writingTip":"適合討論媒體說服與理性消費。","topic":"廣告與消費","source":"self-authored"}],"usageNote":"attract 是動詞；attractive 是形容詞，不能寫 the place is attract。"},"available":{"senses":[{"pos":"adj.","meaning":"可取得的；可使用的","usage":""},{"pos":"adj.","meaning":"有空的","usage":""}],"collocations":[{"en":"readily available information","zh":"容易取得的資訊","note":""},{"en":"available to all students","zh":"所有學生都可使用的","note":""},{"en":"available for download","zh":"可供下載","note":""},{"en":"be available for a meeting","zh":"有空開會","note":""}],"synonyms":[{"en":"accessible","zh":"可取得的","note":"也可能指無障礙或易理解"},{"en":"free","zh":"有空的","note":"free 也可指免費，available 不保證免費"}],"idioms":[],"family":[{"word":"availability","pos":"n.","meaning":"可取得性；可用程度"},{"word":"unavailable","pos":"adj.","meaning":"無法取得的；沒空的"}],"usageNote":"available to + 使用者；available for + 用途。資訊存在不代表每個人都能取得。","examples":[{"text":"Although the information was available online, the instructions were so confusing that many older residents still needed help completing the form.","translationZh":"雖然資訊可在網路取得，說明卻很混亂，許多年長居民仍需要協助填表。","source":"self-authored","grammar":"so confusing that + 結果子句；help completing 表協助的事項。","writingTip":"指出資訊可取得與實際可使用之間的落差。","topic":"數位行政"},{"text":"Making sports facilities available to the public after school can encourage exercise and strengthen connections between the school and its neighborhood.","translationZh":"放學後讓公眾使用運動設施，能鼓勵運動，並加強學校與社區的連結。","source":"self-authored","grammar":"making + 設施 + available to + 使用者，整個片語作主詞。","writingTip":"可分析開放校園資源如何促進社區連結。","topic":"共享校園設施"}]},"average":{"senses":[{"pos":"n.","meaning":"平均值","usage":""},{"pos":"adj.","meaning":"平均的；普通的","usage":""},{"pos":"v.","meaning":"平均為","usage":""}],"collocations":[{"en":"on average","zh":"平均而言","note":""},{"en":"an average of ten hours","zh":"平均十小時","note":""},{"en":"above average","zh":"高於平均","note":""},{"en":"average six hours a night","zh":"每晚平均六小時","note":""}],"synonyms":[{"en":"typical","zh":"典型的","note":"典型不一定是統計平均"},{"en":"ordinary","zh":"普通的","note":"適用一般水準義"}],"idioms":[],"family":[{"word":"averaging","pos":"v.","meaning":"平均為（現在分詞）"},{"word":"above-average","pos":"adj.","meaning":"高於平均的"}],"usageNote":"on average 是片語；an average of + 數量。平均值可能掩蓋個別差異。","examples":[{"text":"Students in the survey slept an average of six hours on school nights, which was less than they expected.","translationZh":"調查中的學生在上課日前夜平均睡六小時，比他們原先以為的少。","source":"self-authored","grammar":"an average of + 時間數量；which 補充與預期的差異。","writingTip":"報告平均值後，可與學生原先認知比較。","topic":"睡眠調查"},{"text":"Although the class average improved, the teacher reviewed individual results to identify students who still needed extra support in reading.","translationZh":"雖然全班平均成績提升，老師仍檢視個別結果，找出閱讀上還需要額外支持的學生。","source":"self-authored","grammar":"although 引導讓步；who still needed 修飾 students。","writingTip":"指出平均改善不代表每位學生都得到足夠支持。","topic":"個別學習支持"}]},"avoid":{"senses":[{"pos":"vt.","meaning":"避免；避開","usage":"直接接名詞或 V-ing，不接 to V。"}],"collocations":[{"en":"avoid making mistakes","zh":"避免犯錯","note":""},{"en":"avoid unnecessary waste","zh":"避免不必要的浪費","note":""},{"en":"avoid heavy traffic","zh":"避開交通壅塞","note":""},{"en":"avoid contact with sick animals","zh":"避免接觸生病的動物","note":""}],"synonyms":[{"en":"prevent","zh":"預防；阻止","note":"prevent something from happening 著重阻止事件發生。"},{"en":"stay away from","zh":"遠離","note":"常指避開人或地方，不涵蓋所有避免結果的用法。"}],"idioms":[],"family":[{"word":"avoidance","pos":"n.","meaning":"避免；迴避"},{"word":"avoidable","pos":"adj.","meaning":"可避免的"},{"word":"unavoidable","pos":"adj.","meaning":"無法避免的"}],"usageNote":"avoid doing 而非 avoid to do；avoid an accident 是設法避開事故，prevent an accident 是阻止事故發生。","examples":[{"text":"To avoid misunderstanding the assignment, I asked the teacher to explain what the final report should include.","translationZh":"為避免誤解作業要求，我請老師說明期末報告應包含哪些內容。","grammar":"To avoid 表目的；avoid + V-ing；what 引導間接問句。","writingTip":"描寫主動澄清如何減少後續錯誤。","topic":"作業澄清","source":"self-authored"},{"text":"Shoppers can avoid unnecessary packaging by bringing their own containers when local stores allow them to do so.","translationZh":"當地商店允許時，消費者可自備容器，避免不必要的包裝。","grammar":"by bringing 表方法；when 子句交代做法適用的條件。","writingTip":"環保建議加上實際限制，比一概而論更周全。","topic":"消費與減廢","source":"self-authored"}]},"aware":{"senses":[{"pos":"adj.","meaning":"知道的；察覺的","usage":"通常作述語，搭配 of 或 that 子句。"}],"collocations":[{"en":"be aware of","zh":"意識到……","note":""},{"en":"become aware that","zh":"開始察覺……","note":""},{"en":"fully aware of","zh":"完全了解……","note":""},{"en":"raise awareness of","zh":"提高對……的認識","note":"使用名詞 awareness。"}],"synonyms":[{"en":"conscious of","zh":"意識到……","note":"有時強調當下的自覺或刻意注意。"},{"en":"informed about","zh":"了解……資訊的","note":"強調掌握資料，不完全等同察覺。"}],"idioms":[],"family":[{"word":"awareness","pos":"n.","meaning":"認識；察覺"},{"word":"unaware","pos":"adj.","meaning":"未察覺的"}],"examples":[{"text":"Many shoppers are not aware of how much water is used to produce a single cotton shirt.","translationZh":"許多消費者不知道，製造一件棉質上衣要用掉多少水。","grammar":"be aware of，how much 引導名詞子句，is used to V 表被用來。","writingTip":"可揭示日常消費隱藏的環境成本。","topic":"消費與環境","source":"self-authored"},{"text":"After interviewing wheelchair users, we became aware that small design choices could create serious barriers.","translationZh":"訪談輪椅使用者後，我們察覺到小小的設計選擇可能造成嚴重障礙。","grammar":"became aware that 後接完整子句，could 表潛在影響。","writingTip":"適合寫從他人經驗學會同理。","topic":"無障礙與同理","source":"self-authored"}],"usageNote":"aware 通常不直接置於名詞前；可寫 people who are aware of the risks。"},"balance":{"senses":[{"pos":"n.","meaning":"平衡；餘額","usage":"兼指身體、生活或帳戶狀態。"},{"pos":"vt.","meaning":"使平衡；兼顧","usage":"常用 balance A with B。"}],"collocations":[{"en":"keep one's balance","zh":"保持平衡","note":""},{"en":"strike a balance between","zh":"在……之間取得平衡","note":""},{"en":"balance work with leisure","zh":"兼顧工作與休閒","note":""},{"en":"a bank balance","zh":"銀行帳戶餘額","note":""}],"synonyms":[{"en":"equilibrium","zh":"平衡狀態","note":"較正式，常用於科學或經濟。"},{"en":"stability","zh":"穩定","note":"強調不易變動，不等同兼顧兩件事。"}],"idioms":[],"family":[{"word":"balanced","pos":"adj.","meaning":"均衡的"},{"word":"imbalance","pos":"n.","meaning":"不平衡"},{"word":"unbalanced","pos":"adj.","meaning":"不均衡的"}],"examples":[{"text":"A balanced schedule allows students to study effectively while leaving enough time for exercise and rest.","translationZh":"均衡的作息讓學生能有效讀書，也保留足夠的運動與休息時間。","grammar":"allow someone to V，while V-ing 表同時兼顧。","writingTip":"適合寫讀書計畫與身心健康。","topic":"學習與健康","source":"self-authored"},{"text":"Cities must balance the need for new housing with the responsibility to protect valuable green spaces.","translationZh":"城市必須兼顧新增住宅的需求，以及保護珍貴綠地的責任。","grammar":"balance A with B，the responsibility to V 表責任內容。","writingTip":"可用於比較都市發展的兩項需求。","topic":"都市與環境","source":"self-authored"}],"usageNote":"a balanced diet 指均衡飲食；a balance diet 的詞性不合。"},"bear":{"senses":[{"pos":"n.","meaning":"熊","usage":"可數名詞：a bear / bears；與動詞 bear 讀音相同，但詞義及變化不同。"},{"pos":"vt.","meaning":"忍受；承受","usage":"bear pain / pressure；cannot bear + 名詞、V-ing 或 to V 表無法忍受。"},{"pos":"vt.","meaning":"承擔；負擔","usage":"bear the cost / responsibility / burden，後接費用、責任或負擔。"},{"pos":"vt.","meaning":"帶有；具有；懷有","usage":"bear a name / label / resemblance / grudge；依受詞可指標示、相似之處或怨恨。"},{"pos":"vt.","meaning":"生育；生下","usage":"She has borne two children. 用 borne；出生用被動形式 be born，如 I was born in Taipei。"},{"pos":"vt./vi.","meaning":"結果實；產生結果","usage":"Trees bear fruit. 可指植物結果實；努力 bear fruit 則指取得成果。"},{"pos":"vi.","meaning":"向某方向行進；轉向","usage":"bear left / right = 向左／右轉或偏移，常見於路線指示。"}],"collocations":[{"en":"bear the cost","zh":"負擔費用","note":""},{"en":"bear responsibility","zh":"承擔責任","note":""},{"en":"bear fruit","zh":"取得成果","note":""},{"en":"bear in mind","zh":"記住；考慮到","note":""},{"en":"bear a resemblance to someone","zh":"與某人相像","note":"resemblance 為名詞；to 後接比較對象，不等同於 bear someone。"},{"en":"bear left at the junction","zh":"在岔路向左行","note":"bear 在此為不及物動詞，指轉向，與「忍受」無關。"}],"synonyms":[{"en":"endure","zh":"忍受","note":"強調持續承受困難"},{"en":"carry","zh":"帶有","note":"carry/bear a label 可指帶標示"}],"idioms":[{"en":"bear in mind","zh":"記住；留意","note":"後可接 that 子句"}],"family":[{"word":"bearable","pos":"adj.","meaning":"能忍受的"},{"word":"unbearable","pos":"adj.","meaning":"難以忍受的"},{"word":"bearing","pos":"n.","meaning":"姿態；關聯"},{"word":"bore","pos":"v.","meaning":"bear 的過去式；注意 bore 另可作「使厭煩」的原形動詞"},{"word":"borne","pos":"v.","meaning":"bear 的過去分詞：承擔、帶有或生育"},{"word":"born","pos":"v./adj.","meaning":"用於 be born 出生；born in / on / into 等搭配"}],"usageNote":"一般動詞變化 bear–bore–borne。主動談母親生育用 borne；描述某人出生用 be born。bearing 可指姿態、方向或關聯，have a bearing on = 對……有關聯／影響。與 bare「裸露的」不同。","examples":[{"text":"When planning a group trip, we must bear in mind that some classmates cannot afford the same activities as others.","translationZh":"規畫團體旅行時，我們必須記住，有些同學無法負擔和其他人相同的活動。","source":"self-authored","grammar":"bear in mind that + 子句；when planning 表決策情境。","writingTip":"規畫團體活動時考慮不同經濟能力。","topic":"團體旅行"},{"text":"The community's efforts finally bore fruit when a neglected lot became a garden where neighbors could grow vegetables and meet.","translationZh":"當荒廢空地變成鄰居可以種菜和相聚的花園時，社區的努力終於有了成果。","source":"self-authored","grammar":"bore fruit 表努力有成果；where 修飾 garden 的用途。","writingTip":"用具體空間改造呈現長期努力的成果。","topic":"社區花園"}]},"behavior":{"senses":[{"pos":"n.","meaning":"行為；表現","usage":"一般行為常作不可數名詞。"}],"collocations":[{"en":"change one's behavior","zh":"改變行為","note":""},{"en":"social behavior","zh":"社交行為","note":""},{"en":"appropriate behavior","zh":"合宜的行為","note":""},{"en":"behavior toward others","zh":"對他人的行為","note":""}],"synonyms":[{"en":"conduct","zh":"行為；操守","note":"較正式，常涉及規範與道德。"},{"en":"actions","zh":"行動","note":"指具體作為，未必是整體行為模式。"}],"idioms":[],"family":[{"word":"behave","pos":"vi.","meaning":"表現；守規矩"},{"word":"behavioral","pos":"adj.","meaning":"行為的"},{"word":"misbehavior","pos":"n.","meaning":"不當行為"}],"examples":[{"text":"Children often copy adults' behavior, so everyday actions can teach lessons more powerfully than spoken advice.","translationZh":"孩子常模仿大人的行為，因此日常行動可能比口頭建議更有教育力量。","grammar":"so 表結果，more powerfully than 為比較結構。","writingTip":"適合討論身教與家庭教育。","topic":"家庭與教育","source":"self-authored"},{"text":"The campaign encouraged responsible online behavior by showing how careless comments could hurt real people.","translationZh":"這項宣導透過呈現草率留言如何傷害真實的人，鼓勵負責任的網路行為。","grammar":"by showing how 接名詞子句，could 表可能後果。","writingTip":"可寫網路互動與尊重。","topic":"網路與倫理","source":"self-authored"}],"usageNote":"美式拼字為 behavior，英式為 behaviour；一般描述行為不寫 a behavior。"},"belonging":{"senses":[{"pos":"n.","meaning":"歸屬感","usage":"常用 a sense of belonging。"},{"pos":"n. pl.","meaning":"個人物品","usage":"belongings 為複數名詞。"}],"collocations":[{"en":"a sense of belonging","zh":"歸屬感","note":""},{"en":"develop a sense of belonging","zh":"建立歸屬感","note":""},{"en":"personal belongings","zh":"個人物品","note":""},{"en":"belong to a community","zh":"屬於一個社群","note":"belong 為動詞。"}],"synonyms":[{"en":"inclusion","zh":"融入；被納入","note":"強調有機會參與，可能促成歸屬感。"},{"en":"attachment","zh":"依附；情感連結","note":"可指對人或地方的感情。"}],"idioms":[],"family":[{"word":"belong","pos":"vi.","meaning":"屬於；有歸屬"},{"word":"belongings","pos":"n. pl.","meaning":"個人物品"}],"examples":[{"text":"Joining the school band gave me a sense of belonging that I had struggled to find before.","translationZh":"加入學校樂團，給了我先前一直難以找到的歸屬感。","grammar":"a sense of belonging 後接關係子句，had struggled 表較早經驗。","writingTip":"可用於社團參與與自我認同。","topic":"校園與歸屬","source":"self-authored"},{"text":"Volunteers helped families carry their belongings to the shelter after floodwater entered the neighborhood.","translationZh":"洪水進入社區後，志工協助家庭把個人物品搬到避難所。","grammar":"help someone carry 用原形動詞，after 引導時間子句。","writingTip":"適合描述災害中的具體互助。","topic":"災害與服務","source":"self-authored"}],"usageNote":"belonging 與 belongings 字義不同；belong to 無被動語態，不寫 is belonged to。"},"benefit":{"senses":[{"pos":"n.","meaning":"好處；益處","usage":"常接 of 或 to"},{"pos":"vi.","meaning":"受益","usage":"benefit from + 來源"},{"pos":"vt.","meaning":"使受益","usage":"直接接受詞"}],"collocations":[{"en":"benefit from regular exercise","zh":"從規律運動受益","note":"from 表受益來源"},{"en":"bring benefits to communities","zh":"為社區帶來好處","note":"to 指受益者"},{"en":"health benefits","zh":"健康益處","note":"複數常見"},{"en":"benefit local residents","zh":"讓當地居民受益","note":"動詞直接接受詞"}],"synonyms":[{"en":"advantage","zh":"優點","note":"著重有利條件"},{"en":"gain","zh":"收穫","note":"著重獲得的成果"}],"idioms":[],"family":[{"word":"beneficial","pos":"adj.","meaning":"有益的"},{"word":"beneficiary","pos":"n.","meaning":"受益人"}],"examples":[{"text":"Students benefit from outdoor activities because physical movement can improve their concentration in class.","translationZh":"學生能從戶外活動受益，因為身體活動能改善上課時的專注力。","source":"self-authored","grammar":"benefit from outdoor activities 中 from 引出受益來源；because 子句說明改善專注力的原因。","writingTip":"論述戶外活動的好處時，連結身體活動與課堂專注。","topic":"health"},{"text":"The new community garden benefits residents by offering fresh vegetables and opportunities to meet neighbors.","translationZh":"新社區菜園提供新鮮蔬菜與認識鄰居的機會，使居民受益。","source":"self-authored","grammar":"benefit + 人；by + V-ing","writingTip":"可連結環境與社區互動。","topic":"community"}],"usageNote":"benefit from 表主詞受益；benefit someone 表主詞讓別人受益。"},"bias":{"senses":[{"pos":"n.","meaning":"偏見；偏差","usage":"可指對群體的成見，也可指取樣或測量的系統性偏差。"},{"pos":"vt.","meaning":"使產生偏見；使結果偏向","usage":"如 bias the results。"}],"collocations":[{"en":"bias against a group","zh":"對某群體的偏見","note":""},{"en":"bias in favor of one option","zh":"偏向某個選項","note":""},{"en":"sampling bias","zh":"取樣偏差","note":"樣本無法合理代表目標群體。"},{"en":"reduce bias in a survey","zh":"減少調查偏差","note":""}],"synonyms":[{"en":"prejudice","zh":"偏見","note":"常指對群體先入為主的負面判斷。"},{"en":"partiality","zh":"偏袒","note":"較正式，強調偏向某一方。"}],"idioms":[],"family":[{"word":"biased","pos":"adj.","meaning":"有偏見的；有偏差的"},{"word":"unbiased","pos":"adj.","meaning":"無偏見的；無偏差的"}],"usageNote":"biased 可形容人、報導或樣本；統計偏差不一定來自惡意。be biased against／in favor of 要辨清方向。","examples":[{"text":"A survey conducted only online may contain bias because residents without internet access have little chance to participate.","translationZh":"只在線上進行的調查可能有偏差，因為無法上網的居民幾乎沒有機會參與。","grammar":"conducted 為過去分詞修飾 survey；because 交代取樣限制。","writingTip":"分析圖表時可指出誰沒有被納入調查。","topic":"取樣與資料","source":"self-authored"},{"text":"To reduce bias in our discussion, we invited people with different experiences to explain how the policy affected them.","translationZh":"為減少討論中的偏見，我們邀請不同經驗的人說明政策如何影響他們。","grammar":"To reduce 表目的；invite + 人 + to V。","writingTip":"討論公平決策時，提出讓多方發言的具體方法。","topic":"公共討論","source":"self-authored"}]},"board":{"senses":[{"pos":"n.","meaning":"木板；板材","usage":"a wooden board；可數名詞，指平整的板狀材料。"},{"pos":"n.","meaning":"公告板；黑板；遊戲板","usage":"a notice board / a whiteboard / a chessboard；用途通常由前面的名詞或複合字決定。"},{"pos":"n.","meaning":"董事會；委員會","usage":"the board of directors / a school board；通常是具有管理或決策職能的一群人。"},{"pos":"n.","meaning":"膳食；伙食","usage":"room and board = 住宿及膳食；board 在此通常不可數，不表示一塊木板。"},{"pos":"vt.","meaning":"登上交通工具","usage":"board a plane / train / ship；直接接交通工具，不需 on。"},{"pos":"vi.","meaning":"寄宿；搭伙","usage":"board with a family / at a school；表示寄宿並接受膳食，常見於 boarding school 的相關情境。"},{"pos":"vt.","meaning":"提供膳食或食宿","usage":"board students / board pets；依受詞指供人食宿或寄養動物，與登上交通工具不同。"},{"pos":"vt.","meaning":"用木板封住；覆蓋","usage":"board up a window / a building；常用 board up，指以板材封住開口。"}],"collocations":[{"en":"board a plane","zh":"登機","note":""},{"en":"a notice board","zh":"公告板","note":""},{"en":"a school board","zh":"教育委員會","note":""},{"en":"on board a ship","zh":"在船上","note":""},{"en":"room and board","zh":"住宿及膳食","note":"board 在此為不可數名詞；費用是否另含住宿需看表達。"},{"en":"board up a window","zh":"用木板封住窗戶","note":"片語動詞；代名詞受詞置於中間，如 board it up。"}],"synonyms":[{"en":"get on","zh":"上車","note":"常用於公車火車"},{"en":"committee","zh":"委員會","note":"board 通常具有管理或決策職能"}],"idioms":[],"family":[{"word":"boarding","pos":"n.","meaning":"登機；寄宿"},{"word":"boarder","pos":"n.","meaning":"寄宿者"},{"word":"boarding pass","pos":"n.","meaning":"登機證"}],"usageNote":"board a plane 是登機，on board a plane 是在機上；board 可直接接受詞，on board 是介系詞或副詞片語。board of directors 表董事會；room and board 表住宿及膳食；boarding school 表寄宿學校。","examples":[{"text":"Before boarding the train, we checked the platform number twice because several departures had been changed after the heavy rain.","translationZh":"上火車前，我們確認月台號碼兩次，因為大雨後幾班列車的出發安排有變動。","source":"self-authored","grammar":"before boarding 表登車前；had been changed 為過去完成被動。","writingTip":"可描寫天候造成交通變動後的確認行動。","topic":"鐵路旅行"},{"text":"The school board invited students to share their views before deciding whether to extend the library's opening hours during exam season.","translationZh":"教育委員會在決定是否延長考季的圖書館開放時間前，邀請學生分享看法。","source":"self-authored","grammar":"before deciding 表決策前；whether to extend 表是否延長。","writingTip":"呈現先聽取學生意見再制定政策的程序。","topic":"圖書館政策"}]},"bond":{"senses":[{"pos":"n.","meaning":"情感連結；關係","usage":""},{"pos":"v.","meaning":"建立親近關係","usage":""}],"collocations":[{"en":"a strong bond between friends","zh":"朋友間深厚的連結","note":""},{"en":"form a bond with someone","zh":"與某人建立情誼","note":""},{"en":"bond over a shared interest","zh":"因共同興趣建立情誼","note":""},{"en":"strengthen family bonds","zh":"加強家庭連結","note":""}],"synonyms":[{"en":"connection","zh":"連結","note":"範圍較廣"},{"en":"attachment","zh":"依戀","note":"強調情感依附，不一定雙向"}],"idioms":[],"family":[{"word":"bonding","pos":"n.","meaning":"建立情感連結的過程"},{"word":"bonded","pos":"adj.","meaning":"結合的；緊密連結的"}],"usageNote":"bond with + 人；bond over + 共同活動或興趣，不能任意互換介系詞。","examples":[{"text":"Caring for our dog together strengthened the bond between my brother and me because we learned to share daily responsibilities.","translationZh":"一起照顧我們的狗加強了我和弟弟的情感連結，因為我們學會分擔日常責任。","source":"self-authored","grammar":"strengthened the bond between A and B；because 解釋關係變化原因。","writingTip":"透過分擔照護責任描寫家庭關係的成長。","topic":"家庭照護"},{"text":"Students from different backgrounds bonded over their shared interest in music while preparing a performance for the school festival.","translationZh":"來自不同背景的學生在準備校慶表演時，因共同的音樂興趣建立了情誼。","source":"self-authored","grammar":"bonded over + 共同興趣；while preparing 表同時進行的活動。","writingTip":"可說明共同興趣如何拉近不同背景的學生。","topic":"社團交流"}]},"break":{"senses":[{"pos":"v.","meaning":"打破；違反；中斷","usage":""},{"pos":"n.","meaning":"休息；機會","usage":""}],"collocations":[{"en":"break a promise","zh":"違背承諾","note":""},{"en":"take a short break","zh":"短暫休息","note":""},{"en":"break the silence","zh":"打破沉默","note":""},{"en":"a big break","zh":"重要機會","note":""}],"synonyms":[{"en":"violate","zh":"違反","note":"較正式，常搭配 rule/law"},{"en":"pause","zh":"暫停","note":"不包含打破物品義"}],"idioms":[{"en":"break the ice","zh":"打破僵局","note":"指讓初次見面或緊張場合開始放鬆交談"}],"family":[{"word":"breakage","pos":"n.","meaning":"破損"},{"word":"breakable","pos":"adj.","meaning":"易碎的"},{"word":"broken","pos":"adj.","meaning":"壞掉的；破裂的"}],"usageNote":"不規則變化 break–broke–broken；break down 可指機器故障或情緒崩潰。","examples":[{"text":"To break the ice on the first day of camp, our teacher asked everyone to share a small personal story.","translationZh":"為打破營隊第一天的陌生氣氛，老師請每個人分享一個小小的個人故事。","source":"self-authored","grammar":"to break the ice 表目的；asked everyone to share 表活動安排。","writingTip":"以簡單分享活動說明如何減少初見的緊張。","topic":"營隊新朋友"},{"text":"Taking a short break after an hour of study helped me return to the task with greater patience and concentration.","translationZh":"讀書一小時後短暫休息，幫助我以更多耐心和專注回到任務上。","source":"self-authored","grammar":"taking 動名詞片語作主詞；after an hour of study 表時間。","writingTip":"描述短暫休息對耐心和專注的影響。","topic":"讀書與休息"}]},"capable":{"senses":[{"pos":"adj.","meaning":"有能力的；能勝任的","usage":"常接 of 加名詞或動名詞。"}],"collocations":[{"en":"be capable of solving problems","zh":"有能力解決問題","note":""},{"en":"a capable leader","zh":"能幹的領導者","note":""},{"en":"fully capable of","zh":"完全有能力……","note":""},{"en":"capable hands","zh":"可靠能幹的人手","note":"in capable hands 指交給可靠的人。"}],"synonyms":[{"en":"competent","zh":"勝任的","note":"強調達到工作所需的能力標準。"},{"en":"able","zh":"有能力的","note":"通常搭配 to V，句型不同。"}],"idioms":[],"family":[{"word":"capability","pos":"n.","meaning":"能力；功能"},{"word":"incapable","pos":"adj.","meaning":"無能力的"},{"word":"capably","pos":"adv.","meaning":"能幹地"}],"examples":[{"text":"Students are capable of making thoughtful decisions when adults provide clear information and opportunities for discussion.","translationZh":"大人若提供清楚的資訊與討論機會，學生就有能力作出周全的決定。","grammar":"capable of 後接動名詞，when 表條件情境。","writingTip":"可支持讓學生參與決策的主張。","topic":"教育與參與","source":"self-authored"},{"text":"Although she was young, the capable organizer managed a large event without overlooking the volunteers' needs.","translationZh":"雖然年紀輕，這位能幹的籌辦者仍妥善管理大型活動，沒有忽略志工的需求。","grammar":"although 表讓步，without 後接動名詞。","writingTip":"適合描述能力不受年齡限制。","topic":"領導與合作","source":"self-authored"}],"usageNote":"capable of doing 與 able to do 意義相近，但後接形式不同。"},"capacity":{"senses":[{"pos":"n.","meaning":"容量；容納量","usage":"設備或場所的上限"},{"pos":"n.","meaning":"能力","usage":"capacity to V 或 for + 名詞"}],"collocations":[{"en":"seating capacity","zh":"座位容量","note":"場地資訊"},{"en":"at full capacity","zh":"滿載運作","note":"介系詞片語"},{"en":"the capacity to learn","zh":"學習能力","note":"to 不定詞"},{"en":"increase storage capacity","zh":"增加儲存容量","note":"科技情境"}],"synonyms":[{"en":"ability","zh":"能力","note":"對應執行事情的能力"},{"en":"volume","zh":"容量","note":"對應容器可容納的量"}],"idioms":[],"family":[{"word":"capacious","pos":"adj.","meaning":"容量大的"}],"examples":[{"text":"The shelter reached full capacity after dozens of families lost their homes in the flood.","translationZh":"數十個家庭因洪水失去家園後，收容所達到滿額。","source":"self-authored","grammar":"reached full capacity 表達容量達到上限；after 子句交代收容所滿額之前發生的事。","writingTip":"寫災後安置需求時，可用收容所滿額呈現設施承受的壓力。","topic":"disaster"},{"text":"Young children have a remarkable capacity to learn languages through daily interaction with others.","translationZh":"幼兒有出色的能力，能透過日常互動學習語言。","source":"self-authored","grammar":"a capacity to learn 中 to learn 是不定詞片語，說明能力內容；through 引出學習方式。","writingTip":"討論兒童語言學習時，可把能力與日常互動相連。","topic":"education"}],"usageNote":"capacity 可指物理容量或潛在能力；at full capacity 表運作達到上限。"},"career":{"senses":[{"pos":"n.","meaning":"職涯；職業生涯","usage":"強調長期發展，不只是一份工作。"}],"collocations":[{"en":"pursue a career in","zh":"從事……領域的職涯","note":""},{"en":"career opportunities","zh":"職涯機會","note":""},{"en":"career goals","zh":"職涯目標","note":""},{"en":"a career change","zh":"職涯轉換","note":""}],"synonyms":[{"en":"profession","zh":"專業職業","note":"常涉及專門訓練，如醫師或律師。"},{"en":"occupation","zh":"職業","note":"指出目前從事的工作類型。"}],"idioms":[],"family":[{"word":"career-related","pos":"adj.","meaning":"與職涯相關的"}],"examples":[{"text":"Before choosing a career, students should explore their interests and learn what different jobs actually involve.","translationZh":"選擇職涯前，學生應探索興趣，了解各種工作實際包含哪些內容。","grammar":"before V-ing，what 引導名詞子句並作 involve 的受詞。","writingTip":"可寫職涯探索與選系。","topic":"職涯與教育","source":"self-authored"},{"text":"Her career change was difficult at first, but the new position gave her a stronger sense of purpose.","translationZh":"她轉換職涯的初期很辛苦，但新職位讓她更有目標感。","grammar":"at first 表最初，but 連接轉折結果。","writingTip":"適合描述改變選擇後的成長。","topic":"工作與成長","source":"self-authored"}],"usageNote":"career 指連續的職涯歷程；job 常指特定職位，兩者不可處處互換。"},"celebrate":{"senses":[{"pos":"vt.","meaning":"慶祝；頌揚","usage":"可接節日、成就或值得肯定的特質。"},{"pos":"vi.","meaning":"慶祝","usage":"可不帶受詞。"}],"collocations":[{"en":"celebrate a birthday","zh":"慶祝生日","note":""},{"en":"celebrate an achievement","zh":"慶祝成就","note":""},{"en":"celebrate cultural diversity","zh":"讚揚文化多樣性","note":""},{"en":"celebrate with friends","zh":"與朋友一同慶祝","note":""}],"synonyms":[{"en":"commemorate","zh":"紀念","note":"常較正式，未必歡樂，亦可紀念悲劇。"},{"en":"honor","zh":"表揚；致敬","note":"強調給予尊重或肯定。"}],"idioms":[],"family":[{"word":"celebration","pos":"n.","meaning":"慶祝；慶典"},{"word":"celebratory","pos":"adj.","meaning":"慶祝的"}],"examples":[{"text":"The community celebrated the library's reopening with a book exchange that brought residents of different ages together.","translationZh":"社區舉辦書籍交換，慶祝圖書館重新開放，讓不同年齡的居民聚在一起。","grammar":"celebrate A with B，that 引導活動的關係子句。","writingTip":"可描述公共空間促進社區互動。","topic":"閱讀與社區","source":"self-authored"},{"text":"Rather than celebrating only high scores, teachers can recognize students' persistence and willingness to help classmates.","translationZh":"老師不必只慶祝高分，也可以肯定學生的毅力與幫助同學的意願。","grammar":"rather than 後接動名詞，willingness to V 表意願內容。","writingTip":"適合討論多元評量與學習價值。","topic":"教育與價值","source":"self-authored"}],"usageNote":"celebrate 接事件或成就；為某人辦慶祝活動可寫 celebrate someone's birthday。"},"challenge":{"senses":[{"pos":"n.","meaning":"挑戰；難題；考驗","usage":"可數；a challenge for someone，指需要努力處理的情況。"},{"pos":"n.","meaning":"挑戰邀請；要求競賽或證明","usage":"a challenge to a game，指邀請或要求對方較量。"},{"pos":"n.","meaning":"質疑；異議","usage":"a challenge to a decision，對決定的正當性提出問題。"},{"pos":"n.","meaning":"盤問；要求表明身分","usage":"如 a guard's challenge，要求陌生人說明來意或身分；語氣較正式。"},{"pos":"vt.","meaning":"向……挑戰；要求……做某事","usage":"challenge someone to a contest／to prove a claim；to 後依結構接名詞或原形動詞。"},{"pos":"vt.","meaning":"質疑；對……表示異議","usage":"challenge an assumption／a decision，懷疑其正確性、效力或正當性。"},{"pos":"vt.","meaning":"考驗；激發……的能力","usage":"The task challenges students. 指任務要求學生運用能力。"},{"pos":"vt.","meaning":"盤問；要求證明資格或身分","usage":"The guard challenged the visitor. 依語境可指要求說明來意，並非邀請競賽。"},{"pos":"vi.","meaning":"提出挑戰或異議","usage":"對象已明確時可省略受詞；學習造句優先掌握 challenge a decision 等清楚表達。"}],"collocations":[{"en":"face a major challenge","zh":"面臨重大挑戰","note":"face 常見搭配"},{"en":"meet the challenge","zh":"迎接並應付挑戰","note":"meet 不只是遇見"},{"en":"challenge an assumption","zh":"質疑假設","note":"思辨語境"},{"en":"a challenging task","zh":"有挑戰性的任務","note":"形容詞形式"},{"en":"challenge someone to a chess match","zh":"向某人挑戰下棋","note":"to 後接競賽名詞。"},{"en":"challenge someone to prove a claim","zh":"要求某人證明主張","note":"to prove 為不定詞，說明要求做的事。"},{"en":"a legal challenge to a decision","zh":"對決定提出的法律異議","note":"challenge 為可數名詞。"},{"en":"challenge a visitor at the gate","zh":"在門口盤問訪客","note":"警衛要求表明身分或說明來意的語境。"}],"synonyms":[{"en":"difficulty","zh":"困難","note":"著重障礙"},{"en":"question","zh":"質疑","note":"只對應動詞的懷疑義"}],"idioms":[],"family":[{"word":"challenging","pos":"adj.","meaning":"具挑戰性的"},{"word":"challenger","pos":"n.","meaning":"挑戰者"}],"examples":[{"text":"Finding affordable housing remains a major challenge for young adults who work in large cities.","translationZh":"對在大城市工作的年輕人來說，找到負擔得起的住房仍是一大挑戰。","source":"self-authored","grammar":"V-ing 作主詞；who 修飾 adults","writingTip":"可用於社會現象分析。","topic":"housing"},{"text":"The experiment challenged our assumption that all plants grow better when given more water.","translationZh":"這個實驗質疑了我們原先認為所有植物澆水越多就長得越好的假設。","source":"self-authored","grammar":"challenged 直接接 our assumption；that all plants grow better 是解釋 assumption 內容的同位語子句；when given 省略 they are。","writingTip":"敘述實驗時，寫出原先假設，再呈現證據如何促使自己修正觀點。","topic":"science"}],"usageNote":"challenge 可指難題、競賽邀請、質疑或盤問；challenge someone to V 可含「要求證明／挑戰去做」之意。challenging 描述任務有難度，不等於單純否定對方；具體意思須依受詞與語境判斷。"},"charge":{"senses":[{"pos":"n.","meaning":"費用；收費","usage":"an admission charge / a service charge；free of charge = 免費。"},{"pos":"n.","meaning":"指控；控罪","usage":"a charge of theft / face criminal charges；法律指控不等於已被定罪。"},{"pos":"n.","meaning":"管理責任；照管","usage":"in charge of + 人或事 = 負責；in the charge of + 人 = 由該人負責。"},{"pos":"n.","meaning":"電荷；電量","usage":"an electric charge；a battery holds a charge 指電池可儲存電量。"},{"pos":"n.","meaning":"衝鋒；猛衝","usage":"a charge toward the enemy；在戰鬥或快速衝向某處的情境使用。"},{"pos":"vt./vi.","meaning":"收費；索價","usage":"charge someone an amount for something；charge for admission 也可省略付費者。"},{"pos":"vt.","meaning":"替……充電","usage":"charge a phone / a battery；the battery is charging 為正在充電。"},{"pos":"vt.","meaning":"正式指控；控告","usage":"charge someone with + 罪名／V-ing；with 後不是付費項目。"},{"pos":"vt.","meaning":"交付任務；使負責","usage":"charge someone with a task / doing something；正式用法，須由受詞判斷是委託還是指控。"},{"pos":"vi.","meaning":"衝向；衝鋒","usage":"charge at / toward someone；at 常指猛衝攻擊對象。"}],"collocations":[{"en":"charge a fee","zh":"收取費用","note":""},{"en":"charge a phone","zh":"替手機充電","note":""},{"en":"in charge of a team","zh":"負責一個團隊","note":""},{"en":"free of charge","zh":"免費","note":""},{"en":"charge someone for a service","zh":"向某人收取服務費","note":"for + 付費項目；可加入金額：charge someone ten dollars for a service。"},{"en":"charge someone with theft","zh":"指控某人竊盜","note":"with + 罪名；與 accuse someone of theft 的介系詞不同。"}],"synonyms":[{"en":"fee","zh":"費用","note":"fee 多指服務費"},{"en":"accuse","zh":"指控","note":"accuse A of B，charge A with B 是正式指控"}],"idioms":[],"family":[{"word":"charger","pos":"n.","meaning":"充電器"},{"word":"recharge","pos":"v.","meaning":"重新充電；恢復精力"},{"word":"rechargeable","pos":"adj.","meaning":"可充電的"}],"usageNote":"charge A for B 表向 A 收取 B 的費用；charge A with B 依 B 的內容表示正式指控或委託任務。in charge of 表主動負責；in the charge of 表交由某人負責。充電、收費與控告應分別依受詞及介系詞判義。","examples":[{"text":"The museum charges no admission fee for students, making it easier for young people to explore local history and culture.","translationZh":"博物館不向學生收取門票費，使年輕人更容易探索在地歷史與文化。","source":"self-authored","grammar":"charges no admission fee；making 補充免收費的結果。","writingTip":"可分析免費入場如何降低文化參與門檻。","topic":"文化資源"},{"text":"As the student in charge of equipment, I checked every microphone before the performance and kept extra batteries nearby.","translationZh":"身為負責器材的學生，我在表演前檢查每支麥克風，並把備用電池放在附近。","source":"self-authored","grammar":"in charge of + 器材；checked/kept 為並列過去式。","writingTip":"以器材檢查及備用物品描寫負責態度。","topic":"表演準備"}]},"clarify":{"senses":[{"pos":"vt.","meaning":"澄清；說明清楚","usage":"使意思、規則或問題更容易理解。"}],"collocations":[{"en":"clarify a misunderstanding","zh":"澄清誤解","note":""},{"en":"clarify the meaning of a term","zh":"說明某個詞的意思","note":""},{"en":"clarify the rules","zh":"說明清楚規則","note":""},{"en":"ask for clarification","zh":"請求進一步說明","note":"名詞搭配。"}],"synonyms":[{"en":"explain","zh":"解釋","note":"範圍較廣，不一定處理原有模糊處。"},{"en":"make clear","zh":"說清楚","note":"較日常，需依受詞調整句型。"}],"idioms":[],"family":[{"word":"clarification","pos":"n.","meaning":"澄清；說明"},{"word":"clarity","pos":"n.","meaning":"清楚；明確"},{"word":"clear","pos":"adj.","meaning":"清楚的"}],"usageNote":"clarify 直接接需要釐清的內容；explain something to someone 與 clarify something for someone 常見，句型不要混用。","examples":[{"text":"Before dividing the work, we clarified what each member was expected to contribute and when the first draft was due.","translationZh":"分工前，我們釐清每位成員應貢獻什麼，以及初稿何時到期。","grammar":"clarified 後接 what 與 when 兩個間接問句；be expected to V。","writingTip":"團隊經驗可交代分工內容及期限，避免只寫大家努力。","topic":"小組分工","source":"self-authored"},{"text":"A simple example helped clarify the difference between recycling a bottle and reducing the need to buy one.","translationZh":"一個簡單例子幫助說清楚回收瓶子與減少購買需求之間的差別。","grammar":"help + 原形 clarify；between 後並列兩個 V-ing 片語。","writingTip":"比較相近環保概念時，使用具體行動說明差異。","topic":"環境概念","source":"self-authored"}]},"climate":{"senses":[{"pos":"n.","meaning":"氣候","usage":"長期天候模式"},{"pos":"n.","meaning":"風氣；形勢","usage":"social 或 political climate"}],"collocations":[{"en":"climate change","zh":"氣候變遷","note":"長期變化"},{"en":"a mild climate","zh":"溫和的氣候","note":"氣候特性"},{"en":"the political climate","zh":"政治氛圍","note":"抽象義"},{"en":"a climate of trust","zh":"信任的風氣","note":"of 說明氣氛"}],"synonyms":[{"en":"weather patterns","zh":"天候模式","note":"長期模式才接近 climate"},{"en":"environment","zh":"環境；氛圍","note":"對應組織或社會情勢"}],"idioms":[],"family":[{"word":"climatic","pos":"adj.","meaning":"氣候的"}],"examples":[{"text":"Changes in the climate have forced some farmers to grow crops that tolerate hotter conditions.","translationZh":"氣候的變化迫使一些農民改種能耐高溫的作物。","source":"self-authored","grammar":"force 人 to V；that 修飾 crops","writingTip":"說明氣候影響時加入調適行動。","topic":"agriculture"},{"text":"A climate of trust allows students to admit mistakes and ask for help without embarrassment.","translationZh":"信任的氛圍讓學生能坦承錯誤，並自在地尋求協助。","source":"self-authored","grammar":"A climate of trust 為主詞；allows students to admit 使用 allow + 人 + to V；admit 與 ask 共用 to。","writingTip":"寫理想班級時，說明信任如何讓學生敢於承認錯誤並求助。","topic":"education"}],"usageNote":"weather 指短期天氣；climate 指長期氣候，也可比喻社會風氣。"},"collaboration":{"senses":[{"pos":"n.","meaning":"合作；協作","usage":"常接 with + 夥伴或 between + 雙方。"}],"collocations":[{"en":"in collaboration with local artists","zh":"與當地藝術家合作","note":""},{"en":"close collaboration between schools","zh":"學校間的密切合作","note":""},{"en":"a collaborative project","zh":"合作專題","note":"形容詞搭配。"},{"en":"encourage collaboration","zh":"鼓勵合作","note":""}],"synonyms":[{"en":"cooperation","zh":"合作；配合","note":"可只是配合要求，collaboration 常含共同投入工作。"},{"en":"teamwork","zh":"團隊合作","note":"著重團隊成員協調，通常不可數。"}],"idioms":[],"family":[{"word":"collaborate","pos":"vi.","meaning":"合作"},{"word":"collaborative","pos":"adj.","meaning":"合作的"},{"word":"collaborator","pos":"n.","meaning":"合作者"}],"usageNote":"collaborate with someone on a project；collaboration 常不可數，也可指一項合作案。避免把合作等同每人各做一段而不交流。","examples":[{"text":"The exhibition was created in collaboration with local residents, whose photographs showed how the neighborhood had changed over time.","translationZh":"展覽與當地居民合作製作，他們的照片呈現社區隨時間的變化。","grammar":"in collaboration with 表合作對象；whose 表居民所擁有的照片。","writingTip":"用參與者提供的具體材料呈現社區合作。","topic":"地方記憶","source":"self-authored"},{"text":"Successful collaboration requires more than dividing tasks; team members also need to listen carefully and discuss disagreements openly.","translationZh":"成功合作不只需要分工；團隊成員也須仔細聆聽並坦誠討論分歧。","grammar":"more than + V-ing 表不只是；listen 與 discuss 為並列動詞。","writingTip":"論述合作時補上溝通與處理分歧的行動。","topic":"團隊溝通","source":"self-authored"}]},"combine":{"senses":[{"pos":"vt./vi.","meaning":"結合；合併","usage":"combine A with B 或 combine A and B。"}],"collocations":[{"en":"combine theory with practice","zh":"結合理論與實踐","note":""},{"en":"combine efforts","zh":"共同努力","note":""},{"en":"combine two methods","zh":"結合兩種方法","note":""},{"en":"a combination of factors","zh":"多項因素的結合","note":"名詞搭配。"}],"synonyms":[{"en":"join","zh":"連結；加入","note":"範圍較廣，不一定形成一個整體。"},{"en":"merge","zh":"合併","note":"常指組織或部分融成一體，程度可能更強。"}],"idioms":[],"family":[{"word":"combination","pos":"n.","meaning":"組合；結合"},{"word":"combined","pos":"adj.","meaning":"結合的；共同的"}],"usageNote":"combine A with B；combined efforts 指共同努力。結合方法需說明各自用途，不能只假設加得越多越有效。","examples":[{"text":"Our project combined interviews with old photographs to show how a railway station had shaped the town.","translationZh":"我們的專題結合訪談與老照片，呈現一座車站如何影響城鎮。","grammar":"combine A with B；to show 表資料整合的目的。","writingTip":"文化專題可交代不同材料如何互相補充。","topic":"地方研究","source":"self-authored"},{"text":"By combining short walks with regular breaks, I found a daily routine that felt easier to maintain during exam preparation.","translationZh":"透過結合短程散步與規律休息，我找到備考期間較容易維持的日常安排。","grammar":"By combining 表方法；that felt easier 修飾 routine。","writingTip":"以個人經驗說明調整日常，不把感受當成普遍研究結論。","topic":"備考生活","source":"self-authored"}]},"comfort":{"senses":[{"pos":"n.","meaning":"安慰；舒適","usage":""},{"pos":"v.","meaning":"安慰","usage":""}],"collocations":[{"en":"offer comfort to someone","zh":"給予某人安慰","note":""},{"en":"take comfort in something","zh":"從某事得到安慰","note":""},{"en":"comfort a frightened child","zh":"安慰受驚的孩子","note":""},{"en":"the comfort of home","zh":"家的舒適感","note":""}],"synonyms":[{"en":"console","zh":"安慰","note":"常用於失落或悲傷"},{"en":"ease","zh":"緩解","note":"ease pain/anxiety 表示減輕不適"}],"idioms":[],"family":[{"word":"comfortable","pos":"adj.","meaning":"舒適的；自在的"},{"word":"comfortably","pos":"adv.","meaning":"舒適地"},{"word":"comforting","pos":"adj.","meaning":"令人寬慰的"}],"usageNote":"comfort 可以是心情慰藉或身體舒適；comfortable 描述感受或環境，comforting 描述帶來安慰的人事物。","examples":[{"text":"After I failed the audition, my sister offered comfort and reminded me that one result could not define my ability.","translationZh":"試鏡失敗後，姊姊安慰我，提醒我一次結果不能定義我的能力。","source":"self-authored","grammar":"after 引導時間；reminded me that 接提醒內容。","writingTip":"把具體提醒寫成安慰他人的方式。","topic":"挫折與安慰"},{"text":"Even a short call from an old friend can bring comfort to someone spending the holidays far away from home.","translationZh":"對遠離家鄉過節的人而言，老朋友一通短短的電話也能帶來安慰。","source":"self-authored","grammar":"spending 修飾 someone；far away from home 交代對象處境。","writingTip":"說明簡單聯繫如何改善離家的情緒。","topic":"離家過節"}]},"commitment":{"senses":[{"pos":"n.","meaning":"承諾；投入","usage":"commitment to + 名詞／V-ing。"},{"pos":"n.","meaning":"必須履行的事務","usage":"可數，常用複數 commitments。"}],"collocations":[{"en":"make a commitment","zh":"作出承諾","note":""},{"en":"show commitment to a goal","zh":"展現對目標的投入","note":""},{"en":"family commitments","zh":"家庭責任與事務","note":""},{"en":"a long-term commitment","zh":"長期承諾","note":""}],"synonyms":[{"en":"dedication","zh":"奉獻；投入","note":"強調持續付出的精神。"},{"en":"promise","zh":"承諾","note":"未必涉及長期投入，也不涵蓋已安排的事務義。"}],"idioms":[],"family":[{"word":"commit","pos":"vt./vi.","meaning":"承諾；投入；犯下"},{"word":"committed","pos":"adj.","meaning":"盡心盡力的；已承諾的"}],"usageNote":"commit oneself to doing；commitment to learning 中的 to 是介系詞。commit a crime 為另一動詞義，不是承諾犯罪。","examples":[{"text":"Her commitment to helping younger students continued even after the tutoring project was no longer part of her schoolwork.","translationZh":"即使課業已不再要求參與課輔計畫，她仍持續投入協助年幼學生。","grammar":"commitment to + V-ing；even after 表事情結束後仍持續。","writingTip":"以超出課業要求的行動表現長期投入。","topic":"服務與責任","source":"self-authored"},{"text":"Because of family commitments, I could not attend every meeting, but I completed my share of the work at home.","translationZh":"因為家庭事務，我無法每次都出席會議，但會在家完成自己負責的工作。","grammar":"Because of 接名詞；my share of 指自己應負責的部分。","writingTip":"交代參與限制，同時說明履行責任的替代方式。","topic":"時間分配","source":"self-authored"}]},"companionship":{"senses":[{"pos":"n.","meaning":"陪伴；有人相伴的情誼","usage":""}],"collocations":[{"en":"provide companionship","zh":"提供陪伴","note":""},{"en":"seek companionship","zh":"尋求陪伴","note":""},{"en":"human companionship","zh":"人際陪伴","note":""},{"en":"a source of companionship","zh":"陪伴的來源","note":""}],"synonyms":[{"en":"company","zh":"陪伴","note":"company 在此為不可數名詞，也另有公司義"},{"en":"friendship","zh":"友誼","note":"friendship 強調關係，companionship 強調相伴"}],"idioms":[],"family":[{"word":"companion","pos":"n.","meaning":"同伴；伴侶"},{"word":"companionable","pos":"adj.","meaning":"友善且適合相伴的"}],"usageNote":"通常不可數；寵物能提供陪伴，但飼養也涉及長期責任與費用。","examples":[{"text":"For older adults who live alone, a pet may provide companionship and a reason to keep a regular daily routine.","translationZh":"對獨居長者而言，寵物可能提供陪伴，也給他們維持規律作息的理由。","source":"self-authored","grammar":"who live alone 修飾 older adults；may provide 表示可能的益處。","writingTip":"討論寵物陪伴時，同時說明它如何影響日常生活。","topic":"獨居長者"},{"text":"Although online messages help us stay connected, they cannot always replace the comfort of face-to-face companionship during difficult times.","translationZh":"雖然網路訊息有助我們保持聯繫，卻不一定能取代困難時期面對面陪伴帶來的慰藉。","source":"self-authored","grammar":"although 引導讓步；cannot always 表示並非總能取代。","writingTip":"肯定科技聯繫的用途，再說明面對面陪伴的作用。","topic":"線上與實體交流"}]},"compare":{"senses":[{"pos":"vt./vi.","meaning":"比較；比擬","usage":"compare A with B 常指比較；compare A to B 也可比喻兩者相似。"}],"collocations":[{"en":"compare prices","zh":"比較價格","note":""},{"en":"compare one method with another","zh":"比較兩種方法","note":""},{"en":"compared with last year","zh":"與去年相比","note":""},{"en":"beyond compare","zh":"無與倫比","note":"固定片語，語氣較強。"}],"synonyms":[{"en":"contrast","zh":"對照差異","note":"特別強調不同之處，compare 可談相同與不同。"},{"en":"liken","zh":"比作","note":"liken A to B 只對應比擬義。"}],"idioms":[],"family":[{"word":"comparison","pos":"n.","meaning":"比較"},{"word":"comparable","pos":"adj.","meaning":"可比較的；相近的"},{"word":"comparatively","pos":"adv.","meaning":"相對而言"}],"usageNote":"compare with 和 compare to 在比較義上均可使用；比喻某物像另一物時常用 compare to。比較數據應確認單位與範圍一致。","examples":[{"text":"Before buying a bicycle, I compared prices and checked whether each model was suitable for my daily route.","translationZh":"買自行車前，我比較價格，也檢查各款是否適合每天行經的路線。","grammar":"Before buying 省略相同主詞；whether 引導檢查內容。","writingTip":"比較選項時加入用途，避免只看價格。","topic":"消費決策","source":"self-authored"},{"text":"Compared with last year, more students walked to school, although the survey did not explain why their habits had changed.","translationZh":"與去年相比，更多學生步行上學，但調查未說明習慣改變的原因。","grammar":"Compared with 為分詞片語；although 保留調查的限制。","writingTip":"圖表作文分開寫觀察到的變化與尚未證實的原因。","topic":"交通圖表","source":"self-authored"}]},"compensate":{"senses":[{"pos":"vt.","meaning":"賠償；補償某人","usage":"compensate someone for a loss。"},{"pos":"vi.","meaning":"彌補","usage":"compensate for a disadvantage。"}],"collocations":[{"en":"compensate workers for lost wages","zh":"補償工人損失的薪資","note":""},{"en":"compensate for a lack of experience","zh":"彌補經驗不足","note":""},{"en":"receive compensation","zh":"獲得賠償","note":""},{"en":"adequate compensation for damage","zh":"足以彌補損害的賠償","note":""}],"synonyms":[{"en":"make up for","zh":"彌補","note":"較口語，對應不足或損失，不必付錢。"},{"en":"reimburse","zh":"償還費用","note":"通常歸還已支出的款項，範圍較窄。"}],"idioms":[],"family":[{"word":"compensation","pos":"n.","meaning":"補償；賠償"},{"word":"compensatory","pos":"adj.","meaning":"補償性的"}],"usageNote":"compensate someone for something；compensate for something。付出補償不一定能完全消除損害。","examples":[{"text":"The airline offered to compensate passengers for the extra transport costs caused by the canceled flight.","translationZh":"航空公司提出補償旅客因航班取消而額外支出的交通費。","grammar":"compensate + 人 + for + 損失；caused by 修飾 costs。","writingTip":"描述服務中斷時，明確交代補償涵蓋的費用。","topic":"交通與消費","source":"self-authored"},{"text":"Careful preparation helped compensate for my lack of experience when I guided visitors through the community exhibition.","translationZh":"帶領訪客參觀社區展覽時，充分準備幫助我彌補經驗不足。","grammar":"helped + 原形；compensate for + 不足之處。","writingTip":"個人成長作文可寫出如何以準備補足弱點。","topic":"導覽經驗","source":"self-authored"}]},"complex":{"senses":[{"pos":"adj.","meaning":"複雜的","usage":"包含多個彼此關聯的部分。"},{"pos":"n.","meaning":"綜合建築群","usage":"如 sports complex。"},{"pos":"n.","meaning":"情結","usage":"常見於 inferiority complex 等固定搭配。"}],"collocations":[{"en":"a complex problem","zh":"複雜的問題","note":""},{"en":"a complex relationship","zh":"複雜的關係","note":""},{"en":"a sports complex","zh":"綜合運動中心","note":"名詞義。"},{"en":"an inferiority complex","zh":"自卑情結","note":"不是所有缺乏自信都宜如此稱呼。"}],"synonyms":[{"en":"complicated","zh":"複雜的","note":"常強調難以處理或理解。"},{"en":"intricate","zh":"錯綜細密的","note":"常形容具有許多細節的結構或設計。"}],"idioms":[],"family":[{"word":"complexity","pos":"n.","meaning":"複雜性"},{"word":"complexities","pos":"n. pl.","meaning":"複雜之處"}],"usageNote":"complex 可作形容詞或名詞；a complex problem 是問題，a sports complex 是建築設施，須看名詞組結構。","examples":[{"text":"A simple slogan cannot explain a complex problem involving housing costs, transport options, and the needs of different families.","translationZh":"一句簡單標語無法解釋涉及房價、交通選擇與不同家庭需求的複雜問題。","grammar":"involving 為分詞修飾 problem；三個名詞組並列。","writingTip":"公共議題寫作可列出問題涉及的多項因素。","topic":"居住議題","source":"self-authored"},{"text":"The new sports complex provides an indoor pool and courts that residents can use even during heavy rain.","translationZh":"新的綜合運動中心提供室內游泳池與球場，居民大雨時也能使用。","grammar":"complex 為主詞中的名詞；that 引導限定關係子句。","writingTip":"介紹設施時把內容連結居民實際使用的情境。","topic":"公共空間","source":"self-authored"}]},"concentrate":{"senses":[{"pos":"vi.","meaning":"專注","usage":"concentrate on + 名詞／V-ing。"},{"pos":"vt.","meaning":"集中；使濃縮","usage":"concentrate efforts；concentrate a liquid。"},{"pos":"n.","meaning":"濃縮物","usage":"如果汁濃縮液。"}],"collocations":[{"en":"concentrate on a task","zh":"專注於任務","note":""},{"en":"concentrate efforts on improving safety","zh":"集中力量改善安全","note":""},{"en":"a high concentration of salt","zh":"高濃度的鹽","note":"名詞濃度義。"},{"en":"juice made from concentrate","zh":"以濃縮液製成的果汁","note":"名詞義。"}],"synonyms":[{"en":"focus","zh":"專注；集中","note":"focus on 常可對應專注義。"},{"en":"condense","zh":"濃縮；精簡","note":"只對應某些濃縮或縮減語境，不等於專心。"}],"idioms":[],"family":[{"word":"concentration","pos":"n.","meaning":"專注；集中；濃度"},{"word":"concentrated","pos":"adj.","meaning":"集中的；濃縮的"}],"usageNote":"concentrate on studying 的 on 是介系詞；concentration 也可指物質濃度或人口集中，不只指注意力。","examples":[{"text":"I turned off notifications so that I could concentrate on understanding the article before discussing it with my classmates.","translationZh":"我關閉通知，先專心理解文章，再與同學討論。","grammar":"so that 表目的；concentrate on + V-ing。","writingTip":"用可觀察的環境調整說明如何減少干擾。","topic":"專注學習","source":"self-authored"},{"text":"The volunteers concentrated their efforts on clearing blocked drains before the next storm was expected to reach the village.","translationZh":"志工集中力量清理堵塞水溝，趕在下一場暴風雨預期抵達村莊之前完成。","grammar":"concentrate efforts on + V-ing；was expected to V 為被動。","writingTip":"災害準備作文交代有限人力優先投入何處。","topic":"社區防災","source":"self-authored"}]},"concern":{"senses":[{"pos":"n.","meaning":"擔憂；關注的事","usage":""},{"pos":"v.","meaning":"使擔心；與……有關","usage":""}],"collocations":[{"en":"raise concerns about safety","zh":"提出安全方面的憂慮","note":""},{"en":"express concern for others","zh":"表達對他人的關心","note":""},{"en":"be concerned about the future","zh":"擔心未來","note":""},{"en":"as far as I am concerned","zh":"就我而言","note":""}],"synonyms":[{"en":"worry","zh":"擔心","note":"worry 多指情緒"},{"en":"issue","zh":"議題","note":"a concern 可是需要重視的問題"}],"idioms":[],"family":[{"word":"concerned","pos":"adj.","meaning":"擔心的；相關的"},{"word":"concerning","pos":"prep.","meaning":"關於"}],"usageNote":"be concerned about 表示擔心；be concerned with 表示涉及或關注某議題。","examples":[{"text":"Parents raised concerns about the new traffic plan because the proposed bus stop was too close to the school entrance.","translationZh":"家長對新交通計畫提出憂慮，因為提議的公車站離校門太近。","source":"self-authored","grammar":"raised concerns about + 問題；because 解釋擔憂來源。","writingTip":"用公車站距離說明家長擔憂的具體原因。","topic":"交通安全"},{"text":"As far as I am concerned, keeping a pet should begin with an honest discussion about who will provide daily care.","translationZh":"就我而言，飼養寵物應從坦誠討論由誰提供日常照護開始。","source":"self-authored","grammar":"as far as I am concerned 表個人立場；about who will provide 接討論內容。","writingTip":"以照護分工提出對飼養寵物的個人看法。","topic":"家庭養寵物"}]},"conduct":{"senses":[{"pos":"v.","meaning":"進行；指揮","usage":""},{"pos":"n.","meaning":"行為；操守","usage":""}],"collocations":[{"en":"conduct a survey","zh":"進行調查","note":""},{"en":"conduct an experiment","zh":"進行實驗","note":""},{"en":"conduct an orchestra","zh":"指揮管弦樂團","note":""},{"en":"a code of conduct","zh":"行為準則","note":""}],"synonyms":[{"en":"carry out","zh":"執行","note":"carry out a study 可替換 conduct"},{"en":"behavior","zh":"行為","note":"conduct 名詞較正式，常帶規範意味"}],"idioms":[],"family":[{"word":"conductor","pos":"n.","meaning":"指揮家；導體"},{"word":"conductive","pos":"adj.","meaning":"導電或導熱的"},{"word":"conductivity","pos":"n.","meaning":"導電或導熱性"}],"usageNote":"名詞重音常在首音節，動詞常在第二音節；conduct a survey 不是「帶領」調查的泛譯。","examples":[{"text":"Our class conducted a survey to find out why some students preferred printed books while others chose to read on screens.","translationZh":"我們班進行調查，了解有些學生偏好紙本書、其他人卻選擇螢幕閱讀的原因。","source":"self-authored","grammar":"conducted a survey；why 引導調查問題，while 對照兩類學生。","writingTip":"交代調查目的與比較的閱讀偏好。","topic":"閱讀調查"},{"text":"A clear code of conduct can help volunteers understand their responsibilities when working with children at a community center.","translationZh":"清楚的行為準則，能幫助志工了解在社區中心與兒童相處時的責任。","source":"self-authored","grammar":"when working 為省略主詞的時間子句，主詞指 volunteers。","writingTip":"可說明清楚規範如何保護服務對象。","topic":"志工規範"}]},"confidence":{"senses":[{"pos":"n.","meaning":"信心；信任","usage":"in 指信任對象，to V 常表做事的信心。"}],"collocations":[{"en":"have confidence in","zh":"信任……","note":""},{"en":"build confidence","zh":"建立信心","note":""},{"en":"lose confidence","zh":"失去信心","note":""},{"en":"the confidence to speak up","zh":"開口表達的信心","note":""}],"synonyms":[{"en":"self-assurance","zh":"自信","note":"著重沉著相信自身能力。"},{"en":"trust","zh":"信任","note":"通常針對人、資訊或制度的可靠性。"}],"idioms":[{"en":"in confidence","zh":"私下保密地","note":"指信任對方會保密，不指自信。"}],"family":[{"word":"confident","pos":"adj.","meaning":"有信心的"},{"word":"confidently","pos":"adv.","meaning":"有信心地"}],"examples":[{"text":"Practicing with a small audience gradually gave me the confidence to speak in front of the entire class.","translationZh":"先對少數聽眾練習，逐漸給了我站在全班面前說話的信心。","grammar":"動名詞片語作主詞，confidence to V 表具體行動。","writingTip":"可寫循序漸進克服恐懼。","topic":"學習與表達","source":"self-authored"},{"text":"Public confidence in local government may decline when officials fail to explain how decisions are made.","translationZh":"當官員未能解釋決策過程時，民眾對地方政府的信任可能下降。","grammar":"confidence in，how decisions are made 為被動名詞子句。","writingTip":"適合分析透明度與公共信任。","topic":"公共議題","source":"self-authored"}],"usageNote":"confident 表有信心，confidential 表機密；兩者不是同一個形容詞。"},"confirm":{"senses":[{"pos":"vt.","meaning":"確認；證實","usage":"可接安排、身分或 that 子句。"},{"pos":"vt.","meaning":"堅定；使更確信","usage":"confirm a belief。"}],"collocations":[{"en":"confirm a reservation","zh":"確認預訂","note":""},{"en":"confirm someone's identity","zh":"確認某人的身分","note":""},{"en":"confirm that a report is accurate","zh":"證實報導正確","note":""},{"en":"receive written confirmation","zh":"收到書面確認","note":"名詞搭配。"}],"synonyms":[{"en":"verify","zh":"核實","note":"強調查核真實性或準確性。"},{"en":"corroborate","zh":"佐證","note":"較正式，指以獨立證據支持說法，未必完全證實。"}],"idioms":[],"family":[{"word":"confirmation","pos":"n.","meaning":"確認；證實"},{"word":"confirmed","pos":"adj.","meaning":"已確認的"},{"word":"unconfirmed","pos":"adj.","meaning":"尚未證實的"}],"usageNote":"confirm a booking 可指確認安排；confirm a claim 則涉及證據。傳聞反覆出現不等於獲得確認。","examples":[{"text":"Before leaving home, we called the museum to confirm that the workshop would still take place despite the storm warning.","translationZh":"出門前，我們打電話向博物館確認，暴風雨警報發布後工作坊是否仍會舉行。","grammar":"to confirm 表致電目的；that 子句說明確認的內容。","writingTip":"行程作文可寫出出發前如何確認突發狀況。","topic":"活動確認","source":"self-authored"},{"text":"The second interview helped confirm several details, but the reporter still needed evidence for the article's central claim.","translationZh":"第二次訪談幫助確認數項細節，但記者仍需要支持文章核心主張的證據。","grammar":"help + 原形 confirm；but 區分已確認與仍待查證的部分。","writingTip":"媒體識讀作文區分局部資訊與整體主張。","topic":"新聞查核","source":"self-authored"}]},"conflict":{"senses":[{"pos":"n.","meaning":"衝突；矛盾","usage":"可指人際爭執、價值矛盾或武裝衝突。"},{"pos":"vi.","meaning":"相衝突","usage":"常搭配 with。"}],"collocations":[{"en":"resolve a conflict","zh":"化解衝突","note":""},{"en":"a conflict of interest","zh":"利益衝突","note":""},{"en":"come into conflict with","zh":"與……發生衝突","note":""},{"en":"conflict with one's values","zh":"與個人價值觀抵觸","note":""}],"synonyms":[{"en":"disagreement","zh":"意見不合","note":"可能比 conflict 程度輕，未必造成持續對立。"},{"en":"clash","zh":"衝突","note":"常強調直接碰撞或明顯不相容。"}],"idioms":[],"family":[{"word":"conflicting","pos":"adj.","meaning":"互相矛盾的"},{"word":"conflicted","pos":"adj.","meaning":"內心矛盾的"}],"examples":[{"text":"Listening carefully to both sides helped us resolve the conflict before it damaged our friendship.","translationZh":"仔細聆聽雙方意見，幫助我們在衝突傷害友誼之前將它化解。","grammar":"動名詞片語作主詞，before 引導時間子句。","writingTip":"可寫衝突處理與溝通技巧。","topic":"人際與溝通","source":"self-authored"},{"text":"The proposed road conflicts with residents' desire to preserve the quiet character of their neighborhood.","translationZh":"這條擬建道路，與居民希望保留社區寧靜特色的願望相抵觸。","grammar":"conflict with，desire to V 說明願望內容。","writingTip":"適合討論公共建設與在地需求。","topic":"社區與建設","source":"self-authored"}],"usageNote":"名詞 conflict 重音在首音節，動詞重音通常在後音節；介系詞 with 常見於動詞用法。"},"consequence":{"senses":[{"pos":"n.","meaning":"結果；後果","usage":"常指不利結果，也可中性"}],"collocations":[{"en":"face the consequences","zh":"面對後果","note":"常搭配 of"},{"en":"as a consequence of pollution","zh":"由於污染","note":"表原因"},{"en":"unintended consequences","zh":"非預期的後果","note":"政策分析"},{"en":"long-term consequences","zh":"長期後果","note":"形容影響持續時間"}],"synonyms":[{"en":"result","zh":"結果","note":"較中性且範圍廣"},{"en":"outcome","zh":"結果","note":"著重事件的最後狀態"}],"idioms":[{"en":"pay the price","zh":"付出代價","note":"對應承受負面後果，不能用於中性的結果。"}],"family":[{"word":"consequent","pos":"adj.","meaning":"隨之發生的"},{"word":"consequently","pos":"adv.","meaning":"因此"}],"examples":[{"text":"One unintended consequence of the new road was the loss of valuable wildlife habitats.","translationZh":"新道路的一個非預期後果，是珍貴野生動物棲地的流失。","source":"self-authored","grammar":"One unintended consequence of the new road 是主詞；was 後的名詞片語 the loss... 為主詞補語。","writingTip":"評估建設時，可補充棲地流失這类非預期的間接代價。","topic":"environment"},{"text":"As a consequence of repeated flooding, many residents decided to move to higher ground.","translationZh":"由於反覆淹水，許多居民決定搬到地勢較高的地方。","source":"self-authored","grammar":"as a consequence of + 名詞","writingTip":"描述因果時搭配具體後續行動。","topic":"disaster"}],"usageNote":"consequence 常帶負面意味，但並非只能指壞結果；注意 consequence 與 consequently 的詞性。"},"conserve":{"senses":[{"pos":"vt.","meaning":"節約；保護保存","usage":"資源、能源或自然環境"}],"collocations":[{"en":"conserve energy","zh":"節省能源","note":"能源用量"},{"en":"conserve water","zh":"節約用水","note":"生活措施"},{"en":"conserve natural resources","zh":"保護自然資源","note":"資源管理"},{"en":"conserve wildlife habitats","zh":"保護野生動物棲地","note":"保育語境"}],"synonyms":[{"en":"save","zh":"節省","note":"對應避免浪費資源"},{"en":"preserve","zh":"保存；保護","note":"著重維持原有狀態"}],"idioms":[],"family":[{"word":"conservation","pos":"n.","meaning":"保護；節約"},{"word":"conservationist","pos":"n.","meaning":"保育人士"}],"examples":[{"text":"Turning off unused lights is a simple way to conserve energy at home.","translationZh":"關掉未使用的燈，是在家節省能源的簡單方法。","source":"self-authored","grammar":"Turning off unused lights 是 V-ing 片語作主詞；a way to conserve 中不定詞說明方法用途。","writingTip":"環保倡議可從關掉未使用的燈等可立即實行的小事切入。","topic":"energy"},{"text":"Local volunteers work with farmers to conserve wetlands that provide shelter for migratory birds.","translationZh":"地方志工與農民合作，保護為候鳥提供棲身處的濕地。","source":"self-authored","grammar":"work with farmers to conserve 中 with 指合作對象、to conserve 表目的；that provide 修飾 wetlands。","writingTip":"描述保育合作時，交代參與者及濕地對候鳥的功能。","topic":"wildlife"}],"usageNote":"conserve 包含避免消耗及保護；conservation 才是名詞。"},"consistent":{"senses":[{"pos":"adj.","meaning":"一致的；相符的","usage":"consistent with + 證據或原則。"},{"pos":"adj.","meaning":"穩定持續的","usage":"形容表現、做法或品質。"}],"collocations":[{"en":"consistent with the evidence","zh":"與證據相符","note":""},{"en":"consistent effort","zh":"持續穩定的努力","note":""},{"en":"maintain consistent standards","zh":"維持一致標準","note":""},{"en":"be consistent in applying the rules","zh":"一貫地執行規則","note":""}],"synonyms":[{"en":"steady","zh":"穩定的","note":"對應持續或不突然變動的意思。"},{"en":"compatible","zh":"相容的","note":"指可以共存或配合，不一定表示長期一致。"}],"idioms":[],"family":[{"word":"consistency","pos":"n.","meaning":"一致性；穩定性"},{"word":"consistently","pos":"adv.","meaning":"一貫地；持續地"},{"word":"inconsistent","pos":"adj.","meaning":"不一致的"}],"usageNote":"consistent with 表相符；consistent in 表在某方面一貫。consistent 不等於 constant：穩定努力仍可包含休息。","examples":[{"text":"The witness gave an account consistent with the camera footage, although some details remained too unclear to explain.","translationZh":"目擊者的敘述與監視器畫面相符，但某些細節仍不清楚，無法解釋。","grammar":"consistent with 後置修飾 account；too + 形容詞 + to V。","writingTip":"證據寫作可承認吻合之處，同時保留不確定細節。","topic":"事件查證","source":"self-authored"},{"text":"Consistent practice helped me speak with greater confidence, even though my progress from one week to the next was uneven.","translationZh":"持續練習幫助我更有信心開口，儘管每週進步的幅度並不一致。","grammar":"even though 引導讓步；from one week to the next 表週與週之間。","writingTip":"成長敘事可承認進步並非每次都看得見。","topic":"口說練習","source":"self-authored"}]},"construct":{"senses":[{"pos":"vt.","meaning":"建造；建構","usage":"可指實體建築、論證或解釋。"},{"pos":"n.","meaning":"建構的概念","usage":"研究語境，如 a theoretical construct。"}],"collocations":[{"en":"construct a bridge","zh":"建橋","note":""},{"en":"construct an argument","zh":"建立論證","note":""},{"en":"construct a model","zh":"建構模型","note":""},{"en":"a theoretical construct","zh":"理論建構的概念","note":"名詞義，較正式。"}],"synonyms":[{"en":"build","zh":"建造；建立","note":"較日常，適用範圍廣。"},{"en":"formulate","zh":"擬定；表述","note":"常接理論、計畫或說法，不指蓋實體建築。"}],"idioms":[],"family":[{"word":"construction","pos":"n.","meaning":"建造；結構"},{"word":"constructive","pos":"adj.","meaning":"有建設性的"},{"word":"reconstruct","pos":"vt.","meaning":"重建；重現"}],"usageNote":"construct a sentence 是組織句子；constructive criticism 是有助改進的批評，不是「建築式批評」。","examples":[{"text":"Students constructed a small bridge from recycled materials and tested how much weight it could safely support.","translationZh":"學生用回收材料製作小橋，並測試它能安全承受多少重量。","grammar":"construct A from B；how much 引導測試的內容。","writingTip":"實作經驗可交代材料、作品與驗證方式。","topic":"科學實作","source":"self-authored"},{"text":"To construct a convincing argument, writers need clear reasons and evidence that directly supports the point they want to make.","translationZh":"要建立有說服力的論證，作者需要清楚理由，以及直接支持其主張的證據。","grammar":"To construct 表目的；that supports 修飾 evidence。","writingTip":"作文可用理由與證據的關聯檢查段落是否完整。","topic":"議論寫作","source":"self-authored"}]},"consumption":{"senses":[{"pos":"n.","meaning":"消耗量；消費","usage":"能源、食物及商品的使用"}],"collocations":[{"en":"energy consumption","zh":"能源消耗","note":"常見環境用語"},{"en":"water consumption","zh":"用水量","note":"計量語境"},{"en":"reduce sugar consumption","zh":"減少糖的攝取","note":"健康主題"},{"en":"patterns of consumption","zh":"消費模式","note":"社會分析"}],"synonyms":[{"en":"use","zh":"使用量","note":"較日常，常接資源"},{"en":"intake","zh":"攝取量","note":"適用食物與營養，不能泛指商品消費"}],"idioms":[],"family":[{"word":"consume","pos":"vt.","meaning":"消耗；食用"},{"word":"consumer","pos":"n.","meaning":"消費者"},{"word":"consumable","pos":"adj./n.","meaning":"可消耗的；消耗品"}],"examples":[{"text":"The school reduced its water consumption by collecting rainwater for cleaning outdoor areas.","translationZh":"學校收集雨水來清潔戶外區域，降低了用水量。","source":"self-authored","grammar":"reduce + 名詞；by + V-ing","writingTip":"可寫節水措施與其用途。","topic":"environment"},{"text":"A rise in online shopping has changed patterns of consumption among young people.","translationZh":"網路購物的增加，改變了年輕人的消費模式。","source":"self-authored","grammar":"A rise in online shopping 為單數主詞，搭配 has changed；patterns of consumption 是受詞。","writingTip":"描述消費趨勢時，可先點出網購增加，再說明消費模式改變。","topic":"consumer behavior"}],"usageNote":"consumption 通常不可數；談健康時可搭配 sugar、salt，談環境時搭配 energy、water。"},"content":{"senses":[{"pos":"n.","meaning":"內容；所含成分","usage":""},{"pos":"adj.","meaning":"滿足的","usage":""},{"pos":"v.","meaning":"使滿足","usage":""}],"collocations":[{"en":"the content of a report","zh":"報告的內容","note":""},{"en":"online content","zh":"網路內容","note":""},{"en":"sugar content","zh":"含糖量","note":""},{"en":"be content with the result","zh":"對結果感到滿足","note":""}],"synonyms":[{"en":"material","zh":"內容材料","note":"常指供閱讀或學習的內容"},{"en":"satisfied","zh":"滿意的","note":"對應形容詞 content，不是名詞內容義"}],"idioms":[],"family":[{"word":"contentment","pos":"n.","meaning":"滿足"},{"word":"contents","pos":"n.","meaning":"目錄；內含物"},{"word":"contented","pos":"adj.","meaning":"心滿意足的"}],"usageNote":"內容義重音在首音節；滿足義重音在第二音節。contents 可指書的目錄或容器內的物品。","examples":[{"text":"Before sharing online content, readers should check who created it and whether reliable evidence supports the claims it makes.","translationZh":"分享網路內容前，讀者應確認作者是誰，以及其主張是否有可靠證據支持。","source":"self-authored","grammar":"who/whether 引導查核問題；claims it makes 省略關係代名詞。","writingTip":"分享內容前先檢視作者和證據的可靠性。","topic":"網路查核"},{"text":"I was content with our modest result because the project had taught me how to listen and cooperate with others.","translationZh":"我對我們並不突出的成果感到滿足，因為專題教會我如何傾聽並與他人合作。","source":"self-authored","grammar":"was content with + 成果；how to listen/cooperate 為平行結構。","writingTip":"把滿足感連結過程中的學習，而不只成果高低。","topic":"專題成長"}]},"contract":{"senses":[{"pos":"n.","meaning":"契約","usage":""},{"pos":"v.","meaning":"收縮；感染疾病","usage":""}],"collocations":[{"en":"sign a contract","zh":"簽訂契約","note":""},{"en":"under contract","zh":"依契約受聘","note":""},{"en":"contract a disease","zh":"感染疾病","note":""},{"en":"muscles contract","zh":"肌肉收縮","note":""}],"synonyms":[{"en":"agreement","zh":"協議","note":"contract 通常具法律效力"},{"en":"shrink","zh":"縮小","note":"常用於尺寸，非簽約義"}],"idioms":[],"family":[{"word":"contraction","pos":"n.","meaning":"收縮；縮約"},{"word":"contractual","pos":"adj.","meaning":"契約上的"},{"word":"contractor","pos":"n.","meaning":"承包商"}],"usageNote":"名詞與動詞重音常不同；contract a disease 表感染，contract muscles 表使肌肉收縮。","examples":[{"text":"Before signing the rental contract, my parents carefully checked the rules about pets, repairs, and the return of the deposit.","translationZh":"簽租約前，父母仔細確認寵物、修繕與押金退還方面的規定。","source":"self-authored","grammar":"before signing 表簽約前；the rules about + 名詞串列。","writingTip":"租約條件可連結寵物、修繕與押金的具體考量。","topic":"租屋權益"},{"text":"The scientist explained how muscles contract and relax, using a simple model to help students understand the movement of an arm.","translationZh":"科學家解釋肌肉如何收縮與放鬆，並用簡單模型幫助學生理解手臂的動作。","source":"self-authored","grammar":"how muscles contract and relax；using 補充解說方式。","writingTip":"描寫簡單模型如何使科學概念容易理解。","topic":"科學解說"}]},"contrast":{"senses":[{"pos":"n.","meaning":"對比；差異","usage":"contrast between A and B。"},{"pos":"vt./vi.","meaning":"對照；形成對比","usage":"contrast A with B；A contrasts with B。"}],"collocations":[{"en":"in contrast to the past","zh":"與過去相比之下","note":""},{"en":"a sharp contrast between two views","zh":"兩種觀點間的鮮明對比","note":""},{"en":"contrast the results with earlier findings","zh":"將結果與較早發現對照","note":""},{"en":"by contrast","zh":"相較之下","note":"銜接兩個相反情況。"}],"synonyms":[{"en":"difference","zh":"差異","note":"一般不同之處，未必強烈或經過對照。"},{"en":"compare","zh":"比較","note":"可談異同；contrast 特別著重差異。"}],"idioms":[],"family":[{"word":"contrasting","pos":"adj.","meaning":"形成對比的"},{"word":"contrastive","pos":"adj.","meaning":"對比的"}],"usageNote":"in contrast to／with 後接比較對象；by contrast 可獨立銜接句子。避免比較不同統計單位而造成假對比。","examples":[{"text":"In contrast to the crowded city center, the riverside path offered a quiet place where neighbors could walk and talk.","translationZh":"與擁擠的市中心相較，河岸步道提供了鄰居可以散步交談的安靜空間。","grammar":"In contrast to + 名詞；where 修飾 place。","writingTip":"照片或地點比較可選擇同一面向描述差異。","topic":"城鄉空間","source":"self-authored"},{"text":"The report contrasted students' expectations with their actual experiences, revealing a gap that school planners had not anticipated.","translationZh":"報告對照學生的期待與實際經驗，呈現校方規畫人員未預料到的落差。","grammar":"contrast A with B；revealing 補充對照揭示的結果。","writingTip":"比較期望與實況後，指出需要回應的落差。","topic":"校園調查","source":"self-authored"}]},"contribute":{"senses":[{"pos":"vi.","meaning":"貢獻；促成","usage":"contribute to + 結果"},{"pos":"vt.","meaning":"提供；捐獻","usage":"contribute 金錢或想法"}],"collocations":[{"en":"contribute to global warming","zh":"促成全球暖化","note":"to 為介系詞"},{"en":"contribute ideas","zh":"提供想法","note":"直接接受詞"},{"en":"contribute money to a charity","zh":"捐款給慈善機構","note":"to 指對象"},{"en":"make a contribution to society","zh":"為社會作貢獻","note":"名詞搭配"}],"synonyms":[{"en":"help cause","zh":"促成","note":"對應造成某結果的意思"},{"en":"donate","zh":"捐贈","note":"適用金錢或物品，非所有 contribute 語境"}],"idioms":[{"en":"do one's part","zh":"盡一份力","note":"對應為共同目標作貢獻，不表示促成壞結果。"}],"family":[{"word":"contribution","pos":"n.","meaning":"貢獻；捐款"},{"word":"contributor","pos":"n.","meaning":"貢獻者；投稿者"}],"examples":[{"text":"Heavy traffic contributes to air pollution, especially when drivers leave their engines running.","translationZh":"繁忙交通會造成空氣污染，尤其是駕駛讓引擎持續運轉時。","source":"self-authored","grammar":"contribute to + 名詞；leave + 受詞 + V-ing","writingTip":"可連結環境問題與日常行為。","topic":"transport"},{"text":"Every team member contributed useful ideas before we chose the final design for our project.","translationZh":"選定專題的最終設計前，每位組員都提供了實用的想法。","source":"self-authored","grammar":"contributed 為及物動詞，直接接 useful ideas；before 子句說明提供想法發生在選定設計之前。","writingTip":"團隊敘事可強調每位成員在決策前都有參與。","topic":"teamwork"}],"usageNote":"contribute to 可表示正面的貢獻，也可表示促成負面結果。"},"convert":{"senses":[{"pos":"vt./vi.","meaning":"轉換；改變用途","usage":"convert A into B"},{"pos":"vt./vi.","meaning":"改變信仰或立場","usage":"convert to + 信仰"}],"collocations":[{"en":"convert sunlight into electricity","zh":"將陽光轉為電力","note":"into 指結果"},{"en":"convert a warehouse into apartments","zh":"將倉庫改為公寓","note":"改變用途"},{"en":"convert dollars to euros","zh":"將美元換成歐元","note":"貨幣換算"},{"en":"convert to a different religion","zh":"改信其他宗教","note":"to 指新信仰"}],"synonyms":[{"en":"transform","zh":"轉變","note":"著重明顯改變"},{"en":"change","zh":"改變","note":"較廣泛，需按情境選擇"}],"idioms":[],"family":[{"word":"conversion","pos":"n.","meaning":"轉換；改建"},{"word":"convertible","pos":"adj.","meaning":"可轉換的"}],"examples":[{"text":"Solar panels convert sunlight into electricity that can power lights and household appliances.","translationZh":"太陽能板把陽光轉成電力，供照明和家電使用。","source":"self-authored","grammar":"convert A into B；that 修飾 electricity","writingTip":"可清楚解釋科技運作原理。","topic":"energy"},{"text":"The city converted an abandoned factory into a public space for exhibitions and workshops.","translationZh":"市府把廢棄工廠改建成提供展覽與工作坊的公共空間。","source":"self-authored","grammar":"converted an abandoned factory into a public space 使用 convert + A + into + B；for 引出新用途。","writingTip":"介紹舊建築再利用時，同時寫出原用途、新用途與可舉辦的活動。","topic":"urban life"}],"usageNote":"convert A into B 常用於形態或用途轉換；貨幣、單位轉換也可用 to。"},"convince":{"senses":[{"pos":"vt.","meaning":"使信服；說服","usage":"convince someone of something／that...／to V。"}],"collocations":[{"en":"convince someone of the need for change","zh":"使某人相信改變的必要","note":""},{"en":"convince someone that a plan is practical","zh":"使某人相信計畫可行","note":""},{"en":"convince a friend to join","zh":"說服朋友加入","note":""},{"en":"be convinced of someone's honesty","zh":"深信某人的誠實","note":""}],"synonyms":[{"en":"persuade","zh":"說服","note":"常著重促成行動，但與 convince 的用法有重疊。"},{"en":"assure","zh":"使放心；保證","note":"常安撫疑慮，未必提供足以使人信服的證據。"}],"idioms":[],"family":[{"word":"convinced","pos":"adj.","meaning":"確信的"},{"word":"convincing","pos":"adj.","meaning":"有說服力的"},{"word":"convincingly","pos":"adv.","meaning":"有說服力地"}],"usageNote":"convincing 形容理由等有說服力；convinced 形容人確信。convince someone to do 是通行用法，不應一律判錯。","examples":[{"text":"The trial results convinced the team that the simpler design could meet users' needs without adding unnecessary features.","translationZh":"試用結果使團隊相信，較簡單的設計不用加入多餘功能也能符合使用者需求。","grammar":"convince + 人 + that 子句；without adding 表不加入功能。","writingTip":"提案作文以試用結果支持選擇，避免只憑偏好。","topic":"產品設計","source":"self-authored"},{"text":"I convinced my friend to try the hiking club by explaining that beginners could choose a shorter, easier route.","translationZh":"我說明初學者可以選較短較容易的路線，說服朋友試著參加健行社。","grammar":"convince + 人 + to V；by explaining 表說服方式。","writingTip":"描寫邀請活動時如何回應對方的具體顧慮。","topic":"社團參與","source":"self-authored"}]},"cooperate":{"senses":[{"pos":"vi.","meaning":"合作；配合","usage":"與人合作用 with，針對事項可用 on。"}],"collocations":[{"en":"cooperate with others","zh":"與他人合作","note":""},{"en":"cooperate on a project","zh":"在專案上合作","note":""},{"en":"cooperate to solve a problem","zh":"合作解決問題","note":""},{"en":"cooperate fully with authorities","zh":"充分配合主管機關","note":""}],"synonyms":[{"en":"collaborate","zh":"共同合作","note":"常強調共同創作或專業工作。"},{"en":"work together","zh":"一起工作","note":"日常且範圍較廣。"}],"idioms":[],"family":[{"word":"cooperation","pos":"n.","meaning":"合作"},{"word":"cooperative","pos":"adj.","meaning":"合作的；願意配合的"},{"word":"cooperatively","pos":"adv.","meaning":"以合作方式"}],"examples":[{"text":"Schools and families need to cooperate to ensure that students receive support both inside and outside the classroom.","translationZh":"學校與家庭必須合作，確保學生在課堂內外都能獲得支持。","grammar":"cooperate to V 表共同目的，ensure that 接子句。","writingTip":"可寫家庭與學校的共同責任。","topic":"教育與支持","source":"self-authored"},{"text":"When residents cooperated on the cleanup, the neglected riverside became a pleasant place for evening walks.","translationZh":"居民合作清理之後，原本乏人照顧的河岸變成適合晚間散步的地方。","grammar":"cooperate on 表合作事項，when 引導時間子句。","writingTip":"適合呈現集體行動的具體成果。","topic":"社區與環境","source":"self-authored"}],"usageNote":"cooperate 為不及物動詞，不能直接寫 cooperate someone；應加 with。"},"coordinate":{"senses":[{"pos":"vt./vi.","meaning":"協調；統籌","usage":"協調人員、時間或動作，使之配合。"},{"pos":"n.","meaning":"座標","usage":"常用複數 coordinates。"}],"collocations":[{"en":"coordinate a rescue operation","zh":"協調救援行動","note":""},{"en":"coordinate with local volunteers","zh":"與當地志工協調","note":""},{"en":"coordinate schedules","zh":"協調時間安排","note":""},{"en":"geographical coordinates","zh":"地理座標","note":"名詞複數。"}],"synonyms":[{"en":"organize","zh":"組織；安排","note":"範圍較廣，未必強調各部分同步配合。"},{"en":"synchronize","zh":"使同步","note":"強調時間一致，不涵蓋所有協調工作。"}],"idioms":[],"family":[{"word":"coordination","pos":"n.","meaning":"協調"},{"word":"coordinator","pos":"n.","meaning":"協調人"},{"word":"coordinated","pos":"adj.","meaning":"協調一致的"}],"usageNote":"coordinate with + 合作對象；coordinate + 活動或安排。coordinates 是可定位的座標，與協調工作是不同詞義。","examples":[{"text":"A student coordinator helped us coordinate schedules so that volunteers could cover every shift without missing their regular classes.","translationZh":"學生協調人幫忙統籌時程，讓志工能支援每個班次，也不耽誤正常課程。","grammar":"help + 人 + 原形 coordinate；so that 表安排的目的。","writingTip":"志工經驗可說明如何兼顧服務與課業。","topic":"志工排班","source":"self-authored"},{"text":"Rescue teams coordinated with local residents to identify roads that remained safe after the heavy rain.","translationZh":"救援團隊與當地居民協調，確認哪些道路在大雨後仍安全可行。","grammar":"coordinate with + 人；to identify 表合作目的。","writingTip":"防災作文可交代在地資訊如何協助救援。","topic":"災後協調","source":"self-authored"}]},"cope":{"senses":[{"pos":"vi.","meaning":"應付；因應","usage":"cope with + 困難或需求，不直接接困難作受詞。"}],"collocations":[{"en":"cope with stress","zh":"因應壓力","note":""},{"en":"cope with a sudden change","zh":"應付突發改變","note":""},{"en":"learn to cope","zh":"學習應對","note":"可不明說 with 的受詞。"},{"en":"coping strategies","zh":"因應策略","note":"名詞組。"}],"synonyms":[{"en":"deal with","zh":"處理；應對","note":"範圍較廣，不一定表示困難。"},{"en":"manage","zh":"設法應付","note":"可直接接受詞，句型不同。"}],"idioms":[],"family":[{"word":"coping","pos":"n.","meaning":"因應；應對"},{"word":"coping","pos":"adj.","meaning":"因應用的"}],"usageNote":"cope with a problem，不寫 cope a problem。cope 通常暗示情況有壓力或難度，不代表問題已完全解決。","examples":[{"text":"When the deadline changed unexpectedly, our group coped with the pressure by identifying the tasks that needed immediate attention.","translationZh":"期限突然改變時，我們先辨認急需處理的任務，以應對壓力。","grammar":"cope with + 壓力；by identifying 表方法；that 修飾 tasks。","writingTip":"臨時變動的敘事可用優先排序呈現解決方式。","topic":"期限與壓力","source":"self-authored"},{"text":"Talking with a trusted adult helped me cope with disappointment after I failed to reach the final round.","translationZh":"未能進入決賽後，與可信任的成人談談，幫助我應對失望。","grammar":"Talking 為主詞；help + 人 + 原形 cope；after 表先後。","writingTip":"描寫挫折時可具體寫出求助對象及支持方式。","topic":"挫折與支持","source":"self-authored"}]},"courage":{"senses":[{"pos":"n.","meaning":"勇氣","usage":"通常不可數，常用 courage to V。"}],"collocations":[{"en":"have the courage to","zh":"有勇氣……","note":""},{"en":"show courage","zh":"展現勇氣","note":""},{"en":"take courage","zh":"需要勇氣","note":""},{"en":"gather one's courage","zh":"鼓起勇氣","note":""}],"synonyms":[{"en":"bravery","zh":"勇敢","note":"常指面對危險的勇氣。"},{"en":"boldness","zh":"大膽","note":"可能帶冒險或不顧慣例的意味。"}],"idioms":[{"en":"pluck up one's courage","zh":"鼓起勇氣","note":"較口語，常指準備開口或採取行動。"}],"family":[{"word":"courageous","pos":"adj.","meaning":"勇敢的"},{"word":"courageously","pos":"adv.","meaning":"勇敢地"},{"word":"encourage","pos":"vt.","meaning":"鼓勵"}],"examples":[{"text":"It took courage to admit that I needed help, but doing so made the problem easier to face.","translationZh":"承認自己需要幫助需要勇氣，但這麼做讓問題更容易面對。","grammar":"It takes courage to V，doing so 代替前面的行為。","writingTip":"可寫求助也是勇敢的表現。","topic":"心理與成長","source":"self-authored"},{"text":"The young reporter showed courage by asking difficult questions even when powerful officials tried to avoid them.","translationZh":"即使有權勢的官員試圖迴避，這位年輕記者仍勇敢提出尖銳的問題。","grammar":"by V-ing 表方式，even when 表讓步情境。","writingTip":"適合討論新聞責任與公共監督。","topic":"媒體與責任","source":"self-authored"}],"usageNote":"courage 為名詞，courageous 為形容詞；寫 a courageous person，而非 a courage person。"},"cover":{"senses":[{"pos":"v.","meaning":"覆蓋；涵蓋；報導；負擔","usage":""},{"pos":"n.","meaning":"封面；遮蓽物","usage":""}],"collocations":[{"en":"cover the cost","zh":"負擔費用","note":""},{"en":"cover a news story","zh":"報導新聞","note":""},{"en":"cover a wide range of topics","zh":"涵蓋廣泛主題","note":""},{"en":"a book cover","zh":"書籍封面","note":""}],"synonyms":[{"en":"include","zh":"包含","note":"對應涵蓋，不適用物理覆蓋"},{"en":"report on","zh":"報導","note":"用於新聞，不表示負擔費用"}],"idioms":[],"family":[{"word":"coverage","pos":"n.","meaning":"報導；涵蓋；保險範圍"},{"word":"covered","pos":"adj.","meaning":"被覆蓋的"},{"word":"uncover","pos":"v.","meaning":"揭露；揭開"}],"usageNote":"cover the cost 指支付足夠金額；cover a topic 表涵蓋，不是把主題蓋起來。","examples":[{"text":"The money raised at the charity fair covered the cost of new blankets and basic medical supplies for the shelter.","translationZh":"慈善園遊會募得的錢支付了收容所新毛毯與基本醫療用品的費用。","source":"self-authored","grammar":"raised at the fair 修飾 money；covered the cost of + 用品。","writingTip":"把募款結果連結到實際購置的物資。","topic":"慈善募款"},{"text":"The documentary covers several environmental issues, but its most powerful scenes show how ordinary families respond to sudden water shortages.","translationZh":"紀錄片涵蓋多種環境議題，但最有力的場景呈現一般家庭如何面對突發缺水。","source":"self-authored","grammar":"covers + 議題；how 引導場景呈現的內容。","writingTip":"可比較作品涵蓋的主題與最有力的具體場景。","topic":"紀錄片分析"}]},"credit":{"senses":[{"pos":"n.","meaning":"信用；功勞；學分","usage":""},{"pos":"v.","meaning":"歸功於；相信","usage":""}],"collocations":[{"en":"give someone credit for an idea","zh":"肯定某人的點子","note":""},{"en":"receive academic credit","zh":"取得學分","note":""},{"en":"a credit card","zh":"信用卡","note":""},{"en":"credit success to teamwork","zh":"把成功歸功於團隊合作","note":""}],"synonyms":[{"en":"recognition","zh":"肯定","note":"指功勞義"},{"en":"attribute","zh":"歸因","note":"attribute A to B 對應 credit A to B"}],"idioms":[],"family":[{"word":"credible","pos":"adj.","meaning":"可信的"},{"word":"credibility","pos":"n.","meaning":"可信度"},{"word":"creditworthy","pos":"adj.","meaning":"信用良好的"}],"usageNote":"give credit to + 人；give someone credit for + 事；不能把所有 credit 都翻成信用卡。","examples":[{"text":"Although I presented the final report, I gave my teammates credit for collecting the data and checking every figure carefully.","translationZh":"雖然是我發表最終報告，我仍肯定隊友蒐集資料與仔細核對每項數字的功勞。","source":"self-authored","grammar":"gave + 人 + credit for + V-ing；although 引導發表者與贡献者的差別。","writingTip":"承認發表之外的資料蒐集與核對貢獻。","topic":"團隊功勞"},{"text":"The athlete credited her recovery to patient support from her family and a training plan designed by an experienced coach.","translationZh":"運動員把康復歸功於家人耐心的支持，以及有經驗教練設計的訓練計畫。","source":"self-authored","grammar":"credited A to B；designed by + 人修飾 plan。","writingTip":"描述康復時可把成功歸功於家人與專業支持。","topic":"運動員康復"}]},"critical":{"senses":[{"pos":"adj.","meaning":"關鍵的；危急的","usage":""},{"pos":"adj.","meaning":"批判性的；挑剔的","usage":""}],"collocations":[{"en":"critical thinking","zh":"批判思考","note":""},{"en":"a critical decision","zh":"關鍵決定","note":""},{"en":"be critical of a proposal","zh":"批評提案","note":""},{"en":"in critical condition","zh":"處於病危狀態","note":""}],"synonyms":[{"en":"crucial","zh":"關鍵的","note":"對應重要性"},{"en":"analytical","zh":"分析性的","note":"不含苛責或病危義"}],"idioms":[],"family":[{"word":"critic","pos":"n.","meaning":"評論者"},{"word":"criticism","pos":"n.","meaning":"批評；評論"},{"word":"critically","pos":"adv.","meaning":"批判地；極度地"}],"usageNote":"critical thinking 指分析證據與論點，不等於一味找缺點；critical of 表批評。","examples":[{"text":"Critical thinking helps students examine the evidence behind a claim instead of accepting it simply because many people repeat it.","translationZh":"批判思考幫助學生檢視主張背後的證據，而非只因很多人重複就接受。","source":"self-authored","grammar":"instead of + V-ing；because 解釋錯誤的接受依據。","writingTip":"主張接受資訊應以證據而非轉傳次數判斷。","topic":"批判思考"},{"text":"The first few minutes after the accident were critical, so bystanders called emergency services rather than move the injured cyclist.","translationZh":"事故後最初幾分鐘至關重要，因此旁觀者打給急救單位，而非移動受傷的自行車騎士。","source":"self-authored","grammar":"rather than move 與 called 平行；after the accident 交代時段。","writingTip":"強調關鍵時刻的具體安全處置。","topic":"事故應變"}]},"curious":{"senses":[{"pos":"adj.","meaning":"好奇的；奇特的","usage":"對某事好奇用 about，急於知道可用 to V。"}],"collocations":[{"en":"be curious about","zh":"對……好奇","note":""},{"en":"curious to know","zh":"想知道","note":""},{"en":"a curious child","zh":"好奇的孩子","note":""},{"en":"a curious coincidence","zh":"奇妙的巧合","note":"此處指奇特，不指好奇。"}],"synonyms":[{"en":"inquisitive","zh":"好問的","note":"可能正面，也可能暗示探問過多。"},{"en":"strange","zh":"奇怪的","note":"只對應 curious 的奇特義。"}],"idioms":[],"family":[{"word":"curiosity","pos":"n.","meaning":"好奇心"},{"word":"curiously","pos":"adv.","meaning":"好奇地"}],"examples":[{"text":"Curious about where our food came from, we visited a farm and interviewed the people who worked there.","translationZh":"因為好奇食物從哪裡來，我們參訪農場，訪問在那裡工作的人。","grammar":"形容詞片語置於句首說明主詞狀態，where 引導名詞子句。","writingTip":"可寫從日常疑問開始的探究。","topic":"飲食與學習","source":"self-authored"},{"text":"A curious pattern emerged from the survey: students with longer commutes often valued quiet spaces more highly.","translationZh":"調查顯示一個有趣的現象：通勤時間較長的學生，往往更重視安靜的空間。","grammar":"curious 在此表示不尋常而有趣，冒號引出具體發現。","writingTip":"適合寫調查結果與現象分析。","topic":"調查與校園","source":"self-authored"}],"usageNote":"curious 的字義由搭配決定；curious about 表好奇，a curious result 可指奇特的結果。"},"current":{"senses":[{"pos":"adj.","meaning":"目前的","usage":""},{"pos":"n.","meaning":"水流；電流；趨勢","usage":""}],"collocations":[{"en":"current events","zh":"時事","note":""},{"en":"the current situation","zh":"目前情況","note":""},{"en":"a strong ocean current","zh":"強勁洋流","note":""},{"en":"an electric current","zh":"電流","note":""}],"synonyms":[{"en":"present","zh":"目前的","note":"形容詞義相近"},{"en":"flow","zh":"流動","note":"可對應水流，但不限 current 的名詞義"}],"idioms":[],"family":[{"word":"currently","pos":"adv.","meaning":"目前"},{"word":"currency","pos":"n.","meaning":"貨幣；通行"},{"word":"recurrent","pos":"adj.","meaning":"反覆出現的"}],"usageNote":"current 作名詞需從上下文判斷水流或電流；currently 不等於 finally。","examples":[{"text":"The current school policy allows students to use phones for research, but they must put them away during ordinary class discussions.","translationZh":"目前的校規允許學生用手機查資料，但一般課堂討論時必須收起來。","source":"self-authored","grammar":"allows + 人 + to V；but 對比手機研究與一般課堂規範。","writingTip":"以使用目的區分手機的教學用途與限制。","topic":"校園手機政策"},{"text":"A strong ocean current carried the swimmers away from the beach before lifeguards reached them and guided them back to safety.","translationZh":"強勁洋流把游泳者帶離沙灘，救生員隨後接近他們，帶他們回到安全處。","source":"self-authored","grammar":"carried A away from B；before 引導救生員到達的時間。","writingTip":"可敘述水流造成風險與救生人員的應變。","topic":"海洋安全"}]},"decline":{"senses":[{"pos":"vi.","meaning":"下降；衰退","usage":"數量、品質或健康"},{"pos":"vt./vi.","meaning":"婉拒","usage":"decline an offer 或 to V"},{"pos":"n.","meaning":"下降；衰退","usage":"a decline in"}],"collocations":[{"en":"a decline in sales","zh":"銷售下滑","note":"in 接下降項目"},{"en":"decline an invitation","zh":"婉拒邀請","note":"及物用法"},{"en":"decline to comment","zh":"拒絕評論","note":"接不定詞"},{"en":"a steady decline","zh":"持續下降","note":"名詞用法"}],"synonyms":[{"en":"decrease","zh":"下降","note":"通常針對數量"},{"en":"turn down","zh":"婉拒","note":"對應拒絕邀請或提議"}],"idioms":[],"family":[{"word":"declining","pos":"adj.","meaning":"下降中的"}],"examples":[{"text":"The number of butterflies has declined as urban development reduces the plants they depend on.","translationZh":"都市開發減少蝴蝶賴以生存的植物，使蝴蝶數量下降。","source":"self-authored","grammar":"the number of + 複數名詞 + 單數動詞","writingTip":"描述生態趨勢時交代成因。","topic":"wildlife"},{"text":"I politely declined the invitation because I had promised to help my grandfather that evening.","translationZh":"我禮貌地婉拒了邀請，因為已答應那晚幫爺爺的忙。","source":"self-authored","grammar":"decline + 名詞；had promised 表較早發生","writingTip":"可敘述選擇與承諾。","topic":"personal experience"}],"usageNote":"decline 可指下降或婉拒；decline to V 是拒絕做某事。"},"decrease":{"senses":[{"pos":"vi./vt.","meaning":"減少","usage":"及物用法可接數量"},{"pos":"n.","meaning":"減少；減少量","usage":"a decrease in + 項目"}],"collocations":[{"en":"decrease by twenty percent","zh":"減少百分之二十","note":"by 指幅度"},{"en":"decrease to a lower level","zh":"降至較低水準","note":"to 指終點"},{"en":"a decrease in energy use","zh":"能源使用量下降","note":"名詞接 in"},{"en":"decrease the risk of injury","zh":"降低受傷風險","note":"及物搭配"}],"synonyms":[{"en":"reduce","zh":"減少","note":"及物動詞，通常需受詞"},{"en":"drop","zh":"下降","note":"較口語，常描述數字下滑"}],"idioms":[],"family":[{"word":"decreasing","pos":"adj.","meaning":"逐漸減少的"}],"examples":[{"text":"Electricity use decreased after the office replaced its old lights with more efficient models.","translationZh":"辦公室把舊燈換成更有效率的款式後，用電量下降了。","source":"self-authored","grammar":"Electricity use 為主詞，decreased 不接受詞；replaced its old lights with... 使用 replace A with B。","writingTip":"說明節能成果時，可把用電量下降連結到更換燈具這項措施。","topic":"energy"},{"text":"Regular stretching may decrease the risk of injury, but it cannot replace proper training.","translationZh":"規律伸展可能降低受傷風險，但不能取代適當訓練。","source":"self-authored","grammar":"decrease + 受詞；cannot replace + 名詞","writingTip":"健康論述可兼顧效益與限制。","topic":"health"}],"usageNote":"decrease by 指減少多少；decrease to 指下降後達到多少。"},"dedicate":{"senses":[{"pos":"vt.","meaning":"奉獻；致力於；題獻","usage":"dedicate A to B 的 to 是介系詞。"}],"collocations":[{"en":"dedicate time to helping others","zh":"投入時間幫助他人","note":""},{"en":"dedicate oneself to education","zh":"獻身教育","note":""},{"en":"dedicate a book to someone","zh":"將書題獻給某人","note":""},{"en":"be dedicated to one's work","zh":"致力於工作","note":""}],"synonyms":[{"en":"devote","zh":"投入；奉獻","note":"常用 devote A to B，搭配相近。"},{"en":"commit","zh":"投入；承諾","note":"commit oneself to 強調作出持續承諾。"}],"idioms":[],"family":[{"word":"dedication","pos":"n.","meaning":"奉獻；致力"},{"word":"dedicated","pos":"adj.","meaning":"盡心盡力的"}],"examples":[{"text":"She dedicated her weekends to teaching older neighbors how to use their phones safely.","translationZh":"她投入週末的時間，教年長鄰居如何安全使用手機。","grammar":"dedicate time to V-ing，how to V 表方法。","writingTip":"可寫志工服務與數位能力。","topic":"服務與科技","source":"self-authored"},{"text":"A dedicated teacher can change a student's future by noticing strengths that others have overlooked.","translationZh":"盡心盡力的老師，能透過發現他人忽略的優點，改變學生的未來。","grammar":"by V-ing 表方法，that 引導 strengths 的關係子句。","writingTip":"適合描寫師長的長期影響。","topic":"教育與成長","source":"self-authored"}],"usageNote":"dedicate ... to 中 to 後接名詞或動名詞，不接原形動詞。"},"deliver":{"senses":[{"pos":"v.","meaning":"遞送；發表；履行","usage":""},{"pos":"v.","meaning":"接生","usage":""}],"collocations":[{"en":"deliver a package","zh":"遞送包裹","note":""},{"en":"deliver a speech","zh":"發表演說","note":""},{"en":"deliver on a promise","zh":"履行承諾","note":""},{"en":"deliver a baby","zh":"接生嬰兒","note":""}],"synonyms":[{"en":"send","zh":"寄送","note":"send 不保證送達"},{"en":"fulfill","zh":"履行","note":"fulfill a promise 對應 deliver on a promise"}],"idioms":[],"family":[{"word":"delivery","pos":"n.","meaning":"遞送；演說方式；分娩"},{"word":"deliverer","pos":"n.","meaning":"遞送者"}],"usageNote":"deliver a speech 不只是把稿件送出；deliver on + 承諾表示兌現。","examples":[{"text":"When delivering her speech, the student paused between key points so that the audience could follow her argument more easily.","translationZh":"學生發表演說時在重點之間停頓，讓聽眾更容易跟上她的論述。","source":"self-authored","grammar":"when delivering 為省略主詞的時間子句；so that 表目的。","writingTip":"說明適當停頓如何幫助聽眾理解論點。","topic":"演說技巧"},{"text":"The local store began delivering groceries to older residents who found it difficult to carry heavy bags home from the market.","translationZh":"在地商店開始把雜貨送給難以從市場提重物回家的年長居民。","source":"self-authored","grammar":"began delivering + 物品 + to + 對象；who 修飾 residents。","writingTip":"以提重物的困難解釋送貨服務的價值。","topic":"長者服務"}]},"demand":{"senses":[{"pos":"n.","meaning":"需求","usage":"demand for + 商品或服務"},{"pos":"vt.","meaning":"要求","usage":"demand + 名詞 或 that 子句"}],"collocations":[{"en":"demand for clean energy","zh":"對乾淨能源的需求","note":"for 接需求對象"},{"en":"meet the demand","zh":"滿足需求","note":"供需搭配"},{"en":"demand immediate action","zh":"要求立即行動","note":"及物用法"},{"en":"in high demand","zh":"需求很高","note":"介系詞片語"}],"synonyms":[{"en":"need","zh":"需求","note":"較中性，語氣較弱"},{"en":"require","zh":"要求","note":"著重必要條件，demand 常含強烈要求"}],"idioms":[],"family":[{"word":"demanding","pos":"adj.","meaning":"要求高的；費力的"}],"examples":[{"text":"Growing demand for affordable housing has encouraged the city to build more public apartments.","translationZh":"對平價住房日增的需求，促使市府興建更多公共住宅。","source":"self-authored","grammar":"demand for；encourage 人 to V","writingTip":"可連結需求與政策回應。","topic":"housing"},{"text":"Residents demanded that the company explain how it would prevent future pollution incidents.","translationZh":"居民要求公司說明，將如何防止未來再發生污染事件。","source":"self-authored","grammar":"demand that + 主詞 + 原形動詞","writingTip":"可用於公民參與及企業責任。","topic":"environment"}],"usageNote":"demand that 後可用原形動詞；表示對某人提出要求通常用 demand something from someone。"},"demonstrate":{"senses":[{"pos":"vt.","meaning":"證明；顯示","usage":"demonstrate that + 子句"},{"pos":"vt.","meaning":"示範","usage":"展示操作方式"},{"pos":"vi.","meaning":"示威","usage":"demonstrate against + 對象"}],"collocations":[{"en":"demonstrate a technique","zh":"示範技巧","note":"教學語境"},{"en":"demonstrate the importance of teamwork","zh":"顯示合作的重要性","note":"證據支持"},{"en":"demonstrate how to use a device","zh":"示範如何使用裝置","note":"how + 不定詞"},{"en":"demonstrate against a policy","zh":"示威反對政策","note":"against 表反對"}],"synonyms":[{"en":"show","zh":"顯示；示範","note":"較日常，意思較廣"},{"en":"prove","zh":"證明","note":"語氣更確定，證據需足夠"}],"idioms":[],"family":[{"word":"demonstration","pos":"n.","meaning":"示範；證明；示威"},{"word":"demonstrator","pos":"n.","meaning":"示範者；示威者"}],"examples":[{"text":"The nurse demonstrated how to wash our hands properly before we entered the ward.","translationZh":"進入病房前，護理師示範了如何正確洗手。","source":"self-authored","grammar":"demonstrate how to V","writingTip":"可敘述健康教育或志工經驗。","topic":"health"},{"text":"Our survey demonstrated that many students preferred quiet study spaces to crowded coffee shops.","translationZh":"我們的調查顯示，許多學生比起擁擠咖啡廳，更喜歡安靜的讀書空間。","source":"self-authored","grammar":"demonstrate that；prefer A to B","writingTip":"圖表或調查作文可據資料下結論。","topic":"education"}],"usageNote":"demonstrate 的意思須依受詞判斷；示威義常接 against 或 for。"},"depend":{"senses":[{"pos":"vi.","meaning":"依賴；取決於","usage":"後接 on 或 upon。"}],"collocations":[{"en":"depend on others","zh":"依賴他人","note":""},{"en":"depend on the weather","zh":"取決於天氣","note":""},{"en":"depend on someone for support","zh":"仰賴某人提供支持","note":""},{"en":"it depends on whether","zh":"這取決於是否……","note":""}],"synonyms":[{"en":"rely on","zh":"依靠","note":"常用於人或可靠資源，與依賴義接近。"},{"en":"be determined by","zh":"由……決定","note":"只對應取決於，不表示信任他人。"}],"idioms":[],"family":[{"word":"dependence","pos":"n.","meaning":"依賴"},{"word":"dependent","pos":"adj.","meaning":"依賴的"},{"word":"dependable","pos":"adj.","meaning":"可靠的"}],"examples":[{"text":"Whether the outdoor concert can take place depends on the weather and the condition of the park.","translationZh":"戶外音樂會能否舉行，取決於天氣以及公園的狀況。","grammar":"whether 子句作主詞，主要動詞用單數 depends。","writingTip":"可說明活動成功的必要條件。","topic":"活動與規畫","source":"self-authored"},{"text":"Many small businesses depend on loyal customers who choose local shops over large online platforms.","translationZh":"許多小型商家仰賴忠實顧客，他們選擇在地店家，而不是大型網購平台。","grammar":"depend on，choose A over B 表偏好選擇。","writingTip":"適合討論消費選擇與地方經濟。","topic":"消費與社區","source":"self-authored"}],"usageNote":"dependent 指依賴他人的；dependable 指值得依靠的，意思不同。"},"despite":{"senses":[{"pos":"prep.","meaning":"儘管；即使","usage":"後接名詞或 V-ing，不直接接完整子句。"}],"collocations":[{"en":"despite the rain","zh":"儘管下雨","note":""},{"en":"despite limited resources","zh":"儘管資源有限","note":""},{"en":"despite being tired","zh":"儘管疲倦","note":"後接 V-ing。"},{"en":"despite the fact that","zh":"儘管……這個事實","note":"fact 後可接完整子句。"}],"synonyms":[{"en":"in spite of","zh":"儘管","note":"同樣後接名詞或 V-ing。"},{"en":"although","zh":"雖然","note":"是連接詞，後接完整子句，不能直接原位互換。"}],"idioms":[],"family":[],"usageNote":"despite 後不加 of；despite + 名詞／V-ing 與 although + 主詞 + 動詞須分清。此常用介系詞不勉強衍生字族。","examples":[{"text":"Despite limited resources, the village library created a welcoming reading corner with donated books and furniture repaired by volunteers.","translationZh":"儘管資源有限，村立圖書館仍用捐書與志工修好的家具，打造親切的閱讀角落。","grammar":"Despite 後接名詞組；repaired 為過去分詞修飾 furniture。","writingTip":"讓步句先交代限制，再具體描述如何運用現有資源。","topic":"社區閱讀","source":"self-authored"},{"text":"Despite feeling nervous, I introduced our project clearly and answered the questions I had practiced with my teammates.","translationZh":"儘管緊張，我仍清楚介紹專題，並回答先前和隊友練習過的問題。","grammar":"Despite + V-ing；had practiced 表較早完成的準備。","writingTip":"個人經驗可同時描寫情緒與準備帶來的作用。","topic":"上台報告","source":"self-authored"}]},"detect":{"senses":[{"pos":"vt.","meaning":"察覺；偵測","usage":"找出不明顯的事物"}],"collocations":[{"en":"detect early signs of illness","zh":"察覺疾病早期徵兆","note":"健康情境"},{"en":"detect a gas leak","zh":"偵測瓦斯外洩","note":"安全情境"},{"en":"detect changes in temperature","zh":"偵測溫度變化","note":"in 表變化項目"},{"en":"detect errors in data","zh":"找出資料錯誤","note":"檢查用語"}],"synonyms":[{"en":"identify","zh":"辨認出","note":"著重確認身分或種類"},{"en":"notice","zh":"注意到","note":"不一定需儀器或仔細檢查"}],"idioms":[],"family":[{"word":"detection","pos":"n.","meaning":"偵測"},{"word":"detector","pos":"n.","meaning":"偵測器"},{"word":"detectable","pos":"adj.","meaning":"可被察覺的"}],"examples":[{"text":"Sensors can detect a gas leak and warn residents before the situation becomes dangerous.","translationZh":"感測器能偵測瓦斯外洩，在情況變危險前警告居民。","source":"self-authored","grammar":"detect + 受詞；before 引導時間子句","writingTip":"介紹科技時說明其實際功能。","topic":"safety"},{"text":"By examining old photographs, researchers detected changes in the coastline that were difficult to notice.","translationZh":"研究人員檢視舊照片，發現了原本難以察覺的海岸線變化。","source":"self-authored","grammar":"By + V-ing；that 修飾 changes","writingTip":"可描寫調查方法及發現。","topic":"environment"}],"usageNote":"detect 強調察覺原先隱藏或難見的現象；detector 是儀器，detection 是過程。"},"determination":{"senses":[{"pos":"n.","meaning":"決心；判定","usage":"決心通常不可數，也可指正式確定或裁決。"}],"collocations":[{"en":"show determination","zh":"展現決心","note":""},{"en":"determination to succeed","zh":"成功的決心","note":""},{"en":"with great determination","zh":"帶著強烈決心","note":""},{"en":"determination of the cause","zh":"判定原因","note":"此處指確認，不指意志。"}],"synonyms":[{"en":"resolve","zh":"決心","note":"名詞時偏正式，強調堅定意志。"},{"en":"persistence","zh":"堅持","note":"強調持續行動，未必是內在決心。"}],"idioms":[],"family":[{"word":"determine","pos":"vt.","meaning":"決定；查明"},{"word":"determined","pos":"adj.","meaning":"堅定的"},{"word":"determinant","pos":"n.","meaning":"決定因素"}],"examples":[{"text":"Her determination to finish the race inspired classmates who had doubted their own ability to persevere.","translationZh":"她完成比賽的決心，激勵了那些原本懷疑自己能否堅持的同學。","grammar":"determination to V，who 引導限定關係子句。","writingTip":"可寫榜樣如何鼓舞他人。","topic":"運動與韌性","source":"self-authored"},{"text":"Accurate determination of the fire's cause is essential before officials decide how to prevent similar accidents.","translationZh":"官員決定如何預防類似事故前，必須準確查明火災原因。","grammar":"determination of 表判定，how to V 作 decide 的受詞。","writingTip":"適合寫證據與公共安全。","topic":"安全與調查","source":"self-authored"}],"usageNote":"determination 不只表示決心；科學與正式報告中的 determination of 可指測定或查明。"},"device":{"senses":[{"pos":"n.","meaning":"裝置；器具","usage":"可數"},{"pos":"n.","meaning":"手法","usage":"文學或表達策略"}],"collocations":[{"en":"a mobile device","zh":"行動裝置","note":"科技語境"},{"en":"a medical device","zh":"醫療器材","note":"健康科技"},{"en":"an electronic device","zh":"電子裝置","note":"可數名詞"},{"en":"a literary device","zh":"文學手法","note":"熟詞偏義"}],"synonyms":[{"en":"gadget","zh":"小型器具","note":"常指新奇便利的小裝置"},{"en":"technique","zh":"手法","note":"對應表達策略，非實體裝置"}],"idioms":[],"family":[{"word":"devise","pos":"vt.","meaning":"設計；想出"}],"examples":[{"text":"The device sends an alert to caregivers when an older person falls at home.","translationZh":"長者在家跌倒時，這個裝置會向照護者發送警示。","source":"self-authored","grammar":"The device 是單數主詞，搭配 sends；send an alert to caregivers 中 to 指收訊者；when 引出觸發事件。","writingTip":"介紹照護科技時，說明它在什麼情況下通知哪一群人。","topic":"technology"},{"text":"The writer uses repetition as a literary device to emphasize the narrator's growing fear.","translationZh":"作者運用重複這種文學手法，凸顯敘事者逐漸加深的恐懼。","source":"self-authored","grammar":"use A as B；to V 表目的","writingTip":"閱讀時注意 device 的非器材義。","topic":"literature"}],"usageNote":"device 是名詞；devise 是動詞，兩者拼字與發音不同。"},"discipline":{"senses":[{"pos":"n.","meaning":"紀律；學科","usage":"可指自我管理或知識領域。"},{"pos":"vt.","meaning":"管教；訓練","usage":"常用 discipline oneself to V。"}],"collocations":[{"en":"self-discipline","zh":"自律","note":""},{"en":"maintain discipline","zh":"維持紀律","note":""},{"en":"an academic discipline","zh":"一門學科","note":""},{"en":"discipline oneself to study regularly","zh":"訓練自己規律讀書","note":""}],"synonyms":[{"en":"self-control","zh":"自制力","note":"較聚焦控制當下衝動。"},{"en":"field of study","zh":"研究領域","note":"只對應學科義。"}],"idioms":[],"family":[{"word":"disciplined","pos":"adj.","meaning":"自律的"},{"word":"disciplinary","pos":"adj.","meaning":"紀律的；學科的"},{"word":"multidisciplinary","pos":"adj.","meaning":"跨多門學科的"}],"examples":[{"text":"Learning to discipline myself helped me stop checking messages whenever I encountered a difficult question.","translationZh":"學習自我約束，幫助我不再每遇到難題就查看訊息。","grammar":"discipline oneself 表自我約束，stop V-ing 表停止某行為，whenever 表每當。","writingTip":"適合寫專注力與讀書習慣。","topic":"學習與科技","source":"self-authored"},{"text":"The project brought together students from different disciplines to design affordable housing for older adults.","translationZh":"這項專案集合不同學科的學生，共同設計長者負擔得起的住宅。","grammar":"from different disciplines 表學科背景，to V 表目的。","writingTip":"可寫跨領域合作回應社會需求。","topic":"設計與高齡","source":"self-authored"}],"usageNote":"discipline 不是只有處罰；academic discipline 指學科，disciplined 常表示自律。"},"distinguish":{"senses":[{"pos":"vt./vi.","meaning":"區分；辨別","usage":"distinguish A from B／distinguish between A and B。"},{"pos":"vt.","meaning":"使具有特色；使出眾","usage":"如 distinguish oneself。"}],"collocations":[{"en":"distinguish fact from opinion","zh":"區分事實與意見","note":""},{"en":"distinguish between two sounds","zh":"辨別兩種聲音","note":""},{"en":"distinguish oneself in a field","zh":"在某領域表現出眾","note":"反身用法。"},{"en":"a distinguishing feature","zh":"可供辨別的特徵","note":""}],"synonyms":[{"en":"differentiate","zh":"區分","note":"較正式，句型可用 differentiate A from B。"},{"en":"recognize","zh":"辨認","note":"強調認出身分或特徵，不必比較兩者。"}],"idioms":[],"family":[{"word":"distinction","pos":"n.","meaning":"差別；卓越"},{"word":"distinctive","pos":"adj.","meaning":"有特色的"},{"word":"distinguished","pos":"adj.","meaning":"卓越的；傑出的"}],"usageNote":"distinctive 指易辨識的特色，distinguished 指傑出。distinguish between A and B，不寫 distinguish between A from B。","examples":[{"text":"Readers need to distinguish facts from opinions when an advertisement presents personal experiences as evidence that a product always works.","translationZh":"廣告把個人經驗當作產品永遠有效的證據時，讀者須區分事實與意見。","grammar":"distinguish A from B；as evidence 表被當成什麼。","writingTip":"媒體識讀作文可指出單一經驗與普遍主張的差別。","topic":"廣告判讀","source":"self-authored"},{"text":"The guide taught us to distinguish between similar birds by observing their beaks, movements, and patterns of sound.","translationZh":"導覽員教我們觀察鳥喙、動作與鳴叫模式，辨別外形相似的鳥。","grammar":"teach + 人 + to V；by observing 後並列三種線索。","writingTip":"自然觀察經驗以具體辨識線索支持描述。","topic":"自然觀察","source":"self-authored"}]},"distribute":{"senses":[{"pos":"vt.","meaning":"分發；分配","usage":"distribute A to 人"},{"pos":"vt.","meaning":"使分布","usage":"常用被動式"}],"collocations":[{"en":"distribute food to families","zh":"分發食物給家庭","note":"to 指收受者"},{"en":"distribute resources fairly","zh":"公平分配資源","note":"副詞修飾動詞"},{"en":"widely distributed species","zh":"分布廣泛的物種","note":"分詞作形容詞"},{"en":"distribute questionnaires","zh":"發放問卷","note":"研究情境"}],"synonyms":[{"en":"hand out","zh":"分發","note":"較日常，適用物品"},{"en":"allocate","zh":"分配","note":"著重有計畫地分派資源"}],"idioms":[],"family":[{"word":"distribution","pos":"n.","meaning":"分配；分布"},{"word":"distributor","pos":"n.","meaning":"經銷商；分發者"}],"examples":[{"text":"Volunteers distributed warm meals to families who had been forced to leave their homes.","translationZh":"志工將熱食分發給被迫離開家園的家庭。","source":"self-authored","grammar":"distribute A to B；who 修飾 families","writingTip":"可敘述救災志工行動。","topic":"community"},{"text":"Because the trees are unevenly distributed, some neighborhoods have much less shade than others.","translationZh":"由於樹木分布不均，有些社區的遮蔭比其他社區少得多。","source":"self-authored","grammar":"be distributed；much 修飾比較級","writingTip":"可討論都市環境資源不均。","topic":"urban life"}],"usageNote":"分給人用 distribute A to B；分散在某範圍可用 distribute A across an area。"},"diverse":{"senses":[{"pos":"adj.","meaning":"多樣的；不同的","usage":"形容群體、背景、觀點或種類。"}],"collocations":[{"en":"diverse backgrounds","zh":"多樣的背景","note":""},{"en":"a diverse range of activities","zh":"多元的活動","note":""},{"en":"diverse perspectives","zh":"不同的觀點","note":""},{"en":"culturally diverse communities","zh":"文化多元的社區","note":""}],"synonyms":[{"en":"varied","zh":"多樣的","note":"強調種類多，不一定涉及群體代表性。"},{"en":"heterogeneous","zh":"異質的","note":"較正式，強調組成部分不同。"}],"idioms":[],"family":[{"word":"diversity","pos":"n.","meaning":"多樣性"},{"word":"diversify","pos":"vt./vi.","meaning":"使多元化；多元發展"},{"word":"diversification","pos":"n.","meaning":"多元化"}],"usageNote":"diverse 描述多樣，diversity 為名詞；多樣背景本身不保證每個人都有發言機會，寫作可再說明如何促進參與。","examples":[{"text":"Students from diverse backgrounds shared family recipes, turning a cooking activity into a chance to learn about one another.","translationZh":"不同背景的學生分享家傳食譜，讓烹飪活動成為彼此了解的機會。","grammar":"from diverse backgrounds 修飾 students；turning 補充活動結果。","writingTip":"文化作文可藉食物與分享過程呈現交流。","topic":"文化交流","source":"self-authored"},{"text":"A group may include diverse perspectives yet still make poor decisions if only its most confident members are heard.","translationZh":"團體即使有多元觀點，若只聽見最有自信成員的聲音，仍可能作出不佳決定。","grammar":"yet 連接轉折；if 子句說明使多元失效的情況。","writingTip":"討論多元團隊時加入公平發言的實際條件。","topic":"團體決策","source":"self-authored"}]},"draw":{"senses":[{"pos":"vt./vi.","meaning":"畫；描繪","usage":"draw a picture / draw with a pencil；繪畫動作可不接受詞。"},{"pos":"vt.","meaning":"拉；拖；拔出","usage":"draw the curtains = 拉動窗簾；draw a sword = 拔劍；draw 接具體物體時通常指拉動。"},{"pos":"vt.","meaning":"吸引","usage":"draw a crowd / draw attention；draw attention to + 人或問題 = 引起對……的注意。"},{"pos":"vt.","meaning":"得出；推論","usage":"draw a conclusion from evidence；from 後接據以推論的資料。"},{"pos":"vt.","meaning":"提取；取得；汲取","usage":"draw money from a bank / draw support from friends；from 指金錢或支持的來源。"},{"pos":"vt.","meaning":"抽出；抽籤選取","usage":"draw a name / a number；指隨機抽選，不是繪製名字或數字。"},{"pos":"vt./vi.","meaning":"打成平手","usage":"The teams drew. / draw a match；drew 為過去式，平局名詞則用 a draw。"},{"pos":"n.","meaning":"平手；平局","usage":"end in a draw；可數名詞，常用於比賽結果。"},{"pos":"n.","meaning":"抽籤；抽獎","usage":"a prize draw；指抽籤或抽獎活動。draw a number 中 draw 則是「抽出」的動詞。"},{"pos":"vi.","meaning":"接近；臨近","usage":"draw near / draw to a close，常用於時間、活動或人接近某個階段。"}],"collocations":[{"en":"draw a conclusion","zh":"得出結論","note":""},{"en":"draw attention to a problem","zh":"引起對問題的注意","note":""},{"en":"draw a picture","zh":"畫圖","note":""},{"en":"end in a draw","zh":"以平手結束","note":""},{"en":"draw up a plan","zh":"擬訂計畫","note":"draw up 表草擬文件；代名詞受詞放中間，如 draw it up。"},{"en":"draw strength from an experience","zh":"從經驗中獲得力量","note":"from 表來源，可用於經驗反思類作文。"}],"synonyms":[{"en":"attract","zh":"吸引","note":"對應吸引注意義"},{"en":"infer","zh":"推論","note":"強調由證據推得，較正式"}],"idioms":[],"family":[{"word":"drawing","pos":"n.","meaning":"畫作；繪畫"},{"word":"drawn","pos":"adj.","meaning":"憔悴的；被抽出的"},{"word":"drew","pos":"v.","meaning":"draw 的過去式：畫；拉；吸引；得出"}],"usageNote":"動詞 draw–drew–drawn。draw a conclusion 表由資料推論，draw a name 表抽籤選人，draw attention to 表引起對……的注意；draw up a plan 是草擬計畫。drawn 作形容詞也可指憔悴，如 a drawn face，應與過去分詞用途分辨。","examples":[{"text":"We should not draw conclusions from a single photograph because it may show only a small part of a complicated event.","translationZh":"我們不應從一張照片就下結論，因為它可能只呈現複雜事件的一小部分。","source":"self-authored","grammar":"draw conclusions from + 證據；because 表不能片面判斷的原因。","writingTip":"主張應理解事件脈絡再下結論。","topic":"照片查核"},{"text":"The colorful mural drew attention to the neglected park and encouraged neighbors to discuss how they could improve the shared space.","translationZh":"色彩鮮豔的壁畫讓人注意荒廢的公園，也鼓勵鄰居討論如何改善共享空間。","source":"self-authored","grammar":"drew attention to + 問題；encouraged + 人 + to V。","writingTip":"可分析壁畫如何促使居民注意並改善公園。","topic":"公共藝術"}]},"due":{"senses":[{"pos":"adj.","meaning":"到期的；應付的","usage":"The payment is due tomorrow. 指付款到期。"},{"pos":"adj.","meaning":"預定的；預期的","usage":"be due to arrive；此處 to 後接原形動詞。"},{"pos":"adj.","meaning":"應得的；應給予的","usage":"due respect／give credit where it is due。"},{"pos":"n.","meaning":"應得的東西或肯定","usage":"give someone their due；不可把 due 一律當形容詞。"},{"pos":"n. pl.","meaning":"會費；應繳費用","usage":"pay membership dues；用複數 dues。"},{"pos":"adv.","meaning":"正向某方位","usage":"due north 指正北方，不表示到期。"}],"collocations":[{"en":"be due tomorrow","zh":"明天到期","note":""},{"en":"be due to arrive","zh":"預定抵達","note":""},{"en":"due to heavy rain","zh":"由於大雨","note":""},{"en":"give someone their due","zh":"給某人應有的肯定","note":""}],"synonyms":[{"en":"scheduled","zh":"預定的","note":"scheduled to arrive 與 due to arrive 相近"},{"en":"owing to","zh":"由於","note":"對應原因片語 due to"}],"idioms":[],"family":[{"word":"dues","pos":"n.","meaning":"會費；應繳款項"},{"word":"overdue","pos":"adj.","meaning":"逾期的；早該發生的"}],"usageNote":"due to + 名詞表原因；be due to + 原形動詞表預定；be due + 時間表期限。due 也有應得肯定的名詞義、dues 會費義，以及 due north 的方位副詞義。","examples":[{"text":"The report is due tomorrow, so our group agreed to finish the charts tonight and check the final draft together.","translationZh":"報告明天截止，因此我們小組同意今晚完成圖表，並一起檢查最後草稿。","source":"self-authored","grammar":"is due tomorrow 表截止時間；agreed to finish/check 為平行動作。","writingTip":"描寫因應期限時的分工與核對。","topic":"報告期限"},{"text":"Due to heavy rain, the outdoor performance was moved into the gym, where volunteers quickly arranged chairs for the audience.","translationZh":"由於大雨，戶外表演移到體育館，志工在那裡迅速為觀眾安排座位。","source":"self-authored","grammar":"due to + 大雨；where 引導體育館內的安排。","writingTip":"交代活動更改原因及志工的具體協助。","topic":"活動遇雨"}]},"effective":{"senses":[{"pos":"adj.","meaning":"有效的；能達到預期效果的","usage":"不等於 efficient（有效率的）。"},{"pos":"adj.","meaning":"生效的","usage":"如 effective from Monday。"}],"collocations":[{"en":"an effective solution to a problem","zh":"有效的問題解決方案","note":""},{"en":"be effective in reducing waste","zh":"有效減少浪費","note":""},{"en":"an effective way to communicate","zh":"有效的溝通方式","note":""},{"en":"effective from next month","zh":"自下個月起生效","note":"規定或合約用語。"}],"synonyms":[{"en":"successful","zh":"成功的","note":"強調達成成果，不完全等於方法有效。"},{"en":"in force","zh":"生效的","note":"只對應法規等已開始施行的意思。"}],"idioms":[],"family":[{"word":"effectiveness","pos":"n.","meaning":"有效性"},{"word":"effectively","pos":"adv.","meaning":"有效地；實際上"},{"word":"ineffective","pos":"adj.","meaning":"無效的"}],"usageNote":"effective 著重能否達成目的；efficient 著重所花時間或資源。某方法有效不代表最省力，兩字不可一律互換。","examples":[{"text":"A clear sign proved more effective than repeated announcements in helping visitors find the correct entrance to the exhibition.","translationZh":"在幫助訪客找到展覽正確入口方面，清楚標示比反覆廣播更有效。","grammar":"proved + 形容詞表結果證明；more effective than + 比較對象。","writingTip":"比較措施時指明衡量的是哪一項具體效果。","topic":"公共指引","source":"self-authored"},{"text":"The new library rules will be effective from Monday, giving students a week to return overdue books without paying fines.","translationZh":"圖書館新規則將於週一生效，學生因此有一週可歸還逾期書籍而免繳罰款。","grammar":"effective from 表生效時間；giving 補充新規則提供的機會。","writingTip":"通知或規範作文可清楚交代生效日與過渡安排。","topic":"圖書館規則","source":"self-authored"}]},"efficient":{"senses":[{"pos":"adj.","meaning":"有效率的","usage":"用較少資源或時間達成目的"}],"collocations":[{"en":"energy-efficient appliances","zh":"節能家電","note":"複合形容詞"},{"en":"an efficient transport system","zh":"有效率的運輸系統","note":"公共建設"},{"en":"use resources efficiently","zh":"有效率地運用資源","note":"副詞形式"},{"en":"an efficient way to work","zh":"有效率的工作方式","note":"way to V"}],"synonyms":[{"en":"productive","zh":"有成效的","note":"著重產出，未必節省資源"},{"en":"well-organized","zh":"安排良好的","note":"可形容帶來效率的流程或人"}],"idioms":[],"family":[{"word":"efficiency","pos":"n.","meaning":"效率"},{"word":"efficiently","pos":"adv.","meaning":"有效率地"},{"word":"inefficient","pos":"adj.","meaning":"沒有效率的"}],"examples":[{"text":"An efficient bus system can shorten travel times and encourage people to leave their cars at home.","translationZh":"有效率的公車系統能縮短交通時間，並鼓勵民眾把車留在家裡。","source":"self-authored","grammar":"efficient 作形容詞修飾 bus system；can 後並列 shorten 與 encourage；encourage people to leave 是人 + to V。","writingTip":"論述大眾運輸時，可把效率具體化為省時與減少開車。","topic":"transport"},{"text":"Our group became more efficient after we assigned tasks according to each member's strengths.","translationZh":"依每位組員的強項分配任務後，我們的團隊變得更有效率。","source":"self-authored","grammar":"become + 比較級；according to + 名詞","writingTip":"適合反思團隊合作策略。","topic":"teamwork"}],"usageNote":"efficient 著重省時、省力或省資源；effective 著重確實達到預期效果。"},"effort":{"senses":[{"pos":"n.","meaning":"努力；嘗試","usage":"可作不可數的投入，也可指一次具體嘗試。"}],"collocations":[{"en":"make an effort to","zh":"努力……","note":""},{"en":"put effort into","zh":"投入心力於……","note":""},{"en":"a joint effort","zh":"共同努力","note":""},{"en":"spare no effort to","zh":"不遺餘力地……","note":""}],"synonyms":[{"en":"attempt","zh":"嘗試","note":"強調採取行動，未必投入很多心力。"},{"en":"endeavor","zh":"努力；嘗試","note":"較正式，可作名詞或動詞。"}],"idioms":[],"family":[{"word":"effortless","pos":"adj.","meaning":"毫不費力的"},{"word":"effortlessly","pos":"adv.","meaning":"毫不費力地"}],"examples":[{"text":"Even a small effort to reduce food waste can make a difference when many households participate.","translationZh":"當許多家庭都參與時，即使是減少食物浪費的小小努力，也能產生影響。","grammar":"effort to V 說明努力內容，when 表條件情境。","writingTip":"適合連結個人行動與集體成果。","topic":"飲食與永續","source":"self-authored"},{"text":"Our joint effort turned an empty classroom into a welcoming reading space for younger students.","translationZh":"我們的共同努力，把一間空教室變成低年級學生喜歡的閱讀空間。","grammar":"turn A into B 表轉變，for 指受益對象。","writingTip":"可描述校園改善的具體成果。","topic":"校園與合作","source":"self-authored"}],"usageNote":"make an effort to do 與 put effort into doing 都常見，介系詞與動詞形式須配合。"},"elbow":{"senses":[{"pos":"n.","meaning":"手肘","usage":""},{"pos":"v.","meaning":"用手肘推擠而前進","usage":""}],"collocations":[{"en":"elbow one's way through a crowd","zh":"用手肘推擠著穿過人群","note":""},{"en":"rest one's elbows on the table","zh":"把手肘靠在桌上","note":""},{"en":"bend one's elbow","zh":"彎曲手肘","note":""},{"en":"elbow someone aside","zh":"用手肘把某人推到一旁","note":""}],"synonyms":[{"en":"push","zh":"推","note":"push 比 elbow 廣泛，不一定用手肘"},{"en":"jostle","zh":"擠撞","note":"強調人群中的碰撞"}],"idioms":[],"family":[{"word":"elbows","pos":"n.","meaning":"手肘（複數）"}],"usageNote":"elbow 作動詞時常搭配 one's way，再接 through 或 into；不可只背身體部位義。","examples":[{"text":"Unable to find a clear path, the reporter elbowed her way through the crowd to reach the injured runner.","translationZh":"找不到暢通的路，記者用手肘推擠著穿過人群，來到受傷的跑者身旁。","source":"self-authored","grammar":"elbowed her way through 表示推擠前進；unable to V 開頭交代原因。","writingTip":"可描寫擁擠現場中的移動方式。","topic":"人群與事故"},{"text":"During the art lesson, I rested my elbows on the desk and carefully sketched the old wooden bridge.","translationZh":"美術課時，我把手肘靠在桌上，仔細描繪那座老木橋。","source":"self-authored","grammar":"rested my elbows on 中 elbows 為名詞複數，on 接支撐表面。","writingTip":"可描寫作畫姿勢與專注的動作細節。","topic":"藝術課"}]},"emission":{"senses":[{"pos":"n.","meaning":"排放；排放物","usage":"複數 emissions 常指氣體排放"}],"collocations":[{"en":"carbon emissions","zh":"碳排放","note":"環境主題"},{"en":"reduce vehicle emissions","zh":"減少車輛排放","note":"政策措施"},{"en":"emission standards","zh":"排放標準","note":"法規用語"},{"en":"greenhouse gas emissions","zh":"溫室氣體排放","note":"科學用語"}],"synonyms":[{"en":"release","zh":"釋放","note":"可指排放過程，範圍較廣"},{"en":"discharge","zh":"排出物；排放","note":"也常用於液體排放"}],"idioms":[],"family":[{"word":"emit","pos":"vt.","meaning":"發出；排放"}],"examples":[{"text":"The city introduced stricter emission standards to reduce air pollution near busy roads.","translationZh":"市府推出更嚴格的排放標準，以降低繁忙道路附近的空氣污染。","source":"self-authored","grammar":"stricter 是比較級形容詞，修飾 emission standards；to reduce 是表示政策目的的不定詞片語。","writingTip":"寫交通環境政策時，指出更嚴排放標準要改善哪個地區的空氣。","topic":"environment"},{"text":"Riding a bicycle for short trips can help lower carbon emissions without increasing travel costs.","translationZh":"短程騎自行車能幫助降低碳排放，又不增加交通費。","source":"self-authored","grammar":"help + 原形動詞；without + V-ing","writingTip":"可用於生活行動倡議。","topic":"transport"}],"usageNote":"emission 是名詞；emit 為動詞；emissions 常用複數指排放的氣體。"},"emphasize":{"senses":[{"pos":"vt.","meaning":"強調；著重","usage":"直接接重點或 that 子句，不加 on。"}],"collocations":[{"en":"emphasize the importance of practice","zh":"強調練習的重要","note":""},{"en":"emphasize a key point","zh":"強調重點","note":""},{"en":"place emphasis on safety","zh":"重視安全","note":"emphasis 是名詞，常接 on。"},{"en":"emphasize that everyone can contribute","zh":"強調人人都能貢獻","note":""}],"synonyms":[{"en":"stress","zh":"強調","note":"動詞義常相近，名詞 stress 另有壓力義。"},{"en":"highlight","zh":"凸顯","note":"常藉視覺、選取或特別提及來突出。"}],"idioms":[],"family":[{"word":"emphasis","pos":"n.","meaning":"強調；重點"},{"word":"emphatic","pos":"adj.","meaning":"強調的；堅決的"},{"word":"emphatically","pos":"adv.","meaning":"強調地；堅決地"}],"usageNote":"emphasize something 與 place emphasis on something 句型不同；不寫 emphasize on something。","examples":[{"text":"The coach emphasized that asking for help was a responsible choice, not a sign that someone had failed.","translationZh":"教練強調，求助是負責任的選擇，不代表一個人失敗了。","grammar":"emphasize + that 子句；asking for help 為子句主詞。","writingTip":"討論求助態度時，可重新說明它代表的正面行動。","topic":"心理支持","source":"self-authored"},{"text":"Our poster emphasized the importance of sorting waste correctly by showing common mistakes beside pictures of the proper bins.","translationZh":"我們在海報上以常見錯誤對照正確垃圾桶圖片，強調正確分類的重要。","grammar":"importance of + V-ing；by showing 表傳達重點的方式。","writingTip":"宣導作文以海報如何呈現內容具體化做法。","topic":"回收宣導","source":"self-authored"}]},"enable":{"senses":[{"pos":"vt.","meaning":"使能夠；讓……得以","usage":"enable someone to V。"},{"pos":"vt.","meaning":"啟用","usage":"如 enable a setting。"}],"collocations":[{"en":"enable students to participate","zh":"讓學生得以參與","note":""},{"en":"enable access to information","zh":"使人得以取得資訊","note":""},{"en":"enable a security feature","zh":"啟用安全功能","note":""},{"en":"enable independent learning","zh":"促進自主學習的實現","note":""}],"synonyms":[{"en":"allow","zh":"讓；允許","note":"可能只是允許，enable 更強調提供能力或條件。"},{"en":"make possible","zh":"使成為可能","note":"需依受詞調整句型，不可直接逐字替換。"}],"idioms":[],"family":[{"word":"enabling","pos":"adj.","meaning":"提供條件的"},{"word":"disable","pos":"vt.","meaning":"使失去功能；停用"},{"word":"enabled","pos":"adj.","meaning":"已啟用的；具備某功能的"}],"usageNote":"enable A to do；不是 enable A do。可說工具提供條件，但實際成效仍須看人如何使用。","examples":[{"text":"Recorded instructions enabled students who missed the workshop to review each step before trying the experiment on their own.","translationZh":"錄製的說明讓錯過工作坊的學生，在獨自嘗試實驗前能複習每個步驟。","grammar":"enable + 人 + to V；who missed 修飾 students。","writingTip":"科技作文說明功能如何回應特定使用者需求。","topic":"學習支援","source":"self-authored"},{"text":"The new ramp enables wheelchair users to enter the building through the same entrance as everyone else.","translationZh":"新的坡道讓輪椅使用者能與其他人一樣，從同一入口進入建築。","grammar":"enable + 使用者 + to enter；the same...as 表相同。","writingTip":"談無障礙設施時連結到平等使用的具體情況。","topic":"無障礙環境","source":"self-authored"}]},"encounter":{"senses":[{"pos":"vt.","meaning":"遇到；遭遇","usage":"直接接人、困難或意外情況。"},{"pos":"n.","meaning":"相遇；遭遇","usage":"an encounter with + 人或事物。"}],"collocations":[{"en":"encounter difficulties","zh":"遇到困難","note":""},{"en":"encounter unexpected resistance","zh":"遭遇意外阻力","note":""},{"en":"a chance encounter","zh":"偶然相遇","note":""},{"en":"an encounter with wildlife","zh":"與野生動物的接觸","note":""}],"synonyms":[{"en":"come across","zh":"偶然遇到；發現","note":"較口語，常強調無意間發現。"},{"en":"face","zh":"面臨","note":"強調必須處理的情況，不必意外遇見。"}],"idioms":[],"family":[{"word":"encountered","pos":"v.","meaning":"遇到（過去式與過去分詞）"},{"word":"encountering","pos":"v.","meaning":"遇到（現在分詞）"}],"usageNote":"動詞 encounter problems 不加 with；名詞 an encounter with someone 則用 with。沒有常用衍生名詞可另造時，列詞形變化即可。","examples":[{"text":"During the interview, we encountered a question that made us reconsider how we had defined success in our project.","translationZh":"訪談時，我們遇到一個問題，讓我們重新思考原先如何定義專題的成功。","grammar":"encounter 直接接 question；made + 人 + 原形 reconsider。","writingTip":"反思作文可用具體提問引出觀念的轉變。","topic":"專題反思","source":"self-authored"},{"text":"An unexpected encounter with a former teacher reminded me of the encouragement that had helped me through a difficult year.","translationZh":"意外遇見以前的老師，讓我想起曾幫我度過艱難一年的鼓勵。","grammar":"encounter 作名詞主詞；remind + 人 + of + 事物。","writingTip":"敘事以偶遇作為回憶過去支持的起點。","topic":"師生回憶","source":"self-authored"}]},"encourage":{"senses":[{"pos":"vt.","meaning":"鼓勵；促進","usage":"可接人，也可接行為或現象。"}],"collocations":[{"en":"encourage someone to try","zh":"鼓勵某人嘗試","note":""},{"en":"encourage participation","zh":"鼓勵參與","note":""},{"en":"encourage healthy habits","zh":"促進健康習慣","note":""},{"en":"be encouraged by","zh":"因……而受到鼓舞","note":""}],"synonyms":[{"en":"motivate","zh":"激勵","note":"強調提供採取行動的動機。"},{"en":"promote","zh":"促進","note":"常針對政策、活動或發展，不一定鼓勵特定的人。"}],"idioms":[],"family":[{"word":"encouragement","pos":"n.","meaning":"鼓勵"},{"word":"encouraging","pos":"adj.","meaning":"令人鼓舞的"},{"word":"encouraged","pos":"adj.","meaning":"受到鼓舞的"}],"examples":[{"text":"My teacher encouraged me to enter the writing contest even though I had never shared my stories publicly.","translationZh":"雖然從未公開分享故事，老師仍鼓勵我參加寫作比賽。","grammar":"encourage someone to V，even though 表讓步。","writingTip":"可寫師長鼓勵如何促成第一步。","topic":"學習與表達","source":"self-authored"},{"text":"Safer bicycle lanes could encourage more residents to leave their cars at home for short trips.","translationZh":"更安全的自行車道，可能鼓勵更多居民在短程出門時不開車。","grammar":"encourage someone to V，could 表可能效果。","writingTip":"適合提出改善交通的具體措施。","topic":"交通與環境","source":"self-authored"}],"usageNote":"encouraging 形容令人鼓舞的事物，encouraged 描述受到鼓舞的人。"},"energy":{"senses":[{"pos":"n.","meaning":"能源","usage":"electricity、heat 等"},{"pos":"n.","meaning":"精力","usage":"人的活動能力"}],"collocations":[{"en":"renewable energy","zh":"再生能源","note":"環境主題"},{"en":"save energy","zh":"節省能源","note":"日常措施"},{"en":"a source of energy","zh":"能源來源","note":"source of"},{"en":"have the energy to exercise","zh":"有精力運動","note":"人的體力"}],"synonyms":[{"en":"power","zh":"動力；電力","note":"對應供設備使用的能源"},{"en":"vitality","zh":"活力","note":"對應人的精神與精力"}],"idioms":[],"family":[{"word":"energetic","pos":"adj.","meaning":"精力充沛的"},{"word":"energetically","pos":"adv.","meaning":"充滿活力地"}],"examples":[{"text":"The school installed solar panels to produce clean energy and lower its electricity bills.","translationZh":"學校安裝太陽能板，生產乾淨能源並降低電費。","source":"self-authored","grammar":"to V 表目的；並列原形動詞","writingTip":"可用於校園永續設施。","topic":"energy"},{"text":"After a full night's sleep, I had enough energy to concentrate during the difficult exam.","translationZh":"睡足一晚後，我有足夠精力在困難的考試中保持專注。","source":"self-authored","grammar":"enough energy to V","writingTip":"可連結生活習慣與學習表現。","topic":"health"}],"usageNote":"energy 通常不可數；既可指能源，也可指人的精力。"},"engage":{"senses":[{"pos":"vt.","meaning":"使參與；吸引注意；聘用","usage":"可接人作受詞。"},{"pos":"vi.","meaning":"參與；從事","usage":"常用 engage in 或 engage with。"}],"collocations":[{"en":"engage in discussion","zh":"參與討論","note":""},{"en":"engage with a text","zh":"深入理解文本","note":""},{"en":"engage students in learning","zh":"讓學生投入學習","note":""},{"en":"be engaged to someone","zh":"與某人訂婚","note":"engaged to 與 engaged in 意義不同。"}],"synonyms":[{"en":"involve","zh":"讓……參與","note":"常強調納入活動或與事件相關。"},{"en":"participate","zh":"參與","note":"不及物動詞，通常加 in。"}],"idioms":[],"family":[{"word":"engagement","pos":"n.","meaning":"參與；訂婚；約定"},{"word":"engaging","pos":"adj.","meaning":"引人入勝的"},{"word":"engaged","pos":"adj.","meaning":"投入的；已訂婚的"}],"examples":[{"text":"Interactive exhibits engage visitors by allowing them to test ideas instead of simply reading descriptions.","translationZh":"互動展品讓訪客親自測試想法，而非只閱讀說明，藉此吸引他們投入。","grammar":"by allowing someone to V 表方式，instead of 後接動名詞。","writingTip":"可討論博物館與主動學習。","topic":"文化與教育","source":"self-authored"},{"text":"Students who engage in thoughtful discussions often discover weaknesses in arguments they once accepted without question.","translationZh":"投入深入討論的學生，常發現自己曾毫不質疑接受的論點其實有弱點。","grammar":"engage in V-ing，省略關係代名詞的 arguments 子句。","writingTip":"適合寫討論促進批判思考。","topic":"學習與思辨","source":"self-authored"}],"usageNote":"engage in 接活動；engage with 可表示與人互動或認真處理想法。"},"enhance":{"senses":[{"pos":"vt.","meaning":"提升；增強","usage":"提高已有事物的品質、效果或價值"}],"collocations":[{"en":"enhance learning","zh":"提升學習效果","note":"教育情境"},{"en":"enhance the quality of life","zh":"提升生活品質","note":"社會議題"},{"en":"enhance public awareness","zh":"提高公眾意識","note":"倡議用語"},{"en":"enhance the flavor","zh":"增添風味","note":"飲食情境"}],"synonyms":[{"en":"improve","zh":"改善","note":"範圍廣，可含修正缺點"},{"en":"strengthen","zh":"加強","note":"著重程度或力量增加"}],"idioms":[],"family":[{"word":"enhancement","pos":"n.","meaning":"提升；增強"},{"word":"enhanced","pos":"adj.","meaning":"提升的；增強的"}],"examples":[{"text":"Adding captions to educational videos can enhance learning for students who struggle with spoken English.","translationZh":"在教學影片加上字幕，能提升聽懂英文有困難學生的學習效果。","source":"self-authored","grammar":"V-ing 作主詞；who 修飾 students","writingTip":"可討論具體教學輔助措施。","topic":"education"},{"text":"The walking path enhances the quality of life by giving residents a safe place to exercise.","translationZh":"這條步道提供居民安全運動的場所，提升了生活品質。","source":"self-authored","grammar":"enhance + 受詞；by + V-ing","writingTip":"可連結公共建設與生活需要。","topic":"community"}],"usageNote":"enhance 通常指把原本已有的品質或效果提高，不等同於全新創造。"},"ensure":{"senses":[{"pos":"vt.","meaning":"確保","usage":"ensure + 名詞 或 that 子句"}],"collocations":[{"en":"ensure public safety","zh":"確保公共安全","note":"目的搭配"},{"en":"ensure equal access","zh":"確保平等取得機會","note":"社會議題"},{"en":"ensure that rules are followed","zh":"確保規則被遵守","note":"that 子句"},{"en":"ensure a steady supply","zh":"確保穩定供應","note":"資源管理"}],"synonyms":[{"en":"make sure","zh":"確保","note":"較日常，常接 that 子句"},{"en":"guarantee","zh":"保證","note":"語氣較強，可能含正式承諾"}],"idioms":[],"family":[],"examples":[{"text":"The school checks playground equipment regularly to ensure that children can use it safely.","translationZh":"學校定期檢查遊樂設備，以確保孩子能安全使用。","source":"self-authored","grammar":"ensure that + 子句","writingTip":"可寫安全管理的具體方法。","topic":"school"},{"text":"Clear instructions help ensure equal access to emergency information for people with different language backgrounds.","translationZh":"清楚的指示有助於確保不同語言背景的人，都能平等取得緊急資訊。","source":"self-authored","grammar":"help 後直接接原形動詞 ensure；ensure 的受詞是 equal access；to emergency information 說明 access 的內容。","writingTip":"寫公共資訊的平等取得時，可指出清楚指示如何幫助不同語言使用者。","topic":"inclusion"}],"usageNote":"ensure 常用 ensure that 或 ensure something；勿把 ensure、insure（投保）混用。"},"environment":{"senses":[{"pos":"n.","meaning":"自然環境","usage":"常用 the environment"},{"pos":"n.","meaning":"生活或工作環境","usage":"可接修飾語"}],"collocations":[{"en":"protect the environment","zh":"保護環境","note":"常見搭配"},{"en":"a supportive learning environment","zh":"支持性的學習環境","note":"教育主題"},{"en":"the natural environment","zh":"自然環境","note":"與人造環境對比"},{"en":"adapt to a new environment","zh":"適應新環境","note":"to 為介系詞"}],"synonyms":[{"en":"surroundings","zh":"周遭環境","note":"通常指身邊的實體條件"},{"en":"setting","zh":"背景；環境","note":"著重活動發生的場所或情境"}],"idioms":[],"family":[{"word":"environmental","pos":"adj.","meaning":"環境的"},{"word":"environmentally","pos":"adv.","meaning":"在環境方面"}],"examples":[{"text":"A supportive learning environment encourages students to ask questions even when they fear making mistakes.","translationZh":"支持性的學習環境，能鼓勵學生即使害怕犯錯，也願意提問。","source":"self-authored","grammar":"encourage 人 to V；fear + V-ing","writingTip":"可用於班級互動與教育討論。","topic":"education"},{"text":"We can protect the environment by repairing useful items instead of throwing them away.","translationZh":"我們能修理仍可用的物品，取代直接丟棄，來保護環境。","source":"self-authored","grammar":"by + V-ing；instead of + V-ing","writingTip":"可用日常例子說明減廢行動。","topic":"sustainability"}],"usageNote":"environment 可指自然環境，也可指人的工作、學習或生活條件。"},"establish":{"senses":[{"pos":"vt.","meaning":"建立；確立；證實","usage":"可指成立組織、建立關係或查明事實。"}],"collocations":[{"en":"establish a relationship","zh":"建立關係","note":""},{"en":"establish a routine","zh":"建立固定作息","note":""},{"en":"establish a business","zh":"創立企業","note":""},{"en":"establish the facts","zh":"查明事實","note":""}],"synonyms":[{"en":"set up","zh":"設立","note":"較口語，多指組織或設備。"},{"en":"verify","zh":"核實","note":"只對應查明或證實義，不表示成立組織。"}],"idioms":[],"family":[{"word":"establishment","pos":"n.","meaning":"建立；機構"},{"word":"established","pos":"adj.","meaning":"已確立的；公認的"}],"examples":[{"text":"The volunteers established a regular delivery service for older residents who could not easily leave home.","translationZh":"志工為不方便外出的年長居民，建立了定期送貨服務。","grammar":"who 引導限定關係子句，could not easily V 表行動困難。","writingTip":"可寫服務如何回應社區需求。","topic":"高齡與服務","source":"self-authored"},{"text":"Before sharing the story online, we should establish the facts by checking reliable sources.","translationZh":"把故事分享到網路前，我們應查閱可靠來源，先確認事實。","grammar":"before V-ing，by V-ing 說明核實方式。","writingTip":"適合討論媒體識讀與負責任分享。","topic":"媒體與資訊","source":"self-authored"}],"usageNote":"establish a fact 指查明並確定事實；established 作形容詞也可表示已有聲望。"},"estimate":{"senses":[{"pos":"vt.","meaning":"估計","usage":"estimate + 數量 或 that 子句"},{"pos":"n.","meaning":"估計值","usage":"an estimate of"}],"collocations":[{"en":"estimate the cost","zh":"估算費用","note":"計畫情境"},{"en":"estimate the number of visitors","zh":"估計訪客人數","note":"數量資訊"},{"en":"a rough estimate","zh":"粗略估計","note":"rough 表大致"},{"en":"an estimated arrival time","zh":"預計抵達時間","note":"分詞形容詞"}],"synonyms":[{"en":"approximate","zh":"估算","note":"強調接近而非精確"},{"en":"assess","zh":"評估","note":"範圍較廣，不限數量"}],"idioms":[],"family":[{"word":"estimation","pos":"n.","meaning":"估計；看法"},{"word":"estimated","pos":"adj.","meaning":"估計的"},{"word":"underestimate","pos":"vt.","meaning":"低估"}],"examples":[{"text":"The organizers estimated the cost of the event before deciding how many tickets to sell.","translationZh":"主辦單位先估算活動費用，再決定販售多少張票。","source":"self-authored","grammar":"before + V-ing；how many + 名詞 + to V","writingTip":"可敘述規劃與決策。","topic":"school"},{"text":"According to a rough estimate, the library receives more visitors on weekends than on weekdays.","translationZh":"根據粗略估計，圖書館週末的訪客比平日多。","source":"self-authored","grammar":"According to 後接名詞片語 a rough estimate；more visitors...than... 使用比較級，省略重複的 receives。","writingTip":"呈現概估資料時，以 rough estimate 標明精確程度，再比較週末與平日。","topic":"data"}],"usageNote":"estimate 常指數量、費用或時間的大致估算；不可把估計值寫成精確事實。"},"evaluate":{"senses":[{"pos":"vt.","meaning":"評估；評價","usage":"依據準則檢視品質、效果或價值。"}],"collocations":[{"en":"evaluate the results","zh":"評估結果","note":""},{"en":"evaluate the effectiveness of a program","zh":"評估計畫的有效性","note":""},{"en":"evaluate different options","zh":"評估不同選項","note":""},{"en":"a careful evaluation of the evidence","zh":"對證據的審慎評估","note":"名詞搭配。"}],"synonyms":[{"en":"assess","zh":"評估","note":"常與 evaluate 相近，可接風險、能力或影響。"},{"en":"appraise","zh":"評估價值；評價","note":"較正式，常指物品估價或工作表現。"}],"idioms":[],"family":[{"word":"evaluation","pos":"n.","meaning":"評估；評價"},{"word":"evaluative","pos":"adj.","meaning":"評估性的"},{"word":"evaluator","pos":"n.","meaning":"評估者"}],"usageNote":"evaluate 不只是算出分數；需交代評估標準。evaluate the evidence 是判斷證據品質，並不自動證明某說法。","examples":[{"text":"Before expanding the program, teachers evaluated whether students could use the new vocabulary in sentences of their own.","translationZh":"擴大計畫前，老師評估學生能否把新單字用在自己造的句子中。","grammar":"evaluate + whether 子句；of their own 表自己創作的。","writingTip":"教育作文可用實際運用能力說明評估標準。","topic":"詞彙應用","source":"self-authored"},{"text":"We evaluated the two designs according to cost, safety, and ease of use rather than appearance alone.","translationZh":"我們依成本、安全與易用性評估兩種設計，而不只看外觀。","grammar":"according to 後列評估準則；rather than 表比較取捨。","writingTip":"比較方案時先建立明確、可解釋的標準。","topic":"設計評估","source":"self-authored"}]},"evidence":{"senses":[{"pos":"n.","meaning":"證據","usage":"通常不可數，a piece of evidence"}],"collocations":[{"en":"provide evidence","zh":"提供證據","note":"研究語境"},{"en":"evidence of damage","zh":"受損的證據","note":"of 接所證明事項"},{"en":"scientific evidence","zh":"科學證據","note":"研究依據"},{"en":"strong evidence that something happened","zh":"某事發生的有力證據","note":"that 子句"}],"synonyms":[{"en":"proof","zh":"證明","note":"通常語氣更強，意味已證實"},{"en":"indication","zh":"跡象","note":"證據強度較弱"}],"idioms":[],"family":[{"word":"evident","pos":"adj.","meaning":"明顯的"},{"word":"evidently","pos":"adv.","meaning":"顯然"}],"examples":[{"text":"The researchers found evidence that warmer sea temperatures were affecting the fish's breeding season.","translationZh":"研究人員發現證據顯示，升高的海水溫度正影響魚類的繁殖季。","source":"self-authored","grammar":"evidence 為不可數名詞；that warmer sea temperatures... 是解釋 evidence 內容的同位語子句。","writingTip":"報告研究發現時，先指出有證據，再陳述受影響的具體現象。","topic":"science"},{"text":"Before sharing the story online, I looked for reliable evidence to support its main claim.","translationZh":"在網路分享這則故事前，我先尋找可靠證據支持它的主要主張。","source":"self-authored","grammar":"Before sharing 是 before + V-ing；looked for 後接 evidence；to support 表尋找證據的用途。","writingTip":"分享網路資訊前查證，可作為媒體識讀的具體行動例子。","topic":"media"}],"usageNote":"evidence 通常不可數，不寫 an evidence 或 evidences；可用 a piece of evidence。"},"exacerbate":{"senses":[{"pos":"v.","meaning":"使問題、病痛或衝突惡化","usage":""}],"collocations":[{"en":"exacerbate the problem","zh":"使問題惡化","note":""},{"en":"exacerbate the situation","zh":"使情況惡化","note":""},{"en":"exacerbate existing inequalities","zh":"加劇既有的不平等","note":""},{"en":"exacerbate the pain","zh":"加劇疼痛","note":""}],"synonyms":[{"en":"worsen","zh":"使惡化","note":"worsen 也能作不及物動詞，exacerbate 通常需要受詞"},{"en":"aggravate","zh":"加重","note":"可用於問題或病痛"}],"idioms":[{"en":"add fuel to the fire","zh":"火上加油","note":"用於使衝突或糟糕情勢更嚴重，不適用所有病痛語境"}],"family":[{"word":"exacerbation","pos":"n.","meaning":"惡化；加劇"}],"usageNote":"正式語體及物動詞；重點是「使原本已存在的負面情況更糟」。","examples":[{"text":"The lack of clear communication may exacerbate the conflict between residents and the company planning to build a factory.","translationZh":"缺乏清楚的溝通，可能使居民與計畫興建工廠的公司之間的衝突惡化。","source":"self-authored","grammar":"may + 原形動詞；exacerbate 的受詞為 the conflict。","writingTip":"可分析溝通不足如何使既有衝突更嚴重。","topic":"社區衝突"},{"text":"Sharing an unverified rumor online can add fuel to the fire and exacerbate tensions within a small community.","translationZh":"在網路上分享未經證實的謠言，可能火上加油，加劇小社群內的緊張。","source":"self-authored","grammar":"sharing 動名詞片語作主詞；add/exacerbate 為並列原形動詞。","writingTip":"把分享未查證訊息連結到群體緊張的後果。","topic":"網路謠言"}]},"exception":{"senses":[{"pos":"n.","meaning":"例外","usage":"an exception to + 規則；with the exception of 表除外。"}],"collocations":[{"en":"an exception to the rule","zh":"規則的例外","note":""},{"en":"make an exception for someone","zh":"為某人破例","note":""},{"en":"with the exception of Sunday","zh":"除了星期日之外","note":""},{"en":"without exception","zh":"無一例外","note":"語氣絕對，須有依據。"}],"synonyms":[{"en":"exclusion","zh":"排除","note":"指刻意不納入，未必是規則的特例。"},{"en":"unusual case","zh":"特殊情況","note":"可解釋例外義，但不一定違反某項規則。"}],"idioms":[],"family":[{"word":"exceptional","pos":"adj.","meaning":"傑出的；例外的"},{"word":"exceptionally","pos":"adv.","meaning":"格外地；異常地"}],"usageNote":"exceptional 常表示格外出色，不一定是違反規則。區分 exception to a rule 與 with the exception of + 被排除項目。","examples":[{"text":"The museum is open every afternoon with the exception of Monday, when staff check the exhibits and clean the rooms.","translationZh":"博物館每天下午開放，星期一除外，工作人員當天會檢查展品並清理展間。","grammar":"with the exception of 接排除項目；when 修飾 Monday。","writingTip":"介紹開放時間時補充例外日期及其原因。","topic":"文化設施","source":"self-authored"},{"text":"Although late entries were usually rejected, the organizers made an exception for students whose school had lost internet service.","translationZh":"主辦人通常不接受逾期報名，但對學校網路中斷的學生破例。","grammar":"make an exception for + 人；whose 表學生所屬學校。","writingTip":"討論公平時可分析特殊情況與一致規則的關係。","topic":"規則與公平","source":"self-authored"}]},"exclude":{"senses":[{"pos":"vt.","meaning":"排除；不包括","usage":"exclude A from B；也可指排除某種可能。"}],"collocations":[{"en":"exclude someone from an activity","zh":"不讓某人參與活動","note":""},{"en":"exclude unnecessary details","zh":"排除多餘細節","note":""},{"en":"exclude the possibility of error","zh":"排除出錯的可能","note":""},{"en":"a price excluding delivery","zh":"未含運費的價格","note":""}],"synonyms":[{"en":"leave out","zh":"省略；未納入","note":"較口語，可能無意遺漏。"},{"en":"rule out","zh":"排除可能","note":"只對應排除解釋或選項，不是排斥某人參與。"}],"idioms":[],"family":[{"word":"exclusion","pos":"n.","meaning":"排除"},{"word":"exclusive","pos":"adj.","meaning":"專有的；排他的"},{"word":"excluded","pos":"adj.","meaning":"被排除的"}],"usageNote":"exclude 的反義詞 include；exclusive 可能指專屬，也可能使人難以加入，需依對象判斷。","examples":[{"text":"Holding every meeting late at night may exclude classmates who depend on limited bus services to get home.","translationZh":"每次都深夜開會，可能讓依賴有限公車班次回家的同學無法參與。","grammar":"Holding...為動名詞主詞；who depend on 修飾 classmates。","writingTip":"分析活動安排時，指出誰可能因交通條件而被排除。","topic":"參與與交通","source":"self-authored"},{"text":"The survey excluded responses without a stated age because the researchers wanted to compare habits across different age groups.","translationZh":"調查排除未填年齡的回覆，因為研究者希望比較不同年齡層的習慣。","grammar":"exclude 直接接 responses；without a stated age 為修飾語。","writingTip":"描述資料處理時說明排除條件，讓讀者理解範圍。","topic":"調查方法","source":"self-authored"}]},"expand":{"senses":[{"pos":"vi./vt.","meaning":"擴大；擴展","usage":"範圍、業務或規模"},{"pos":"vi.","meaning":"膨脹","usage":"材料受熱"},{"pos":"vi.","meaning":"詳述","usage":"expand on + 主題"}],"collocations":[{"en":"expand the program","zh":"擴大計畫","note":"及物搭配"},{"en":"expand into new markets","zh":"拓展至新市場","note":"into 表新範圍"},{"en":"expand on an idea","zh":"詳述一個想法","note":"on 為介系詞"},{"en":"expand knowledge","zh":"拓展知識","note":"學習情境"}],"synonyms":[{"en":"extend","zh":"延伸；擴展","note":"常指範圍或期限"},{"en":"enlarge","zh":"擴大","note":"著重尺寸增加"}],"idioms":[],"family":[{"word":"expansion","pos":"n.","meaning":"擴張；膨脹"},{"word":"expansive","pos":"adj.","meaning":"廣闊的"}],"examples":[{"text":"The library plans to expand its reading program to include children from nearby rural communities.","translationZh":"圖書館計畫擴大閱讀活動，納入附近農村的孩子。","source":"self-authored","grammar":"plan to V；to include 說明擴大範圍","writingTip":"適合教育資源主題。","topic":"education"},{"text":"During the discussion, the speaker expanded on her idea by giving a concrete example.","translationZh":"討論時，講者透過具體例子，進一步闡述自己的想法。","source":"self-authored","grammar":"expand on + 名詞；by + V-ing","writingTip":"可描寫表達技巧。","topic":"communication"}],"usageNote":"expand on 意為詳述；expand into 表拓展至新領域或地區。"},"experience":{"senses":[{"pos":"n.","meaning":"經驗；經歷","usage":"知識與技能的經驗不可數，一次經歷可數。"},{"pos":"vt.","meaning":"經歷；體驗","usage":"直接接情緒或事件。"}],"collocations":[{"en":"gain experience","zh":"累積經驗","note":""},{"en":"a memorable experience","zh":"難忘的經歷","note":""},{"en":"experience difficulty","zh":"遭遇困難","note":""},{"en":"have experience in teaching","zh":"有教學經驗","note":""}],"synonyms":[{"en":"undergo","zh":"經歷","note":"常接治療、改變或困難，不常接愉快活動。"},{"en":"encounter","zh":"遇到","note":"強調遇見某事，不一定整段體驗。"}],"idioms":[],"family":[{"word":"experienced","pos":"adj.","meaning":"有經驗的"},{"word":"inexperienced","pos":"adj.","meaning":"缺乏經驗的"},{"word":"experiential","pos":"adj.","meaning":"體驗式的"}],"examples":[{"text":"Working at the community kitchen gave me valuable experience in preparing meals for people with different needs.","translationZh":"在社區廚房服務，讓我獲得為不同需求的人準備餐點的寶貴經驗。","grammar":"experience in V-ing，with different needs 修飾 people。","writingTip":"可寫服務學習所得到的實務能力。","topic":"服務與飲食","source":"self-authored"},{"text":"Many newcomers experience loneliness at first, even when they are excited about living in a different country.","translationZh":"許多新移居者一開始會感到孤單，即使他們對住在另一個國家很興奮。","grammar":"experience 為及物動詞，even when 表同時存在的相反感受。","writingTip":"適合討論適應新環境的複雜心情。","topic":"文化與適應","source":"self-authored"}],"usageNote":"many experiences 指多次經歷；much experience 指大量經驗，須依意思選可數或不可數。"},"experiment":{"senses":[{"pos":"n.","meaning":"實驗；試驗","usage":"a scientific experiment 或 an experiment in 新做法。"},{"pos":"vi.","meaning":"做實驗；嘗試","usage":"experiment with + 材料或方法。"}],"collocations":[{"en":"conduct an experiment","zh":"進行實驗","note":""},{"en":"an experiment on plant growth","zh":"關於植物生長的實驗","note":""},{"en":"experiment with different materials","zh":"試用不同材料","note":""},{"en":"experimental results","zh":"實驗結果","note":"形容詞搭配。"}],"synonyms":[{"en":"test","zh":"測試；試驗","note":"範圍較廣，未必有控制變因。"},{"en":"trial","zh":"試行；試驗","note":"常指正式採用前的一段試用。"}],"idioms":[],"family":[{"word":"experimental","pos":"adj.","meaning":"實驗的；試驗性的"},{"word":"experimentally","pos":"adv.","meaning":"以實驗方式"},{"word":"experimentation","pos":"n.","meaning":"實驗；嘗試"}],"usageNote":"experiment 作動詞常不及物，用 experiment with。科學實驗應交代比較條件，不把一次結果宣稱為普遍規律。","examples":[{"text":"In our experiment, we changed the amount of light while keeping the soil and watering schedule the same.","translationZh":"在實驗中，我們改變光照量，同時維持相同土壤與澆水時程。","grammar":"while keeping 表同時維持；keep + 受詞 + the same。","writingTip":"科學寫作可清楚指出改變的變因與固定條件。","topic":"植物實驗","source":"self-authored"},{"text":"The art club experimented with recycled paper to find a material that was inexpensive and strong enough for the display.","translationZh":"美術社試用回收紙，尋找價格低且足以支撐展示的材料。","grammar":"experiment with + 材料；strong enough for 表足夠適用。","writingTip":"實作敘事說明試用材料的具體標準。","topic":"材料試作","source":"self-authored"}]},"explanation":{"senses":[{"pos":"n.","meaning":"解釋；說明","usage":"explanation for + 現象或原因，of + 規則或內容。"}],"collocations":[{"en":"give a clear explanation","zh":"作清楚說明","note":""},{"en":"an explanation for the delay","zh":"延誤的原因說明","note":""},{"en":"an explanation of the rules","zh":"規則的說明","note":""},{"en":"seek an alternative explanation","zh":"尋找另一種解釋","note":""}],"synonyms":[{"en":"account","zh":"敘述；解釋","note":"an account of 常指事件經過，不一定說明原因。"},{"en":"reason","zh":"理由；原因","note":"可指成因本身，explanation 是用來說明的內容。"}],"idioms":[],"family":[{"word":"explain","pos":"vt./vi.","meaning":"解釋"},{"word":"explanatory","pos":"adj.","meaning":"解說的"},{"word":"unexplained","pos":"adj.","meaning":"未獲解釋的"}],"usageNote":"explain something to someone；不寫 explain someone something。explanation 不等於 excuse，合理說明仍可承認責任。","examples":[{"text":"The guide gave a clear explanation of the rules before allowing visitors to handle the objects used in the demonstration.","translationZh":"導覽員先清楚說明規則，才讓訪客拿取示範所使用的物件。","grammar":"explanation of + 規則；allow + 人 + to V；used 為分詞。","writingTip":"活動敘事可交代操作之前的說明如何建立安全流程。","topic":"體驗導覽","source":"self-authored"},{"text":"A rise in sales has several possible explanations, so we should not assume that the new advertisement caused it.","translationZh":"銷售上升可能有多種解釋，因此不能直接假設是新廣告造成的。","grammar":"several possible explanations 為複數；assume that 引導未經證實的因果。","writingTip":"圖表作文避免把同時發生的兩件事直接當成因果。","topic":"商業圖表","source":"self-authored"}]},"expose":{"senses":[{"pos":"vt.","meaning":"使接觸；使暴露","usage":"expose someone to + 經驗、刺激或危險。"},{"pos":"vt.","meaning":"揭露","usage":"直接接問題、真相或不當行為。"}],"collocations":[{"en":"expose students to different viewpoints","zh":"讓學生接觸不同觀點","note":""},{"en":"be exposed to sunlight","zh":"曝曬於陽光下","note":""},{"en":"expose a hidden problem","zh":"揭露隱藏的問題","note":""},{"en":"expose personal information","zh":"暴露個人資訊","note":""}],"synonyms":[{"en":"reveal","zh":"揭露","note":"對應使人知道原本不明的資訊。"},{"en":"subject to","zh":"使遭受","note":"常含不利經驗；須用 subject A to B。"}],"idioms":[],"family":[{"word":"exposure","pos":"n.","meaning":"接觸；暴露；揭露"},{"word":"exposed","pos":"adj.","meaning":"暴露的；無遮蔽的"}],"usageNote":"expose A to B 可指有益經驗，也可指危險；判讀正負面要看 B，不可只背「使遭受」。","examples":[{"text":"Reading stories from different cultures exposes students to viewpoints they may not encounter in their immediate surroundings.","translationZh":"閱讀不同文化的故事，讓學生接觸身邊環境不一定會遇到的觀點。","grammar":"Reading 為主詞；expose A to B；viewpoints 後省略關係代名詞。","writingTip":"文化閱讀作文可說明內容如何擴展接觸觀點的範圍。","topic":"跨文化閱讀","source":"self-authored"},{"text":"Sharing a photo of a ticket online may expose personal information that strangers could use without the owner's permission.","translationZh":"在網路分享票券照片，可能暴露陌生人可未經本人同意使用的個人資訊。","grammar":"Sharing 為動名詞主詞；that 引導關係子句修飾 information。","writingTip":"數位生活作文以票券等具體物件說明隱私風險。","topic":"網路隱私","source":"self-authored"}]},"exposure":{"senses":[{"pos":"n.","meaning":"接觸；暴露","usage":"exposure to + 事物"},{"pos":"n.","meaning":"曝光；公開","usage":"媒體或攝影情境"}],"collocations":[{"en":"exposure to sunlight","zh":"日光曝曬","note":"to 為介系詞"},{"en":"exposure to different cultures","zh":"接觸不同文化","note":"正面語境"},{"en":"limit exposure to noise","zh":"限制接觸噪音","note":"健康防護"},{"en":"media exposure","zh":"媒體曝光","note":"公眾能見度"}],"synonyms":[{"en":"contact","zh":"接觸","note":"較廣泛，不必持續"},{"en":"publicity","zh":"宣傳；曝光","note":"對應媒體能見度，不等同於環境暴露"}],"idioms":[],"family":[{"word":"expose","pos":"vt.","meaning":"使接觸；揭露"},{"word":"exposed","pos":"adj.","meaning":"暴露的；無遮蔽的"}],"examples":[{"text":"Regular exposure to spoken English helps learners recognize natural patterns of rhythm and pronunciation.","translationZh":"經常接觸英語口語，有助於學習者辨識自然的節奏與發音模式。","source":"self-authored","grammar":"exposure to + 名詞 作主詞","writingTip":"可用於語言學習方法。","topic":"education"},{"text":"Workers should limit their exposure to loud noise by using suitable protective equipment.","translationZh":"工作者應使用適當防護設備，減少接觸高分貝噪音。","source":"self-authored","grammar":"limit exposure to；by + V-ing","writingTip":"可討論工作場所的健康措施。","topic":"health"}],"usageNote":"exposure to 可指有益的接觸，也可指有害因素的暴露；依受詞判斷。"},"express":{"senses":[{"pos":"vt.","meaning":"表達；表示","usage":"常接意見、感受或感謝。"},{"pos":"adj.","meaning":"快遞的；快速的","usage":"如 express delivery。"},{"pos":"n.","meaning":"快車","usage":"如 an express to the airport。"}],"collocations":[{"en":"express an opinion","zh":"表達意見","note":""},{"en":"express concern about","zh":"表達對……的憂慮","note":""},{"en":"express gratitude to","zh":"向……表達感謝","note":""},{"en":"express delivery","zh":"快遞配送","note":""}],"synonyms":[{"en":"convey","zh":"傳達","note":"可透過語言、動作或作品表達訊息。"},{"en":"voice","zh":"表達","note":"常接疑慮、反對或意見，比一般 express 範圍窄。"}],"idioms":[],"family":[{"word":"expression","pos":"n.","meaning":"表達；表情；用語"},{"word":"expressive","pos":"adj.","meaning":"富於表現力的"},{"word":"expressively","pos":"adv.","meaning":"富有表情地"}],"examples":[{"text":"Art allows students to express feelings that they may find difficult to explain in ordinary conversation.","translationZh":"藝術讓學生能表達那些在日常交談中可能難以說清楚的感受。","grammar":"allow someone to V，find something difficult to V。","writingTip":"可寫藝術在情緒表達上的價值。","topic":"藝術與心理","source":"self-authored"},{"text":"Residents expressed concern about the new building's impact on sunlight, traffic, and the neighborhood's familiar atmosphere.","translationZh":"居民對新建築影響日照、交通及社區熟悉氛圍，表達了憂慮。","grammar":"express concern about，impact on 表對……的影響。","writingTip":"適合描述公共建設爭議中的居民觀點。","topic":"社區與建設","source":"self-authored"}],"usageNote":"express 為動詞時直接接受詞；express oneself 指表達自己的想法或情感。"},"face":{"senses":[{"pos":"n.","meaning":"臉；表面","usage":""},{"pos":"v.","meaning":"面對；朝向","usage":""}],"collocations":[{"en":"face a challenge","zh":"面對挑戰","note":""},{"en":"face the sea","zh":"朝向海洋","note":""},{"en":"face-to-face communication","zh":"面對面溝通","note":""},{"en":"in the face of difficulty","zh":"面對困難時","note":""}],"synonyms":[{"en":"confront","zh":"面對","note":"常帶直接處理難題意味"},{"en":"encounter","zh":"遇到","note":"不一定積極處理"}],"idioms":[{"en":"face the music","zh":"承擔後果","note":"常用於接受自己行為的不愉快後果"}],"family":[{"word":"facial","pos":"adj.","meaning":"臉部的"},{"word":"facing","pos":"n.","meaning":"飾面材料"}],"usageNote":"face + 困難直接接受詞；be faced with + 困難。face to face 作副詞，face-to-face 作形容詞。","examples":[{"text":"Facing a difficult choice between two clubs, I listed my priorities and asked experienced students about the time each activity required.","translationZh":"面對兩個社團之間的艱難選擇，我列出優先事項，並詢問學長姐各活動需要的時間。","source":"self-authored","grammar":"facing 分詞開頭對應主詞 I；between two clubs 表兩者間選擇。","writingTip":"以列優先事項和詢問經验來說明抉擇過程。","topic":"社團抉擇"},{"text":"In the face of repeated setbacks, our team continued testing the design until we found a safer and more practical solution.","translationZh":"面對多次挫折，我們小組持續測試設計，直到找到更安全實用的方案。","source":"self-authored","grammar":"in the face of + 挫折；until 引導找到方案的時間。","writingTip":"把堅持描寫成持續測試，而不只是口號。","topic":"設計挫折"}]},"facilitate":{"senses":[{"pos":"vt.","meaning":"促進；使更容易","usage":"直接接受詞，指降低困難或提供條件。"}],"collocations":[{"en":"facilitate communication","zh":"促進溝通","note":""},{"en":"facilitate access to services","zh":"讓人更容易取得服務","note":""},{"en":"facilitate learning","zh":"促進學習","note":""},{"en":"facilitate a discussion","zh":"協助討論順利進行","note":""}],"synonyms":[{"en":"ease","zh":"使容易；減輕","note":"較日常，也可接疼痛或負擔。"},{"en":"enable","zh":"使能夠","note":"更強調使某事成為可能，句型常為 enable someone to V。"}],"idioms":[],"family":[{"word":"facilitation","pos":"n.","meaning":"促進；協助"},{"word":"facilitator","pos":"n.","meaning":"引導者；協調者"}],"usageNote":"facilitate learning，不寫 facilitate students to learn；可改 enable students to learn。促進不代表保證成功。","examples":[{"text":"Clear labels and a simple map facilitated communication between volunteers and visitors who spoke different languages at the event.","translationZh":"清楚標示與簡單地圖，促進活動中不同語言的志工與訪客之間的溝通。","grammar":"facilitate 直接接 communication；between A and B 表溝通雙方。","writingTip":"說明溝通改善時，交代採用何種共同線索。","topic":"活動溝通","source":"self-authored"},{"text":"The teacher used short questions to facilitate discussion, giving quieter students time to organize their ideas before speaking.","translationZh":"老師用簡短問題協助討論，讓較安靜的學生有時間整理想法再發言。","grammar":"to facilitate 表目的；giving 補充問題安排的作用。","writingTip":"團體討論作文可寫出如何照顧不同發言節奏。","topic":"課堂討論","source":"self-authored"}]},"factor":{"senses":[{"pos":"n.","meaning":"因素","usage":"影響結果的條件"},{"pos":"vt.","meaning":"將因素納入","usage":"factor in 或 factor into"}],"collocations":[{"en":"a key factor","zh":"關鍵因素","note":"論述原因"},{"en":"environmental factors","zh":"環境因素","note":"複數搭配"},{"en":"factor in travel costs","zh":"把交通費算進去","note":"片語動詞"},{"en":"contributing factors","zh":"促成因素","note":"原因分析"}],"synonyms":[{"en":"element","zh":"要素","note":"較廣泛的構成部分"},{"en":"consideration","zh":"考量因素","note":"指決策時需考慮的事"}],"idioms":[],"family":[{"word":"factorial","pos":"adj./n.","meaning":"階乘的；階乘"}],"examples":[{"text":"Sleep quality is a key factor in students' ability to stay focused during morning classes.","translationZh":"睡眠品質是學生早上上課能否保持專注的關鍵因素。","source":"self-authored","grammar":"a key factor 為主詞補語；in students' ability 引出影響面向；ability to stay 中 to stay 說明能力。","writingTip":"分析學習表現時，把睡眠品質連結到早晨課堂專注的具體情境。","topic":"health"},{"text":"When planning the trip, we factored in travel costs as well as entrance fees.","translationZh":"規劃旅行時，我們除了門票，也把交通費納入考量。","source":"self-authored","grammar":"factor in + 名詞；as well as","writingTip":"可寫預算規劃的細節。","topic":"travel"}],"usageNote":"名詞常用 a factor in；動詞 factor in 表納入考量，不是單純製造影響。"},"fail":{"senses":[{"pos":"vi.","meaning":"失敗；未能做到；失靈","usage":"fail to V 表沒有做到。"},{"pos":"vt.","meaning":"未通過；使不及格","usage":"可接考試，也可指辜負某人。"}],"collocations":[{"en":"fail to notice","zh":"未能注意到","note":""},{"en":"fail an exam","zh":"考試不及格","note":""},{"en":"fail in an attempt","zh":"嘗試失敗","note":""},{"en":"the brakes fail","zh":"煞車失靈","note":""}],"synonyms":[{"en":"be unsuccessful","zh":"未成功","note":"較中性，不一定有辜負或未履行的意味。"},{"en":"let someone down","zh":"讓某人失望","note":"只對應 fail someone 的辜負義。"}],"idioms":[{"en":"without fail","zh":"一定；必定","note":"常強調每次都做到。"}],"family":[{"word":"failure","pos":"n.","meaning":"失敗；故障"},{"word":"failing","pos":"n.","meaning":"缺點；不足"},{"word":"failed","pos":"adj.","meaning":"失敗的"}],"examples":[{"text":"When my first experiment failed, I reviewed the procedure instead of assuming that science was beyond my ability.","translationZh":"第一次實驗失敗時，我檢查流程，而不是認定自己沒有學科學的能力。","grammar":"instead of V-ing，assuming that 接想法內容。","writingTip":"可寫從失敗中找出改進方向。","topic":"科學與成長","source":"self-authored"},{"text":"A warning system is useless if people fail to understand the instructions it provides during an emergency.","translationZh":"若人們在緊急情況下無法理解警報系統提供的指示，系統便毫無用處。","grammar":"fail to V 表未做到，if 引導條件子句。","writingTip":"適合討論資訊清晰度與安全。","topic":"安全與溝通","source":"self-authored"}],"usageNote":"fail to do 指沒有做到某事，與 try and fail「試了但失敗」不必然相同。"},"fair":{"senses":[{"pos":"adj.","meaning":"公平的；還不錯的","usage":""},{"pos":"n.","meaning":"園遊會；展覽會","usage":""}],"collocations":[{"en":"a fair chance","zh":"公平的機會","note":""},{"en":"a fair decision","zh":"公正的決定","note":""},{"en":"a book fair","zh":"書展","note":""},{"en":"a charity fair","zh":"慈善園遊會","note":""}],"synonyms":[{"en":"just","zh":"公正的","note":"較正式道德或法律用語"},{"en":"reasonable","zh":"合理的","note":"fair price 常可理解為合理價格"}],"idioms":[],"family":[{"word":"fairness","pos":"n.","meaning":"公平"},{"word":"fairly","pos":"adv.","meaning":"公平地；相當地"},{"word":"unfair","pos":"adj.","meaning":"不公平的"}],"usageNote":"fairly can mean「相當」，不一定「公平地」；fair 名詞為展覽或市集。","examples":[{"text":"To give everyone a fair chance, the coach allowed beginners to join the training session before selecting players for the school team.","translationZh":"為讓每人都有公平機會，教練先讓初學者參加訓練，再選校隊成員。","source":"self-authored","grammar":"to give 表目的；before selecting 表先訓練再選拔。","writingTip":"透過選拔流程呈現公平機會的具體做法。","topic":"校隊公平"},{"text":"At the charity fair, students sold handmade bookmarks and explained how the money would support a reading program for younger children.","translationZh":"慈善園遊會上，學生販售手工書籤，並說明收入如何支持年幼兒童的閱讀計畫。","source":"self-authored","grammar":"at the charity fair 表場所；how 子句說明募款用途。","writingTip":"販售活動後接資金支持的具體公益目的。","topic":"慈善活動"}]},"familiar":{"senses":[{"pos":"adj.","meaning":"熟悉的；常見的","usage":"人熟悉事物用 with，事物為人熟悉用 to。"}],"collocations":[{"en":"be familiar with a topic","zh":"熟悉某主題","note":""},{"en":"a familiar face","zh":"熟面孔","note":""},{"en":"be familiar to someone","zh":"對某人來說很熟悉","note":""},{"en":"a familiar routine","zh":"熟悉的固定流程","note":""}],"synonyms":[{"en":"well-known","zh":"廣為人知的","note":"強調知名度，不必是個人熟悉。"},{"en":"recognizable","zh":"可辨認的","note":"表示能認出，未必了解內容。"}],"idioms":[],"family":[{"word":"familiarity","pos":"n.","meaning":"熟悉"},{"word":"familiarize","pos":"vt.","meaning":"使熟悉"},{"word":"unfamiliar","pos":"adj.","meaning":"不熟悉的"}],"examples":[{"text":"The song sounded familiar to my grandmother because she had often heard it on the radio as a child.","translationZh":"這首歌讓祖母覺得很熟悉，因為她小時候常在收音機上聽到。","grammar":"familiar to 表為某人熟悉，had heard 指較早經驗。","writingTip":"可寫音樂喚起世代記憶。","topic":"音樂與記憶","source":"self-authored"},{"text":"Being familiar with the route allowed us to guide lost visitors back to the station before dark.","translationZh":"因為熟悉路線，我們能在天黑前帶迷路的遊客回到車站。","grammar":"Being familiar with 作主詞，allow someone to V。","writingTip":"適合描述在地知識如何幫助他人。","topic":"旅行與互助","source":"self-authored"}],"usageNote":"I am familiar with the song 與 The song is familiar to me 都正確，主詞不同決定介系詞。"},"favor":{"senses":[{"pos":"n.","meaning":"幫忙；偏好","usage":""},{"pos":"v.","meaning":"偏好；支持","usage":""}],"collocations":[{"en":"do someone a favor","zh":"幫某人一個忙","note":""},{"en":"in favor of a proposal","zh":"支持提案","note":""},{"en":"favor one option over another","zh":"偏好某方案","note":""},{"en":"ask a favor of someone","zh":"請某人幫忙","note":""}],"synonyms":[{"en":"support","zh":"支持","note":"對應方案立場"},{"en":"prefer","zh":"偏好","note":"prefer A to B 對應 favor A over B"}],"idioms":[],"family":[{"word":"favorable","pos":"adj.","meaning":"有利的；贊同的"},{"word":"favorably","pos":"adv.","meaning":"有利地；贊同地"},{"word":"favorite","pos":"adj./n.","meaning":"最喜愛的（事物）"}],"usageNote":"do someone a favor 不用 make；in favor of + 名詞／V-ing。英式拼法 favour。","examples":[{"text":"Most students were in favor of longer library hours because they needed a quiet place to study after their regular classes.","translationZh":"多數學生支持延長圖書館開放時間，因為他們在正常課程後需要安靜的讀書空間。","source":"self-authored","grammar":"in favor of + 名詞；because 解釋支持方案的原因。","writingTip":"陳述支持延長開放時間時，可補上讀書空間需求。","topic":"圖書館服務"},{"text":"My neighbor did me a favor by taking care of our plants while my family was away for the weekend.","translationZh":"週末我們全家不在時，鄰居幫忙照顧植物，幫了我一個忙。","source":"self-authored","grammar":"did me a favor；by taking care of 表幫忙方式。","writingTip":"用具體照顧行動描寫鄰居的善意。","topic":"鄰里互助"}]},"feature":{"senses":[{"pos":"n.","meaning":"特徵；特色","usage":"可數"},{"pos":"n.","meaning":"專題報導","usage":"新聞語境"},{"pos":"vt.","meaning":"以…為特色；包含","usage":"節目或產品呈現內容"}],"collocations":[{"en":"a distinctive feature","zh":"鮮明特色","note":"描述差異"},{"en":"safety features","zh":"安全功能","note":"產品資訊"},{"en":"feature local artists","zh":"邀當地藝術家演出或展示","note":"動詞用法"},{"en":"a feature article","zh":"專題報導","note":"新聞用語"}],"synonyms":[{"en":"characteristic","zh":"特徵","note":"對應辨識性質"},{"en":"include","zh":"包含","note":"對應動詞義，語氣較中性"}],"idioms":[],"family":[{"word":"featured","pos":"adj.","meaning":"特別介紹的；主打的"}],"examples":[{"text":"One useful feature of the app is that it reminds users to take regular breaks.","translationZh":"這個應用程式的一項實用功能，是提醒使用者定時休息。","source":"self-authored","grammar":"One feature of A is that + 子句","writingTip":"可描述產品功能與用途。","topic":"technology"},{"text":"The festival features local musicians and gives young performers a chance to reach larger audiences.","translationZh":"這個節慶邀請當地音樂家演出，讓年輕表演者有機會接觸更多觀眾。","source":"self-authored","grammar":"features 直接接 local musicians；gives young performers a chance 使用 give + 人 + 物；to reach 說明機會的內容。","writingTip":"介紹文化活動時，可同時寫出表演內容與對年輕人的益處。","topic":"culture"}],"usageNote":"feature 作動詞通常直接接被呈現的人、物或內容；作名詞可指功能或專題。"},"feed":{"senses":[{"pos":"v.","meaning":"餵食；供給","usage":""},{"pos":"v.","meaning":"提供資料","usage":""},{"pos":"n.","meaning":"連續更新的訊息串","usage":""}],"collocations":[{"en":"feed a stray cat","zh":"餵流浪貓","note":""},{"en":"feed data into a system","zh":"把資料輸入系統","note":""},{"en":"a news feed","zh":"動態消息串","note":""},{"en":"feed a family","zh":"養活一家人","note":""}],"synonyms":[{"en":"nourish","zh":"滋養","note":"較正式，強調提供養分"},{"en":"supply","zh":"供給","note":"適用資源，不一定食物"}],"idioms":[],"family":[{"word":"feeding","pos":"n.","meaning":"餵食；進食"},{"word":"feeder","pos":"n.","meaning":"餵食器；供料器"}],"usageNote":"不規則變化 feed–fed–fed；feed on + 食物表示以……為食。","examples":[{"text":"Although feeding stray cats may seem kind, residents also need a long-term plan to control the population and protect wildlife.","translationZh":"雖然餵流浪貓看似友善，居民仍需要長期計畫來控制數量並保護野生動物。","source":"self-authored","grammar":"although feeding 為讓步子句；to control/protect 表計畫目的。","writingTip":"可討論善意行動也需要長期生態規畫。","topic":"流浪動物照護"},{"text":"The app's news feed kept showing similar stories, so I checked other sources before forming an opinion about the event.","translationZh":"應用程式的動態消息一直顯示相似報導，因此我先查閱其他來源才對事件形成看法。","source":"self-authored","grammar":"kept showing 表反覆出現；before forming 表先查證再判斷。","writingTip":"以不同來源查核回應動態消息的侷限。","topic":"資訊偏誤"}]},"figure":{"senses":[{"pos":"n.","meaning":"數字；人物；外形","usage":""},{"pos":"v.","meaning":"認為；理解","usage":""}],"collocations":[{"en":"sales figures","zh":"銷售數字","note":""},{"en":"a public figure","zh":"公眾人物","note":""},{"en":"figure out a solution","zh":"想出解決方案","note":""},{"en":"a figure of speech","zh":"修辭說法","note":""}],"synonyms":[{"en":"number","zh":"數字","note":"對應統計資料義"},{"en":"understand","zh":"理解","note":"figure out 強調經過思考後弄懂"}],"idioms":[],"family":[{"word":"figurative","pos":"adj.","meaning":"比喻的"},{"word":"figuratively","pos":"adv.","meaning":"比喻地"},{"word":"figurehead","pos":"n.","meaning":"名義上的領袖"}],"usageNote":"figure out + 名詞或疑問詞子句；figure 作人形義時與數據義不同。","examples":[{"text":"The sales figures showed a sharp rise in reusable bottles after the school launched a campaign to reduce plastic waste.","translationZh":"學校推動減少塑膠垃圾的活動後，銷售數字顯示環保水瓶的銷量大幅上升。","source":"self-authored","grammar":"sales figures 為主詞；after 引導活動與銷量變化的時序。","writingTip":"可描述數據變化與活動實施的先後關係，避免直接斷言因果。","topic":"環保消費趨勢"},{"text":"It took us several attempts to figure out why the model bridge kept collapsing whenever we added more weight.","translationZh":"我們嘗試好幾次，才弄懂模型橋為何每次加重就一直垮塌。","source":"self-authored","grammar":"it took + 人 + 嘗試次數 + to V；figure out why + 子句。","writingTip":"寫問題解決時，呈現反覆嘗試後理解原因。","topic":"模型測試"}]},"fine":{"senses":[{"pos":"adj.","meaning":"良好的；細小的","usage":""},{"pos":"n.","meaning":"罰款","usage":""},{"pos":"v.","meaning":"處以罰款","usage":""}],"collocations":[{"en":"pay a fine","zh":"繳罰款","note":""},{"en":"fine someone for littering","zh":"因亂丟垃圾處罰某人","note":""},{"en":"fine details","zh":"細節","note":""},{"en":"be perfectly fine","zh":"完全沒問題","note":""}],"synonyms":[{"en":"penalty","zh":"處罰","note":"不一定金錢罰款"},{"en":"delicate","zh":"精細的","note":"可對應 fine workmanship，但不是健康安好義"}],"idioms":[],"family":[{"word":"finely","pos":"adv.","meaning":"細緻地；細碎地"},{"word":"fineness","pos":"n.","meaning":"細度；精細程度"}],"usageNote":"fine 作罰款時是可數名詞；fine A for B，for 後可接 V-ing。","examples":[{"text":"Visitors who leave trash on the trail may have to pay a fine, but education is also important for lasting change.","translationZh":"把垃圾留在步道上的遊客可能必須繳罰款，但教育對長期改變也很重要。","source":"self-authored","grammar":"who leave trash 修飾 visitors；may have to 表可能義務。","writingTip":"可比較處罰與教育對長期行為改變的作用。","topic":"步道規範"},{"text":"The artist used a small brush to add fine details that made the painted birds look almost ready to fly.","translationZh":"畫家用小刷子加入精細細節，讓畫中的鳥看起來幾乎隨時會飛走。","source":"self-authored","grammar":"to add 表目的；that made 修飾 details，make + 受詞 + 原形 look。","writingTip":"用精細筆觸描寫作品的生動效果。","topic":"繪畫細節"}]},"firm":{"senses":[{"pos":"adj.","meaning":"堅定的；牢固的","usage":""},{"pos":"n.","meaning":"公司","usage":""}],"collocations":[{"en":"a firm decision","zh":"堅定的決定","note":""},{"en":"a firm belief","zh":"堅定的信念","note":""},{"en":"a law firm","zh":"律師事務所","note":""},{"en":"stand firm","zh":"立場堅定","note":""}],"synonyms":[{"en":"resolute","zh":"堅定的","note":"強調不動搖"},{"en":"company","zh":"公司","note":"firm 常指商業或專業服務公司"}],"idioms":[],"family":[{"word":"firmly","pos":"adv.","meaning":"堅定地；牢固地"},{"word":"firmness","pos":"n.","meaning":"堅定；硬度"}],"usageNote":"firm 作形容詞可描述立場或物體；a firm 作名詞是公司。","examples":[{"text":"The teacher was firm about the deadline but offered guidance to students who had genuine difficulty finding reliable sources for their reports.","translationZh":"老師對期限立場堅定，卻也指導確實難以找到可靠報告資料的學生。","source":"self-authored","grammar":"firm about + 期限；who had genuine difficulty 修飾 students。","writingTip":"以期限和額外指導呈現原則與同理的並存。","topic":"原則與支持"},{"text":"A local design firm invited our class to visit its office and learn how architects develop plans for environmentally friendly buildings.","translationZh":"在地設計公司邀請我們班參觀辦公室，了解建築師如何規畫環保建築。","source":"self-authored","grammar":"invited + 人 + to visit/learn；how 引導規畫方法。","writingTip":"敘述參訪時，把所見連結到職業工作內容。","topic":"職涯參訪"}]},"fit":{"senses":[{"pos":"v.","meaning":"適合；裝得下","usage":""},{"pos":"adj.","meaning":"健康的；合適的","usage":""},{"pos":"n.","meaning":"一陣發作","usage":""}],"collocations":[{"en":"keep fit","zh":"保持健康","note":""},{"en":"fit into a small space","zh":"裝進狹小空間","note":""},{"en":"be fit for the job","zh":"適合這份工作","note":""},{"en":"a fit of laughter","zh":"一陣大笑","note":""}],"synonyms":[{"en":"suit","zh":"適合","note":"suit 常指符合需要風格，fit 常指尺寸"},{"en":"healthy","zh":"健康的","note":"fit 更強調身體狀態適於活動"}],"idioms":[],"family":[{"word":"fitness","pos":"n.","meaning":"健康狀態；適合程度"},{"word":"fitting","pos":"adj.","meaning":"合適的"},{"word":"unfit","pos":"adj.","meaning":"不適合的；不健康的"}],"usageNote":"fit 可指尺寸、適用或健康；fit in with 表融入人群或配合安排。","examples":[{"text":"Walking to school helps me keep fit, and it gives me a chance to notice changes in my neighborhood each morning.","translationZh":"步行上學幫助我保持健康，也讓我每天早上有機會注意社區的變化。","source":"self-authored","grammar":"walking 動名詞片語作主詞；gives a chance to notice 表額外益處。","writingTip":"可從健康及社區觀察兩方面說明步行的好處。","topic":"步行健康"},{"text":"The new desk did not fit into my small room, so I chose a folding table that could be stored easily.","translationZh":"新書桌放不進我的小房間，因此我選了容易收納的折疊桌。","source":"self-authored","grammar":"fit into + 空間；that could be stored 修飾 table，為被動式。","writingTip":"描述依空間限制調整家具選擇的經驗。","topic":"空間規畫"}]},"flat":{"senses":[{"pos":"adj.","meaning":"平坦的；扁平的","usage":"a flat surface；不一定與地面水平。"},{"pos":"adj.","meaning":"沒氣的；不再起泡的","usage":"a flat tire；flat soda。"},{"pos":"adj.","meaning":"固定的；一律相同的","usage":"a flat fee 指固定收費，不隨用量變動。"},{"pos":"adj.","meaning":"平淡的；無精打采的；景氣低迷的","usage":"a flat voice／a flat market，依所修飾事物判斷。"},{"pos":"adj.","meaning":"斷然的；乾脆的","usage":"a flat refusal 是明確拒絕。"},{"pos":"adv.","meaning":"平躺地；平貼地；斷然地","usage":"lie flat；turn someone down flat。"},{"pos":"n.","meaning":"公寓；一層的住家單位（英式）","usage":"rent a flat；美式常用 apartment。"}],"collocations":[{"en":"a flat surface","zh":"平坦的表面","note":""},{"en":"a flat tire","zh":"沒氣的輪胎","note":""},{"en":"rent a flat","zh":"租公寓","note":""},{"en":"a flat fee","zh":"固定費用","note":""}],"synonyms":[{"en":"level","zh":"平的","note":"指表面水平"},{"en":"apartment","zh":"公寓","note":"美式英語常用 apartment，英式常用 flat"}],"idioms":[],"family":[{"word":"flatten","pos":"v.","meaning":"使變平"},{"word":"flatness","pos":"n.","meaning":"平坦"},{"word":"flatly","pos":"adv.","meaning":"斷然地；平淡地"}],"usageNote":"flat 可形容形狀、沒氣、固定費率或平淡狀態，也可作副詞或英式公寓名詞。a flat fee 是固定收費；flat 與 level 不完全相同，平面仍可能傾斜。","examples":[{"text":"A flat tire delayed our trip, but a nearby mechanic helped us repair the bicycle before the afternoon rain began.","translationZh":"輪胎沒氣耽誤了旅程，但附近技師在午後降雨前幫我們修好了自行車。","source":"self-authored","grammar":"a flat tire 為主詞；helped + 人 + repair 表協助修理。","writingTip":"以輪胎故障說明旅途中遇到的困難與幫助。","topic":"自行車旅途"},{"text":"The service charges a flat fee each month, so users should compare it with their actual needs before signing up.","translationZh":"服務每月收取固定費用，因此使用者應先比較自己的實際需求再註冊。","source":"self-authored","grammar":"charges a flat fee；before signing up 表註冊前的比較。","writingTip":"評估固定收費方案時，可比較實際使用需求。","topic":"訂閱消費"}]},"flexible":{"senses":[{"pos":"adj.","meaning":"可彎曲的","usage":"材料性質"},{"pos":"adj.","meaning":"有彈性；可調整的","usage":"時間、制度或想法"}],"collocations":[{"en":"a flexible schedule","zh":"彈性的行程","note":"時間安排"},{"en":"flexible working hours","zh":"彈性工時","note":"職場情境"},{"en":"flexible materials","zh":"可彎曲的材料","note":"實體義"},{"en":"remain flexible","zh":"保持彈性","note":"remain + 形容詞"}],"synonyms":[{"en":"adaptable","zh":"可適應的","note":"著重配合變化的能力"},{"en":"bendable","zh":"可彎曲的","note":"只對應實體材料義"}],"idioms":[],"family":[{"word":"flexibility","pos":"n.","meaning":"彈性"},{"word":"flexibly","pos":"adv.","meaning":"靈活地"},{"word":"inflexible","pos":"adj.","meaning":"僵硬的；不知變通的"}],"examples":[{"text":"Flexible working hours allow parents to balance their jobs with the needs of their children.","translationZh":"彈性工時讓家長能兼顧工作與孩子的需求。","source":"self-authored","grammar":"allow 人 to V；balance A with B","writingTip":"可分析職場制度的影響。","topic":"work"},{"text":"Our plan remained flexible so that we could change activities if the weather became worse.","translationZh":"我們的計畫保持彈性，以便天氣惡化時調整活動。","source":"self-authored","grammar":"remained flexible 使用 remain + 形容詞；so that 引出目的；if the weather became worse 為條件子句。","writingTip":"旅遊或活動計畫可把彈性安排連結到天氣惡化時的應變。","topic":"planning"}],"usageNote":"flexible 既可指可彎曲的物件，也可指可調整的安排與態度。"},"frustrate":{"senses":[{"pos":"vt.","meaning":"使沮喪；阻撓","usage":"可指情緒受挫，也可指計畫無法成功。"}],"collocations":[{"en":"frustrate someone's efforts","zh":"使某人的努力受阻","note":""},{"en":"be frustrated by delays","zh":"因延誤而沮喪","note":""},{"en":"be frustrated with a situation","zh":"對某情況感到挫折","note":""},{"en":"a frustrating experience","zh":"令人受挫的經歷","note":""}],"synonyms":[{"en":"discourage","zh":"使氣餒","note":"可能降低繼續行動的意願。"},{"en":"thwart","zh":"阻撓","note":"較正式，只對應阻止計畫成功的意思。"}],"idioms":[],"family":[{"word":"frustration","pos":"n.","meaning":"挫折；沮喪"},{"word":"frustrated","pos":"adj.","meaning":"感到挫折的"},{"word":"frustrating","pos":"adj.","meaning":"令人受挫的"}],"examples":[{"text":"Repeated technical problems frustrated the students, but they eventually found another way to present their work.","translationZh":"反覆發生的技術問題令學生受挫，但他們最後找到另一種展示作品的方法。","grammar":"frustrate someone 表使人受挫，another way to V 表替代方法。","writingTip":"可寫遇到意外後的應變。","topic":"科技與學習","source":"self-authored"},{"text":"The lack of reliable transportation can frustrate rural residents' efforts to attend classes or seek better jobs.","translationZh":"缺乏可靠交通，可能阻礙偏鄉居民上課或尋找更好工作的努力。","grammar":"frustrate efforts to V 表阻撓努力，or 連接兩個行動。","writingTip":"適合分析交通與機會平等。","topic":"偏鄉與交通","source":"self-authored"}],"usageNote":"人感到挫折用 frustrated，事情令人挫折用 frustrating；frustrate 也有阻撓義。"},"function":{"senses":[{"pos":"n.","meaning":"功能；作用","usage":"a function of"},{"pos":"n.","meaning":"典禮；正式活動","usage":"社交場合"},{"pos":"vi.","meaning":"運作；發揮作用","usage":"function as + 角色"}],"collocations":[{"en":"function properly","zh":"正常運作","note":"動詞加副詞"},{"en":"function as a meeting place","zh":"充當聚會場所","note":"as 指作用"},{"en":"the main function of a device","zh":"裝置的主要功能","note":"名詞搭配"},{"en":"attend a formal function","zh":"參加正式活動","note":"熟詞偏義"}],"synonyms":[{"en":"operate","zh":"運作","note":"對應機器或系統的動詞義"},{"en":"role","zh":"作用；角色","note":"對應某物的用途"}],"idioms":[],"family":[{"word":"functional","pos":"adj.","meaning":"有功能的；實用的"},{"word":"functionality","pos":"n.","meaning":"功能性"},{"word":"malfunction","pos":"n./vi.","meaning":"故障"}],"examples":[{"text":"The old train station now functions as a meeting place for artists and local residents.","translationZh":"舊火車站如今充當藝術家與當地居民的聚會場所。","source":"self-authored","grammar":"functions 是第三人稱單數動詞；function as a meeting place 中 as 引出場所現在扮演的角色。","writingTip":"介紹舊站改用時，可用 function as 說明新角色與使用者。","topic":"community"},{"text":"Without regular maintenance, the water pump may fail to function properly during an emergency.","translationZh":"若沒有定期維護，抽水幫浦可能在緊急情況時無法正常運作。","source":"self-authored","grammar":"Without regular maintenance 是介系詞片語；fail to function 使用 fail + to V；properly 為修飾 function 的副詞。","writingTip":"說明設備維護的重要性時，可指出緊急情況下故障的後果。","topic":"safety"}],"usageNote":"function as 表充當某種角色；a function 也可能指正式社交活動。"},"generate":{"senses":[{"pos":"vt.","meaning":"產生；引發","usage":"電力、收入、興趣等"}],"collocations":[{"en":"generate electricity","zh":"發電","note":"能源主題"},{"en":"generate income","zh":"產生收入","note":"經濟語境"},{"en":"generate public interest","zh":"引起公眾興趣","note":"宣傳效果"},{"en":"generate new ideas","zh":"產生新想法","note":"創作情境"}],"synonyms":[{"en":"produce","zh":"生產；產生","note":"範圍廣泛"},{"en":"create","zh":"創造","note":"著重新事物的形成"}],"idioms":[],"family":[{"word":"generation","pos":"n.","meaning":"產生；世代"},{"word":"generator","pos":"n.","meaning":"發電機；產生器"}],"examples":[{"text":"The wind farm generates enough electricity to supply several villages throughout most of the year.","translationZh":"這座風力發電場的發電量，足以在一年大部分時間供應數個村莊。","source":"self-authored","grammar":"enough + 名詞 + to V","writingTip":"介紹能源設施時說明規模與範圍。","topic":"energy"},{"text":"A surprising question can generate new ideas by encouraging people to examine familiar problems differently.","translationZh":"出人意料的問題能鼓勵人們換個角度看熟悉的難題，激發新想法。","source":"self-authored","grammar":"generate + 受詞；by + V-ing","writingTip":"可用於創意與課堂討論。","topic":"innovation"}],"usageNote":"generate 不只指發電，也可搭配收入、討論、興趣及想法。"},"goal":{"senses":[{"pos":"n.","meaning":"目標；進球","usage":"學習或工作目標與球賽得分皆可用。"}],"collocations":[{"en":"set a goal","zh":"設定目標","note":""},{"en":"achieve a goal","zh":"達成目標","note":""},{"en":"a long-term goal","zh":"長期目標","note":""},{"en":"score a goal","zh":"踢進一球；進球得分","note":""}],"synonyms":[{"en":"aim","zh":"目標","note":"與一般目標相近，可作動詞。"},{"en":"objective","zh":"目標","note":"常用於較具體、正式的計畫。"}],"idioms":[],"family":[{"word":"goal-oriented","pos":"adj.","meaning":"以目標為導向的"},{"word":"goalkeeper","pos":"n.","meaning":"守門員"}],"examples":[{"text":"Setting a realistic goal helped me measure my progress without comparing myself constantly with classmates.","translationZh":"設定切合實際的目標，讓我能衡量進步，不必一直與同學比較。","grammar":"動名詞作主詞，without 後接動名詞。","writingTip":"可寫依自身情況設定學習目標。","topic":"學習與自我管理","source":"self-authored"},{"text":"Our team's final goal brought the crowd to its feet and changed the mood of the entire match.","translationZh":"我們球隊最後的進球讓觀眾起立歡呼，也改變了整場比賽的氣氛。","grammar":"bring someone to their feet 表使人站起來。","writingTip":"適合描寫運動比賽的高潮。","topic":"運動與敘事","source":"self-authored"}],"usageNote":"goal 指目標時常搭配 set 或 achieve；進球義則常搭配 score。"},"grateful":{"senses":[{"pos":"adj.","meaning":"感激的","usage":"對人用 to，對事情用 for，也可接 that 子句。"}],"collocations":[{"en":"be grateful to someone","zh":"感謝某人","note":""},{"en":"be grateful for support","zh":"感激獲得支持","note":""},{"en":"deeply grateful","zh":"深深感激","note":""},{"en":"grateful that","zh":"感激……","note":""}],"synonyms":[{"en":"thankful","zh":"感激的","note":"常用 thank someone 或 be thankful for，語氣日常。"},{"en":"appreciative","zh":"感謝的；欣賞的","note":"常強調表現出感激或欣賞。"}],"idioms":[],"family":[{"word":"gratitude","pos":"n.","meaning":"感激"},{"word":"gratefully","pos":"adv.","meaning":"感激地"},{"word":"ungrateful","pos":"adj.","meaning":"不知感恩的"}],"examples":[{"text":"I am grateful to my neighbors for checking on my grandmother when our family was away.","translationZh":"家人不在時，鄰居關心祖母的狀況，讓我十分感激。","grammar":"grateful to 人 for 事情，check on 表查看安危。","writingTip":"可寫社區照顧與感恩。","topic":"高齡與鄰里","source":"self-authored"},{"text":"After losing access to clean water for two days, we became grateful for something we had always taken for granted.","translationZh":"兩天沒有乾淨的水可用後，我們開始感激原本一直視為理所當然的事物。","grammar":"grateful for，take something for granted 表視為理所當然。","writingTip":"適合從不便反思日常資源。","topic":"資源與反思","source":"self-authored"}],"usageNote":"grateful 與 great 無關；gratitude 是名詞，gratefully 才是副詞。"},"habit":{"senses":[{"pos":"n.","meaning":"習慣","usage":"常接 of 加動名詞，表示固定行為。"}],"collocations":[{"en":"develop a habit of reading","zh":"養成閱讀習慣","note":""},{"en":"break a bad habit","zh":"戒除壞習慣","note":""},{"en":"out of habit","zh":"出於習慣","note":""},{"en":"be in the habit of","zh":"習慣於……","note":""}],"synonyms":[{"en":"routine","zh":"例行流程","note":"指規律的活動安排，可能包含數個習慣。"},{"en":"custom","zh":"習俗","note":"較常指群體傳統，不只個人行為。"}],"idioms":[],"family":[{"word":"habitual","pos":"adj.","meaning":"習慣性的"},{"word":"habitually","pos":"adv.","meaning":"習慣性地"},{"word":"habit-forming","pos":"adj.","meaning":"容易形成習慣或依賴的"}],"examples":[{"text":"Keeping a reusable bottle in my schoolbag helped me develop the habit of buying fewer disposable drinks.","translationZh":"把可重複使用的水瓶放在書包裡，幫助我養成少買一次性包裝飲料的習慣。","grammar":"develop the habit of V-ing，help someone V。","writingTip":"可寫環保行動如何融入日常。","topic":"習慣與永續","source":"self-authored"},{"text":"He reached for his phone out of habit, then realized that he wanted a break from constant notifications.","translationZh":"他習慣性地伸手拿手機，接著才發現自己想暫時遠離接連不斷的通知。","grammar":"out of habit 表行為原因，realize that 接發現內容。","writingTip":"適合寫意識到無意識的科技習慣。","topic":"科技與自我覺察","source":"self-authored"}],"usageNote":"habit of doing 常見；break a habit 是改掉習慣，與休息 take a break 不同。"},"head":{"senses":[{"pos":"n.","meaning":"頭；頭部","usage":"head 可指人的頭，也可指動物頭部；a headache 是頭痛，不可由 head 的每個義項推導。"},{"pos":"n.","meaning":"頭腦；思考或判斷能力","usage":"use your head = 動腦；keep a cool head = 保持冷靜。"},{"pos":"n.","meaning":"主管；領導者","usage":"the head of a department / an organization；of 後接所主管的單位。"},{"pos":"n.","meaning":"頂端；最前部；首位","usage":"the head of the table / the queue；依實體位置指頂端或最前的位置。"},{"pos":"adj.","meaning":"主要的；居首位的","usage":"the head teacher / head office；常放在名詞前，表示主管或主要地位。"},{"pos":"vt.","meaning":"領導；主管","usage":"head a committee / a research team；直接接受詞，意思是擔任領導者。"},{"pos":"vi.","meaning":"朝……前進；前往","usage":"head for / toward / to + 地點；for 常指朝目的地前進。"},{"pos":"vt.","meaning":"用頭頂球","usage":"head the ball；體育用法，通常指足球中用頭觸球。"}],"collocations":[{"en":"head for the station","zh":"前往車站","note":""},{"en":"head a committee","zh":"領導委員會","note":""},{"en":"the head of a department","zh":"部門主管","note":""},{"en":"keep a cool head","zh":"保持冷靜","note":""},{"en":"head office","zh":"總公司；總部辦公室","note":"head 在此作置於名詞前的形容詞，意為主要的。"},{"en":"head toward the exit","zh":"朝出口前進","note":"toward 後接方向或地點；head 在此不及物。"}],"synonyms":[{"en":"lead","zh":"領導","note":"對應擔任領導者"},{"en":"go toward","zh":"朝向","note":"對應前往某地"}],"idioms":[{"en":"keep a cool head","zh":"保持冷靜","note":"多用於壓力或緊急情況"}],"family":[{"word":"heading","pos":"n.","meaning":"標題；方向"},{"word":"headteacher","pos":"n.","meaning":"校長（英式用語）"},{"word":"headquarters","pos":"n.","meaning":"總部"}],"usageNote":"head a team 表領導團隊，head for/toward/to + 地點 表前往；head office 中 head 表主要的。headed、heading 是正常屈折變化；heading 也可單獨作名詞表示標題或行進方向。","examples":[{"text":"When the fire alarm rang, our teacher kept a cool head and led the class toward the nearest safe exit.","translationZh":"火警響起時，老師保持冷靜，帶全班走向最近的安全出口。","source":"self-authored","grammar":"kept a cool head 表保持冷靜；when 引導警報響起的時間。","writingTip":"用引導疏散的行動呈現冷靜處事。","topic":"火警疏散"},{"text":"After the workshop, we headed for the station together and discussed which ideas we could apply to our community project.","translationZh":"工作坊後，我們一起前往車站，討論哪些想法可應用於社區專題。","source":"self-authored","grammar":"headed for + 地點；which ideas 引導討論的間接問句。","writingTip":"敘述行程後可補上如何把所學用於社區。","topic":"工作坊應用"}]},"hesitate":{"senses":[{"pos":"vi.","meaning":"猶豫；遲疑","usage":"常接 to V 或 about 加動名詞。"}],"collocations":[{"en":"hesitate to ask","zh":"猶豫是否開口問","note":""},{"en":"hesitate about making a decision","zh":"對作決定猶豫","note":""},{"en":"without hesitation","zh":"毫不猶豫","note":"此處使用名詞。"},{"en":"do not hesitate to contact","zh":"請隨時聯絡","note":"正式邀請用法。"}],"synonyms":[{"en":"pause","zh":"停頓","note":"未必因不確定或猶豫。"},{"en":"waver","zh":"動搖","note":"強調立場或決心不穩。"}],"idioms":[],"family":[{"word":"hesitation","pos":"n.","meaning":"猶豫"},{"word":"hesitant","pos":"adj.","meaning":"猶豫的"},{"word":"hesitantly","pos":"adv.","meaning":"猶豫地"}],"examples":[{"text":"I hesitated to ask a question because I feared that everyone else already understood the lesson.","translationZh":"我因為怕其他人都已經懂了，而猶豫是否要問問題。","grammar":"hesitate to V，because 引導原因子句。","writingTip":"可寫克服求助時的心理障礙。","topic":"課堂與勇氣","source":"self-authored"},{"text":"Although the price was low, she hesitated before buying the jacket because she was unsure whether she needed it.","translationZh":"雖然價格很低，她購買外套前仍猶豫了，因為不確定自己是否需要。","grammar":"before V-ing，whether 引導名詞子句。","writingTip":"適合討論衝動購物與理性選擇。","topic":"消費與決策","source":"self-authored"}],"usageNote":"Don't hesitate to ask 常表示「有問題儘管問」，語氣是鼓勵而非批評遲疑。"},"identify":{"senses":[{"pos":"vt.","meaning":"辨識；確認；找出","usage":"identify a person／a cause／a need。"},{"pos":"vi.","meaning":"產生共鳴；認同","usage":"identify with + 人或經驗。"}],"collocations":[{"en":"identify the cause of a problem","zh":"找出問題原因","note":""},{"en":"identify someone by their voice","zh":"憑聲音辨認某人","note":""},{"en":"identify areas for improvement","zh":"找出可改進之處","note":""},{"en":"identify with a character","zh":"對角色產生認同","note":"不及物片語。"}],"synonyms":[{"en":"recognize","zh":"認出；認可","note":"常帶先前見過或意識到的意思。"},{"en":"pinpoint","zh":"精確指出","note":"強調位置或原因明確，比 identify 更精準。"}],"idioms":[],"family":[{"word":"identification","pos":"n.","meaning":"辨識；身分證明"},{"word":"identifiable","pos":"adj.","meaning":"可辨認的"},{"word":"identity","pos":"n.","meaning":"身分；認同"}],"usageNote":"identify A as B 表確認 A 是 B；identify with A 表對 A 有共鳴。identity 不等於 personality（個性）。","examples":[{"text":"Instead of correcting every sentence at once, the teacher helped me identify the two mistakes that most often confused my readers.","translationZh":"老師沒有一次改完每句，而是幫我找出最常讓讀者困惑的兩項錯誤。","grammar":"help + 人 + 原形 identify；that 修飾 mistakes。","writingTip":"學習反思可把回饋轉成少量明確改善目標。","topic":"寫作回饋","source":"self-authored"},{"text":"Many readers identify with the character because she wants to help her family while also pursuing a dream of her own.","translationZh":"許多讀者對角色有共鳴，因為她想幫助家人，也想追求自己的夢想。","grammar":"identify with + 人；while also pursuing 補充同時追求的目標。","writingTip":"閱讀心得可用角色面臨的兩難解釋共鳴。","topic":"閱讀與夢想","source":"self-authored"}]},"identity":{"senses":[{"pos":"n.","meaning":"身分；認同","usage":"可指證明自己是誰，也可指自我或群體認同。"}],"collocations":[{"en":"a sense of identity","zh":"認同感","note":""},{"en":"confirm someone's identity","zh":"確認某人身分","note":""},{"en":"cultural identity","zh":"文化認同","note":""},{"en":"identity theft","zh":"身分資料竊取","note":""}],"synonyms":[{"en":"self-image","zh":"自我形象","note":"聚焦自己如何看待自己。"},{"en":"individuality","zh":"個性；獨特性","note":"強調與他人不同，不等同身分。"}],"idioms":[],"family":[{"word":"identify","pos":"vt.","meaning":"辨識；確認"},{"word":"identification","pos":"n.","meaning":"辨識；身分證明"},{"word":"identifiable","pos":"adj.","meaning":"可辨識的"}],"examples":[{"text":"Learning my grandparents' language helped me develop a stronger sense of identity and connection to my family's history.","translationZh":"學習祖父母的語言，讓我建立更強的認同感，也與家族歷史更加連結。","grammar":"help someone develop，sense of 接抽象名詞。","writingTip":"可寫語言與文化傳承。","topic":"語言與認同","source":"self-authored"},{"text":"Sharing personal details too freely online can expose people to identity theft and other serious risks.","translationZh":"在網路上過度分享個人資訊，可能讓人面臨身分資料遭竊等嚴重風險。","grammar":"動名詞片語作主詞，expose someone to 表使面臨。","writingTip":"適合討論隱私與資訊安全。","topic":"網路與隱私","source":"self-authored"}],"usageNote":"identity 是身分或認同；identification 也可指證明身分的證件或辨識程序。"},"ignore":{"senses":[{"pos":"vt.","meaning":"忽視；不理會","usage":"常指未給應有注意或刻意不理。"}],"collocations":[{"en":"ignore a warning","zh":"忽視警告","note":""},{"en":"ignore someone's advice","zh":"不理會某人的建議","note":""},{"en":"ignore the needs of others","zh":"忽視他人需求","note":""},{"en":"a problem that cannot be ignored","zh":"不能忽視的問題","note":""}],"synonyms":[{"en":"overlook","zh":"忽略","note":"可能是疏忽未察覺，也可表示不追究，與 ignore 不完全相同。"},{"en":"disregard","zh":"不理會；不顧","note":"較正式，常強調不予考量。"}],"idioms":[],"family":[{"word":"ignorance","pos":"n.","meaning":"無知；不了解"},{"word":"ignorant","pos":"adj.","meaning":"無知的；不了解的"}],"usageNote":"ignore 是不理會；be ignorant of 是不知道，兩者不能直接互換。ignorant 作人身評語時可能帶貶意。","examples":[{"text":"Ignoring the warning signs, several visitors entered the closed trail and later needed help when the weather suddenly changed.","translationZh":"幾名遊客無視警告標誌，走入封閉步道，之後因天候突然改變而需要協助。","grammar":"Ignoring 分詞片語主詞同為 visitors；when 引導情況變化。","writingTip":"敘述風險時建立忽視警告與後續困境的關聯。","topic":"戶外風險","source":"self-authored"},{"text":"A plan that ignores the needs of older residents may create new barriers even if it seems convenient to younger users.","translationZh":"忽視年長居民需求的計畫，即使看來方便年輕使用者，也可能製造新障礙。","grammar":"that ignores 修飾 plan；even if 表讓步條件。","writingTip":"科技服務作文檢查不同年齡使用者是否同樣受益。","topic":"高齡與科技","source":"self-authored"}]},"illustrate":{"senses":[{"pos":"vt.","meaning":"以例子說明","usage":"illustrate a point／how something works。"},{"pos":"vt.","meaning":"加插圖；圖解","usage":"illustrate a book。"}],"collocations":[{"en":"illustrate a point with an example","zh":"舉例說明重點","note":""},{"en":"illustrate the difference between two ideas","zh":"說明兩個概念的差別","note":""},{"en":"a beautifully illustrated book","zh":"插圖精美的書","note":""},{"en":"illustrate how a system works","zh":"圖解或說明系統如何運作","note":""}],"synonyms":[{"en":"demonstrate","zh":"說明；展示","note":"可透過操作或證據，不一定用圖或例子。"},{"en":"depict","zh":"描繪","note":"強調呈現人事物的樣貌，不一定解說原理。"}],"idioms":[],"family":[{"word":"illustration","pos":"n.","meaning":"插圖；例證"},{"word":"illustrator","pos":"n.","meaning":"插畫家"},{"word":"illustrative","pos":"adj.","meaning":"用於說明的"}],"usageNote":"illustrate 可用文字例子，不限圖片；an illustration 可能是一張圖，也可能是一個例證，須看上下文。","examples":[{"text":"The chart illustrates how the proportion of students using public transportation changed over the five years covered by the survey.","translationZh":"圖表說明調查涵蓋的五年間，使用大眾運輸的學生比例如何改變。","grammar":"illustrate + how 子句；covered 為分詞修飾 years。","writingTip":"圖表開頭可交代衡量項目與時間範圍。","topic":"交通圖表","source":"self-authored"},{"text":"To illustrate her point about waste, the speaker displayed the packaging left after a single family meal.","translationZh":"為說明浪費的問題，講者展示一頓家庭餐後留下的包裝。","grammar":"To illustrate 表目的；left 為過去分詞修飾 packaging。","writingTip":"議論作文用具體可見的例子支撐抽象主張。","topic":"生活減廢","source":"self-authored"}]},"impact":{"senses":[{"pos":"n.","meaning":"影響","usage":"impact on + 對象"},{"pos":"n.","meaning":"撞擊","usage":"實體碰撞"},{"pos":"vt.","meaning":"影響","usage":"直接接受詞"}],"collocations":[{"en":"have an impact on health","zh":"對健康產生影響","note":"on 指對象"},{"en":"environmental impact","zh":"環境影響","note":"政策評估"},{"en":"reduce the impact of a disaster","zh":"降低災害衝擊","note":"of 指來源"},{"en":"the impact of a collision","zh":"碰撞的衝擊","note":"實體義"}],"synonyms":[{"en":"effect","zh":"影響；效果","note":"一般影響語境"},{"en":"influence","zh":"影響力","note":"常指逐漸改變思想或行為"}],"idioms":[],"family":[{"word":"impactful","pos":"adj.","meaning":"有影響力的"}],"examples":[{"text":"Excessive screen time can have a negative impact on sleep, especially when devices are used late at night.","translationZh":"過多螢幕時間會對睡眠產生負面影響，尤其是在深夜使用裝置時。","source":"self-authored","grammar":"have an impact on；被動語態","writingTip":"可討論科技習慣與健康。","topic":"health"},{"text":"The helmet absorbed much of the impact and prevented the cyclist from suffering a serious head injury.","translationZh":"安全帽吸收大部分撞擊力，避免騎士受到嚴重頭部傷害。","source":"self-authored","grammar":"prevent 人 from V-ing","writingTip":"安全敘事可指出防護用品的具體作用。","topic":"safety"}],"usageNote":"impact on 是名詞搭配；impact 作動詞時可直接接受詞。"},"implement":{"senses":[{"pos":"vt.","meaning":"實施；落實","usage":"政策、計畫或措施"},{"pos":"n.","meaning":"工具；器具","usage":"常見於 farming implements"}],"collocations":[{"en":"implement a policy","zh":"實施政策","note":"政府語境"},{"en":"implement safety measures","zh":"落實安全措施","note":"組織管理"},{"en":"implement a plan","zh":"執行計畫","note":"把計畫付諸行動"},{"en":"farming implements","zh":"農具","note":"名詞熟詞偏義"}],"synonyms":[{"en":"carry out","zh":"執行","note":"對應計畫或任務"},{"en":"put into practice","zh":"付諸實行","note":"強調由想法轉為行動"}],"idioms":[],"family":[{"word":"implementation","pos":"n.","meaning":"實施"}],"examples":[{"text":"The school implemented a new recycling policy after students noticed too much waste in the cafeteria.","translationZh":"學生注意到餐廳有過多垃圾後，學校實施了新的回收政策。","source":"self-authored","grammar":"implemented 直接接 a new recycling policy；after 子句交代促成政策的先前觀察。","writingTip":"寫校園改善時，可用學生發現垃圾問題作為實施回收政策的起點。","topic":"sustainability"},{"text":"Local officials must provide clear guidance before implementing the rules in crowded tourist areas.","translationZh":"地方官員在擁擠觀光區實施規定前，必須提供清楚指引。","source":"self-authored","grammar":"must 後接原形動詞 provide；before implementing 是 before + V-ing，主詞仍為 Local officials。","writingTip":"討論規定落實時，可先指出必須提供清楚指引的配套工作。","topic":"tourism"}],"usageNote":"implement 作動詞指實施已規劃的措施；作名詞時指器具，尤見於農業。"},"implication":{"senses":[{"pos":"n.","meaning":"可能的影響；含意","usage":"影響義常用複數 implications for。"},{"pos":"n.","meaning":"暗示；牽涉","usage":"如 implication that... 或 implication in a crime。"}],"collocations":[{"en":"the implications of a decision","zh":"決定可能帶來的影響","note":""},{"en":"implications for public health","zh":"對公共衛生的潛在影響","note":""},{"en":"an implication that something is wrong","zh":"暗示某事有問題","note":""},{"en":"consider the wider implications","zh":"考慮更廣泛的影響","note":""}],"synonyms":[{"en":"consequence","zh":"結果；後果","note":"較常指實際或直接後果，implication 可指推論出的影響。"},{"en":"suggestion","zh":"暗示","note":"只對應間接透露的意思，也另有建議義。"}],"idioms":[],"family":[{"word":"imply","pos":"vt.","meaning":"暗示；意味著"},{"word":"implicit","pos":"adj.","meaning":"未明說的；隱含的"},{"word":"implicate","pos":"vt.","meaning":"牽連；顯示與某事有關"}],"usageNote":"implications for 指對某對象的影響；imply 是訊息或說話者暗示，infer 是讀者根據線索推論。","examples":[{"text":"The rise in housing costs has important implications for young adults who hope to work near their families.","translationZh":"房價上升對希望在家人附近工作的年輕成人，有重要的潛在影響。","grammar":"have implications for + 對象；who hope 修飾 young adults。","writingTip":"分析現象時指出受影響的是哪一群人。","topic":"住房與職涯","source":"self-authored"},{"text":"Before collecting students' personal data, schools should consider the implications for privacy as well as the possible benefits for learning.","translationZh":"蒐集學生個資前，學校應同時考慮隱私影響與可能的學習效益。","grammar":"Before collecting 省略主詞；as well as 並列兩項考量。","writingTip":"科技議題作文比較益處與資料使用造成的影響。","topic":"資料與隱私","source":"self-authored"}]},"improve":{"senses":[{"pos":"vt./vi.","meaning":"改善；進步","usage":"可接能力或條件"}],"collocations":[{"en":"improve air quality","zh":"改善空氣品質","note":"環境主題"},{"en":"improve communication skills","zh":"增進溝通技巧","note":"學習情境"},{"en":"improve steadily","zh":"穩定進步","note":"不及物用法"},{"en":"room for improvement","zh":"改進空間","note":"名詞搭配"}],"synonyms":[{"en":"enhance","zh":"提升","note":"著重增強既有品質"},{"en":"make progress","zh":"進步","note":"對應人的能力或工作進展"}],"idioms":[{"en":"turn things around","zh":"扭轉局面","note":"表示讓原本不佳的狀況改善，語氣比一般 improve 強。"}],"family":[{"word":"improvement","pos":"n.","meaning":"改善；進步"},{"word":"improved","pos":"adj.","meaning":"改善過的"}],"examples":[{"text":"Planting trees can improve air quality while providing shade for people walking through the neighborhood.","translationZh":"種樹能改善空氣品質，同時為行經社區的人提供遮蔭。","source":"self-authored","grammar":"while + V-ing 表同時效果","writingTip":"可用於都市綠化的好處。","topic":"urban life"},{"text":"My speaking skills improved after I began recording myself and listening carefully to my mistakes.","translationZh":"開始錄下自己的口說並仔細聽錯誤後，我的口說能力進步了。","source":"self-authored","grammar":"improve 不及物；begin + V-ing","writingTip":"可用具體方法寫學習反思。","topic":"education"}],"usageNote":"improve 可及物也可不及物；improvement 是名詞，常用 improvement in + 項目。"},"independent":{"senses":[{"pos":"adj.","meaning":"獨立的；不依賴的","usage":"常搭配 of 表不受依賴或影響的對象。"}],"collocations":[{"en":"be independent of one's parents","zh":"不依賴父母","note":""},{"en":"independent living","zh":"獨立生活","note":""},{"en":"an independent investigation","zh":"獨立調查","note":""},{"en":"financially independent","zh":"經濟獨立","note":""}],"synonyms":[{"en":"self-reliant","zh":"自立的","note":"強調靠自己處理事情。"},{"en":"autonomous","zh":"自主的","note":"較正式，強調自行決策的權限。"}],"idioms":[],"family":[{"word":"independence","pos":"n.","meaning":"獨立"},{"word":"independently","pos":"adv.","meaning":"獨立地"},{"word":"dependence","pos":"n.","meaning":"依賴"}],"examples":[{"text":"Living in a dormitory taught me to become more independent while still asking for help when necessary.","translationZh":"住在宿舍教會我更獨立，同時在必要時仍能尋求幫助。","grammar":"teach someone to V，while V-ing 表並存的行動。","writingTip":"可寫獨立與求助如何兼顧。","topic":"生活與成長","source":"self-authored"},{"text":"An independent investigation can help the public judge whether a company has reported its environmental impact honestly.","translationZh":"獨立調查可以幫助大眾判斷，公司是否誠實揭露環境影響。","grammar":"whether 引導名詞子句，has reported 表已發生的揭露。","writingTip":"適合討論資訊透明與外部監督。","topic":"企業與環境","source":"self-authored"}],"usageNote":"independent of 表不受某事影響或不依賴；independently of 是副詞片語。"},"indicate":{"senses":[{"pos":"vt.","meaning":"顯示；指出","usage":"證據或數據表明"},{"pos":"vt.","meaning":"示意","usage":"動作表示意向"}],"collocations":[{"en":"indicate a change","zh":"顯示變化","note":"趨勢描述"},{"en":"indicate that something is wrong","zh":"顯示有問題","note":"that 子句"},{"en":"indicate a direction","zh":"指示方向","note":"標示用途"},{"en":"indicate an intention","zh":"表示意圖","note":"溝通情境"}],"synonyms":[{"en":"show","zh":"顯示","note":"較日常，範圍較廣"},{"en":"suggest","zh":"暗示；顯示可能","note":"推論語氣通常較弱"}],"idioms":[],"family":[{"word":"indication","pos":"n.","meaning":"跡象；指示"},{"word":"indicator","pos":"n.","meaning":"指標；指示器"},{"word":"indicative","pos":"adj.","meaning":"顯示的；指示的"}],"examples":[{"text":"The survey results indicate that students value practical experience as much as classroom instruction.","translationZh":"調查結果顯示，學生重視實務經驗的程度不亞於課堂教學。","source":"self-authored","grammar":"indicate that；as much as","writingTip":"圖表作文可用於報告調查發現。","topic":"data"},{"text":"A sudden drop in water level may indicate a leak somewhere in the building.","translationZh":"水位突然下降，可能顯示建築物某處有漏水。","source":"self-authored","grammar":"may 後接原形動詞 indicate；a leak 是 indicate 的受詞；somewhere 修飾漏水所在的未知位置。","writingTip":"以 may indicate 表達從水位下降推測漏水，保留未確認的語氣。","topic":"safety"}],"usageNote":"indicate 常用於資料顯示某事，may indicate 保留不確定性；不要把跡象當成證實。"},"influence":{"senses":[{"pos":"n.","meaning":"影響；影響力","usage":"常接 on。"},{"pos":"vt.","meaning":"影響","usage":"直接接人或決策等受詞。"}],"collocations":[{"en":"have an influence on","zh":"對……有影響","note":""},{"en":"under the influence of","zh":"受到……影響","note":""},{"en":"influence a decision","zh":"影響決定","note":""},{"en":"a positive influence","zh":"正面的影響","note":""}],"synonyms":[{"en":"affect","zh":"影響","note":"動詞，範圍較廣，未必逐漸改變想法。"},{"en":"impact","zh":"影響","note":"常強調明顯效果，名詞或動詞皆可。"}],"idioms":[],"family":[{"word":"influential","pos":"adj.","meaning":"有影響力的"},{"word":"influencer","pos":"n.","meaning":"網路意見領袖"}],"examples":[{"text":"The books we read can influence how we understand people whose experiences are different from our own.","translationZh":"我們閱讀的書，能影響我們如何理解那些經歷與自己不同的人。","grammar":"how 引導名詞子句，whose 表所有格關係。","writingTip":"可寫閱讀培養理解他人的能力。","topic":"閱讀與同理","source":"self-authored"},{"text":"Peer influence may encourage healthy habits, but it can also lead teenagers to take unnecessary risks.","translationZh":"同儕影響可能鼓勵健康習慣，也可能使青少年冒不必要的風險。","grammar":"lead someone to V 表導致行動，but 連接兩面效果。","writingTip":"適合分析人際影響的利弊。","topic":"同儕與健康","source":"self-authored"}],"usageNote":"動詞 influence 不加 on：influence my decision；名詞則可寫 an influence on my decision。"},"innovation":{"senses":[{"pos":"n.","meaning":"創新","usage":"不可數指過程或能力"},{"pos":"n.","meaning":"創新事物","usage":"可數指新方法或產品"}],"collocations":[{"en":"technological innovation","zh":"科技創新","note":"產業主題"},{"en":"encourage innovation","zh":"鼓勵創新","note":"組織文化"},{"en":"a major innovation","zh":"重大創新","note":"可數用法"},{"en":"innovation in healthcare","zh":"醫療領域的創新","note":"in 指領域"}],"synonyms":[{"en":"invention","zh":"發明","note":"較偏新產品或新裝置"},{"en":"new approach","zh":"新方法","note":"適用處理方式的創新"}],"idioms":[],"family":[{"word":"innovate","pos":"vi./vt.","meaning":"創新；改革"},{"word":"innovative","pos":"adj.","meaning":"創新的"},{"word":"innovator","pos":"n.","meaning":"創新者"}],"examples":[{"text":"Innovation in public transport can make daily travel easier for older people and those with disabilities.","translationZh":"大眾運輸的創新，能讓長者及身心障礙者的日常交通更方便。","source":"self-authored","grammar":"Innovation in public transport 是主詞；make daily travel easier 使用 make + 受詞 + 形容詞比較級。","writingTip":"分析交通創新時，寫出長者與身心障礙者等具體受益者。","topic":"inclusion"},{"text":"The teacher encouraged innovation by allowing students to design their own solutions to local problems.","translationZh":"老師讓學生自行設計地方問題的解方，藉此鼓勵創新。","source":"self-authored","grammar":"by + V-ing；solutions to + 問題","writingTip":"可寫探究式學習。","topic":"education"}],"usageNote":"innovation 指創新過程時通常不可數；指個別新方法或新產品時可數。"},"inspire":{"senses":[{"pos":"vt.","meaning":"激勵；啟發；引起","usage":"可接人，也可接希望、信心等感受。"}],"collocations":[{"en":"inspire someone to act","zh":"激勵某人行動","note":""},{"en":"inspire confidence","zh":"激發信心","note":""},{"en":"be inspired by nature","zh":"受到自然啟發","note":""},{"en":"inspire a sense of hope","zh":"帶來希望感","note":""}],"synonyms":[{"en":"motivate","zh":"激勵","note":"強調採取行動的動機，未必含創作啟發。"},{"en":"stimulate","zh":"刺激；促進","note":"可指促進思考、興趣或活動，不一定情感鼓舞。"}],"idioms":[],"family":[{"word":"inspiration","pos":"n.","meaning":"靈感；鼓舞"},{"word":"inspiring","pos":"adj.","meaning":"令人鼓舞的"},{"word":"inspired","pos":"adj.","meaning":"受到啟發的"}],"examples":[{"text":"A documentary about ocean pollution inspired our class to organize a cleanup along the nearby coast.","translationZh":"一部海洋污染紀錄片，啟發我們班到附近海岸舉辦淨灘活動。","grammar":"inspire someone to V，about 引出影片主題。","writingTip":"可寫媒體內容促成實際行動。","topic":"海洋與行動","source":"self-authored"},{"text":"The architect's design was inspired by local trees, allowing the building to blend naturally into its surroundings.","translationZh":"建築師的設計受在地樹木啟發，讓建築自然融入周圍環境。","grammar":"be inspired by，allowing 分詞片語說明結果。","writingTip":"適合描述自然與創作的關係。","topic":"設計與自然","source":"self-authored"}],"usageNote":"inspiring 描述令人受鼓舞的事物，inspired 描述受到啟發的人或創作。"},"integral":{"senses":[{"pos":"adj.","meaning":"不可或缺的","usage":""},{"pos":"adj.","meaning":"構成整體的一部分的","usage":""}],"collocations":[{"en":"an integral part of daily life","zh":"日常生活不可或缺的一部分","note":""},{"en":"an integral part of the team","zh":"團隊不可或缺的一員","note":""},{"en":"integral to success","zh":"成功所不可或缺的","note":""},{"en":"an integral component of the system","zh":"系統的必要組成部分","note":""}],"synonyms":[{"en":"essential","zh":"必要的","note":"essential 強調必要性，integral 強調與整體的關係"},{"en":"indispensable","zh":"不可缺少的","note":"語氣強烈"}],"idioms":[],"family":[{"word":"integrate","pos":"v.","meaning":"使整合；使融入"},{"word":"integration","pos":"n.","meaning":"整合；融入"},{"word":"integrated","pos":"adj.","meaning":"整合的"}],"usageNote":"常用 integral to + 名詞，或 an integral part of + 名詞；不是「完整的」的通用替換。","examples":[{"text":"Pets have become an integral part of many families, offering companionship and encouraging their owners to maintain a daily routine.","translationZh":"寵物已成為許多家庭不可或缺的一部分，提供陪伴，也鼓勵飼主維持日常作息。","source":"self-authored","grammar":"have become 表示至今形成的變化；offering/encouraging 補充作用。","writingTip":"從家庭中的重要性銜接陪伴與規律作息。","topic":"寵物陪伴"},{"text":"Reliable public transportation is integral to a city's development because it connects residents with schools, jobs, and essential services.","translationZh":"可靠的大眾運輸是城市發展不可或缺的一環，因為它連結居民與學校、工作及基本服務。","source":"self-authored","grammar":"integral to + 名詞；because 引導對必要性的說明。","writingTip":"以交通連結工作和服務來支持城市發展的論點。","topic":"公共運輸"}]},"integration":{"senses":[{"pos":"n.","meaning":"整合；融入群體或社會","usage":""}],"collocations":[{"en":"social integration","zh":"社會融入","note":""},{"en":"the integration of new students","zh":"新生的融入","note":""},{"en":"the integration of technology into teaching","zh":"科技融入教學","note":""},{"en":"promote community integration","zh":"促進社區融合","note":""}],"synonyms":[{"en":"inclusion","zh":"包容；納入","note":"inclusion 強調不被排除，integration 強調參與整體"},{"en":"combination","zh":"結合","note":"不一定涉及人融入社會"}],"idioms":[],"family":[{"word":"integrate","pos":"v.","meaning":"整合；使融入"},{"word":"integrated","pos":"adj.","meaning":"整合的"},{"word":"integral","pos":"adj.","meaning":"不可或缺的"}],"usageNote":"常見 the integration of A into B；融入不等於必須放棄自身文化。","examples":[{"text":"The integration of new students into school life becomes easier when classmates invite them to join clubs and group projects.","translationZh":"當同學邀請新生參與社團與小組作業時，新生更容易融入校園生活。","source":"self-authored","grammar":"the integration of A into B；when 引導變容易的條件。","writingTip":"用社團和小組作業具體說明如何幫助新生。","topic":"新生融入"},{"text":"The thoughtful integration of technology into teaching can expand learning opportunities without replacing meaningful interaction between teachers and students.","translationZh":"將科技適當融入教學，能擴大學習機會，同時保留師生間有意義的互動。","source":"self-authored","grammar":"of technology into teaching；without + V-ing 表示仍保留某要素。","writingTip":"可兼談科技帶來的機會與師生互動的價值。","topic":"科技教學"}]},"intention":{"senses":[{"pos":"n.","meaning":"意圖；打算","usage":"常用 intention of V-ing 或 intention to V。"}],"collocations":[{"en":"have no intention of leaving","zh":"無意離開","note":""},{"en":"with the intention of helping","zh":"抱著幫忙的意圖","note":""},{"en":"good intentions","zh":"善意","note":""},{"en":"make one's intentions clear","zh":"明確表達意圖","note":""}],"synonyms":[{"en":"purpose","zh":"目的","note":"聚焦想達到的結果或功能。"},{"en":"plan","zh":"計畫","note":"常比 intention 更具體，包括行動安排。"}],"idioms":[],"family":[{"word":"intend","pos":"vt.","meaning":"打算"},{"word":"intentional","pos":"adj.","meaning":"故意的"},{"word":"intentionally","pos":"adv.","meaning":"故意地"}],"examples":[{"text":"I joined the club with the intention of improving my English, but I also made lasting friendships.","translationZh":"我抱著增進英文的想法加入社團，卻也建立了長久的友誼。","grammar":"with the intention of V-ing，but 引出額外收穫。","writingTip":"可寫原先目標與意外收穫。","topic":"社團與友誼","source":"self-authored"},{"text":"Good intentions are not enough if a charity project ignores what the local community actually needs.","translationZh":"若公益專案忽略當地社區真正的需求，只有善意仍然不夠。","grammar":"if 引導條件子句，what 引導名詞子句。","writingTip":"適合討論服務前理解需求的重要性。","topic":"服務與社區","source":"self-authored"}],"usageNote":"intend to do 常見於動詞句型；名詞可用 intention of doing 或 intention to do。"},"interpret":{"senses":[{"pos":"vt.","meaning":"理解；詮釋","usage":"interpret A as B，把 A 理解為 B。"},{"pos":"vt./vi.","meaning":"口譯","usage":"為不同語言使用者口頭或手語傳譯。"}],"collocations":[{"en":"interpret the results","zh":"解讀結果","note":""},{"en":"interpret silence as agreement","zh":"把沉默理解為同意","note":""},{"en":"interpret a poem","zh":"詮釋詩作","note":""},{"en":"interpret for a visitor","zh":"為訪客口譯","note":""}],"synonyms":[{"en":"explain","zh":"解釋","note":"範圍較廣，interpret 更強調賦予或判讀意義。"},{"en":"translate","zh":"翻譯","note":"日常可泛稱翻譯；專業語境常區分筆譯與口譯。"}],"idioms":[],"family":[{"word":"interpretation","pos":"n.","meaning":"解讀；詮釋；口譯"},{"word":"interpreter","pos":"n.","meaning":"口譯員；解譯器"},{"word":"misinterpret","pos":"vt.","meaning":"誤解"}],"usageNote":"interpret data 須看背景與限制；interpret A as B 是一種解讀，不保證 B 就是原意。","examples":[{"text":"We should not interpret a classmate's silence as agreement, especially when the discussion moves too quickly for everyone to respond.","translationZh":"不應把同學的沉默解讀為同意，尤其當討論太快、不是每個人都來得及回應時。","grammar":"interpret A as B；too quickly for everyone to V 表速度造成限制。","writingTip":"團體決策作文提醒讀者確認意見，而非只依沉默推斷。","topic":"溝通與參與","source":"self-authored"},{"text":"The volunteer interpreted for a visitor at the clinic, helping the nurse understand which symptoms had started first.","translationZh":"志工在診所為訪客口譯，協助護理師了解哪些症狀最先出現。","grammar":"interpret for + 人；which 引導間接問句；had started 表較早發生。","writingTip":"服務經驗可具體寫出跨語言協助解決的需求。","topic":"醫療溝通","source":"self-authored"}]},"investigate":{"senses":[{"pos":"vt./vi.","meaning":"調查；研究","usage":"系統性尋找原因與事實"}],"collocations":[{"en":"investigate the cause","zh":"調查原因","note":"常接 of"},{"en":"investigate a complaint","zh":"調查申訴","note":"公共服務"},{"en":"investigate a possible link","zh":"研究可能的關聯","note":"研究語境"},{"en":"launch an investigation","zh":"展開調查","note":"名詞搭配"}],"synonyms":[{"en":"look into","zh":"調查","note":"較日常的片語"},{"en":"examine","zh":"檢查；研究","note":"不一定涉及完整調查"}],"idioms":[],"family":[{"word":"investigation","pos":"n.","meaning":"調查"},{"word":"investigator","pos":"n.","meaning":"調查人員"},{"word":"investigative","pos":"adj.","meaning":"調查的"}],"examples":[{"text":"Scientists are investigating whether warmer winters change the migration patterns of birds in the region.","translationZh":"科學家正在研究，較暖的冬天是否改變當地鳥類的遷徙模式。","source":"self-authored","grammar":"investigate whether + 子句","writingTip":"可描述研究問題而不預設結論。","topic":"science"},{"text":"The school investigated the complaint and asked students to describe what had happened during lunch.","translationZh":"學校調查了這項申訴，請學生描述午餐時發生的事。","source":"self-authored","grammar":"investigate + 受詞；what 引導名詞子句","writingTip":"可寫公平處理事件的程序。","topic":"school"}],"usageNote":"investigate 可直接接名詞或 whether 子句；look into 意近，但不能寫 investigate into the cause。"},"involve":{"senses":[{"pos":"vt.","meaning":"涉及；包含；使參與","usage":"可接人、事物或動名詞。"}],"collocations":[{"en":"involve someone in a project","zh":"讓某人參與專案","note":""},{"en":"involve careful planning","zh":"包含周詳規畫","note":""},{"en":"be involved in","zh":"參與；涉及","note":""},{"en":"involve taking risks","zh":"涉及冒險","note":""}],"synonyms":[{"en":"include","zh":"包含","note":"表示某項為整體的一部分，不一定要求行動。"},{"en":"engage","zh":"使參與","note":"常強調讓人投入或吸引注意。"}],"idioms":[],"family":[{"word":"involvement","pos":"n.","meaning":"參與；牽涉"},{"word":"involved","pos":"adj.","meaning":"參與的；複雜的"},{"word":"uninvolved","pos":"adj.","meaning":"未參與的"}],"examples":[{"text":"The cleanup involved sorting waste carefully so that recyclable materials would not end up in the wrong bins.","translationZh":"這次清理包含仔細分類垃圾，好讓可回收材料不會進入錯誤的桶子。","grammar":"involve V-ing，so that 表目的。","writingTip":"可寫環境行動所需的具體步驟。","topic":"環境與實作","source":"self-authored"},{"text":"Involving students in school decisions can help them feel responsible for improving the places they use every day.","translationZh":"讓學生參與校務決策，能使他們對改善日常使用的空間產生責任感。","grammar":"involve someone in，responsible for 後接動名詞。","writingTip":"適合支持學生參與公共事務。","topic":"校園與參與","source":"self-authored"}],"usageNote":"involve doing 表包含某行為，不寫 involve to do；involved in 的 in 是介系詞。"},"issue":{"senses":[{"pos":"n.","meaning":"議題；爭論焦點","usage":"a social / environmental issue；可指需要討論的主題，不一定是故障或錯誤。"},{"pos":"n.","meaning":"問題；困難","usage":"a technical issue / an issue with the device；此義常與 problem 接近。"},{"pos":"n.","meaning":"一期出版物；期號","usage":"the latest issue of a magazine；issue 指一期，article 指其中一篇文章。"},{"pos":"n.","meaning":"發行；核發","usage":"the issue of a passport / new shares；較正式，指核發或發行的行為。"},{"pos":"vt.","meaning":"正式發出；發布；核發","usage":"issue a warning / statement / ticket / passport；受詞是被發出的警告、文件或證件。"},{"pos":"vi.","meaning":"流出；冒出","usage":"Smoke issued from the building.；issue from 表從某處出現或流出，偏正式書面語。"}],"collocations":[{"en":"a social issue","zh":"社會議題","note":""},{"en":"the latest issue of a magazine","zh":"雜誌最新一期","note":""},{"en":"issue a warning","zh":"發布警告","note":""},{"en":"raise an issue","zh":"提出問題","note":""},{"en":"take issue with a claim","zh":"對某個說法提出異議","note":"take issue with = disagree with；不表示接收一期刊物。"},{"en":"issue a passport","zh":"核發護照","note":"issue 在此及物，政府或有權核發的機關通常作主詞。"}],"synonyms":[{"en":"problem","zh":"問題","note":"issue 也可指討論主題，不一定負面"},{"en":"release","zh":"發布","note":"適用公告或文件"}],"idioms":[],"family":[{"word":"issuance","pos":"n.","meaning":"發行；核發"},{"word":"issuer","pos":"n.","meaning":"發行者"}],"usageNote":"issue a warning 是正式發布警告；an issue of a magazine 是一期雜誌；an issue with a device 是裝置的問題。take issue with 表不同意，issue from 表正式語氣的流出或冒出；文法結構能幫助選義。","examples":[{"text":"The class discussed a social issue from several perspectives before each student wrote a short essay explaining a personal position.","translationZh":"全班先從不同角度討論一項社會議題，再由每位學生寫短文說明個人立場。","source":"self-authored","grammar":"before each student wrote 表先討論再寫作；explaining 修飾 essay。","writingTip":"以多角度討論作為形成個人立場的準備。","topic":"議論寫作"},{"text":"Local authorities issued a warning after heavy rainfall increased the risk of landslides along several roads leading to the mountain villages.","translationZh":"大雨增加通往山村的多條道路的崩塌風險後，地方政府發布警告。","source":"self-authored","grammar":"issued a warning；leading to 修飾 roads，表示道路通往的地方。","writingTip":"交代警告的天候背景及受影響地点。","topic":"山區災害"}]},"judgment":{"senses":[{"pos":"n.","meaning":"判斷；判決","usage":"可指判斷能力、看法或正式裁決。"}],"collocations":[{"en":"make a judgment","zh":"作出判斷","note":""},{"en":"use good judgment","zh":"運用良好判斷力","note":""},{"en":"pass judgment on","zh":"對……作評斷","note":""},{"en":"a court judgment","zh":"法院判決","note":""}],"synonyms":[{"en":"assessment","zh":"評估","note":"較強調根據資料作分析。"},{"en":"verdict","zh":"裁決","note":"常指陪審團結論，範圍比 judgment 窄。"}],"idioms":[{"en":"reserve judgment","zh":"暫不下定論","note":"表示先等更多證據。"}],"family":[{"word":"judge","pos":"vt.","meaning":"判斷；審判"},{"word":"judicial","pos":"adj.","meaning":"司法的"},{"word":"judgmental","pos":"adj.","meaning":"愛批判的"}],"examples":[{"text":"We should reserve judgment until we have heard both sides of the story and checked the available evidence.","translationZh":"聽過雙方說法並查證現有證據前，我們應暫不下定論。","grammar":"until 引導等待的界線，現在完成式表先完成查證。","writingTip":"可寫公平判斷與媒體識讀。","topic":"資訊與思辨","source":"self-authored"},{"text":"Her careful judgment helped the group choose a practical solution rather than the most impressive but costly proposal.","translationZh":"她審慎的判斷，幫團隊選擇實用方案，而非最吸睛卻昂貴的提案。","grammar":"rather than 連接兩種選擇，help someone choose 用原形。","writingTip":"適合比較可行性與表面吸引力。","topic":"合作與決策","source":"self-authored"}],"usageNote":"judgment 為常見美式拼字，judgement 亦見於英式用法；judgmental 多帶負面批判意味。"},"justify":{"senses":[{"pos":"vt.","meaning":"證明合理；為……辯護","usage":"後接名詞或 V-ing，提出足夠理由。"}],"collocations":[{"en":"justify a decision","zh":"說明決定的合理性","note":""},{"en":"justify spending more money","zh":"提出多花錢的充分理由","note":""},{"en":"justify the cost","zh":"證明這筆費用值得","note":""},{"en":"be justified in asking questions","zh":"有理由提出疑問","note":""}],"synonyms":[{"en":"defend","zh":"為……辯護","note":"可指維護立場，不一定已證明合理。"},{"en":"provide grounds for","zh":"為……提供理由","note":"須改成名詞或 V-ing 結構，不能直接逐字替換。"}],"idioms":[],"family":[{"word":"justification","pos":"n.","meaning":"正當理由；辯護"},{"word":"justifiable","pos":"adj.","meaning":"有正當理由的"},{"word":"unjustified","pos":"adj.","meaning":"沒有充分理由的"}],"usageNote":"justify doing，不寫 justify to do。說明原因不等於證明做法合理；理由仍須與代價、證據一起判斷。","examples":[{"text":"The team had to justify spending more money on durable materials instead of choosing the cheapest option available.","translationZh":"團隊必須說明，為何要多花錢選耐用材料，而不是最便宜的選項。","grammar":"justify + V-ing；instead of + V-ing；available 後置修飾 option。","writingTip":"比較成本時說明額外花費帶來的具體價值。","topic":"採購與永續","source":"self-authored"},{"text":"A desire to finish quickly does not justify ignoring safety rules that protect both workers and visitors.","translationZh":"想快速完成工作，並不足以合理化忽視保障工作人員與訪客安全的規則。","grammar":"desire to V 修飾名詞；justify ignoring；both A and B。","writingTip":"議論文可評估效率理由是否足以支持某種做法。","topic":"效率與安全","source":"self-authored"}]},"last":{"senses":[{"pos":"adj.","meaning":"最後的；上一次的","usage":""},{"pos":"v.","meaning":"持續；夠用","usage":""},{"pos":"adv.","meaning":"最後","usage":""}],"collocations":[{"en":"last for three hours","zh":"持續三小時","note":""},{"en":"make supplies last","zh":"讓物資用得更久","note":""},{"en":"at last","zh":"終於","note":""},{"en":"the last train","zh":"末班車","note":""}],"synonyms":[{"en":"final","zh":"最後的","note":"適用順序"},{"en":"continue","zh":"持續","note":"不一定有指定期限"}],"idioms":[],"family":[{"word":"lasting","pos":"adj.","meaning":"持久的"},{"word":"lastly","pos":"adv.","meaning":"最後一點"}],"usageNote":"last 作動詞不能與 last year 的形容詞義混淆；last for + 時間長度。","examples":[{"text":"The discussion lasted for two hours because students wanted to understand both the benefits and the drawbacks of the proposed policy.","translationZh":"討論持續兩小時，因為學生想了解提議政策的好處與缺點。","source":"self-authored","grammar":"lasted for + 時間；both A and B 連結利與弊。","writingTip":"可用討論時間反映學生對政策的认真評估。","topic":"政策討論"},{"text":"To make our limited supplies last, we shared tools and repaired old materials instead of buying new ones for every activity.","translationZh":"為讓有限物資用得更久，我們共用工具並修補舊材料，而非每次活動都買新的。","source":"self-authored","grammar":"make + supplies + 原形 last；instead of + V-ing。","writingTip":"說明共用和修補如何延長有限物資的使用。","topic":"資源節用"}]},"light":{"senses":[{"pos":"n.","meaning":"光；光線；日光","usage":"物理光線多作不可數名詞：natural light、the speed of light。"},{"pos":"n.","meaning":"燈；光源","usage":"指一盞燈或一處光源時可數：turn on the lights；a traffic light = 交通號誌。"},{"pos":"adj.","meaning":"重量輕的","usage":"a light bag；反義為 heavy。比較級 lighter 依語境也可能表示顏色更淡。"},{"pos":"adj.","meaning":"少量的；輕微的","usage":"a light meal、light rain、light traffic，分別指餐點份量少、雨勢小、車流少。"},{"pos":"adj.","meaning":"淡色的；明亮的","usage":"light blue = 淺藍色；a light room 可指光線充足的房間，需由後接名詞判義。"},{"pos":"adj.","meaning":"輕鬆的；輕快的","usage":"light reading / light entertainment 指輕鬆的讀物或娛樂；a light step 可指輕快的步伐。"},{"pos":"vt.","meaning":"點燃","usage":"light a candle / a fire；受詞為被點燃的物品。"},{"pos":"vt.","meaning":"照亮；提供照明","usage":"Street lamps light the road.；受詞為被照亮的地方。"},{"pos":"vi.","meaning":"點著；亮起","usage":"The candle will not light.；light up 也可指燈亮起或人的臉露出喜悅。"},{"pos":"adv.","meaning":"輕裝地","usage":"travel light = 輕裝旅行；light 在此修飾 travel，不寫成 travel lightly。"}],"collocations":[{"en":"light a candle","zh":"點燃蠟燭","note":""},{"en":"natural light","zh":"自然光","note":""},{"en":"a light meal","zh":"簡便的餐點","note":""},{"en":"in light of new evidence","zh":"考慮到新證據","note":""},{"en":"travel light","zh":"輕裝旅行","note":"固定搭配，light 作副詞；表示少帶行李。"},{"en":"light up the room","zh":"照亮房間","note":"light up 可為及物片語動詞；代名詞受詞放中間，如 light it up。"}],"synonyms":[{"en":"illumination","zh":"照明","note":"較正式的光照義"},{"en":"mild","zh":"輕微的","note":"可對應 light rain，不是重量輕"}],"idioms":[{"en":"shed light on","zh":"使更容易理解","note":"用於提供資訊釐清問題"}],"family":[{"word":"lighting","pos":"n.","meaning":"照明"},{"word":"lighten","pos":"v.","meaning":"減輕；使變亮"},{"word":"lightness","pos":"n.","meaning":"輕；明亮程度"},{"word":"lit","pos":"v.","meaning":"light 的過去式與過去分詞：點燃；照亮"},{"word":"lighted","pos":"v./adj.","meaning":"light 的另一過去式／過去分詞；點亮的"}],"usageNote":"動詞 light–lit/lighted–lit/lighted；lit 在一般敘事常見，lighted 也正確，如 a lighted candle。light 可指重量輕、程度小、顏色淡或光線亮，須看所修飾的名詞；travel light 中作副詞。","examples":[{"text":"The interview shed light on why some teenagers avoided school activities even when they wanted to make new friends.","translationZh":"訪談說明了有些青少年即使想交新朋友，為何仍避開校園活動。","source":"self-authored","grammar":"shed light on why + 子句；even when 引導讓步情境。","writingTip":"用訪談結果釐清表面行為背後的原因。","topic":"青少年訪談"},{"text":"We placed our reading desks near the window to use natural light and reduce the need for electric lamps during the day.","translationZh":"我們把閱讀桌放在窗邊利用自然光，減少白天使用電燈的需求。","source":"self-authored","grammar":"to use/reduce 為並列目的不定詞；near the window 表位置。","writingTip":"以位置調整說明簡單節能方法。","topic":"自然照明"}]},"limit":{"senses":[{"pos":"n.","meaning":"限制；界限","usage":"常接 on 表受限制的事物。"},{"pos":"vt.","meaning":"限制","usage":"常用 limit A to B。"}],"collocations":[{"en":"set a limit on screen time","zh":"限制螢幕使用時間","note":""},{"en":"limit spending to a fixed amount","zh":"把支出限於固定金額","note":""},{"en":"reach one's limit","zh":"達到自身極限","note":""},{"en":"within the speed limit","zh":"在速限內","note":""}],"synonyms":[{"en":"restrict","zh":"限制","note":"常表示以規則約束範圍或自由。"},{"en":"boundary","zh":"界線","note":"名詞，常強調邊界或人際界線。"}],"idioms":[],"family":[{"word":"limitation","pos":"n.","meaning":"限制；不足"},{"word":"limited","pos":"adj.","meaning":"有限的"},{"word":"limitless","pos":"adj.","meaning":"無限的"}],"examples":[{"text":"Setting clear limits on screen time helped our family make more room for conversation and outdoor activities.","translationZh":"明確限制螢幕時間，幫助我們家騰出更多時間交談與從事戶外活動。","grammar":"limits on，make room for 表挪出空間或機會。","writingTip":"可寫家庭約定如何改變生活。","topic":"科技與家庭","source":"self-authored"},{"text":"Limited public transportation can prevent people from reaching jobs that would otherwise improve their financial situation.","translationZh":"有限的大眾運輸，可能使人無法前往那些原本能改善經濟狀況的工作地點。","grammar":"prevent someone from V-ing，otherwise 表若無此限制。","writingTip":"適合分析交通資源對機會的影響。","topic":"交通與機會","source":"self-authored"}],"usageNote":"limited 為形容詞，limit 為名詞或動詞；limit A to B 的 to 後接範圍。"},"loneliness":{"senses":[{"pos":"n.","meaning":"孤獨；寂寞","usage":"通常不可數，指主觀缺乏連結的感受。"}],"collocations":[{"en":"experience loneliness","zh":"感到孤獨","note":""},{"en":"reduce loneliness","zh":"減輕孤獨","note":""},{"en":"feelings of loneliness","zh":"孤獨感","note":""},{"en":"loneliness among older adults","zh":"長者的孤獨問題","note":""}],"synonyms":[{"en":"isolation","zh":"孤立","note":"可能客觀與人分離，不一定感到寂寞。"},{"en":"solitude","zh":"獨處","note":"可自願且愉快，不等同 loneliness。"}],"idioms":[],"family":[{"word":"lonely","pos":"adj.","meaning":"寂寞的；偏僻的"}],"examples":[{"text":"Regular visits from volunteers can reduce loneliness among older adults who live far from their families.","translationZh":"志工定期探訪，能減輕那些遠離家人生活的長者的孤獨感。","grammar":"loneliness among 表特定群體，who 引導關係子句。","writingTip":"適合討論高齡社會的情感需求。","topic":"高齡與服務","source":"self-authored"},{"text":"Having hundreds of online contacts does not necessarily protect a person from loneliness or provide meaningful emotional support.","translationZh":"擁有數百位網路聯絡人，不一定能避免孤獨，也不一定提供有意義的情感支持。","grammar":"動名詞作主詞，not necessarily 表不必然。","writingTip":"可比較聯絡人數與人際品質。","topic":"社群與心理","source":"self-authored"}],"usageNote":"loneliness 是感受，alone 描述一個人的狀態；獨處不必然等於孤獨。"},"loyal":{"senses":[{"pos":"adj.","meaning":"忠誠的；忠實的","usage":""}],"collocations":[{"en":"loyal to one's friends","zh":"忠於朋友","note":""},{"en":"a loyal customer","zh":"忠實顧客","note":""},{"en":"a loyal companion","zh":"忠實的同伴","note":""},{"en":"remain loyal to a team","zh":"持續支持某團隊","note":""}],"synonyms":[{"en":"faithful","zh":"忠誠的","note":"faithful 也可指如實的翻譯"},{"en":"devoted","zh":"專注且忠誠的","note":"強調深厚投入"}],"idioms":[],"family":[{"word":"loyalty","pos":"n.","meaning":"忠誠；忠實"},{"word":"loyally","pos":"adv.","meaning":"忠誠地"},{"word":"disloyal","pos":"adj.","meaning":"不忠的"}],"usageNote":"loyal to + 對象；loyalty to + 對象。忠誠不等於不能提出合理批評。","examples":[{"text":"A loyal friend does more than agree with everything we say; sometimes, honest advice is the most valuable form of support.","translationZh":"忠實的朋友不只附和我們所有的話；有時誠實的建議才是最珍貴的支持。","source":"self-authored","grammar":"does more than + 原形動詞；sometimes 引出以 honest advice 為主詞的補充說明。","writingTip":"可論述支持朋友也包括誠實建議。","topic":"真誠友情"},{"text":"The shop kept many loyal customers by remembering their preferences and responding politely whenever a problem arose with an order.","translationZh":"那家店記得顧客喜好，並在訂單出問題時禮貌回應，因此留住了許多忠實顧客。","source":"self-authored","grammar":"by remembering/responding 表留住顧客的方法；whenever 引導每次出問題時。","writingTip":"把忠實顧客的形成連結到具體服務品質。","topic":"顧客服務"}]},"maintain":{"senses":[{"pos":"vt.","meaning":"維持","usage":"狀態或水準"},{"pos":"vt.","meaning":"保養","usage":"設備"},{"pos":"vt.","meaning":"堅稱","usage":"maintain that + 子句"}],"collocations":[{"en":"maintain a healthy balance","zh":"維持健康平衡","note":"生活安排"},{"en":"maintain equipment","zh":"保養設備","note":"實體義"},{"en":"maintain contact with friends","zh":"與朋友保持聯絡","note":"with 指對象"},{"en":"maintain that a claim is true","zh":"堅稱某主張屬實","note":"陳述觀點"}],"synonyms":[{"en":"preserve","zh":"維持；保存","note":"著重避免狀態流失"},{"en":"insist","zh":"堅稱","note":"只對應主張的意思"}],"idioms":[{"en":"keep something going","zh":"讓某事持續運作","note":"對應維持活動或服務，不適用堅稱觀點的意思。"}],"family":[{"word":"maintenance","pos":"n.","meaning":"維護；保養"},{"word":"maintainable","pos":"adj.","meaning":"可維護的"}],"examples":[{"text":"Regular checks help maintain the equipment and reduce the chance of accidents during school experiments.","translationZh":"定期檢查有助於保養設備，降低學校實驗發生事故的可能。","source":"self-authored","grammar":"help 後接原形動詞 maintain 與 reduce；the equipment 與 the chance 分別是兩動詞的受詞。","writingTip":"說明定期檢查時，可並列維護設備與降低事故機率兩項效益。","topic":"safety"},{"text":"Despite the criticism, the mayor maintained that the new park would benefit nearby residents.","translationZh":"儘管受到批評，市長仍堅稱新公園會使附近居民受益。","source":"self-authored","grammar":"maintain that；despite + 名詞","writingTip":"閱讀報導時辨別說話者主張與已證實事實。","topic":"public policy"}],"usageNote":"maintain 可指保養設備、維持狀態，也可指堅稱觀點；maintenance 是保養的名詞。"},"mature":{"senses":[{"pos":"adj.","meaning":"成熟的；發育完全的","usage":"可描述人、思考或生物。"},{"pos":"vi.","meaning":"成熟；到期","usage":"可指成長或投資到期。"}],"collocations":[{"en":"a mature attitude","zh":"成熟的態度","note":""},{"en":"mature into an adult","zh":"成長為成人","note":""},{"en":"a mature forest","zh":"成熟林","note":""},{"en":"a bond matures","zh":"債券到期","note":"金融語境的特殊意思。"}],"synonyms":[{"en":"grown-up","zh":"成熟的；成年的","note":"較日常，未必表示思考成熟。"},{"en":"develop","zh":"發展","note":"範圍更廣，不一定達到成熟階段。"}],"idioms":[],"family":[{"word":"maturity","pos":"n.","meaning":"成熟；到期"},{"word":"immature","pos":"adj.","meaning":"不成熟的"},{"word":"maturation","pos":"n.","meaning":"成熟過程"}],"examples":[{"text":"A mature response to criticism involves listening carefully and deciding which suggestions can genuinely improve our work.","translationZh":"成熟面對批評，包含仔細聆聽，並判斷哪些建議真能改進作品。","grammar":"involve 後接並列動名詞，which 引導名詞子句。","writingTip":"可寫理性接受回饋。","topic":"學習與成長","source":"self-authored"},{"text":"As the young trees mature, they will provide more shade and create habitats for local wildlife.","translationZh":"隨著幼樹成熟，它們將提供更多樹蔭，並為在地野生動物創造棲地。","grammar":"as 表隨著，when 或 as 的未來時間子句使用現在式。","writingTip":"適合說明植樹的長期效益。","topic":"生態與永續","source":"self-authored"}],"usageNote":"mature 可形容心理或生物成熟；financial products mature 則指到期。"},"mean":{"senses":[{"pos":"vt.","meaning":"表示；意指","usage":"mean + 字詞、符號或子句，說明其意義：What does this sign mean?"},{"pos":"vt.","meaning":"打算；有意做","usage":"mean to V = intend to V；I meant to call you 指原本打算打電話。"},{"pos":"vt.","meaning":"意味著；必然涉及","usage":"mean + V-ing 或名詞，表示某事所帶來的結果或代價；mean changing the plan = 意味著要改變計畫。"},{"pos":"vt.","meaning":"對某人有重要性","usage":"mean a lot / much / something to someone；to 後接感到其重要性的人。"},{"pos":"adj.","meaning":"刻薄的；不友善的","usage":"be mean to someone = 對某人刻薄；形容態度，不能當作 mean to V「打算」解讀。"},{"pos":"adj.","meaning":"吝嗇的","usage":"be mean with money = 不願花錢或給錢；與形容待人刻薄的語境不同。"},{"pos":"adj.","meaning":"平均的","usage":"mean temperature / mean score 指統計平均值，修飾後面的名詞。"},{"pos":"n.","meaning":"平均數","usage":"the mean of the scores；通常指各數值相加後除以數量的算術平均數，與 median「中位數」不同。"}],"collocations":[{"en":"mean a lot to someone","zh":"對某人很重要","note":""},{"en":"mean to help","zh":"打算幫忙","note":""},{"en":"mean giving up free time","zh":"意味著放棄空閒時間","note":""},{"en":"the mean score","zh":"平均分數","note":""},{"en":"be mean to someone","zh":"對某人刻薄","note":"to + 人；be mean to someone 與 mean to do something 的結構及詞性不同。"},{"en":"calculate the mean","zh":"計算平均數","note":"mean 在此為可數名詞；常見於圖表與統計情境。"}],"synonyms":[{"en":"signify","zh":"表示","note":"較正式的意義表達"},{"en":"intend","zh":"打算","note":"mean to V 對應 intend to V"}],"idioms":[],"family":[{"word":"meaning","pos":"n.","meaning":"意思；意義"},{"word":"meaningful","pos":"adj.","meaning":"有意義的"},{"word":"meaningless","pos":"adj.","meaning":"無意義的"},{"word":"meant","pos":"v.","meaning":"mean 的過去式與過去分詞：意指；打算；意味著"}],"usageNote":"動詞 mean–meant–meant。mean to V 表打算，mean V-ing 表意味著；be mean to + 人 表對某人刻薄。mean、median、mode 分別是平均數、中位數、眾數。原釋義中的低劣、卑賤等較舊或特定語域用法仍保留於完整原釋義，日常寫作應依語境選義。","examples":[{"text":"Taking care of a pet means giving up some free time, but it can also teach patience and responsibility.","translationZh":"照顧寵物意味著犧牲部分空閒時間，但也能教人耐心與責任感。","source":"self-authored","grammar":"taking care of 動名詞作主詞；means + V-ing 表意味著。","writingTip":"同時說明飼養需要付出及可能學到的責任。","topic":"養寵物取捨"},{"text":"Your encouragement meant a lot to me when I was unsure whether I could complete the project on my own.","translationZh":"當我不確定能否獨力完成專題時，你的鼓勵對我很重要。","source":"self-authored","grammar":"meant a lot to + 人；whether 引導當時不確定的問題。","writingTip":"可用對我很重要來連結鼓勵與克服自我懷疑。","topic":"朋友鼓勵"}]},"measure":{"senses":[{"pos":"vt.","meaning":"測量","usage":"尺寸或數量"},{"pos":"vt.","meaning":"衡量","usage":"評估抽象表現"},{"pos":"n.","meaning":"措施","usage":"常用複數 measures"}],"collocations":[{"en":"measure the temperature","zh":"測量溫度","note":"科學操作"},{"en":"take preventive measures","zh":"採取預防措施","note":"名詞搭配"},{"en":"measure success","zh":"衡量成功","note":"抽象義"},{"en":"a measure of ability","zh":"能力的衡量指標","note":"名詞義"}],"synonyms":[{"en":"gauge","zh":"測量；判斷","note":"適用程度或狀況"},{"en":"step","zh":"措施","note":"只對應行動方案的名詞義"}],"idioms":[],"family":[{"word":"measurement","pos":"n.","meaning":"測量；測量值"},{"word":"measurable","pos":"adj.","meaning":"可測量的"}],"examples":[{"text":"Students measured the temperature of the water before adding ice to observe how quickly it changed.","translationZh":"學生先測量水溫，再加入冰塊，觀察溫度改變的速度。","source":"self-authored","grammar":"measure + 受詞；before + V-ing","writingTip":"可敘述實驗步驟。","topic":"science"},{"text":"The city took several measures to protect pedestrians near schools during busy morning hours.","translationZh":"市府採取多項措施，在繁忙的早晨時段保護學校附近的行人。","source":"self-authored","grammar":"take measures to V","writingTip":"可用於交通安全政策。","topic":"transport"}],"usageNote":"measure 作名詞可指措施；take measures to V 是常見搭配，不是進行測量。"},"monitor":{"senses":[{"pos":"vt.","meaning":"監測；持續觀察","usage":"追蹤變化"},{"pos":"n.","meaning":"螢幕；監測器","usage":"電子設備"},{"pos":"n.","meaning":"班長；監督者","usage":"特定職務"}],"collocations":[{"en":"monitor air quality","zh":"監測空氣品質","note":"環境數據"},{"en":"monitor student progress","zh":"追蹤學生進展","note":"教育情境"},{"en":"a computer monitor","zh":"電腦螢幕","note":"名詞"},{"en":"a heart monitor","zh":"心臟監測器","note":"醫療設備"}],"synonyms":[{"en":"track","zh":"追蹤","note":"著重持續記錄變化"},{"en":"observe","zh":"觀察","note":"不一定長期或有系統"}],"idioms":[],"family":[{"word":"monitoring","pos":"n.","meaning":"監測"},{"word":"monitored","pos":"adj.","meaning":"受到監測的"}],"examples":[{"text":"Researchers monitor air quality near the factory to determine whether new regulations are working.","translationZh":"研究人員監測工廠附近的空氣品質，以確認新規定是否奏效。","source":"self-authored","grammar":"monitor + 受詞；whether 引導名詞子句","writingTip":"政策分析可交代驗證方法。","topic":"environment"},{"text":"The nurse checked the heart monitor before explaining the patient's condition to the family.","translationZh":"護理師先查看心臟監測器，再向家屬說明病人的狀況。","source":"self-authored","grammar":"the heart monitor 是 checked 的受詞，monitor 在此為可數名詞；before explaining 是 before + V-ing。","writingTip":"醫療情境可用 monitor 指儀器，並以查看後說明病況呈現動作順序。","topic":"health"}],"usageNote":"monitor 作動詞指持續監測；作名詞可指螢幕、監測器或班級職務。"},"motivation":{"senses":[{"pos":"n.","meaning":"動機；動力","usage":"通常不可數，也可指某項行為背後的原因。"}],"collocations":[{"en":"motivation to learn","zh":"學習動力","note":""},{"en":"intrinsic motivation","zh":"內在動機","note":""},{"en":"lose motivation","zh":"失去動力","note":""},{"en":"the motivation behind a decision","zh":"決定背後的動機","note":""}],"synonyms":[{"en":"incentive","zh":"誘因","note":"常是外在獎勵或刺激，不等於內在動力。"},{"en":"drive","zh":"幹勁","note":"強調持續追求目標的強烈力量。"}],"idioms":[],"family":[{"word":"motivate","pos":"vt.","meaning":"激勵"},{"word":"motivated","pos":"adj.","meaning":"有動力的"},{"word":"motivational","pos":"adj.","meaning":"激勵的"}],"examples":[{"text":"My motivation to learn Spanish increased when I realized that it would help me communicate with new friends.","translationZh":"當我發現西班牙文能幫助我與新朋友溝通時，學習動力便增加了。","grammar":"motivation to V，realize that 接認知內容。","writingTip":"可寫真實需求帶來學習動力。","topic":"語言與友誼","source":"self-authored"},{"text":"Rewards may provide short-term motivation, but genuine interest often keeps students learning after the rewards disappear.","translationZh":"獎勵可能提供短期動力，但真正的興趣往往讓學生在獎勵消失後仍持續學習。","grammar":"keep someone V-ing，after 引導時間子句。","writingTip":"適合比較外在獎勵與內在興趣。","topic":"教育與動機","source":"self-authored"}],"usageNote":"motivation 是名詞，motivated 是有動力的；不要把 motivational 當成描述人的常用形式。"},"natural":{"senses":[{"pos":"adj.","meaning":"天然的；自然的","usage":"非人工"},{"pos":"adj.","meaning":"天生的","usage":"能力或傾向"},{"pos":"adj.","meaning":"合理正常的","usage":"反應可理解"}],"collocations":[{"en":"natural resources","zh":"自然資源","note":"環境用語"},{"en":"a natural talent","zh":"天生才能","note":"能力描述"},{"en":"natural disasters","zh":"天然災害","note":"災害主題"},{"en":"a natural reaction","zh":"自然反應","note":"情緒或行為"}],"synonyms":[{"en":"inborn","zh":"天生的","note":"對應能力或特質"},{"en":"normal","zh":"正常的","note":"對應合理常見的反應"}],"idioms":[],"family":[{"word":"nature","pos":"n.","meaning":"自然；本性"},{"word":"naturally","pos":"adv.","meaning":"自然地；當然"},{"word":"unnatural","pos":"adj.","meaning":"不自然的"}],"examples":[{"text":"It is natural to feel nervous before speaking in public, even after careful preparation.","translationZh":"即使做了仔細準備，在公開發言前感到緊張也是自然的。","source":"self-authored","grammar":"It 是形式主詞，真正主詞為 to feel nervous；before speaking 是 before + V-ing。","writingTip":"寫公開發言經驗時，可用 It is natural to... 表達緊張是可理解的反應。","topic":"personal experience"},{"text":"Protecting natural resources requires us to think about the needs of future generations.","translationZh":"保護自然資源，需要我們考量未來世代的需求。","source":"self-authored","grammar":"V-ing 作主詞；require 人 to V","writingTip":"適合永續議題的責任論述。","topic":"sustainability"}],"usageNote":"natural 的意思依名詞而變；natural talent 是天生才能，natural reaction 是合理的反應。"},"neglect":{"senses":[{"pos":"vt.","meaning":"忽視；疏於照顧","usage":"neglect to V 表疏忽而沒做。"},{"pos":"n.","meaning":"疏忽；疏於照顧","usage":"通常不可數。"}],"collocations":[{"en":"neglect one's health","zh":"忽視健康","note":""},{"en":"neglect one's duties","zh":"疏於履行職責","note":""},{"en":"neglect to check","zh":"忘了或疏於檢查","note":""},{"en":"suffer from neglect","zh":"因乏人照顧而受苦","note":""}],"synonyms":[{"en":"ignore","zh":"忽略","note":"可能刻意不理會，neglect 常含未善盡照顧責任。"},{"en":"overlook","zh":"漏看；忽視","note":"可能因未注意而遺漏，不必有照顧義。"}],"idioms":[],"family":[{"word":"neglected","pos":"adj.","meaning":"被忽略的；乏人照顧的"},{"word":"neglectful","pos":"adj.","meaning":"疏忽的"},{"word":"neglectfully","pos":"adv.","meaning":"疏忽地"}],"examples":[{"text":"Students should not neglect their health while preparing for exams, since exhaustion can make learning less effective.","translationZh":"學生準備考試時不該忽視健康，因為疲憊可能降低學習效果。","grammar":"while V-ing，make 受詞 adjective 描述結果。","writingTip":"適合寫考試與休息的平衡。","topic":"升學與健康","source":"self-authored"},{"text":"Years of neglect left the playground unsafe, prompting residents to request repairs from the local government.","translationZh":"多年失修讓遊樂場變得不安全，促使居民向地方政府要求修繕。","grammar":"leave 受詞 adjective，prompting 分詞片語表示後續結果。","writingTip":"可描述公共空間維護與公民行動。","topic":"社區與安全","source":"self-authored"}],"usageNote":"neglect one's health 指沒有妥善照顧；neglect to do 側重疏於採取必要行動。"},"novel":{"senses":[{"pos":"n.","meaning":"小說","usage":""},{"pos":"adj.","meaning":"新穎的","usage":""}],"collocations":[{"en":"read a novel","zh":"讀小說","note":""},{"en":"a historical novel","zh":"歷史小說","note":""},{"en":"a novel approach","zh":"新穎的方法","note":""},{"en":"a novel idea","zh":"新穎的點子","note":""}],"synonyms":[{"en":"fiction","zh":"小說類文學","note":"fiction 是不可數文類，a novel 是一本長篇小說"},{"en":"innovative","zh":"創新的","note":"形容詞義相近"}],"idioms":[],"family":[{"word":"novelist","pos":"n.","meaning":"小說家"},{"word":"novelty","pos":"n.","meaning":"新奇；新奇事物"}],"usageNote":"novel 作形容詞不是「小說的」；novel method 表新穎方法。","examples":[{"text":"The historical novel helped me imagine everyday life in the past, though I checked other sources to separate fact from fiction.","translationZh":"歷史小說幫助我想像過去的日常生活，但我仍查閱其他來源，區分事實與虛構。","source":"self-authored","grammar":"though 引導讓步；to separate A from B 表區分目的。","writingTip":"區分閱讀的想像力收益與事實查核需求。","topic":"歷史小說閱讀"},{"text":"Our group proposed a novel approach to collecting used batteries by placing clearly labeled boxes beside familiar school recycling bins.","translationZh":"我們小組提出收集廢電池的新方法，在熟悉的校園回收桶旁放置清楚標示的箱子。","source":"self-authored","grammar":"a novel approach to + V-ing；by placing 表實施方法。","writingTip":"以回收箱的位置與標示具體化新方法。","topic":"電池回收"}]},"object":{"senses":[{"pos":"n.","meaning":"物件；目標","usage":""},{"pos":"v.","meaning":"反對","usage":""}],"collocations":[{"en":"a physical object","zh":"實體物件","note":""},{"en":"the object of the exercise","zh":"練習的目的","note":""},{"en":"object to a decision","zh":"反對決定","note":""},{"en":"object to being photographed","zh":"反對被拍照","note":""}],"synonyms":[{"en":"item","zh":"物品","note":"較常見且具體"},{"en":"oppose","zh":"反對","note":"oppose 直接接受詞，object 必須接 to"}],"idioms":[],"family":[{"word":"objection","pos":"n.","meaning":"反對；異議"},{"word":"objective","pos":"adj./n.","meaning":"客觀的；目標"},{"word":"objector","pos":"n.","meaning":"反對者"}],"usageNote":"名詞和動詞重音常不同；object to + 名詞／V-ing，其中 to 是介系詞。","examples":[{"text":"Some residents objected to the new parking lot because they feared it would remove the neighborhood's only safe place for children to play.","translationZh":"一些居民反對新停車場，因為他們擔心這會移除社區唯一能讓孩子安全玩耍的地方。","source":"self-authored","grammar":"objected to + 名詞；because 解釋反對停車場的原因。","writingTip":"反對方案時指出它對公共空間的實際影響。","topic":"社區空間"},{"text":"The object of the activity was not to win, but to help students communicate clearly while solving a problem together.","translationZh":"活動的目的不是獲勝，而是讓學生在共同解決問題時學習清楚溝通。","source":"self-authored","grammar":"the object of + 活動；not to V, but to V 比較目的。","writingTip":"可說明活動價值在合作而不只在勝負。","topic":"合作學習"}]},"observe":{"senses":[{"pos":"vt.","meaning":"觀察；注意到","usage":"observe someone do／doing 可描述觀察動作。"},{"pos":"vt.","meaning":"遵守","usage":"observe rules。"},{"pos":"vt.","meaning":"慶祝；紀念","usage":"observe a holiday。"},{"pos":"vt.","meaning":"評論；說到","usage":"observe that...，較正式。"}],"collocations":[{"en":"observe changes in behavior","zh":"觀察行為變化","note":""},{"en":"observe safety rules","zh":"遵守安全規則","note":""},{"en":"observe a minute of silence","zh":"默哀一分鐘","note":""},{"en":"observe that something has changed","zh":"指出某事已改變","note":""}],"synonyms":[{"en":"watch","zh":"觀看；留意","note":"較日常，不涵蓋遵守或評論義。"},{"en":"comply with","zh":"遵守","note":"只對應規則義，句型需加 with。"}],"idioms":[],"family":[{"word":"observation","pos":"n.","meaning":"觀察；評論"},{"word":"observer","pos":"n.","meaning":"觀察者"},{"word":"observant","pos":"adj.","meaning":"善於觀察的"}],"usageNote":"observe 有觀察、遵守、紀念與評論等義。observant 指眼光敏銳；observed 可指被觀察到的，兩者不同。","examples":[{"text":"During the field trip, students observed how birds used different parts of the wetland for feeding and resting.","translationZh":"校外教學時，學生觀察鳥類如何利用濕地不同區域覓食與休息。","grammar":"observe + how 子句；for feeding and resting 表用途。","writingTip":"自然觀察作文交代行為與場所的關聯。","topic":"濕地觀察","source":"self-authored"},{"text":"Visitors are asked to observe the quiet hours so that patients can rest without being disturbed by conversations in the hallway.","translationZh":"院方請訪客遵守安靜時段，讓病人不受走廊交談干擾而能休息。","grammar":"are asked to V 為被動；without being disturbed 為動名詞被動。","writingTip":"規範作文可把要求連結受到保護者的需求。","topic":"公共禮儀","source":"self-authored"}]},"obtain":{"senses":[{"pos":"vt.","meaning":"取得；獲得","usage":"通常經過努力、申請或程序"}],"collocations":[{"en":"obtain permission","zh":"取得許可","note":"程序語境"},{"en":"obtain information","zh":"取得資訊","note":"研究工作"},{"en":"obtain a license","zh":"取得執照","note":"正式資格"},{"en":"obtain reliable results","zh":"取得可靠結果","note":"研究語境"}],"synonyms":[{"en":"get","zh":"取得","note":"較日常，範圍廣"},{"en":"acquire","zh":"獲得","note":"較正式，常指知識、技能或資產"}],"idioms":[],"family":[{"word":"obtainable","pos":"adj.","meaning":"可取得的"}],"examples":[{"text":"Students must obtain permission from their parents before joining the overnight trip organized by the school.","translationZh":"學生參加學校安排的過夜旅行前，必須先取得家長許可。","source":"self-authored","grammar":"obtain A from B；before + V-ing","writingTip":"適合活動規範說明。","topic":"school"},{"text":"The team obtained useful information by interviewing residents who had lived in the area for decades.","translationZh":"團隊訪談在當地住了數十年的居民，取得了實用資訊。","source":"self-authored","grammar":"obtain + 受詞；by + V-ing","writingTip":"可描寫田野調查方法。","topic":"research"}],"usageNote":"obtain 比 get 正式，常暗示透過程序或努力取得；動詞後直接接受詞。"},"occur":{"senses":[{"pos":"vi.","meaning":"發生","usage":"不接受詞"},{"pos":"vi.","meaning":"浮現於心中","usage":"occur to + 人"}],"collocations":[{"en":"occur frequently","zh":"經常發生","note":"副詞搭配"},{"en":"occur in nature","zh":"在自然界出現","note":"in 指場所"},{"en":"occur to someone","zh":"某人想到","note":"熟詞偏義"},{"en":"an unexpected occurrence","zh":"意外事件","note":"名詞形式"}],"synonyms":[{"en":"happen","zh":"發生","note":"較日常，未必有規律"},{"en":"take place","zh":"舉行；發生","note":"常用於已安排事件或實際發生的事"}],"idioms":[],"family":[{"word":"occurrence","pos":"n.","meaning":"發生；事件"}],"examples":[{"text":"Flooding may occur more often when heavy rain falls on streets covered with concrete.","translationZh":"豪雨落在鋪滿混凝土的街道上時，淹水可能更常發生。","source":"self-authored","grammar":"occur 為不及物動詞；covered with 修飾 streets","writingTip":"可解釋都市淹水原因。","topic":"environment"},{"text":"It suddenly occurred to me that our project could include interviews with older residents.","translationZh":"我突然想到，我們的專題可以加入對年長居民的訪談。","source":"self-authored","grammar":"It occurred to 人 that + 子句","writingTip":"敘事作文可描述靈感出現。","topic":"personal experience"}],"usageNote":"occur 不及物，沒有被動式；過去式 occurred，現在分詞 occurring 要雙寫 r。"},"operate":{"senses":[{"pos":"vt.","meaning":"操作；經營","usage":"operate equipment 或 business"},{"pos":"vi.","meaning":"運作","usage":"機器或系統"},{"pos":"vi.","meaning":"動手術","usage":"operate on + 人或部位"}],"collocations":[{"en":"operate machinery","zh":"操作機器","note":"及物動詞"},{"en":"operate a business","zh":"經營企業","note":"商業語境"},{"en":"operate on a patient","zh":"替病人動手術","note":"on 不可省略"},{"en":"operate smoothly","zh":"運作順暢","note":"不及物動詞"}],"synonyms":[{"en":"run","zh":"運作；經營","note":"對應設備或企業語境"},{"en":"perform surgery","zh":"進行手術","note":"只對應醫療義"}],"idioms":[],"family":[{"word":"operation","pos":"n.","meaning":"運作；手術"},{"word":"operator","pos":"n.","meaning":"操作員；經營者"},{"word":"operational","pos":"adj.","meaning":"運作中的"}],"examples":[{"text":"Only trained staff are allowed to operate the machinery because even a small mistake can cause injury.","translationZh":"只有受過訓練的員工才能操作機器，因為小錯誤也可能造成傷害。","source":"self-authored","grammar":"are allowed to operate 是 allow 人 to V 的被動式；operate 直接接受詞 the machinery；because 引出原因。","writingTip":"列安全規定時，補上小失誤可能傷人的理由，讓規定有依據。","topic":"safety"},{"text":"The bus service operates late into the night so that shift workers can return home safely.","translationZh":"公車服務營運至深夜，讓輪班工作者能安全回家。","source":"self-authored","grammar":"operate 不及物；so that 引導目的","writingTip":"可討論交通服務的社會需求。","topic":"transport"}],"usageNote":"操作機器用 operate + 受詞；替病人動手術用 operate on + 人。"},"opportunity":{"senses":[{"pos":"n.","meaning":"機會","usage":"通常可數，可接 to V 或 for 加名詞。"}],"collocations":[{"en":"an opportunity to learn","zh":"學習機會","note":""},{"en":"provide opportunities for students","zh":"提供學生機會","note":""},{"en":"take the opportunity to","zh":"把握機會……","note":""},{"en":"equal opportunities","zh":"平等機會","note":""}],"synonyms":[{"en":"chance","zh":"機會","note":"較日常，也可表示可能性。"},{"en":"opening","zh":"空缺；機會","note":"常用於職缺，適用範圍較窄。"}],"idioms":[],"family":[{"word":"opportune","pos":"adj.","meaning":"時機恰當的"},{"word":"opportunistic","pos":"adj.","meaning":"投機的；伺機而動的"}],"examples":[{"text":"The exchange program gave students an opportunity to challenge stereotypes through conversations with people from different backgrounds.","translationZh":"這項交流計畫讓學生有機會與不同背景的人交談，挑戰既有刻板印象。","grammar":"opportunity to V，through 表藉由途徑。","writingTip":"可寫文化交流的具體收穫。","topic":"交流與文化","source":"self-authored"},{"text":"Without affordable transportation, many rural students miss opportunities to attend events that could broaden their interests.","translationZh":"缺乏負擔得起的交通，許多偏鄉學生會錯失拓展興趣的活動機會。","grammar":"without 表缺少條件，that 引導關係子句。","writingTip":"適合討論資源差距與機會平等。","topic":"教育與偏鄉","source":"self-authored"}],"usageNote":"opportunity 通常可數，寫 many opportunities；opportunistic 常有趁勢謀利的意味，不等於機會很多。"},"option":{"senses":[{"pos":"n.","meaning":"選項；選擇權","usage":"option to V 或 of V-ing"}],"collocations":[{"en":"have the option of staying","zh":"可以選擇留下","note":"of 接 V-ing"},{"en":"consider different options","zh":"考慮不同選項","note":"可數複數"},{"en":"a practical option","zh":"可行選項","note":"方案評估"},{"en":"keep options open","zh":"保留選擇餘地","note":"常見慣用搭配"}],"synonyms":[{"en":"choice","zh":"選擇；選項","note":"較日常，意思廣"},{"en":"alternative","zh":"替代方案","note":"通常指另一個可取代現有方案的選擇"}],"idioms":[{"en":"keep one's options open","zh":"保留選擇餘地","note":"表示暫不把選擇限制在單一方案。"}],"family":[{"word":"optional","pos":"adj.","meaning":"可選擇的；非必要的"},{"word":"optionally","pos":"adv.","meaning":"可選擇地"}],"examples":[{"text":"For students who live nearby, walking to school is a healthy and inexpensive option.","translationZh":"對住得近的學生而言，走路上學是健康又便宜的選項。","source":"self-authored","grammar":"walking to school 是 V-ing 片語作主詞；a healthy and inexpensive option 是主詞補語；who live nearby 修飾 students。","writingTip":"比較交通方式時，先限定住得近的學生，避免建議過度概括。","topic":"transport"},{"text":"The course gives learners the option of completing the final project individually or in pairs.","translationZh":"這門課讓學習者可以選擇獨自或兩人一組完成期末專題。","source":"self-authored","grammar":"the option of + V-ing","writingTip":"可說明學習制度提供的彈性。","topic":"education"}],"usageNote":"option 是名詞；optional 是形容詞，表示非必選，不等同於可替換的 alternative。"},"overcome":{"senses":[{"pos":"vt.","meaning":"克服；戰勝","usage":"overcome a difficulty；不用 with 直接接困難。"},{"pos":"vt.","meaning":"使承受不住","usage":"常用 be overcome by／with emotion。"}],"collocations":[{"en":"overcome a fear","zh":"克服恐懼","note":""},{"en":"overcome an obstacle","zh":"克服障礙","note":""},{"en":"overcome a language barrier","zh":"克服語言障礙","note":""},{"en":"be overcome with emotion","zh":"情緒激動得難以自已","note":"被動用法。"}],"synonyms":[{"en":"conquer","zh":"征服；克服","note":"語氣較強，可用於恐懼或困難。"},{"en":"get over","zh":"克服；恢復","note":"較口語，可指從疾病或失落中恢復。"}],"idioms":[],"family":[{"word":"overcame","pos":"v.","meaning":"克服（過去式）"},{"word":"overcome","pos":"v.","meaning":"克服（原形與過去分詞）"}],"usageNote":"變化為 overcome–overcame–overcome。overcome obstacles 是克服；be overcome with grief 則是被悲傷壓倒。","examples":[{"text":"To overcome my fear of speaking in public, I first practiced explaining one idea to a small group of friends.","translationZh":"為克服公開說話的恐懼，我先練習向一小群朋友說明一個想法。","grammar":"To overcome 表目的；fear of + V-ing；practice + V-ing。","writingTip":"成長敘事寫出循序增加難度的第一步。","topic":"公開表達","source":"self-authored"},{"text":"Clear pictures helped us overcome the language barrier when we worked with visitors who could not read the local signs.","translationZh":"與看不懂當地標示的訪客互動時，清楚圖片幫助我們克服語言障礙。","grammar":"help + 人 + 原形 overcome；who 修飾 visitors。","writingTip":"用具體溝通工具說明如何處理跨語言困難。","topic":"跨語言服務","source":"self-authored"}]},"participate":{"senses":[{"pos":"vi.","meaning":"參與","usage":"通常接 in，不能直接接活動名稱作受詞。"}],"collocations":[{"en":"participate in a discussion","zh":"參與討論","note":""},{"en":"participate actively","zh":"積極參與","note":""},{"en":"participate in community service","zh":"參與社區服務","note":""},{"en":"encourage participation","zh":"鼓勵參與","note":"使用名詞 participation。"}],"synonyms":[{"en":"take part in","zh":"參與","note":"常可替換 participate in。"},{"en":"join","zh":"加入","note":"及物動詞，可直接接團體或某些活動，句型不同。"}],"idioms":[],"family":[{"word":"participation","pos":"n.","meaning":"參與"},{"word":"participant","pos":"n.","meaning":"參與者"},{"word":"participatory","pos":"adj.","meaning":"參與式的"}],"examples":[{"text":"Students who participate in community service often learn to recognize needs that are easily overlooked in daily life.","translationZh":"參與社區服務的學生，常學會察覺日常生活中容易被忽略的需求。","grammar":"participate in，that 引導 needs 的關係子句。","writingTip":"可寫服務如何增加對社會的理解。","topic":"服務與學習","source":"self-authored"},{"text":"The discussion became more useful when quieter members were invited to participate instead of being interrupted.","translationZh":"當較安靜的成員受到邀請參與，而非被打斷時，討論變得更有幫助。","grammar":"be invited to V，instead of being V-ed 為被動動名詞。","writingTip":"適合描述包容性的團隊互動。","topic":"合作與溝通","source":"self-authored"}],"usageNote":"participate in an activity 正確；不要省略 in，也不要與 participant「參與者」混用。"},"patience":{"senses":[{"pos":"n.","meaning":"耐心","usage":"不可數，常搭配 with 或 to V。"}],"collocations":[{"en":"have patience with children","zh":"對孩子有耐心","note":""},{"en":"lose one's patience","zh":"失去耐心","note":""},{"en":"run out of patience","zh":"耗盡耐心","note":""},{"en":"the patience to listen","zh":"傾聽的耐心","note":""}],"synonyms":[{"en":"forbearance","zh":"克制；容忍","note":"較正式，常指不對刺激作反應。"},{"en":"endurance","zh":"耐力","note":"強調長時間承受困難，不等同等待的耐心。"}],"idioms":[],"family":[{"word":"patient","pos":"adj.","meaning":"有耐心的"},{"word":"patiently","pos":"adv.","meaning":"耐心地"},{"word":"impatience","pos":"n.","meaning":"不耐煩"}],"examples":[{"text":"Teaching my younger brother to ride a bicycle required patience, especially when he wanted to give up.","translationZh":"教弟弟騎腳踏車需要耐心，尤其是在他想放棄的時候。","grammar":"動名詞片語作主詞，especially when 補充特定情境。","writingTip":"可寫陪伴他人學習的體會。","topic":"家庭與學習","source":"self-authored"},{"text":"With patience and consistent practice, the injured athlete gradually regained the confidence to return to competition.","translationZh":"帶著耐心並持續練習，這位受傷運動員逐漸重拾回到賽場的信心。","grammar":"with 引出方式或條件，confidence to V。","writingTip":"適合寫復原需要時間與毅力。","topic":"運動與復原","source":"self-authored"}],"usageNote":"patient 作形容詞指有耐心；作名詞 a patient 則指病人。"},"patient":{"senses":[{"pos":"n.","meaning":"病人","usage":""},{"pos":"adj.","meaning":"有耐心的","usage":""}],"collocations":[{"en":"be patient with beginners","zh":"對初學者有耐心","note":""},{"en":"remain patient","zh":"保持耐心","note":""},{"en":"treat a patient","zh":"治療病人","note":""},{"en":"a patient explanation","zh":"耐心的說明","note":""}],"synonyms":[{"en":"tolerant","zh":"包容的","note":"tolerant 強調容忍差異"},{"en":"calm","zh":"冷靜的","note":"不一定能長久等待"}],"idioms":[],"family":[{"word":"patience","pos":"n.","meaning":"耐心"},{"word":"patiently","pos":"adv.","meaning":"耐心地"},{"word":"impatient","pos":"adj.","meaning":"不耐煩的"}],"usageNote":"patient with + 人；patience 是不可數名詞，patients 是病人複數，發音近但不同。","examples":[{"text":"My grandfather was patient with me when I first learned to cook, repeating each step without making me feel embarrassed.","translationZh":"初學煮飯時，祖父對我很有耐心，反覆說明每一步，也不讓我尷尬。","source":"self-authored","grammar":"patient with + 人；repeating 為補充祖父行為的分詞。","writingTip":"以反覆說明而不責備，呈現耐心的具體樣貌。","topic":"學習烹飪"},{"text":"The patient asked the doctor to explain the treatment options again so that she could make an informed decision with her family.","translationZh":"病人請醫師再說明治療選項，以便和家人作出充分知情的決定。","source":"self-authored","grammar":"asked + 人 + to explain；so that 引導作決定的目的。","writingTip":"用再次詢問來描寫充分理解後的選擇。","topic":"醫療決策"}]},"perceive":{"senses":[{"pos":"vt.","meaning":"察覺；感知","usage":"透過感官或理解注意到。"},{"pos":"vt.","meaning":"認為；視為","usage":"perceive A as B。"}],"collocations":[{"en":"perceive a change","zh":"察覺改變","note":""},{"en":"perceive a threat","zh":"感到威脅","note":"不一定表示確有危險。"},{"en":"perceive a mistake as a learning opportunity","zh":"把錯誤視為學習機會","note":""},{"en":"be perceived as unfair","zh":"被認為不公平","note":""}],"synonyms":[{"en":"notice","zh":"注意到","note":"較日常，常指察覺某細節。"},{"en":"regard as","zh":"視為","note":"只對應看待義，需用 regard A as B。"}],"idioms":[],"family":[{"word":"perception","pos":"n.","meaning":"感知；看法"},{"word":"perceptive","pos":"adj.","meaning":"敏銳的；有洞察力的"},{"word":"perceptible","pos":"adj.","meaning":"可察覺的"}],"usageNote":"perceived danger 是被感受到的危險，未必已經證實；perceptive 形容人敏銳，perceptible 形容事物可被察覺。","examples":[{"text":"Students may perceive feedback as criticism if teachers point out errors without explaining how the work can be improved.","translationZh":"若老師只指出錯誤、卻不說明如何改善，學生可能把回饋視為批評。","grammar":"perceive A as B；without explaining 表缺少的步驟。","writingTip":"學習回饋作文可分析表達方式如何影響接受程度。","topic":"回饋與感受","source":"self-authored"},{"text":"After spending time in the neighborhood, I began to perceive the old market as a place of connection rather than disorder.","translationZh":"在社區待了一段時間後，我開始把老市場視為人際連結之處，而非雜亂場所。","grammar":"began to perceive A as B；rather than 並列兩種看法。","writingTip":"敘述經驗如何改變對地方的第一印象。","topic":"地方印象","source":"self-authored"}]},"perspective":{"senses":[{"pos":"n.","meaning":"觀點；看法","usage":"from someone's perspective。"},{"pos":"n.","meaning":"看待事物的比例感；全貌","usage":"put something in perspective。"},{"pos":"n.","meaning":"透視法","usage":"美術中的空間表現方法。"}],"collocations":[{"en":"from a different perspective","zh":"從不同角度","note":""},{"en":"gain a new perspective on an issue","zh":"對議題獲得新看法","note":""},{"en":"put a setback in perspective","zh":"以適當眼光看待挫折","note":""},{"en":"draw in perspective","zh":"用透視法繪圖","note":""}],"synonyms":[{"en":"viewpoint","zh":"觀點","note":"對應看待問題的立場，不包含繪圖義。"},{"en":"outlook","zh":"看法；人生觀","note":"常指較整體的態度或未來展望。"}],"idioms":[],"family":[{"word":"perspectival","pos":"adj.","meaning":"觀點的；透視的（較正式）"}],"usageNote":"perspective 可是看法，也可是理解某事相對重要性的能力。put in perspective 不等於否認問題，而是放回更完整的背景。","examples":[{"text":"Listening to commuters gave us a different perspective on the bus schedule and the difficulties caused by long gaps between services.","translationZh":"聽通勤者的想法，讓我們從不同角度理解公車時刻與班距過長造成的困難。","grammar":"Listening 為主詞；perspective on + 議題；caused 修飾 difficulties。","writingTip":"公共政策作文可透過使用者經驗補充數字以外的觀點。","topic":"通勤需求","source":"self-authored"},{"text":"Remembering how much I had learned helped me put one disappointing test result in perspective and plan my next step.","translationZh":"回想自己已學會多少，幫我以較全面的眼光看待一次不理想成績，並規畫下一步。","grammar":"put + 事物 + in perspective；helped me 後並列 put 與 plan。","writingTip":"成長作文把單次失利放回長期學習歷程。","topic":"挫折調整","source":"self-authored"}]},"persuade":{"senses":[{"pos":"vt.","meaning":"說服","usage":"常用 persuade someone to V 或 persuade someone of something。"}],"collocations":[{"en":"persuade someone to change","zh":"說服某人改變","note":""},{"en":"persuade someone of the need","zh":"使某人相信有必要","note":""},{"en":"persuade someone that","zh":"使某人相信……","note":""},{"en":"persuade someone into joining","zh":"說服某人加入","note":""}],"synonyms":[{"en":"convince","zh":"使信服","note":"強調讓人相信，現代用法也常接 to V。"},{"en":"urge","zh":"敦促","note":"表示強烈建議，不必已成功說服。"}],"idioms":[],"family":[{"word":"persuasion","pos":"n.","meaning":"說服"},{"word":"persuasive","pos":"adj.","meaning":"有說服力的"},{"word":"persuasively","pos":"adv.","meaning":"有說服力地"}],"examples":[{"text":"We persuaded the shop owner to reduce plastic packaging by showing how much waste customers produced each week.","translationZh":"我們向店主展示顧客每週產生的垃圾量，說服他減少塑膠包裝。","grammar":"persuade someone to V，by showing how 表說服方法。","writingTip":"可寫以證據推動環保改變。","topic":"消費與環境","source":"self-authored"},{"text":"A speech should persuade listeners with clear reasons rather than rely only on emotional language and dramatic images.","translationZh":"演說應以明確的理由說服聽眾，而不是只依賴情緒性語言和戲劇化影像。","grammar":"persuade listeners with reasons 表說服方式，rather than 連接原形動詞。","writingTip":"適合討論有效溝通與公共說服。","topic":"溝通與思辨","source":"self-authored"}],"usageNote":"persuade 常暗示成功說服；try to persuade 才清楚表示嘗試，結果未必成功。"},"pet":{"senses":[{"pos":"n.","meaning":"寵物","usage":""},{"pos":"v.","meaning":"輕撫動物","usage":""},{"pos":"adj.","meaning":"特別喜愛的","usage":""}],"collocations":[{"en":"keep a pet","zh":"飼養寵物","note":""},{"en":"adopt a pet","zh":"認養寵物","note":""},{"en":"pet a dog","zh":"輕撫狗","note":""},{"en":"a pet project","zh":"特別喜愛的計畫","note":""}],"synonyms":[{"en":"companion animal","zh":"伴侶動物","note":"正式稱呼，強調人與動物的陪伴關係"},{"en":"stroke","zh":"輕撫","note":"動詞 stroke 可描述撫摸動物"}],"idioms":[],"family":[{"word":"pet owner","pos":"n.","meaning":"寵物飼主"},{"word":"pet-friendly","pos":"adj.","meaning":"允許或歡迎寵物的"}],"usageNote":"pet 作動詞常見美式英語；pet project 是喜愛的計畫，與動物無關。","examples":[{"text":"Before adopting a pet, a family should consider whether it can provide enough time, space, and money for proper care.","translationZh":"認養寵物前，家庭應考慮是否能提供足夠的時間、空間與金錢來妥善照顧。","source":"self-authored","grammar":"before + V-ing；whether 引導應考慮的間接問句。","writingTip":"用時間、空間與費用評估認養準備。","topic":"負責任飼養"},{"text":"The child asked the owner for permission before petting the dog, which helped both the animal and the child feel safer.","translationZh":"孩子先徵求飼主同意才撫摸狗，這讓動物與孩子都感到更安全。","source":"self-authored","grammar":"before petting 中 pet 為動詞；which 補充前述做法的結果。","writingTip":"描寫先徵求同意再接觸寵物的具體行動。","topic":"動物互動安全"}]},"pleasure":{"senses":[{"pos":"n.","meaning":"愉悅；樂事","usage":"抽象快樂不可數，一件樂事可數。"}],"collocations":[{"en":"take pleasure in reading","zh":"以閱讀為樂","note":""},{"en":"for pleasure","zh":"為了興趣或享受","note":""},{"en":"the pleasure of meeting someone","zh":"見到某人的喜悅","note":""},{"en":"it is a pleasure to","zh":"很高興……","note":""}],"synonyms":[{"en":"enjoyment","zh":"享受；樂趣","note":"通常不可數，與一般愉悅義接近。"},{"en":"delight","zh":"喜悅","note":"往往比 pleasure 更強烈。"}],"idioms":[{"en":"with pleasure","zh":"樂意效勞","note":"常用於接受請求，較正式。"}],"family":[{"word":"please","pos":"vt.","meaning":"使高興"},{"word":"pleasant","pos":"adj.","meaning":"令人愉快的"},{"word":"pleasurable","pos":"adj.","meaning":"帶來愉悅的"}],"examples":[{"text":"Reading for pleasure gave me a quiet space to relax and discover ideas beyond my school textbooks.","translationZh":"為興趣而閱讀，讓我有安靜放鬆的空間，也能發現課本以外的想法。","grammar":"for pleasure 表目的，to relax and discover 並列不定詞。","writingTip":"可寫閱讀與休閒的價值。","topic":"閱讀與生活","source":"self-authored"},{"text":"She took pleasure in preparing meals that brought her family together after everyone's busy day.","translationZh":"她以準備餐點為樂，讓忙碌一整天的家人能聚在一起。","grammar":"take pleasure in V-ing，that 引導 meals 的關係子句。","writingTip":"適合描寫平凡生活中的滿足。","topic":"家庭與飲食","source":"self-authored"}],"usageNote":"pleasant 描述令人愉快的事物；pleased 描述感到高興的人，pleasure 則是名詞。"},"potential":{"senses":[{"pos":"n.","meaning":"潛力；可能性","usage":"potential for + 名詞"},{"pos":"adj.","meaning":"潛在的；可能的","usage":"放在名詞前"}],"collocations":[{"en":"reach one's full potential","zh":"發揮全部潛力","note":"能力發展"},{"en":"potential benefits","zh":"潛在好處","note":"尚未確認"},{"en":"the potential for growth","zh":"成長潛力","note":"for 接名詞"},{"en":"potential customers","zh":"潛在顧客","note":"商業情境"}],"synonyms":[{"en":"possibility","zh":"可能性","note":"對應事件發生的機會"},{"en":"promise","zh":"潛力","note":"指未來表現良好的前景"}],"idioms":[{"en":"have what it takes","zh":"具備成功所需的能力","note":"可描述一個人有潛力，但語氣更接近已具備條件。"}],"family":[{"word":"potentially","pos":"adv.","meaning":"可能地；潛在地"}],"examples":[{"text":"A supportive teacher can help students reach their full potential without comparing them constantly with others.","translationZh":"支持學生的老師能幫助他們發揮全部潛力，而不必一直拿他們與他人比較。","source":"self-authored","grammar":"help 人 + 原形動詞；without + V-ing","writingTip":"可討論教育與個別發展。","topic":"education"},{"text":"Before buying the device, consumers should consider both its potential benefits and its privacy risks.","translationZh":"購買裝置前，消費者應同時考慮潛在好處與隱私風險。","source":"self-authored","grammar":"Before buying 是 before + V-ing；potential 作形容詞修飾 benefits；both...and... 連接並列受詞。","writingTip":"評估科技產品時，同時考慮潛在利益與隱私風險。","topic":"technology"}],"usageNote":"potential 作名詞多不可數；作形容詞表示尚未實現或確認的可能性。"},"prefer":{"senses":[{"pos":"vt.","meaning":"偏好；較喜歡","usage":"prefer A to B，或 prefer to V rather than V。"}],"collocations":[{"en":"prefer tea to coffee","zh":"比起咖啡更喜歡茶","note":""},{"en":"prefer walking to driving","zh":"比起開車更喜歡走路","note":""},{"en":"prefer to stay home","zh":"較想待在家","note":""},{"en":"would prefer someone to leave","zh":"比較希望某人離開","note":""}],"synonyms":[{"en":"favor","zh":"較支持；偏好","note":"常用於方案或立場，不必是個人享受。"},{"en":"choose","zh":"選擇","note":"描述實際選擇，未必長期偏好。"}],"idioms":[],"family":[{"word":"preference","pos":"n.","meaning":"偏好"},{"word":"preferable","pos":"adj.","meaning":"較可取的"},{"word":"preferably","pos":"adv.","meaning":"最好是"}],"examples":[{"text":"Some students prefer studying alone to working in groups because they can control their pace more easily.","translationZh":"有些學生比起分組學習，更喜歡自己讀書，因為較容易掌握進度。","grammar":"prefer V-ing to V-ing，to 為介系詞。","writingTip":"可比較不同學習方式的適用情況。","topic":"學習與選擇","source":"self-authored"},{"text":"I would prefer to repair my old bicycle rather than replace it with a new one.","translationZh":"我比較希望修好舊腳踏車，而不是換一輛新的。","grammar":"prefer to V rather than V，兩個動詞形式平行。","writingTip":"適合寫節省資源與日常選擇。","topic":"消費與永續","source":"self-authored"}],"usageNote":"prefer A to B 不用 than；prefer to do rather than do 則用另一套句型。"},"present":{"senses":[{"pos":"adj.","meaning":"目前的；在場的","usage":""},{"pos":"n.","meaning":"禮物","usage":""},{"pos":"v.","meaning":"提出；呈現","usage":""}],"collocations":[{"en":"at present","zh":"目前","note":""},{"en":"be present at a meeting","zh":"出席會議","note":""},{"en":"present a proposal","zh":"提出提案","note":""},{"en":"a birthday present","zh":"生日禮物","note":""}],"synonyms":[{"en":"current","zh":"目前的","note":"對應形容詞時間義"},{"en":"show","zh":"呈現","note":"present 較正式，常帶向人展示的意思"}],"idioms":[],"family":[{"word":"presentation","pos":"n.","meaning":"簡報；呈現"},{"word":"presenter","pos":"n.","meaning":"報告者；主持人"},{"word":"presence","pos":"n.","meaning":"在場；存在"}],"usageNote":"present 作動詞常在第二音節重讀；present A to B 表向 B 提出 A。","examples":[{"text":"At present, our school is testing a new lunch system that allows students to choose portions according to their needs.","translationZh":"目前學校正在試行新午餐制度，讓學生依需求選擇份量。","source":"self-authored","grammar":"at present 表目前；that allows 修飾 system。","writingTip":"可介紹正在試行、仍需評估的新措施。","topic":"午餐制度"},{"text":"When presenting our proposal to the principal, we used survey results to explain why students wanted more shaded areas on campus.","translationZh":"向校長提出提案時，我們用調查結果說明學生為何希望校園有更多遮蔭區。","source":"self-authored","grammar":"when presenting 表發表時；why 引導調查説明的內容。","writingTip":"提出改善方案時用調查結果作為理由。","topic":"校園提案"}]},"preserve":{"senses":[{"pos":"vt.","meaning":"保存；維護","usage":"維持原貌、狀態或價值。"},{"pos":"vt.","meaning":"保藏食物","usage":"透過冷藏、醃漬等延緩腐敗。"},{"pos":"n.","meaning":"保護區；專有領域","usage":"如 a wildlife preserve；the preserve of。"}],"collocations":[{"en":"preserve local traditions","zh":"保存地方傳統","note":""},{"en":"preserve food in salt","zh":"用鹽保藏食物","note":""},{"en":"preserve a historic building","zh":"保存歷史建築","note":""},{"en":"a wildlife preserve","zh":"野生動物保護區","note":"名詞義。"}],"synonyms":[{"en":"conserve","zh":"保護；節約","note":"常強調妥善使用資源以免耗盡。"},{"en":"maintain","zh":"維持","note":"較一般，不一定含保護原貌或避免受損。"}],"idioms":[],"family":[{"word":"preservation","pos":"n.","meaning":"保存；維護"},{"word":"preservative","pos":"n.","meaning":"防腐劑"},{"word":"preserved","pos":"adj.","meaning":"保存的；醃製的"}],"usageNote":"preserve 保留狀態或使不受損；reserve 常指預訂或保留備用。preservative 是防腐劑，不是形容人的保守。","examples":[{"text":"The town preserved the old railway station while turning unused rooms into spaces for exhibitions and community meetings.","translationZh":"城鎮保存老火車站，同時把閒置房間改成展覽與社區會議空間。","grammar":"preserve 直接接建築；while turning 表同時改作新用途。","writingTip":"文化保存作文可兼談保留特色與增加使用價值。","topic":"文化保存","source":"self-authored"},{"text":"Recording local stories can help preserve memories that might otherwise disappear as older residents move away or pass away.","translationZh":"記錄地方故事，有助保存可能隨年長居民搬離或過世而消失的記憶。","grammar":"help + 原形 preserve；might otherwise 表若不採取行動的可能情況。","writingTip":"文化議題可說明不記錄時可能失去什麼。","topic":"地方記憶","source":"self-authored"}]},"pressure":{"senses":[{"pos":"n.","meaning":"壓力；施壓","usage":"可指物理力量或心理負擔。"},{"pos":"vt.","meaning":"迫使；施壓","usage":"常用 pressure someone into V-ing。"}],"collocations":[{"en":"under pressure","zh":"承受壓力","note":""},{"en":"put pressure on someone","zh":"向某人施壓","note":""},{"en":"peer pressure","zh":"同儕壓力","note":""},{"en":"pressure someone into agreeing","zh":"迫使某人同意","note":""}],"synonyms":[{"en":"stress","zh":"壓力","note":"常指身心緊張，不一定是別人施加要求。"},{"en":"coerce","zh":"強迫","note":"比 pressure 更強，可能涉及威脅。"}],"idioms":[],"family":[{"word":"pressurize","pos":"vt.","meaning":"加壓"},{"word":"pressurized","pos":"adj.","meaning":"加壓的"},{"word":"pressure-free","pos":"adj.","meaning":"沒有壓力的"}],"examples":[{"text":"Pressure from classmates may lead teenagers to buy expensive products that they neither need nor can afford.","translationZh":"同學帶來的壓力，可能使青少年購買既不需要、也負擔不起的昂貴商品。","grammar":"lead someone to V，neither...nor... 連接兩項否定。","writingTip":"可寫同儕壓力與理性消費。","topic":"同儕與消費","source":"self-authored"},{"text":"The deadline pressured us into rushing the report, leaving little time to check whether the evidence was accurate.","translationZh":"截止期限迫使我們趕著完成報告，幾乎沒有時間檢查證據是否正確。","grammar":"pressure someone into V-ing，leaving 分詞片語表示結果。","writingTip":"適合分析時間壓力如何影響品質。","topic":"學習與時間","source":"self-authored"}],"usageNote":"pressure someone into doing 常表示施壓促成行為；blood pressure 則指血壓。"},"prevent":{"senses":[{"pos":"vt.","meaning":"防止；阻止","usage":"prevent 人或事物 from V-ing"}],"collocations":[{"en":"prevent accidents","zh":"防止事故","note":"安全主題"},{"en":"prevent disease","zh":"預防疾病","note":"健康主題"},{"en":"prevent someone from entering","zh":"阻止某人進入","note":"from + V-ing"},{"en":"prevent food waste","zh":"避免食物浪費","note":"環境主題"}],"synonyms":[{"en":"stop","zh":"阻止","note":"常指停止正在發生的行為"},{"en":"keep from","zh":"阻止；使免於","note":"需依句型搭配受詞"}],"idioms":[],"family":[{"word":"prevention","pos":"n.","meaning":"預防"},{"word":"preventive","pos":"adj.","meaning":"預防的"},{"word":"preventable","pos":"adj.","meaning":"可避免的"}],"examples":[{"text":"Wearing a helmet can prevent serious injuries when cyclists lose their balance or hit an obstacle.","translationZh":"騎士失去平衡或撞上障礙物時，戴安全帽能防止嚴重傷害。","source":"self-authored","grammar":"prevent + 名詞；when 引導時間子句","writingTip":"安全論述可指明防護情境。","topic":"safety"},{"text":"The heavy snow prevented residents from reaching the hospital until workers cleared the road.","translationZh":"大雪阻止居民前往醫院，直到工人清理道路。","source":"self-authored","grammar":"prevent 人 from V-ing；until","writingTip":"可敘述災害造成的阻礙。","topic":"disaster"}],"usageNote":"prevent 後不接人 + to V；常用 prevent 人 from V-ing。"},"principle":{"senses":[{"pos":"n.","meaning":"原則；準則","usage":"行事或判斷所依循的基準。"},{"pos":"n.","meaning":"原理","usage":"解釋某現象的基本規律。"}],"collocations":[{"en":"a basic principle","zh":"基本原則或原理","note":"依語境判斷。"},{"en":"stick to one's principles","zh":"堅守原則","note":""},{"en":"in principle","zh":"原則上","note":"未必已同意全部細節。"},{"en":"the principle behind a device","zh":"裝置背後的原理","note":""}],"synonyms":[{"en":"rule","zh":"規則","note":"可指具體規定；principle 通常較基本或抽象。"},{"en":"standard","zh":"標準","note":"可指評量尺度，不一定是原理或信念。"}],"idioms":[],"family":[{"word":"principled","pos":"adj.","meaning":"有原則的"},{"word":"unprincipled","pos":"adj.","meaning":"無原則的；不道德的"}],"usageNote":"principle 是原則／原理；principal 作形容詞指主要的，作名詞可指校長，拼字勿混。in principle 不保證所有條件都談妥。","examples":[{"text":"We agreed with the proposal in principle but asked for more details about how the money would be spent.","translationZh":"我們原則上贊同提案，但要求提供更詳細的經費用途。","grammar":"agree with + 提案；in principle 限定同意程度；how 引導間接問句。","writingTip":"議論作文可表達基本支持，同時保留需要確認的細節。","topic":"提案討論","source":"self-authored"},{"text":"The experiment helped students understand the principle behind a simple water filter rather than merely memorize the names of its parts.","translationZh":"實驗幫學生理解簡易濾水器的原理，而非只背零件名稱。","grammar":"principle behind + 裝置；rather than 連接 understand 與 memorize。","writingTip":"教育作文以理解運作方式說明學習目標。","topic":"科學理解","source":"self-authored"}]},"priority":{"senses":[{"pos":"n.","meaning":"優先事項；優先權","usage":"可數時指優先要做的事，不可數時指優先地位。"}],"collocations":[{"en":"make safety a priority","zh":"把安全列為優先事項","note":""},{"en":"give priority to","zh":"優先考慮……","note":""},{"en":"set priorities","zh":"訂定優先順序","note":""},{"en":"a top priority","zh":"首要任務","note":""}],"synonyms":[{"en":"precedence","zh":"優先地位","note":"較正式，常用 take precedence over。"},{"en":"main concern","zh":"主要關切","note":"不一定表示明確的處理順序。"}],"idioms":[],"family":[{"word":"prioritize","pos":"vt.","meaning":"排定優先順序"},{"word":"prioritization","pos":"n.","meaning":"優先順序的安排"},{"word":"prior","pos":"adj.","meaning":"先前的"}],"examples":[{"text":"Making sleep a priority helped me stay focused in class and manage exam preparation more effectively.","translationZh":"把睡眠列為優先事項，幫我上課更專心，也更有效安排考試準備。","grammar":"make A a priority，help 後接並列原形動詞。","writingTip":"可寫調整讀書計畫時的取捨。","topic":"健康與學習","source":"self-authored"},{"text":"Cities should give priority to safe sidewalks so that children and older adults can travel independently.","translationZh":"城市應優先改善人行道安全，讓兒童和長者能獨立外出。","grammar":"give priority to，so that 引導目的子句。","writingTip":"適合提出以行人為本的政策。","topic":"交通與高齡","source":"self-authored"}],"usageNote":"priority 與 superiority「優越」不同；give priority to 中 to 是介系詞。"},"process":{"senses":[{"pos":"n.","meaning":"過程；程序","usage":"a process of V-ing"},{"pos":"vt.","meaning":"處理；加工","usage":"資料、食品或申請"}],"collocations":[{"en":"the learning process","zh":"學習過程","note":"教育用語"},{"en":"process information","zh":"處理資訊","note":"認知或科技"},{"en":"a complex process","zh":"複雜的程序","note":"可數名詞"},{"en":"processed foods","zh":"加工食品","note":"分詞作形容詞"}],"synonyms":[{"en":"procedure","zh":"程序","note":"強調依規定的步驟"},{"en":"handle","zh":"處理","note":"對應動詞義，範圍較廣"}],"idioms":[],"family":[{"word":"processing","pos":"n.","meaning":"處理；加工"},{"word":"processor","pos":"n.","meaning":"處理器；加工者"},{"word":"processed","pos":"adj.","meaning":"經處理的；加工的"}],"examples":[{"text":"Learning a new skill is a gradual process that requires practice, patience, and useful feedback.","translationZh":"學習新技能是漸進的過程，需要練習、耐心與有用的回饋。","source":"self-authored","grammar":"Learning a new skill 為 V-ing 片語作主詞；that requires 是修飾 process 的關係子句，列出過程需要的條件。","writingTip":"描述學習進步時，可用 gradual process 強調練習、耐心與回饋。","topic":"education"},{"text":"The computer processes large amounts of information before presenting the results in a simple chart.","translationZh":"電腦處理大量資訊後，將結果呈現在簡單圖表中。","source":"self-authored","grammar":"The computer 是單數主詞，搭配 processes；large amounts of information 中 information 不可數；before presenting 表先後。","writingTip":"介紹資料處理時，可依處理資訊、呈現圖表的順序寫流程。","topic":"technology"}],"usageNote":"process 作名詞指過程；作動詞可指資訊處理或食品加工。"},"promise":{"senses":[{"pos":"n.","meaning":"承諾；潛力","usage":"show promise 表有前景。"},{"pos":"vt.","meaning":"承諾；預示","usage":"可接 to V 或 that 子句。"}],"collocations":[{"en":"keep a promise","zh":"遵守承諾","note":""},{"en":"break a promise","zh":"違背承諾","note":""},{"en":"promise to help","zh":"承諾幫忙","note":""},{"en":"show great promise","zh":"展現很大的潛力","note":""}],"synonyms":[{"en":"pledge","zh":"鄭重承諾","note":"常較正式或公開，可作動詞與名詞。"},{"en":"potential","zh":"潛力","note":"只對應前景義，不表示答應。"}],"idioms":[],"family":[{"word":"promising","pos":"adj.","meaning":"有前途的"},{"word":"promised","pos":"adj.","meaning":"已承諾的"},{"word":"unpromising","pos":"adj.","meaning":"前景不佳的"}],"examples":[{"text":"I promised to help my friend rehearse, so I arranged my schedule before accepting another invitation.","translationZh":"我答應幫朋友排練，因此在接受另一個邀請前，先安排好自己的時間。","grammar":"promise to V，before V-ing 表先後順序。","writingTip":"可寫守信與時間管理。","topic":"友誼與責任","source":"self-authored"},{"text":"The young designer showed promise by creating low-cost tools that made everyday tasks easier for older users.","translationZh":"這位年輕設計師製作了方便長者處理日常工作的低成本工具，展現出潛力。","grammar":"show promise，make 受詞 adjective 表結果。","writingTip":"適合描述具社會價值的創作。","topic":"設計與高齡","source":"self-authored"}],"usageNote":"promise 常指明確答應；promising 是有前景，不是正在承諾的唯一意思。"},"promote":{"senses":[{"pos":"vt.","meaning":"促進；推廣","usage":"行為、商品或活動"},{"pos":"vt.","meaning":"升遷","usage":"promote 人 to + 職位"}],"collocations":[{"en":"promote healthy habits","zh":"促進健康習慣","note":"公共健康"},{"en":"promote local products","zh":"推廣地方產品","note":"商業語境"},{"en":"promote understanding","zh":"增進理解","note":"人際交流"},{"en":"be promoted to manager","zh":"升任經理","note":"to 指新職位"}],"synonyms":[{"en":"encourage","zh":"鼓勵；促進","note":"對應行為發展"},{"en":"advertise","zh":"宣傳","note":"只對應商品推廣，非所有 promote 語境"}],"idioms":[],"family":[{"word":"promotion","pos":"n.","meaning":"促進；推銷；升遷"},{"word":"promotional","pos":"adj.","meaning":"宣傳的"},{"word":"promoter","pos":"n.","meaning":"推動者；主辦者"}],"examples":[{"text":"The campaign promotes healthy habits by encouraging students to choose water instead of sugary drinks.","translationZh":"這項活動鼓勵學生選擇水而非含糖飲料，藉此促進健康習慣。","source":"self-authored","grammar":"promote + 名詞；by + V-ing","writingTip":"可用於健康倡議。","topic":"health"},{"text":"After years of reliable work, my aunt was promoted to a position with greater responsibility.","translationZh":"多年可靠的工作表現後，阿姨獲得升遷，擔任責任更重的職位。","source":"self-authored","grammar":"be promoted to + 職位","writingTip":"可敘述職涯發展。","topic":"work"}],"usageNote":"promote 可指促進、推廣或升遷；依受詞與 to 後內容判讀。"},"propose":{"senses":[{"pos":"vt.","meaning":"提議；提出","usage":"propose a plan／doing／that 子句。"},{"pos":"vi.","meaning":"求婚","usage":"propose to someone。"}],"collocations":[{"en":"propose a solution","zh":"提出解決方式","note":""},{"en":"propose making a change","zh":"提議改變","note":"後接 V-ing。"},{"en":"propose that a rule be revised","zh":"提議修訂規則","note":"美式常用原形 be。"},{"en":"propose to someone","zh":"向某人求婚","note":"另有 propose to V 表打算的用法。"}],"synonyms":[{"en":"suggest","zh":"建議","note":"常接 V-ing 或 that 子句，語氣可較輕。"},{"en":"put forward","zh":"提出","note":"可接主張、計畫或解釋，較一般。"}],"idioms":[],"family":[{"word":"proposal","pos":"n.","meaning":"提案；求婚"},{"word":"proposed","pos":"adj.","meaning":"擬議中的"}],"usageNote":"propose doing 表提議做；propose to do 可表打算做，不能只當成同一句型。proposal 尚未必獲核准。","examples":[{"text":"Our class proposed setting up a repair corner where students could learn to fix simple problems with their belongings.","translationZh":"我們班提議設置修繕角，讓學生學習處理物品的簡單故障。","grammar":"propose + V-ing；where 修飾 corner 的用途。","writingTip":"環保提案可列出場地與可提供的具體學習活動。","topic":"校園修繕","source":"self-authored"},{"text":"The residents proposed that the empty lot be turned into a shaded playground rather than another parking area.","translationZh":"居民提議把空地改成有遮蔭的遊戲場，而不是另一處停車場。","grammar":"propose that + 主詞 + 原形 be 為建議句型；rather than 表方案對比。","writingTip":"公共空間作文可比較同一土地的兩種用途。","topic":"公共空間","source":"self-authored"}]},"protect":{"senses":[{"pos":"vt.","meaning":"保護","usage":"protect A from 或 against B"}],"collocations":[{"en":"protect wildlife","zh":"保護野生動物","note":"保育主題"},{"en":"protect personal information","zh":"保護個人資訊","note":"數位隱私"},{"en":"protect skin from sunlight","zh":"保護皮膚免受日曬","note":"from 表危害"},{"en":"protect against infection","zh":"防止感染","note":"against 表防禦對象"}],"synonyms":[{"en":"safeguard","zh":"保護","note":"較正式，常指權益或重要事物"},{"en":"shield","zh":"遮蔽；保護","note":"著重形成屏障"}],"idioms":[],"family":[{"word":"protection","pos":"n.","meaning":"保護"},{"word":"protective","pos":"adj.","meaning":"保護性的"},{"word":"protector","pos":"n.","meaning":"保護者"}],"examples":[{"text":"Strong passwords help protect personal information, but users must also be careful about suspicious links.","translationZh":"強密碼有助於保護個人資訊，但使用者也須小心可疑連結。","source":"self-authored","grammar":"protect + 受詞；be careful about + 名詞","writingTip":"可討論網路安全的多項措施。","topic":"technology"},{"text":"The trees protect nearby houses from strong winds while providing habitats for many birds.","translationZh":"樹木保護附近房屋免受強風侵襲，也提供許多鳥類棲地。","source":"self-authored","grammar":"protect A from B；while + V-ing","writingTip":"可列出綠地的具體功能。","topic":"environment"}],"usageNote":"protect from 強調免受危害；protect against 常用於防範疾病、攻擊或風險。"},"pursue":{"senses":[{"pos":"vt.","meaning":"追求；從事；追趕","usage":"直接接目標、興趣、職涯或追逐對象。"}],"collocations":[{"en":"pursue a dream","zh":"追求夢想","note":""},{"en":"pursue a career","zh":"追求職涯","note":""},{"en":"pursue further studies","zh":"繼續深造","note":""},{"en":"pursue a suspect","zh":"追捕嫌疑人","note":""}],"synonyms":[{"en":"seek","zh":"尋求","note":"重點在尋找，不必持續投入。"},{"en":"chase","zh":"追逐","note":"較具體或口語，部分語境含急切追求。"}],"idioms":[],"family":[{"word":"pursuit","pos":"n.","meaning":"追求；追捕"},{"word":"pursuer","pos":"n.","meaning":"追逐者"}],"examples":[{"text":"She chose to pursue a career in social work after seeing how one caring adult could change a child's life.","translationZh":"她看見一位關懷孩子的大人如何改變孩子的人生後，選擇投入社工職涯。","grammar":"choose to V，how 引導名詞子句。","writingTip":"可連結個人經驗與職涯選擇。","topic":"職涯與關懷","source":"self-authored"},{"text":"Pursuing personal interests outside school can help students discover strengths that grades alone do not reveal.","translationZh":"在校外追求個人興趣，能幫助學生發現光靠成績看不出的優勢。","grammar":"Pursuing 為動名詞，that 引導限定關係子句。","writingTip":"適合討論學業之外的能力探索。","topic":"興趣與成長","source":"self-authored"}],"usageNote":"pursue 為動詞，pursuit 為名詞；in pursuit of 表為了追求某事。"},"range":{"senses":[{"pos":"n.","meaning":"範圍；多樣種類","usage":"a range of"},{"pos":"n.","meaning":"山脈","usage":"a mountain range"},{"pos":"vi.","meaning":"介於…之間","usage":"range from A to B"}],"collocations":[{"en":"a wide range of choices","zh":"多樣的選擇","note":"a range of + 複數名詞"},{"en":"range from simple to complex","zh":"從簡單到複雜","note":"from...to..."},{"en":"within range of a signal","zh":"在訊號可接收範圍內","note":"通訊語境"},{"en":"a mountain range","zh":"山脈","note":"地理義"}],"synonyms":[{"en":"variety","zh":"種類；多樣性","note":"對應多種選擇"},{"en":"scope","zh":"範圍","note":"對應活動或研究涵蓋程度"}],"idioms":[],"family":[{"word":"ranging","pos":"adj.","meaning":"涵蓋不同範圍的"}],"examples":[{"text":"The museum offers a wide range of activities, from guided tours to hands-on science workshops.","translationZh":"博物館提供多樣活動，從導覽到動手操作的科學工作坊都有。","source":"self-authored","grammar":"a wide range of activities 是 offers 的受詞；from guided tours to... 列出範圍內的不同活動。","writingTip":"介紹博物館活動時，列出導覽及實作工作坊等具體類型。","topic":"culture"},{"text":"Daily temperatures range from ten degrees at night to twenty-five degrees in the afternoon, so visitors should bring layers.","translationZh":"每日氣溫從夜晚的十度到午後的二十五度不等，因此遊客應攜帶可分層穿著的衣物。","source":"self-authored","grammar":"range from A to B；so 表結果","writingTip":"可用於旅遊建議與環境描述。","topic":"travel"}],"usageNote":"range 作名詞可指範圍、種類或山脈；作動詞常搭配 from...to...。"},"recall":{"senses":[{"pos":"vt.","meaning":"回想；記起","usage":"recall doing／that...，不寫 recall to do。"},{"pos":"vt.","meaning":"召回","usage":"召回有問題的產品或在外人員。"},{"pos":"n.","meaning":"回憶能力；召回","usage":"如 product recall。"}],"collocations":[{"en":"recall a childhood memory","zh":"想起童年回憶","note":""},{"en":"recall seeing someone","zh":"記得見過某人","note":""},{"en":"recall a defective product","zh":"召回有瑕疵的產品","note":""},{"en":"active recall","zh":"主動回想","note":"不先看答案，試著從記憶提取。"}],"synonyms":[{"en":"remember","zh":"記得","note":"較日常；remember to do 另有記得去做的意思。"},{"en":"retrieve","zh":"提取；找回","note":"可指從記憶提取，也可找回物品或資料。"}],"idioms":[],"family":[{"word":"recollection","pos":"n.","meaning":"回憶；記憶"},{"word":"recalled","pos":"v.","meaning":"回想；召回（過去式與過去分詞）"}],"usageNote":"recall doing 指回想做過；remember to do 指記得要去做。練習回想後仍須核對答案，避免把猜錯的內容當成正確記憶。","examples":[{"text":"Before checking my notes, I tried to recall the main argument and explain it in a few sentences of my own.","translationZh":"查看筆記前，我先試著回想主要論點，並用自己的幾句話解釋。","grammar":"try to recall；recall 與 explain 並列；of my own 表自己組織的。","writingTip":"學習經驗可描述先提取再核對的實際步驟。","topic":"主動回想","source":"self-authored"},{"text":"The company recalled several models after tests showed that a faulty battery could become dangerously hot during normal use.","translationZh":"測試顯示故障電池在正常使用時也可能過熱後，公司召回數款產品。","grammar":"recall 為召回義；after tests showed that 引出召回原因。","writingTip":"消費安全作文把檢測問題與後續處置連結。","topic":"產品安全","source":"self-authored"}]},"recognize":{"senses":[{"pos":"vt.","meaning":"認出；承認；賞識","usage":"可指辨識熟悉事物，也可指肯定價值或權利。"}],"collocations":[{"en":"recognize a familiar face","zh":"認出熟面孔","note":""},{"en":"recognize the importance of","zh":"認識到……的重要性","note":""},{"en":"recognize someone's contribution","zh":"肯定某人的貢獻","note":""},{"en":"be recognized as","zh":"被認為是……","note":""}],"synonyms":[{"en":"identify","zh":"辨識","note":"常指確認身分或特徵，不必曾見過。"},{"en":"acknowledge","zh":"承認；肯定","note":"常含公開承認或表達感謝。"}],"idioms":[],"family":[{"word":"recognition","pos":"n.","meaning":"辨識；肯定"},{"word":"recognizable","pos":"adj.","meaning":"可辨認的"},{"word":"unrecognized","pos":"adj.","meaning":"未被認出的；未獲認可的"}],"examples":[{"text":"At the market, I recognized the farmer who had visited our school to explain sustainable farming.","translationZh":"在市場裡，我認出那位曾到學校介紹永續農業的農夫。","grammar":"who 引導關係子句，had visited 表先前到訪。","writingTip":"可寫學習經驗連結日常生活。","topic":"飲食與永續","source":"self-authored"},{"text":"We should recognize unpaid caregivers' contributions rather than measure a person's value only by income.","translationZh":"我們應肯定無酬照顧者的貢獻，而非只用收入衡量一個人的價值。","grammar":"rather than 連接並列原形動詞，by 表衡量標準。","writingTip":"適合討論照顧工作與社會價值。","topic":"家庭與社會","source":"self-authored"}],"usageNote":"recognize 熟人指認出，不一定想起名字；recognize as 常表示認可某種地位。"},"recommend":{"senses":[{"pos":"vt.","meaning":"建議；推薦","usage":"recommend doing／that...；recommend something to someone。"}],"collocations":[{"en":"recommend a book to a friend","zh":"向朋友推薦書","note":""},{"en":"recommend taking regular breaks","zh":"建議規律休息","note":""},{"en":"recommend that students keep a journal","zh":"建議學生寫日誌","note":"that 子句可用原形動詞。"},{"en":"highly recommended","zh":"大力推薦的","note":""}],"synonyms":[{"en":"suggest","zh":"建議","note":"未必帶對品質或適合性的推薦意味。"},{"en":"advise","zh":"勸告；建議","note":"常用 advise someone to V，句型不同。"}],"idioms":[],"family":[{"word":"recommendation","pos":"n.","meaning":"建議；推薦"},{"word":"recommended","pos":"adj.","meaning":"建議的；推薦的"}],"usageNote":"學測寫作可用 recommend doing 或 recommend that someone do；advise someone to do 的結構不要直接套成 recommend someone do。","examples":[{"text":"The librarian recommended a novel to me after asking which topics I enjoyed and how much time I had for reading.","translationZh":"圖書館員詢問我喜歡的主題與可閱讀的時間後，向我推薦一本小說。","grammar":"recommend A to B；after asking 後接 which 與 how much 兩個問句。","writingTip":"閱讀經驗可說明推薦如何考量個人興趣與條件。","topic":"選書與閱讀","source":"self-authored"},{"text":"Our teacher recommended reviewing the mistakes we had made before trying another set of questions on the same topic.","translationZh":"老師建議先複習犯過的錯誤，再做另一組相同主題的題目。","grammar":"recommend + V-ing；we had made 修飾 mistakes；before trying 表順序。","writingTip":"學習作文以先診斷錯誤、再練習呈現改善過程。","topic":"錯誤複習","source":"self-authored"}]},"record":{"senses":[{"pos":"n.","meaning":"紀錄；最佳紀錄","usage":""},{"pos":"v.","meaning":"記錄；錄製","usage":""}],"collocations":[{"en":"keep a record of expenses","zh":"保留開支紀錄","note":""},{"en":"break a record","zh":"打破紀錄","note":""},{"en":"record an interview","zh":"錄下訪談","note":""},{"en":"record daily progress","zh":"記錄每日進度","note":""}],"synonyms":[{"en":"document","zh":"記載","note":"document 強調留下可查證資料"},{"en":"register","zh":"記錄","note":"常用於讀數或正式登錄"}],"idioms":[],"family":[{"word":"recording","pos":"n.","meaning":"錄音；錄影"},{"word":"recorder","pos":"n.","meaning":"錄音器；記錄者"},{"word":"recorded","pos":"adj.","meaning":"錄製的"}],"usageNote":"名詞與動詞重音常不同；a record 可是一般紀錄，不一定世界紀錄。","examples":[{"text":"Keeping a record of daily expenses helped me notice how small purchases gradually reduced the money I had saved for books.","translationZh":"記錄每日花費，幫助我注意小額消費如何逐漸減少原本存來買書的錢。","source":"self-authored","grammar":"keeping 動名詞作主詞；how 引導觀察到的花費變化。","writingTip":"從小額支出的紀錄反思儲蓄習慣。","topic":"消費紀錄"},{"text":"Before recording the interview, we asked the volunteer for permission and explained how the audio would be used in our report.","translationZh":"錄下訪談前，我們徵求志工同意，並說明錄音將如何用於報告。","source":"self-authored","grammar":"before recording 表錄音前；how the audio would be used 為被動語態。","writingTip":"描述訪談前徵求同意與說明用途的步骤。","topic":"訪談同意"}]},"recover":{"senses":[{"pos":"vi.","meaning":"康復；恢復","usage":"recover from + 疾病或打擊"},{"pos":"vt.","meaning":"找回；收回","usage":"recover lost objects 或 costs"}],"collocations":[{"en":"recover from an illness","zh":"病後康復","note":"from 指先前狀況"},{"en":"recover lost data","zh":"找回遺失資料","note":"及物用法"},{"en":"recover the costs","zh":"收回成本","note":"商業語境"},{"en":"a gradual recovery","zh":"逐漸恢復","note":"名詞形式"}],"synonyms":[{"en":"get better","zh":"好轉","note":"適用健康或狀況"},{"en":"retrieve","zh":"找回","note":"只對應找回物品或資料的意思"}],"idioms":[{"en":"get back on one's feet","zh":"重新站穩腳步；恢復元氣","note":"可指病後恢復或困境後重新穩定，不是找回資料。"}],"family":[{"word":"recovery","pos":"n.","meaning":"康復；恢復"},{"word":"recoverable","pos":"adj.","meaning":"可恢復的；可收回的"}],"examples":[{"text":"It took the town several years to recover from the damage caused by the earthquake.","translationZh":"這座小鎮花了數年，才從地震造成的損害中恢復。","source":"self-authored","grammar":"It took 人 + 時間 + to V 表所需時間；recover from 後接受損狀況；caused by 修飾 damage。","writingTip":"描寫重建時，可用所需的數年呈現災害影響的持續性。","topic":"disaster"},{"text":"The technician recovered the lost photographs from a damaged computer and returned them to their owner.","translationZh":"技術人員從受損電腦找回遺失照片，並把它們交還主人。","source":"self-authored","grammar":"recover + 受詞 + from + 來源","writingTip":"敘事可具體說明找回的重要物品。","topic":"technology"}],"usageNote":"recover from 表從疾病或困境恢復；recover something 表找回或收回某物。"},"reduce":{"senses":[{"pos":"vt.","meaning":"減少；降低","usage":"數量、程度或規模"},{"pos":"vt.","meaning":"使陷入某狀態","usage":"reduce 人 to tears"}],"collocations":[{"en":"reduce waste","zh":"減少浪費","note":"環境主題"},{"en":"reduce the risk of disease","zh":"降低疾病風險","note":"健康主題"},{"en":"reduce costs","zh":"降低成本","note":"經濟語境"},{"en":"be reduced to tears","zh":"被弄哭","note":"to 指結果狀態"}],"synonyms":[{"en":"decrease","zh":"減少","note":"可及物也可不及物"},{"en":"cut down on","zh":"減少","note":"常接消費、用量或習慣"}],"idioms":[],"family":[{"word":"reduction","pos":"n.","meaning":"減少；降低"},{"word":"reduced","pos":"adj.","meaning":"降低的；優惠的"},{"word":"reducible","pos":"adj.","meaning":"可減少的"}],"examples":[{"text":"Bringing a reusable bottle to school can reduce waste and save money over time.","translationZh":"帶可重複使用的水瓶上學，能減少垃圾，長期也能省錢。","source":"self-authored","grammar":"V-ing 作主詞；並列動詞","writingTip":"可提出具體且有雙重效益的環保行動。","topic":"sustainability"},{"text":"The moving speech reduced many audience members to tears as they remembered their own families.","translationZh":"感人的演說讓許多觀眾想到自己的家人而落淚。","source":"self-authored","grammar":"reduced many audience members to tears 使用 reduce + 人 + to + 結果狀態；as 引出同時發生的回憶。","writingTip":"情緒敘事可把落淚連結到想起家人，寫出感動的具體原因。","topic":"personal experience"}],"usageNote":"reduce 通常及物；reduce by 指減少幅度，reduce to 指最後數值或狀態。"},"reflect":{"senses":[{"pos":"vt.","meaning":"反射","usage":"光、熱或影像"},{"pos":"vt.","meaning":"反映","usage":"狀況或想法"},{"pos":"vi.","meaning":"深思","usage":"reflect on + 事情"}],"collocations":[{"en":"reflect sunlight","zh":"反射陽光","note":"科學語境"},{"en":"reflect social changes","zh":"反映社會變遷","note":"閱讀分析"},{"en":"reflect on an experience","zh":"反思一段經驗","note":"on 為介系詞"},{"en":"a reflection of values","zh":"價值觀的反映","note":"名詞搭配"}],"synonyms":[{"en":"mirror","zh":"反映","note":"強調呈現相似狀況"},{"en":"think carefully about","zh":"仔細思考","note":"對應 reflect on 的意思"}],"idioms":[],"family":[{"word":"reflection","pos":"n.","meaning":"反射；反思"},{"word":"reflective","pos":"adj.","meaning":"反射的；深思的"}],"examples":[{"text":"The survey results reflect changing attitudes toward public transport among people who live in the city.","translationZh":"調查結果反映了城市居民對大眾運輸態度的轉變。","source":"self-authored","grammar":"reflect + 受詞；who 修飾 people","writingTip":"圖表作文可連結資料與態度變化。","topic":"data"},{"text":"After the competition, I reflected on my mistakes and decided to prepare more carefully next time.","translationZh":"比賽後，我反思自己的錯誤，決定下次更仔細準備。","source":"self-authored","grammar":"reflected on my mistakes 使用 reflect on + 名詞；decided to prepare 使用 decide + to V，兩動詞共用主詞 I。","writingTip":"反思段落可先回顧錯誤，再提出下次更仔細準備的行動。","topic":"personal experience"}],"usageNote":"反映事物用 reflect + 受詞；反思用 reflect on + 受詞。"},"regulate":{"senses":[{"pos":"vt.","meaning":"管制；規範","usage":"以規則管理"},{"pos":"vt.","meaning":"調節","usage":"維持身體或系統穩定"}],"collocations":[{"en":"regulate traffic","zh":"管制交通","note":"公共政策"},{"en":"regulate body temperature","zh":"調節體溫","note":"生理功能"},{"en":"regulate the use of chemicals","zh":"規範化學品使用","note":"of 接對象"},{"en":"strict regulations","zh":"嚴格規定","note":"名詞形式"}],"synonyms":[{"en":"control","zh":"控制","note":"範圍廣，未必透過規則"},{"en":"govern","zh":"規範；管理","note":"著重規則對行為的約束"}],"idioms":[],"family":[{"word":"regulation","pos":"n.","meaning":"規定；調節"},{"word":"regulatory","pos":"adj.","meaning":"監管的"},{"word":"regulator","pos":"n.","meaning":"監管者；調節器"}],"examples":[{"text":"The government regulates the use of certain chemicals to protect rivers and drinking water supplies.","translationZh":"政府管制某些化學品的使用，以保護河川及飲用水供應。","source":"self-authored","grammar":"regulate + 受詞；to V 表目的","writingTip":"可寫環境規範的目的。","topic":"environment"},{"text":"Sweating helps the body regulate its temperature when people exercise in hot weather.","translationZh":"炎熱天氣運動時，流汗有助於身體調節溫度。","source":"self-authored","grammar":"help + 受詞 + 原形動詞","writingTip":"可解釋生理機制。","topic":"health"}],"usageNote":"regulate 可指規章管制，也可指生理調節；regulation 是名詞。"},"relationship":{"senses":[{"pos":"n.","meaning":"關係；人際關係","usage":"可指人與人或兩項事物之間的連結。"}],"collocations":[{"en":"build a relationship with","zh":"與……建立關係","note":""},{"en":"a close relationship","zh":"親密關係","note":""},{"en":"the relationship between A and B","zh":"A 與 B 之間的關係","note":""},{"en":"maintain healthy relationships","zh":"維持健康的人際關係","note":""}],"synonyms":[{"en":"connection","zh":"連結","note":"範圍較廣，未必持續或親密。"},{"en":"bond","zh":"情感連結","note":"常強調親近與牢固的關係。"}],"idioms":[],"family":[{"word":"relate","pos":"vi./vt.","meaning":"有關聯；使相關"},{"word":"related","pos":"adj.","meaning":"相關的"},{"word":"relational","pos":"adj.","meaning":"關係的"}],"examples":[{"text":"Sharing household tasks can strengthen family relationships by giving everyone a chance to contribute and understand others' efforts.","translationZh":"分擔家務能讓每個人有機會付出並理解他人的努力，藉此增進家庭關係。","grammar":"by giving 表方法，a chance to V 說明機會內容。","writingTip":"可寫公平分工與家庭互動。","topic":"家庭與合作","source":"self-authored"},{"text":"The survey examined the relationship between daily exercise and students' ability to concentrate during long lessons.","translationZh":"這項調查研究日常運動與學生長時間上課時的專注能力之間的關係。","grammar":"relationship between A and B，ability to V。","writingTip":"適合敘述調查的變項與目的。","topic":"調查與健康","source":"self-authored"}],"usageNote":"relationship 不一定是戀愛；the relationship between X and Y 常見於研究與圖表說明。"},"relevant":{"senses":[{"pos":"adj.","meaning":"相關的；切題的","usage":"relevant to + 主題、問題或對象。"}],"collocations":[{"en":"relevant to the discussion","zh":"與討論有關","note":""},{"en":"relevant experience","zh":"相關經驗","note":""},{"en":"provide relevant information","zh":"提供相關資訊","note":""},{"en":"remain relevant to readers","zh":"對讀者仍有關聯與意義","note":""}],"synonyms":[{"en":"pertinent","zh":"切題的","note":"較正式，強調直接關係到當前問題。"},{"en":"applicable","zh":"適用的","note":"強調可實際套用；相關資訊未必直接適用。"}],"idioms":[],"family":[{"word":"relevance","pos":"n.","meaning":"相關性；切題程度"},{"word":"irrelevant","pos":"adj.","meaning":"不相關的；不切題的"}],"usageNote":"relevant to，不寫 relevant with。資料來自可信來源仍可能與此題無關，須同時判斷可信度與相關性。","examples":[{"text":"The article contained many interesting facts, but only a few were relevant to the question our group wanted to answer.","translationZh":"文章有很多有趣事實，但只有少數與我們小組想回答的問題相關。","grammar":"relevant to + 問題；our group wanted to answer 修飾 question。","writingTip":"專題寫作說明如何依研究問題篩選資料。","topic":"資料篩選","source":"self-authored"},{"text":"When applying for the volunteer role, I described relevant experience instead of listing every activity I had joined.","translationZh":"申請志工職務時，我描述相關經驗，而非列出所有參加過的活動。","grammar":"When applying 為省略主詞結構；instead of + V-ing。","writingTip":"申請或自我介紹應挑選能說明適任性的經驗。","topic":"服務申請","source":"self-authored"}]},"reliable":{"senses":[{"pos":"adj.","meaning":"可靠的；可信賴的","usage":"資訊、設備或人值得信任"}],"collocations":[{"en":"a reliable source","zh":"可靠來源","note":"查證語境"},{"en":"reliable information","zh":"可信資訊","note":"媒體識讀"},{"en":"reliable public transport","zh":"可靠的大眾運輸","note":"服務穩定"},{"en":"highly reliable equipment","zh":"高度可靠的設備","note":"副詞修飾"}],"synonyms":[{"en":"dependable","zh":"可靠的","note":"常形容人或設備"},{"en":"trustworthy","zh":"值得信任的","note":"著重誠實及資訊可信度"}],"idioms":[],"family":[{"word":"reliability","pos":"n.","meaning":"可靠性"},{"word":"reliably","pos":"adv.","meaning":"可靠地"},{"word":"unreliable","pos":"adj.","meaning":"不可靠的"}],"examples":[{"text":"Students should compare information from several reliable sources before using it in a research report.","translationZh":"學生把資訊用於研究報告前，應比較數個可靠來源的內容。","source":"self-authored","grammar":"information 不可數；before + V-ing","writingTip":"可用於查證與研究能力。","topic":"media"},{"text":"Reliable public transport helps workers arrive on time even when they cannot afford a car.","translationZh":"可靠的大眾運輸能幫助負擔不起汽車的工作者準時抵達。","source":"self-authored","grammar":"helps workers arrive 使用 help + 人 + 原形動詞；even when 引導讓步情境；afford 後接名詞 a car。","writingTip":"分析交通公平時，可指出可靠服務如何幫助無力購車的人準時上班。","topic":"transport"}],"usageNote":"reliable 強調可持續依賴；資料是否 reliable 應看來源、證據與更新情況。"},"relief":{"senses":[{"pos":"n.","meaning":"緩解；安心","usage":""},{"pos":"n.","meaning":"救濟","usage":""}],"collocations":[{"en":"a sense of relief","zh":"如釋重負的感覺","note":""},{"en":"to one's relief","zh":"令某人安心的是","note":""},{"en":"pain relief","zh":"止痛","note":""},{"en":"disaster relief","zh":"災害救濟","note":""}],"synonyms":[{"en":"comfort","zh":"慰藉","note":"偏情感支持"},{"en":"alleviation","zh":"減輕","note":"較正式的症狀或問題緩解"}],"idioms":[],"family":[{"word":"relieve","pos":"v.","meaning":"減輕；解除"},{"word":"relieved","pos":"adj.","meaning":"感到安心的"},{"word":"relieving","pos":"adj.","meaning":"緩解的"}],"usageNote":"relief 常為不可數；relieve pain/stress，但 relieve someone of a duty 表解除某人職務。","examples":[{"text":"To my relief, the lost dog was found near the park and returned to its owner before the storm arrived.","translationZh":"令我安心的是，走失的狗在公園附近被找到，並在暴風雨來臨前送回飼主身邊。","source":"self-authored","grammar":"to my relief 表如釋重負；was found/returned 為並列被動動作。","writingTip":"用找到並送回宠物的結果描寫安心感。","topic":"走失寵物"},{"text":"Students collected blankets and bottled water for disaster relief, checking the requested supplies before sending their donations to the affected community.","translationZh":"學生為災害救濟募集毛毯和瓶裝水，先確認所需物資，再把捐贈送往受災社區。","source":"self-authored","grammar":"for disaster relief 表用途；checking 補充捐贈前的確認。","writingTip":"說明先確認需求如何使捐贈更有帮助。","topic":"救災物資"}]},"remind":{"senses":[{"pos":"vt.","meaning":"提醒；使想起","usage":"常用 remind someone to V、of something 或 that 子句。"}],"collocations":[{"en":"remind someone to call","zh":"提醒某人打電話","note":""},{"en":"remind someone of home","zh":"使某人想起家","note":""},{"en":"remind someone that","zh":"提醒某人……","note":""},{"en":"a gentle reminder","zh":"溫和的提醒","note":"使用名詞 reminder。"}],"synonyms":[{"en":"prompt","zh":"促使；提醒","note":"可能只提供線索使人想起。"},{"en":"recall","zh":"回想","note":"通常是主詞自己想起，不等於提醒他人。"}],"idioms":[],"family":[{"word":"reminder","pos":"n.","meaning":"提醒物；提醒訊息"}],"examples":[{"text":"The smell of freshly baked bread reminded me of the weekends I used to spend at my grandparents' home.","translationZh":"剛出爐麵包的香氣，讓我想起以前在祖父母家度過的週末。","grammar":"remind someone of，used to V 表過去習慣。","writingTip":"可用感官細節帶出回憶。","topic":"家庭與記憶","source":"self-authored"},{"text":"Teachers can remind students to verify information before sharing it, especially when a message triggers strong emotions.","translationZh":"老師可以提醒學生分享資訊前先查證，尤其當訊息引發強烈情緒時。","grammar":"remind someone to V，before V-ing 表先後。","writingTip":"適合討論媒體識讀的日常做法。","topic":"網路與資訊","source":"self-authored"}],"usageNote":"remind 的受詞通常先放人；remember 是自己記得，不能直接取代 remind。"},"renewable":{"senses":[{"pos":"adj.","meaning":"可再生的","usage":"資源可自然補充"},{"pos":"adj.","meaning":"可續期的","usage":"合約或許可證"}],"collocations":[{"en":"renewable energy","zh":"再生能源","note":"環境主題"},{"en":"renewable resources","zh":"可再生資源","note":"資源分類"},{"en":"a renewable contract","zh":"可續期合約","note":"行政語境"},{"en":"invest in renewable power","zh":"投資再生電力","note":"能源轉型"}],"synonyms":[{"en":"replenishable","zh":"可補充的","note":"適用資源，較少用於日常文章"},{"en":"extendable","zh":"可延長的","note":"對應合約或期限，不能代替再生能源義"}],"idioms":[],"family":[{"word":"renew","pos":"vt.","meaning":"更新；續期"},{"word":"renewal","pos":"n.","meaning":"更新；續期"},{"word":"nonrenewable","pos":"adj.","meaning":"不可再生的"}],"examples":[{"text":"The island is investing in renewable energy to reduce its dependence on imported fuel.","translationZh":"這座島正投資再生能源，以減少對進口燃料的依賴。","source":"self-authored","grammar":"is investing 使用現在進行式；invest in 後接能源類別；dependence on 後接依賴的燃料。","writingTip":"描述能源轉型時，可用減少依賴進口燃料來說明投資目的。","topic":"energy"},{"text":"Unlike fossil fuels, renewable resources can be replenished, though responsible use is still necessary.","translationZh":"不同於化石燃料，可再生資源能獲得補充，但負責任地使用仍有必要。","source":"self-authored","grammar":"Unlike + 名詞；though 引導讓步","writingTip":"可討論資源特性與使用責任。","topic":"sustainability"}],"usageNote":"renewable 不等於完全無環境成本；也可指合約或許可證能續期。"},"replace":{"senses":[{"pos":"vt.","meaning":"取代；替換","usage":"replace A with B"},{"pos":"vt.","meaning":"放回原處","usage":"replace something on a shelf"}],"collocations":[{"en":"replace old equipment","zh":"更換舊設備","note":"接受詞"},{"en":"replace A with B","zh":"以 B 替換 A","note":"方向勿倒置"},{"en":"replace a missing part","zh":"補上遺失零件","note":"修理情境"},{"en":"a replacement for plastic","zh":"塑膠的替代品","note":"名詞搭配"}],"synonyms":[{"en":"substitute","zh":"替代","note":"substitute B for A 方向與 replace A with B 不同"},{"en":"take the place of","zh":"取代","note":"對應替代某人或事物"}],"idioms":[],"family":[{"word":"replacement","pos":"n.","meaning":"替換；替代者"},{"word":"replaceable","pos":"adj.","meaning":"可替換的"},{"word":"irreplaceable","pos":"adj.","meaning":"無可取代的"}],"examples":[{"text":"The cafeteria replaced disposable cups with reusable ones to reduce the amount of daily waste.","translationZh":"餐廳以可重複使用的杯子取代免洗杯，減少每天的垃圾量。","source":"self-authored","grammar":"replace A with B；ones 代替 cups","writingTip":"可寫減廢措施。","topic":"sustainability"},{"text":"Online messages are convenient, but they cannot fully replace the warmth of a face-to-face conversation.","translationZh":"線上訊息很方便，卻無法完全取代面對面交談的溫暖。","source":"self-authored","grammar":"they 指 Online messages；cannot 後接原形動詞 replace，直接接 the warmth；but 連接兩個對照分句。","writingTip":"人際互動作文可承認訊息便利，再說明面談帶來的情感價值。","topic":"relationships"}],"usageNote":"replace A with B 指用 B 取代 A；替換方向是常見易錯點。"},"require":{"senses":[{"pos":"vt.","meaning":"需要","usage":"require + 名詞 或 V-ing"},{"pos":"vt.","meaning":"要求","usage":"require 人 to V"}],"collocations":[{"en":"require careful planning","zh":"需要仔細規劃","note":"接受詞"},{"en":"require students to participate","zh":"要求學生參與","note":"人 + to V"},{"en":"meet the requirements","zh":"符合要求","note":"名詞搭配"},{"en":"be required by law","zh":"依法必須","note":"被動語態"}],"synonyms":[{"en":"need","zh":"需要","note":"較日常"},{"en":"demand","zh":"要求","note":"常帶較強烈或迫切的語氣"}],"idioms":[],"family":[{"word":"requirement","pos":"n.","meaning":"要求；必要條件"},{"word":"required","pos":"adj.","meaning":"必需的；規定的"}],"examples":[{"text":"Organizing a school festival requires careful planning and cooperation among students from different classes.","translationZh":"籌辦校園節慶需要仔細規劃，以及不同班級學生間的合作。","source":"self-authored","grammar":"Organizing a school festival 是 V-ing 片語作單數主詞，搭配 requires；planning 與 cooperation 為並列受詞。","writingTip":"寫活動籌辦經驗時，可列出規劃與跨班合作兩项必要條件。","topic":"school"},{"text":"The new policy requires visitors to reserve a time slot before entering the popular exhibition.","translationZh":"新政策要求遊客進入熱門展覽前，先預約時段。","source":"self-authored","grammar":"require 人 to V","writingTip":"適合規則說明或旅遊議題。","topic":"culture"}],"usageNote":"require 人 to V；require V-ing 可表示某事需要被做，如 The roof requires repairing。"},"rescue":{"senses":[{"pos":"v.","meaning":"救援；挽救","usage":""},{"pos":"n.","meaning":"救援行動","usage":""}],"collocations":[{"en":"rescue people from a flood","zh":"救出洪水中的人們","note":""},{"en":"a rescue operation","zh":"救援行動","note":""},{"en":"a rescue team","zh":"救援隊","note":""},{"en":"come to someone's rescue","zh":"前來幫助某人","note":""}],"synonyms":[{"en":"save","zh":"救助","note":"save 還可指節省"},{"en":"retrieve","zh":"取回","note":"強調拿回物品，不一定涉及危險"}],"idioms":[{"en":"come to the rescue","zh":"挺身相助","note":"可用於危急或一般困境"}],"family":[{"word":"rescuer","pos":"n.","meaning":"救援者"},{"word":"rescue worker","pos":"n.","meaning":"救援人員"}],"usageNote":"rescue A from B；from 後接危險來源或受困場所。","examples":[{"text":"The rescue team used a small boat to reach families trapped on the second floor of their flooded homes.","translationZh":"救援隊利用小船，接近受困於淹水住家二樓的家庭。","source":"self-authored","grammar":"trapped 為過去分詞修飾 families；to reach 表目的。","writingTip":"用交通工具與受困位置交代具體救援情境。","topic":"洪水救援"},{"text":"A neighbor came to our rescue when our car broke down, driving us to the station before the last train departed.","translationZh":"車子故障時，一位鄰居前來相助，在末班火車離站前載我們到車站。","source":"self-authored","grammar":"came to our rescue 表前來相助；driving 補充幫忙方式。","writingTip":"可描述陌生或鄰居的幫助如何解決交通困難。","topic":"鄰里互助"}]},"research":{"senses":[{"pos":"n.","meaning":"研究","usage":"通常不可數"},{"pos":"vt./vi.","meaning":"研究","usage":"research a topic 或 into a subject"}],"collocations":[{"en":"conduct research","zh":"進行研究","note":"正式搭配"},{"en":"research into sleep habits","zh":"睡眠習慣研究","note":"into 指研究主題"},{"en":"research findings","zh":"研究發現","note":"名詞修飾名詞"},{"en":"research a local tradition","zh":"研究地方傳統","note":"動詞直接接受詞"}],"synonyms":[{"en":"study","zh":"研究","note":"可數名詞可指個別研究"},{"en":"investigation","zh":"調查","note":"著重釐清事實或原因"}],"idioms":[],"family":[{"word":"researcher","pos":"n.","meaning":"研究人員"},{"word":"researched","pos":"adj.","meaning":"經過研究的"}],"examples":[{"text":"For our research project, we compared students' travel habits by collecting anonymous surveys and observing traffic near the school.","translationZh":"為了研究專題，我們蒐集匿名問卷並觀察學校附近交通，比較學生的通勤習慣。","source":"self-authored","grammar":"research 在 research project 中作名詞修飾語；by 後並列 collecting 與 observing 兩個 V-ing。","writingTip":"研究作文具體交代資料蒐集方式，避免用未註明來源的「近期研究顯示」充當證據。","topic":"交通研究"},{"text":"We researched a local tradition by interviewing craftspeople and examining objects preserved in the museum.","translationZh":"我們訪談工藝師，並檢視博物館保存的物件，研究一項地方傳統。","source":"self-authored","grammar":"research 作及物動詞；by + V-ing","writingTip":"可寫文化專題的資料蒐集方法。","topic":"culture"}],"usageNote":"research 作名詞通常不可數；單一研究可說 a study，不寫 a research。"},"reserve":{"senses":[{"pos":"v.","meaning":"預訂；保留","usage":""},{"pos":"n.","meaning":"儲備；保護區","usage":""}],"collocations":[{"en":"reserve a seat","zh":"預訂座位","note":""},{"en":"reserve time for reading","zh":"保留閱讀時間","note":""},{"en":"a nature reserve","zh":"自然保護區","note":""},{"en":"in reserve","zh":"留作備用","note":""}],"synonyms":[{"en":"book","zh":"預訂","note":"book a seat 與 reserve 相近"},{"en":"retain","zh":"保留","note":"較正式，不表示訂位"}],"idioms":[],"family":[{"word":"reservation","pos":"n.","meaning":"預訂；疑慮"},{"word":"reserved","pos":"adj.","meaning":"已預訂的；拘謹的"}],"usageNote":"reservation 可指預訂或保留意見；have reservations about 表對……有疑慮。","examples":[{"text":"We reserved a table near the entrance so that our grandmother could reach it easily without walking through the crowded restaurant.","translationZh":"我們訂了靠入口的桌位，讓祖母不用穿過擁擠餐廳就能輕鬆抵達。","source":"self-authored","grammar":"reserved a table；so that + 主詞 + could 表目的。","writingTip":"以座位位置呈現對長者行動需求的體貼。","topic":"無障礙用餐"},{"text":"The nature reserve limits the number of visitors each day to protect nesting birds and reduce damage to fragile plants.","translationZh":"自然保護區限制每日遊客人數，以保護築巢的鳥類並減少脆弱植物受到的損害。","source":"self-authored","grammar":"limits the number of + 複數名詞；to protect/reduce 表目的。","writingTip":"把人數限制連結到具體生態保護目的。","topic":"自然保護區"}]},"resource":{"senses":[{"pos":"n.","meaning":"資源","usage":"常用複數 resources"},{"pos":"n.","meaning":"可利用的方法或能力","usage":"人力、教材或財力"}],"collocations":[{"en":"natural resources","zh":"自然資源","note":"環境主題"},{"en":"educational resources","zh":"教育資源","note":"教材與工具"},{"en":"limited resources","zh":"有限資源","note":"問題分析"},{"en":"allocate resources fairly","zh":"公平分配資源","note":"公共政策"}],"synonyms":[{"en":"asset","zh":"有用資產","note":"強調可產生價值的事物"},{"en":"supply","zh":"供應量","note":"適用可用物資，不涵蓋所有人力或教材資源"}],"idioms":[{"en":"make the most of what one has","zh":"充分利用現有條件","note":"與善用有限資源相關，不是 resource 的直接字義。"}],"family":[{"word":"resourceful","pos":"adj.","meaning":"足智多謀的"},{"word":"resourcefulness","pos":"n.","meaning":"應變能力"}],"examples":[{"text":"The website provides free educational resources for students who cannot easily attend extra classes.","translationZh":"這個網站提供免費教育資源，給不方便參加課外補習的學生。","source":"self-authored","grammar":"resources for + 人；who 修飾 students","writingTip":"可用於教育機會與線上學習。","topic":"education"},{"text":"Because resources were limited, the rescue team had to decide which areas needed help most urgently.","translationZh":"由於資源有限，救援隊必須決定哪些地區最迫切需要協助。","source":"self-authored","grammar":"Because resources were limited 為原因子句；had to decide 表當時必須；which areas... 是 decide 的間接問句受詞。","writingTip":"寫救災資源分配時，呈現有限物資迫使團隊比較需求的困難。","topic":"disaster"}],"usageNote":"resources 常用複數表示可用資源；resourceful 形容人善於應變，不是資源豐富。"},"respect":{"senses":[{"pos":"n.","meaning":"尊重；方面","usage":"in this respect 表在這方面。"},{"pos":"vt.","meaning":"尊重；遵守","usage":"可接人、權利、規則或界線。"}],"collocations":[{"en":"show respect for others","zh":"表現對他人的尊重","note":""},{"en":"respect personal boundaries","zh":"尊重個人界線","note":""},{"en":"respect the rules","zh":"遵守規則","note":""},{"en":"in this respect","zh":"在這方面","note":"此處不是尊重。"}],"synonyms":[{"en":"esteem","zh":"敬重","note":"較正式，常表示高度尊敬。"},{"en":"regard","zh":"看待；尊重","note":"high regard 為高度評價，句型與 respect 不同。"}],"idioms":[{"en":"pay one's respects","zh":"致意；弔唁","note":"依情境可表示禮貌拜訪或弔念。"}],"family":[{"word":"respectful","pos":"adj.","meaning":"表示尊重的"},{"word":"respected","pos":"adj.","meaning":"受尊敬的"},{"word":"respectable","pos":"adj.","meaning":"值得尊重的；體面的"}],"examples":[{"text":"Respecting different opinions means listening without insulting people who hold them, even when we disagree with their views.","translationZh":"尊重不同意見，是即使不認同他人的觀點，也能傾聽而不侮辱對方。","grammar":"mean V-ing，who 引導關係子句，even when 表讓步。","writingTip":"可寫公共討論中的尊重。","topic":"溝通與思辨","source":"self-authored"},{"text":"A responsible pet owner respects neighbors' needs by keeping shared spaces clean and controlling unnecessary noise.","translationZh":"負責任的飼主會保持公共空間清潔並減少不必要的噪音，以尊重鄰居需求。","grammar":"by 後接並列動名詞，keep 受詞 adjective。","writingTip":"適合討論養寵物與社區責任。","topic":"寵物與鄰里","source":"self-authored"}],"usageNote":"respectful 指態度恭敬，respected 指受到尊敬，respectable 指體面或值得尊重。"},"respond":{"senses":[{"pos":"vi.","meaning":"回應","usage":"respond to + 人、問題或事件"},{"pos":"vi.","meaning":"有反應；產生療效反應","usage":"生物或身體對刺激"}],"collocations":[{"en":"respond to a question","zh":"回答問題","note":"to 不可省略"},{"en":"respond to an emergency","zh":"應對緊急狀況","note":"行動回應"},{"en":"respond well to treatment","zh":"對治療反應良好","note":"醫療語境"},{"en":"respond quickly","zh":"迅速回應","note":"副詞修飾"}],"synonyms":[{"en":"reply","zh":"回答","note":"偏口語或文字答覆"},{"en":"react","zh":"反應","note":"可能是直覺或身體反應，不一定經思考"}],"idioms":[],"family":[{"word":"response","pos":"n.","meaning":"回應；反應"},{"word":"responsive","pos":"adj.","meaning":"反應敏銳的"},{"word":"respondent","pos":"n.","meaning":"受訪者"}],"examples":[{"text":"The teacher responded to my question by drawing a diagram instead of repeating the same explanation.","translationZh":"老師畫了一張圖來回答我的問題，沒有重複原本的解釋。","source":"self-authored","grammar":"respond to；by + V-ing","writingTip":"可寫教學互動經驗。","topic":"education"},{"text":"Plants respond to changes in light by adjusting the direction in which they grow.","translationZh":"植物透過調整生長方向，回應光線的變化。","source":"self-authored","grammar":"respond to；in which 引導關係子句","writingTip":"可描述科學現象。","topic":"science"}],"usageNote":"respond 是不及物動詞，常用 respond to；response 是名詞，responsive 是形容詞。"},"responsibility":{"senses":[{"pos":"n.","meaning":"責任；應盡的義務","usage":""}],"collocations":[{"en":"take responsibility for one's actions","zh":"為自己的行為負責","note":""},{"en":"a sense of responsibility","zh":"責任感","note":""},{"en":"share household responsibilities","zh":"分擔家務責任","note":""},{"en":"accept full responsibility","zh":"承擔全部責任","note":""}],"synonyms":[{"en":"duty","zh":"職責","note":"常指被指定或道德上的義務"},{"en":"accountability","zh":"可被要求交代的責任","note":"強調對結果負責與說明"}],"idioms":[],"family":[{"word":"responsible","pos":"adj.","meaning":"負責的；負有責任的"},{"word":"responsibly","pos":"adv.","meaning":"負責任地"},{"word":"irresponsible","pos":"adj.","meaning":"不負責任的"}],"usageNote":"responsibility for + 名詞或 V-ing；responsible for 與 responsive to 不同。","examples":[{"text":"Owning a pet is a long-term responsibility that includes daily exercise, medical care, and planning for changes in family circumstances.","translationZh":"飼養寵物是長期責任，包括每日運動、醫療照護，以及因應家庭狀況改變的規畫。","source":"self-authored","grammar":"owning 動名詞片語作主詞；that includes 修飾 responsibility。","writingTip":"列出飼養的具體任務，支持長期承諾的論點。","topic":"寵物責任"},{"text":"After missing the deadline, I took responsibility for my mistake and proposed a realistic schedule to complete the unfinished work.","translationZh":"錯過截止期限後，我為自己的錯誤負責，並提出切實可行的進度來完成未做完的工作。","source":"self-authored","grammar":"after missing 表時間；took responsibility for my mistake 表承擔。","writingTip":"描寫失誤後承擔責任與提出改善計畫。","topic":"學習責任"}]},"responsible":{"senses":[{"pos":"adj.","meaning":"應負責的","usage":"responsible for + 任務或結果"},{"pos":"adj.","meaning":"負責任的；可靠的","usage":"形容人或行為"}],"collocations":[{"en":"be responsible for organizing events","zh":"負責籌辦活動","note":"for + V-ing"},{"en":"responsible behavior","zh":"負責任的行為","note":"品格主題"},{"en":"hold someone responsible","zh":"追究某人責任","note":"hold + 受詞 + 形容詞"},{"en":"environmentally responsible choices","zh":"對環境負責的選擇","note":"副詞修飾"}],"synonyms":[{"en":"accountable","zh":"應負責的","note":"強調需交代後果"},{"en":"dependable","zh":"可靠的","note":"對應人的品格，非造成後果的責任義"}],"idioms":[],"family":[{"word":"responsibility","pos":"n.","meaning":"責任"},{"word":"responsibly","pos":"adv.","meaning":"負責任地"},{"word":"irresponsible","pos":"adj.","meaning":"不負責任的"}],"examples":[{"text":"As the team leader, I was responsible for making sure everyone understood the project schedule.","translationZh":"身為組長，我負責確保每個人都了解專題的時程。","source":"self-authored","grammar":"be responsible for + V-ing","writingTip":"可具體描述團隊中的角色。","topic":"teamwork"},{"text":"Responsible consumers consider how their purchases affect workers, local communities, and the natural environment.","translationZh":"負責任的消費者會考慮，自己的購物如何影響勞工、地方社區及自然環境。","source":"self-authored","grammar":"Responsible 作形容詞修飾 consumers；how their purchases affect... 為 consider 的間接問句受詞。","writingTip":"消費責任作文可列出勞工、社區與自然環境三個受影響面向。","topic":"consumer behavior"}],"usageNote":"responsible for 可指負責一項工作，也可指造成結果；responsible to 指須向誰負責。"},"responsive":{"senses":[{"pos":"adj.","meaning":"對刺激或需求有反應的","usage":""},{"pos":"adj.","meaning":"願意回應意見的","usage":""}],"collocations":[{"en":"responsive to students' needs","zh":"能回應學生的需求","note":""},{"en":"responsive to treatment","zh":"對治療有反應","note":""},{"en":"a responsive government","zh":"願意回應民意的政府","note":""},{"en":"highly responsive customer service","zh":"反應迅速的客服","note":""}],"synonyms":[{"en":"receptive","zh":"樂於接受的","note":"receptive to 指願意接受意見，不保證採取行動"},{"en":"sensitive","zh":"敏感的","note":"sensitive to 可指察覺細微變化"}],"idioms":[],"family":[{"word":"respond","pos":"v.","meaning":"回應"},{"word":"response","pos":"n.","meaning":"回應；反應"},{"word":"responsiveness","pos":"n.","meaning":"回應能力"}],"usageNote":"responsive to 的 to 是介系詞，後接名詞；與 responsible for（對……負責）不同。","examples":[{"text":"A good school should be responsive to students' needs rather than apply the same rule to every situation.","translationZh":"好的學校應回應學生的需求，而非在每種情境都套用同一條規定。","source":"self-authored","grammar":"responsive to + 需求；rather than 後的 apply 與 be 平行。","writingTip":"以學校是否回應學生需求來評估制度。","topic":"學校制度"},{"text":"Because the patient was responsive to treatment, the doctor decided to continue the current plan for another week.","translationZh":"由於病人對治療有反應，醫師決定將目前的方案再持續一週。","source":"self-authored","grammar":"because 引導原因；responsive to treatment 指治療有效的反應。","writingTip":"用具體治療反應說明延續方案的理由。","topic":"醫療照護"}]},"rest":{"senses":[{"pos":"n.","meaning":"休息；剩餘部分","usage":""},{"pos":"v.","meaning":"休息；靠放","usage":""}],"collocations":[{"en":"get enough rest","zh":"得到充分休息","note":""},{"en":"the rest of the class","zh":"班上其餘同學","note":""},{"en":"rest one's head on a pillow","zh":"把頭靠在枕頭上","note":""},{"en":"rest assured","zh":"放心","note":""}],"synonyms":[{"en":"remainder","zh":"剩餘部分","note":"較正式"},{"en":"relax","zh":"放鬆","note":"不一定完全停止活動"}],"idioms":[{"en":"put a concern to rest","zh":"平息疑慮","note":"指消除持續的不安或爭論"}],"family":[{"word":"restful","pos":"adj.","meaning":"令人休息放鬆的"},{"word":"restless","pos":"adj.","meaning":"坐立不安的"},{"word":"restlessness","pos":"n.","meaning":"不安"}],"usageNote":"the rest of + 名詞；動詞單複數依所指對象決定，如 the rest of the students are。","examples":[{"text":"After completing the difficult section, I took a short rest before returning to the remaining questions with a clearer mind.","translationZh":"完成困難部分後，我稍作休息，再以更清楚的頭腦回來作答剩餘題目。","source":"self-authored","grammar":"after completing 表完成某部分後；before returning 表再继續前。","writingTip":"描述短暫休息如何帮助完成後續題目。","topic":"考試節奏"},{"text":"While two students presented the results, the rest of the class listened carefully and prepared questions about how the data had been collected.","translationZh":"兩位學生發表結果時，其餘同學仔細聆聽，並準備詢問資料如何蒐集。","source":"self-authored","grammar":"the rest of the class 指其餘同學；how 引導資料蒐集的問題。","writingTip":"可敘述分工發表與聽眾的積極参與。","topic":"課堂發表"}]},"restrict":{"senses":[{"pos":"vt.","meaning":"限制","usage":"restrict A to B 或 restrict 人 from V-ing"}],"collocations":[{"en":"restrict access to an area","zh":"限制進入某區域","note":"access to 作受詞"},{"en":"restrict the use of plastics","zh":"限制塑膠使用","note":"of 說明使用對象"},{"en":"restrict visitors to marked paths","zh":"限制遊客只能走標示步道","note":"to 指範圍"},{"en":"strict restrictions","zh":"嚴格限制","note":"名詞形式"}],"synonyms":[{"en":"limit","zh":"限制","note":"較一般的範圍或數量控制"},{"en":"confine","zh":"限定","note":"著重限制在特定區域或範圍"}],"idioms":[],"family":[{"word":"restriction","pos":"n.","meaning":"限制"},{"word":"restricted","pos":"adj.","meaning":"受限制的"},{"word":"restrictive","pos":"adj.","meaning":"具限制性的"}],"examples":[{"text":"The park restricts visitors to marked paths to protect fragile plants growing near the trail.","translationZh":"公園限制遊客只能走標示步道，以保護步道旁脆弱的植物。","source":"self-authored","grammar":"restricts visitors to marked paths 使用 restrict + 人 + to + 範圍；growing near the trail 是修飾 plants 的現在分詞片語。","writingTip":"說明步道規則時，可指出保護路旁脆弱植物的具體目的。","topic":"wildlife"},{"text":"Schools may restrict phone use during lessons while allowing students to contact their families after class.","translationZh":"學校可能限制上課使用手機，但允許學生下課後聯絡家人。","source":"self-authored","grammar":"restrict + 名詞；while + V-ing","writingTip":"可寫規範與不同需求的平衡。","topic":"school"}],"usageNote":"restrict A to B 表將 A 限定於 B；restriction 作可數名詞常用複數。"},"retain":{"senses":[{"pos":"vt.","meaning":"保留；維持","usage":"使某物、特徵或資格繼續存在。"},{"pos":"vt.","meaning":"記住","usage":"保留學過的資訊。"}],"collocations":[{"en":"retain information","zh":"記住資訊","note":""},{"en":"retain a sense of identity","zh":"保有認同感","note":""},{"en":"retain moisture","zh":"保持水分","note":""},{"en":"retain the original features","zh":"保留原有特色","note":""}],"synonyms":[{"en":"keep","zh":"保留","note":"較日常，適用範圍廣。"},{"en":"preserve","zh":"保存；維護","note":"常含保護原有狀態免受損的意思。"}],"idioms":[],"family":[{"word":"retention","pos":"n.","meaning":"保留；記憶保持"},{"word":"retained","pos":"adj.","meaning":"保留下來的"},{"word":"retentive","pos":"adj.","meaning":"記性好的；能保持的"}],"usageNote":"retain information 強調後來仍記得；理解當下的內容不等於日後能回想。retention 也可指員工留任或水分保持。","examples":[{"text":"I wanted to retain what I had learned, so I returned to the topic several days later and tested myself.","translationZh":"我希望記住學過的內容，因此隔幾天再回到這個主題，測試自己。","grammar":"retain 後接 what 名詞子句；several days later 表延後回顧。","writingTip":"學習作文寫出間隔後檢查記憶的行動，而非只說多讀。","topic":"延後複習","source":"self-authored"},{"text":"The renovated market retained its original wooden signs while adding better lighting and wider paths for visitors with limited mobility.","translationZh":"整修後的市場保留原有木招牌，同時加強照明、拓寬走道，方便行動不便的訪客。","grammar":"retain 直接接 signs；while adding 表同時加入改良。","writingTip":"保存與更新作文可具體比較保留部分及改善部分。","topic":"市場更新","source":"self-authored"}]},"revise":{"senses":[{"pos":"vt.","meaning":"修訂；修改","usage":"根據檢視或新資訊改變內容。"},{"pos":"vt./vi.","meaning":"複習","usage":"英式用法，如 revise for an exam；美式常用 review。"}],"collocations":[{"en":"revise a draft","zh":"修改草稿","note":""},{"en":"revise an estimate","zh":"修正估計","note":""},{"en":"a revised edition","zh":"修訂版","note":""},{"en":"revise for an exam","zh":"為考試複習","note":"英式用法。"}],"synonyms":[{"en":"amend","zh":"修訂","note":"常指法規、文件或正式細節的修改。"},{"en":"review","zh":"複習；檢視","note":"檢視未必實際更動，revise 在修訂義下含修改。"}],"idioms":[],"family":[{"word":"revision","pos":"n.","meaning":"修訂；複習"},{"word":"revised","pos":"adj.","meaning":"已修訂的"}],"usageNote":"revise a draft 含修改，review a draft 可只是檢視。英式 revise for a test 是複習，不是修改考卷。","examples":[{"text":"After reading my classmates' comments, I revised the opening paragraph to make the main problem clearer to the reader.","translationZh":"讀完同學的評語後，我修改開頭段落，讓讀者更清楚主要問題。","grammar":"After reading 表先後；to make + 受詞 + 形容詞為修改目的。","writingTip":"寫作反思交代根據何種回饋修改哪個部分。","topic":"寫作修訂","source":"self-authored"},{"text":"The organizers revised their estimate of attendance after more families registered than they had expected at the start.","translationZh":"報名家庭比最初預期更多後，主辦人修正了參加人數的估計。","grammar":"estimate of + 數量事項；more...than...表比較；had expected 表先前預期。","writingTip":"活動規畫作文說明新資料如何促使調整預估。","topic":"活動預估","source":"self-authored"}]},"right":{"senses":[{"pos":"adj.","meaning":"正確的；右方的","usage":""},{"pos":"n.","meaning":"權利","usage":""},{"pos":"adv.","meaning":"正好；立刻","usage":""}],"collocations":[{"en":"the right answer","zh":"正確答案","note":""},{"en":"human rights","zh":"人權","note":""},{"en":"turn right","zh":"右轉","note":""},{"en":"right after lunch","zh":"午餐後立刻","note":""}],"synonyms":[{"en":"correct","zh":"正確的","note":"不適用方向或權利義"},{"en":"entitlement","zh":"應有權利","note":"較正式且常由規定賦予"}],"idioms":[],"family":[{"word":"rightly","pos":"adv.","meaning":"正確地；理所當然地"},{"word":"rightful","pos":"adj.","meaning":"合法應有的"},{"word":"rightness","pos":"n.","meaning":"正確性"}],"usageNote":"a right to + 名詞／to V 表權利；right 作副詞可加強時間或位置的精確性。","examples":[{"text":"Every student has the right to express an opinion, but respectful discussion also requires listening carefully to people who disagree.","translationZh":"每位學生都有表達意見的權利，但尊重的討論也需要仔細聆聽不同意見者。","source":"self-authored","grammar":"the right to + 原形動詞；who disagree 修飾 people。","writingTip":"把表达意見的權利連結到傾聽他人的責任。","topic":"發言權與尊重"},{"text":"Right after lunch, we checked the weather forecast and decided to postpone the outdoor activity until the heavy rain stopped.","translationZh":"午餐剛結束，我們查看天氣預報，決定把戶外活動延後到大雨停下來。","source":"self-authored","grammar":"right after lunch 中 right 強調剛結束；until 引導延後的界線。","writingTip":"描寫查看預報後調整計畫的過程。","topic":"戶外活動安排"}]},"risk":{"senses":[{"pos":"n.","meaning":"風險","usage":"risk of + 不利事件"},{"pos":"vt.","meaning":"冒險","usage":"risk + 名詞 或 V-ing"}],"collocations":[{"en":"at risk of injury","zh":"有受傷風險","note":"at risk of"},{"en":"take a risk","zh":"冒險","note":"a 表一次冒險"},{"en":"reduce the risk","zh":"降低風險","note":"安全措施"},{"en":"risk losing valuable data","zh":"冒著遺失重要資料的風險","note":"接 V-ing"}],"synonyms":[{"en":"danger","zh":"危險","note":"可能指實際威脅，不完全等同發生機率"},{"en":"hazard","zh":"危害因素","note":"常指造成危險的來源"}],"idioms":[{"en":"play with fire","zh":"玩火；冒不必要的險","note":"指可能帶來嚴重後果的冒險，常帶警告語氣。"}],"family":[{"word":"risky","pos":"adj.","meaning":"有風險的"},{"word":"riskiness","pos":"n.","meaning":"風險性"}],"examples":[{"text":"Older residents are at greater risk of heat-related illness when they live alone without cooling equipment.","translationZh":"獨居且缺乏降溫設備的年長居民，罹患熱相關疾病的風險更高。","source":"self-authored","grammar":"at greater risk of illness 是表示風險的介系詞片語；when they live alone 引出高風險發生的條件。","writingTip":"討論高溫影響時，指出獨居與缺乏降溫設備等脆弱因素。","topic":"health"},{"text":"Without saving a backup copy, you risk losing all your work if the computer suddenly stops working.","translationZh":"若未存備份，電腦突然停止運作時，你就有失去所有成果的風險。","source":"self-authored","grammar":"risk + V-ing；if 條件子句","writingTip":"可用於科技使用建議。","topic":"technology"}],"usageNote":"risk 作動詞後接 V-ing，不接 to V；at risk of 指有遭遇不利結果的風險。"},"rough":{"senses":[{"pos":"adj.","meaning":"粗糙的；艱難的；大略的","usage":""}],"collocations":[{"en":"a rough surface","zh":"粗糙的表面","note":""},{"en":"a rough estimate","zh":"粗略估計","note":""},{"en":"a rough time","zh":"艱難的時期","note":""},{"en":"rough weather","zh":"惡劣天氣","note":""}],"synonyms":[{"en":"approximate","zh":"大約的","note":"對應估算義"},{"en":"tough","zh":"艱難的","note":"對應困境，不一定粗糙"}],"idioms":[],"family":[{"word":"roughly","pos":"adv.","meaning":"大約；粗暴地"},{"word":"roughness","pos":"n.","meaning":"粗糙；不平"}],"usageNote":"rough estimate 指尚不精確的估計；roughly 可表大約或粗暴地。","examples":[{"text":"We made a rough estimate of the cost before asking local shops for prices and preparing a more detailed budget.","translationZh":"我們先粗估成本，再向在地商店詢價，並準備更詳細的預算。","source":"self-authored","grammar":"a rough estimate of + 費用；before asking/preparing 表後續查核程序。","writingTip":"可區分初估成本與後續更詳盡的預算。","topic":"預算估算"},{"text":"During a rough time after moving to a new city, regular calls from old friends helped me feel less alone.","translationZh":"搬到新城市後的一段艱難時期，老朋友定期打來電話，讓我比較不孤單。","source":"self-authored","grammar":"after moving 表搬家後；helped + 人 + feel 表支持的效果。","writingTip":"描述舊朋友持續聯繫如何緩解陌生環境的孤單。","topic":"搬家適應"}]},"routine":{"senses":[{"pos":"n.","meaning":"固定流程；例行活動","usage":"可指每日安排或固定表演動作。"},{"pos":"adj.","meaning":"例行的；常規的","usage":"描述經常按固定方式進行的事。"}],"collocations":[{"en":"a daily routine","zh":"每日固定作息","note":""},{"en":"establish a routine","zh":"建立固定流程","note":""},{"en":"routine maintenance","zh":"例行保養","note":""},{"en":"break the routine","zh":"打破一成不變的生活","note":""}],"synonyms":[{"en":"habit","zh":"習慣","note":"常是一項慣常行為，routine 可包含多個活動。"},{"en":"regular procedure","zh":"例行程序","note":"較正式，常見於工作或制度。"}],"idioms":[],"family":[{"word":"routinely","pos":"adv.","meaning":"例行地；經常地"},{"word":"nonroutine","pos":"adj.","meaning":"非常規的"}],"examples":[{"text":"A simple morning routine helped me arrive at school on time without feeling rushed or forgetting important materials.","translationZh":"簡單的早晨流程，讓我能準時到校，不必匆忙，也不會忘記重要用品。","grammar":"without 後接並列動名詞，help someone arrive 用原形。","writingTip":"可寫生活規畫帶來的改善。","topic":"生活與時間","source":"self-authored"},{"text":"Routine maintenance may seem unimportant, but it prevents small problems from turning into costly equipment failures.","translationZh":"例行保養看似不重要，卻能避免小問題變成昂貴的設備故障。","grammar":"prevent something from V-ing，turn into 表轉變。","writingTip":"適合說明預防比事後補救更有效。","topic":"科技與安全","source":"self-authored"}],"usageNote":"routine 可作名詞或形容詞；routinely 才是修飾動詞的副詞。"},"satisfy":{"senses":[{"pos":"vt.","meaning":"使滿足；符合；使確信","usage":"可指滿足人或需求，也可指達到標準。"}],"collocations":[{"en":"satisfy customers","zh":"讓顧客滿意","note":""},{"en":"satisfy a need","zh":"滿足需求","note":""},{"en":"satisfy the requirements","zh":"符合要求","note":""},{"en":"be satisfied with the result","zh":"對結果滿意","note":""}],"synonyms":[{"en":"meet","zh":"滿足；符合","note":"meet needs 或 requirements 常見，不能處處替換。"},{"en":"please","zh":"使高興","note":"不一定達到要求或充分滿足。"}],"idioms":[],"family":[{"word":"satisfaction","pos":"n.","meaning":"滿足；滿意"},{"word":"satisfied","pos":"adj.","meaning":"感到滿意的"},{"word":"satisfying","pos":"adj.","meaning":"令人滿足的"},{"word":"satisfactory","pos":"adj.","meaning":"令人滿意的；符合要求的"}],"examples":[{"text":"The new bus service satisfied residents' need for affordable transportation between their homes and the nearest hospital.","translationZh":"新公車服務滿足了居民在住家與最近醫院間，使用平價交通的需求。","grammar":"satisfy a need for，between A and B。","writingTip":"可描述政策回應實際生活需求。","topic":"交通與高齡","source":"self-authored"},{"text":"I felt satisfied with my progress because I could finally explain an idea clearly without reading prepared notes.","translationZh":"我對自己的進步感到滿意，因為終於能不看預先準備的筆記，清楚說明想法。","grammar":"be satisfied with，without 後接動名詞。","writingTip":"適合寫以能力而非分數衡量成果。","topic":"學習與表達","source":"self-authored"}],"usageNote":"satisfied 形容人的感受，satisfying 形容帶來滿足的事物；satisfactory 指達到可接受標準。"},"sense":{"senses":[{"pos":"n.","meaning":"感官；感覺；理解","usage":""},{"pos":"v.","meaning":"察覺","usage":""}],"collocations":[{"en":"a sense of belonging","zh":"歸屬感","note":""},{"en":"make sense","zh":"有道理；容易理解","note":""},{"en":"common sense","zh":"常識","note":""},{"en":"sense a change in mood","zh":"察覺情緒變化","note":""}],"synonyms":[{"en":"feeling","zh":"感覺","note":"不一定理性判斷"},{"en":"perceive","zh":"察覺","note":"較正式，常指由感官或理解感知"}],"idioms":[{"en":"make sense","zh":"合乎道理","note":"make sense of + 內容表示理解內容"}],"family":[{"word":"sensory","pos":"adj.","meaning":"感官的"},{"word":"sensible","pos":"adj.","meaning":"明智的"},{"word":"senseless","pos":"adj.","meaning":"無意義的"}],"usageNote":"sensible（明智的）和 sensitive（敏感的）不同；make sense 不用 make a sense。","examples":[{"text":"Joining a small club gave me a sense of belonging because members noticed when I was absent and welcomed my ideas.","translationZh":"加入小社團讓我有歸屬感，因為成員會注意到我的缺席，也歡迎我的想法。","source":"self-authored","grammar":"a sense of belonging；because 解釋歸屬感形成的原因。","writingTip":"用成員注意與接納的行為支持歸屬感。","topic":"社團歸屬"},{"text":"At first, the chart made little sense to me, but its pattern became clearer after I compared the categories carefully.","translationZh":"起初我不太理解圖表，但仔細比較類別後，其規律變得更清楚。","source":"self-authored","grammar":"made little sense to + 人；after 比較完成後表理解的變化。","writingTip":"敘述仔細比較如何使複雜圖表變清楚。","topic":"圖表理解"}]},"sensitive":{"senses":[{"pos":"adj.","meaning":"敏感的","usage":"sensitive to + 刺激"},{"pos":"adj.","meaning":"體貼的","usage":"sensitive to + 他人需求"},{"pos":"adj.","meaning":"敏感須慎處的","usage":"資訊或議題"}],"collocations":[{"en":"sensitive to temperature changes","zh":"對溫度變化敏感","note":"to 為介系詞"},{"en":"sensitive personal information","zh":"敏感個人資訊","note":"隱私議題"},{"en":"sensitive to others' needs","zh":"能體察他人需求","note":"人際語境"},{"en":"a sensitive issue","zh":"敏感議題","note":"須謹慎處理"}],"synonyms":[{"en":"responsive","zh":"反應敏銳的","note":"對應對刺激或需求的反應"},{"en":"delicate","zh":"須慎重處理的","note":"對應議題，非所有 sensitive 語境"}],"idioms":[],"family":[{"word":"sensitivity","pos":"n.","meaning":"敏感性；體察能力"},{"word":"sensitively","pos":"adv.","meaning":"體貼地；謹慎地"},{"word":"insensitive","pos":"adj.","meaning":"不體貼的；不敏感的"}],"examples":[{"text":"Coral reefs are sensitive to temperature changes, which can threaten the survival of many marine species.","translationZh":"珊瑚礁對溫度變化很敏感，這些變化可能威脅許多海洋物種的生存。","source":"self-authored","grammar":"sensitive to；which 指前述變化","writingTip":"可描述生態對環境變動的反應。","topic":"wildlife"},{"text":"A good listener is sensitive to others' feelings and avoids giving advice before understanding the problem.","translationZh":"好的聆聽者能體察他人感受，在了解問題前避免急著給建議。","source":"self-authored","grammar":"sensitive to；avoid + V-ing","writingTip":"可用於人際互動作文。","topic":"relationships"}],"usageNote":"sensitive 指敏感或體貼；sensible 指明智，兩者容易混淆。"},"share":{"senses":[{"pos":"vt./vi.","meaning":"分享；共用；分擔","usage":"share something with someone 為常見句型。"},{"pos":"n.","meaning":"份額；股份","usage":"one's share 指應得或應負擔的部分。"}],"collocations":[{"en":"share ideas with others","zh":"與他人分享想法","note":""},{"en":"share responsibility","zh":"分擔責任","note":""},{"en":"a fair share","zh":"公平的份額","note":""},{"en":"share a room","zh":"共用房間","note":""}],"synonyms":[{"en":"divide","zh":"分配；分開","note":"強調切分，不必共同使用。"},{"en":"distribute","zh":"分發","note":"常指把物品給多個人，不必自己保留一份。"}],"idioms":[],"family":[{"word":"sharing","pos":"n.","meaning":"分享；共用"},{"word":"shareholder","pos":"n.","meaning":"股東"},{"word":"shared","pos":"adj.","meaning":"共同的；共用的"}],"examples":[{"text":"Sharing ideas with classmates helped us discover solutions that none of us could have developed alone.","translationZh":"與同學分享想法，讓我們找到任何一人都無法獨自想出的解方。","grammar":"Sharing 作主詞，could have V-en 表過去可能性。","writingTip":"可寫合作產生超越個人的成果。","topic":"合作與學習","source":"self-authored"},{"text":"Each family member should do a fair share of the housework rather than leave everything to one person.","translationZh":"每位家人都應公平分擔家務，而非把所有事都交給一個人。","grammar":"a fair share of，rather than 後接平行動詞。","writingTip":"適合討論家庭分工與公平。","topic":"家庭與責任","source":"self-authored"}],"usageNote":"share something with someone 的 with 表分享對象；a share in a company 指公司股份。"},"shelter":{"senses":[{"pos":"n.","meaning":"避難處；收容所","usage":""},{"pos":"v.","meaning":"保護；提供庇護","usage":""}],"collocations":[{"en":"an animal shelter","zh":"動物收容所","note":""},{"en":"seek shelter from the rain","zh":"找地方避雨","note":""},{"en":"provide shelter for homeless people","zh":"為無家者提供住所","note":""},{"en":"shelter someone from harm","zh":"保護某人免於傷害","note":""}],"synonyms":[{"en":"refuge","zh":"庇護處","note":"強調躲避危險"},{"en":"protect","zh":"保護","note":"protect 比 shelter 用途廣"}],"idioms":[],"family":[{"word":"sheltered","pos":"adj.","meaning":"受到庇護的；遮蔽的"},{"word":"sheltering","pos":"adj.","meaning":"提供庇護的"}],"usageNote":"shelter from + 危險或天候；shelter for + 受庇護者。","examples":[{"text":"When a sudden storm interrupted our hike, we sought shelter in a small visitor center near the mountain trail.","translationZh":"突如其來的暴風雨打斷健行時，我們到山徑附近的小遊客中心避難。","source":"self-authored","grammar":"when 引導突發事件；sought shelter in + 避難處。","writingTip":"可敘述戶外活動中的天候應變。","topic":"健行遇雨"},{"text":"Volunteers at the animal shelter teach potential owners how to care for rescued pets before they make a lasting commitment.","translationZh":"動物收容所的志工在潛在飼主作出長期承諾前，教導他們如何照顧獲救的寵物。","source":"self-authored","grammar":"at the animal shelter 表場所；how to care for 表照護方法。","writingTip":"把志工角色連結到長期認養責任的準備。","topic":"認養準備"}]},"shift":{"senses":[{"pos":"v.","meaning":"改變；移動","usage":""},{"pos":"n.","meaning":"轉變；輪班","usage":""}],"collocations":[{"en":"a shift in attitude","zh":"態度轉變","note":""},{"en":"shift attention to a problem","zh":"把注意力轉向問題","note":""},{"en":"work the night shift","zh":"上夜班","note":""},{"en":"shift from A to B","zh":"由甲轉向乙","note":""}],"synonyms":[{"en":"change","zh":"改變","note":"用途較廣"},{"en":"move","zh":"移動","note":"shift 常暗示位置或重心改變"}],"idioms":[],"family":[{"word":"shifting","pos":"adj.","meaning":"不斷變動的"},{"word":"shift worker","pos":"n.","meaning":"輪班工作者"}],"usageNote":"shift from A to B 必須讓 A 與 B 平行；a shift 指改變或工作班次，依語境辨認。","examples":[{"text":"The survey showed a shift in students' reading habits, with more respondents choosing short online articles instead of long printed books.","translationZh":"調查顯示學生閱讀習慣轉變，更多受訪者選短篇網路文章，而非長篇紙本書。","source":"self-authored","grammar":"a shift in + 習慣；with + 受訪者 + choosing 補充趨勢。","writingTip":"圖表作文可對照不同閱讀媒介的選擇。","topic":"閱讀趨勢"},{"text":"After working the night shift, my mother needed a quiet room, so we avoided noisy chores until she had rested.","translationZh":"母親上完夜班後需要安靜房間，因此我們等她休息過後才做吵雜的家事。","source":"self-authored","grammar":"after working 表上班後；until 引導做家事的時間界線。","writingTip":"以降低噪音的行動描寫對家人作息的體貼。","topic":"家庭輪班"}]},"shoulder":{"senses":[{"pos":"n.","meaning":"肩膀","usage":""},{"pos":"v.","meaning":"承擔責任或重擔","usage":""}],"collocations":[{"en":"shoulder responsibility","zh":"承擔責任","note":""},{"en":"shoulder the burden","zh":"承擔重擔","note":""},{"en":"a shoulder to cry on","zh":"可傾訴的支持者","note":""},{"en":"look over one's shoulder","zh":"回頭看","note":""}],"synonyms":[{"en":"take on","zh":"承擔","note":"可接責任任務"},{"en":"carry","zh":"負擔","note":"shoulder 強調承擔重擔的比喻義"}],"idioms":[{"en":"a shoulder to cry on","zh":"可以傾訴的對象","note":"不一定字面上靠著對方肩膀哭"}],"family":[{"word":"shoulder bag","pos":"n.","meaning":"肩背包"},{"word":"shoulder-length","pos":"adj.","meaning":"及肩的"}],"usageNote":"shoulder 作動詞時直接接 responsibility/burden；不需要額外加 take。","examples":[{"text":"Family members should share household tasks so that no one person has to shoulder the entire burden of daily care.","translationZh":"家庭成員應分擔家務，讓任何一人都不必承擔日常照護的全部重擔。","source":"self-authored","grammar":"so that 表分工目的；shoulder the entire burden 表承擔全部重擔。","writingTip":"可主張家務分擔，避免照護責任集中在一人。","topic":"家庭照護分工"},{"text":"When I felt overwhelmed by exam pressure, my best friend offered a shoulder to cry on and helped me regain perspective.","translationZh":"考試壓力讓我不堪負荷時，好友讓我傾訴，並幫我重新看清情況。","source":"self-authored","grammar":"when 引導壓力情境；a shoulder to cry on 指可以傾訴的人。","writingTip":"用傾訴與重新看清問題描寫友人的帮助。","topic":"考試情绪"}]},"significant":{"senses":[{"pos":"adj.","meaning":"重要的；值得注意的","usage":"影響或差異"},{"pos":"adj.","meaning":"具有統計顯著性的","usage":"須有研究檢驗依據"}],"collocations":[{"en":"a significant difference","zh":"顯著差異","note":"一般或統計語境"},{"en":"a significant increase","zh":"明顯增加","note":"趨勢描述"},{"en":"play a significant role","zh":"扮演重要角色","note":"role 搭配"},{"en":"statistically significant results","zh":"統計上顯著的結果","note":"專門研究用語"}],"synonyms":[{"en":"important","zh":"重要的","note":"對應價值或影響"},{"en":"notable","zh":"值得注意的","note":"強調明顯或引人注意"}],"idioms":[],"family":[{"word":"significance","pos":"n.","meaning":"重要性；顯著性"},{"word":"significantly","pos":"adv.","meaning":"明顯地；顯著地"},{"word":"insignificant","pos":"adj.","meaning":"不重要的；不顯著的"}],"examples":[{"text":"The new bus route made a significant difference to residents who previously walked long distances.","translationZh":"新公車路線讓原本得走很遠的居民，生活有了明顯改善。","source":"self-authored","grammar":"significant 作形容詞修飾 difference；make a difference to 人 表對某人造成改變；who 修飾 residents。","writingTip":"寫交通政策成果時，以原本需要長途步行的居民呈現實際改善。","topic":"transport"},{"text":"A significant increase in food waste prompted the school to review the size of its lunch portions.","translationZh":"廚餘明顯增加，促使學校檢討午餐份量。","source":"self-authored","grammar":"an increase in；prompt 人 to V","writingTip":"圖表作文可連結趨勢與措施。","topic":"sustainability"}],"usageNote":"一般 significant 可表示重要或明顯；統計顯著需有檢驗，不能只看差距大小。"},"skill":{"senses":[{"pos":"n.","meaning":"技能；技巧","usage":"具體技能可數，整體熟練度可不可數。"}],"collocations":[{"en":"develop a skill","zh":"培養技能","note":""},{"en":"communication skills","zh":"溝通技巧","note":""},{"en":"practical skills","zh":"實用技能","note":""},{"en":"show great skill in","zh":"在……展現高超技巧","note":""}],"synonyms":[{"en":"ability","zh":"能力","note":"可能天生或後天，不必特定技術。"},{"en":"expertise","zh":"專業知識與技能","note":"通常指較高程度的專業能力。"}],"idioms":[],"family":[{"word":"skilled","pos":"adj.","meaning":"熟練的"},{"word":"skillful","pos":"adj.","meaning":"技術高超的"},{"word":"skillfully","pos":"adv.","meaning":"熟練地"},{"word":"unskilled","pos":"adj.","meaning":"缺乏專門技能的"}],"examples":[{"text":"Learning basic repair skills can save money and help people keep useful objects out of the trash.","translationZh":"學習基本修繕技能，能省錢，也能讓人避免把仍有用的物品丟掉。","grammar":"Learning 作主詞，keep something out of 表避免進入。","writingTip":"可寫實用能力與減少浪費。","topic":"生活與永續","source":"self-authored"},{"text":"The group project tested our communication skills because we had to explain ideas and respond to conflicting opinions.","translationZh":"分組專題考驗我們的溝通技巧，因為我們必須說明想法，也回應不同意見。","grammar":"have to 後接並列原形動詞，because 表原因。","writingTip":"適合寫合作過程中的能力成長。","topic":"學習與合作","source":"self-authored"}],"usageNote":"skilled 常描述人，skillful 可描述人或表現技巧的動作；skills 常用複數列出不同能力。"},"solution":{"senses":[{"pos":"n.","meaning":"解決方法","usage":"solution to + 問題"},{"pos":"n.","meaning":"溶液","usage":"科學實驗語境"}],"collocations":[{"en":"a solution to the problem","zh":"問題的解決方法","note":"to 不是 of"},{"en":"find a practical solution","zh":"找到可行解方","note":"問題處理"},{"en":"a long-term solution","zh":"長期解方","note":"政策評估"},{"en":"a salt solution","zh":"鹽水溶液","note":"科學義"}],"synonyms":[{"en":"answer","zh":"解答；解決方式","note":"較一般且範圍廣"},{"en":"remedy","zh":"補救方法","note":"著重修正問題，不等同化學溶液"}],"idioms":[],"family":[{"word":"solve","pos":"vt.","meaning":"解決"},{"word":"soluble","pos":"adj.","meaning":"可溶的；可解決的"},{"word":"solubility","pos":"n.","meaning":"溶解度"}],"examples":[{"text":"A practical solution to traffic congestion should give people convenient alternatives to using private cars.","translationZh":"解決交通壅塞的可行方法，應提供方便的替代方式，讓人們不用開私家車。","source":"self-authored","grammar":"solution to；alternatives to + V-ing","writingTip":"可提出解方並說明必要條件。","topic":"transport"},{"text":"Students added a small amount of salt to water and stirred the solution carefully.","translationZh":"學生在水中加入少量鹽，並仔細攪拌溶液。","source":"self-authored","grammar":"added A to B 表將鹽加入水中；the solution 是 stirred 的受詞，在此為可數名詞，指形成的溶液。","writingTip":"實驗敘述可按加鹽、攪拌的順序描寫，也要辨識 solution 的化學義。","topic":"science"}],"usageNote":"solution to a problem 指解方；實驗中的 solution 可能指溶液。"},"sound":{"senses":[{"pos":"n.","meaning":"聲音","usage":""},{"pos":"v.","meaning":"聽起來","usage":""},{"pos":"adj.","meaning":"健全的；可靠的","usage":""}],"collocations":[{"en":"sound advice","zh":"可靠的建議","note":""},{"en":"make a sound","zh":"發出聲音","note":""},{"en":"sound like a good idea","zh":"聽起來是好主意","note":""},{"en":"a sound argument","zh":"有根據的論點","note":""}],"synonyms":[{"en":"noise","zh":"聲響","note":"通常指不悅或雜亂聲音"},{"en":"reasonable","zh":"合理的","note":"對應 sound judgment 的判斷義"}],"idioms":[],"family":[{"word":"soundly","pos":"adv.","meaning":"酣暢地；徹底地"},{"word":"soundness","pos":"n.","meaning":"健全；可靠"},{"word":"soundproof","pos":"adj.","meaning":"隔音的"}],"usageNote":"sound + 形容詞；sound like + 名詞。sound 作形容詞不只與聲音有關。","examples":[{"text":"The proposal sounded promising, but we needed sound evidence before spending the money we had collected from classmates and parents.","translationZh":"提案聽來有希望，但使用向同學和家長募得的錢前，我們需要可靠證據。","source":"self-authored","grammar":"sounded + 形容詞；sound evidence 中 sound 為「可靠的」。","writingTip":"區分聽起來有希望與真正有證據的方案。","topic":"方案評估"},{"text":"Although the advice was simple, it gave me a sound basis for planning my study schedule without sacrificing sleep or exercise.","translationZh":"雖然建議簡單，卻給我規畫讀書進度的可靠基礎，同時不犧牲睡眠和運動。","source":"self-authored","grammar":"although 表建議簡單仍有效；without + V-ing 表保留的活動。","writingTip":"用睡眠、運動兩項需求說明健康的讀書規畫。","topic":"讀書規畫"}]},"source":{"senses":[{"pos":"n.","meaning":"來源","usage":"source of + 資訊或資源"},{"pos":"vt.","meaning":"取得；採購","usage":"source materials from + 來源"}],"collocations":[{"en":"a reliable source of information","zh":"可靠資訊來源","note":"查證用語"},{"en":"renewable energy sources","zh":"再生能源來源","note":"環境主題"},{"en":"source ingredients locally","zh":"在當地採購食材","note":"動詞用法"},{"en":"the source of a problem","zh":"問題根源","note":"原因分析"}],"synonyms":[{"en":"origin","zh":"起源","note":"著重開始之處"},{"en":"provider","zh":"供應者","note":"適用提供資源的人或組織"}],"idioms":[],"family":[{"word":"sourcing","pos":"n.","meaning":"採購；尋找來源"},{"word":"sourced","pos":"adj.","meaning":"有來源的；採購的"}],"examples":[{"text":"The article cited several sources of information, allowing readers to check the evidence for themselves.","translationZh":"這篇文章引用了數個資訊來源，讓讀者能自行檢查證據。","source":"self-authored","grammar":"sources of information 是 cited 的受詞；allowing readers to check 為現在分詞片語，補充前述引用帶來的結果。","writingTip":"談查證習慣時，可說引用來源如何讓讀者自行核對證據。","topic":"media"},{"text":"The restaurant sources vegetables from nearby farms to support local growers and reduce transport distances.","translationZh":"餐廳向附近農場採購蔬菜，以支持當地農民並縮短運輸距離。","source":"self-authored","grammar":"sources 在此為及物動詞；source A from B 指從 B 採購 A；to support 與 reduce 共用表示目的的 to。","writingTip":"描述在地採購時，可並列支持農民與縮短運輸距離兩項目的。","topic":"food"}],"usageNote":"source 作動詞可指尋找供應來源並採購；名詞常用 source of。"},"spare":{"senses":[{"pos":"adj.","meaning":"備用的；多餘的","usage":""},{"pos":"v.","meaning":"騰出；免使遭受","usage":""}],"collocations":[{"en":"a spare key","zh":"備用鑰匙","note":""},{"en":"in one's spare time","zh":"在空閒時間","note":""},{"en":"spare a few minutes","zh":"撥出幾分鐘","note":""},{"en":"spare someone the trouble","zh":"免去某人的麻煩","note":""}],"synonyms":[{"en":"extra","zh":"額外的","note":"extra 不一定已預留作備用"},{"en":"save","zh":"省去","note":"save someone trouble 對應 spare 的免除義"}],"idioms":[],"family":[{"word":"spare part","pos":"n.","meaning":"備用零件"},{"word":"spare-time","pos":"adj.","meaning":"利用空暇的"},{"word":"sparingly","pos":"adv.","meaning":"節制地；少量地"}],"usageNote":"spare time 指空閒時間；can you spare...? 常為客氣請求時間或資源。","examples":[{"text":"In my spare time, I help younger students practice reading, which reminds me how much patient encouragement mattered when I was little.","translationZh":"空閒時我幫年幼學生練習閱讀，這提醒我兒時耐心的鼓勵有多重要。","source":"self-authored","grammar":"in my spare time 表空閒時；which 引導行為帶來的提醒。","writingTip":"把志工服務連結自己過去受鼓勵的經驗。","topic":"課外志工"},{"text":"Keeping a spare key with a trusted neighbor spared us the trouble of waiting outside when we accidentally locked ourselves out.","translationZh":"把備用鑰匙交給可信的鄰居，免去我們不慎被鎖在外時在門外等待的麻煩。","source":"self-authored","grammar":"keeping 動名詞作主詞；spared + 人 + 麻煩。","writingTip":"用具體意外說明預先準備備用鑰匙的好處。","topic":"備用準備"}]},"species":{"senses":[{"pos":"n.","meaning":"物種","usage":"單複數同形"}],"collocations":[{"en":"endangered species","zh":"瀕危物種","note":"保育用語"},{"en":"native species","zh":"原生物種","note":"生態主題"},{"en":"invasive species","zh":"入侵物種","note":"環境風險"},{"en":"a rare species of bird","zh":"一種罕見鳥類","note":"a species of"}],"synonyms":[{"en":"type","zh":"類型","note":"較一般，不能當正式分類學等值"},{"en":"kind","zh":"種類","note":"日常分類語境較接近"}],"idioms":[],"family":[],"examples":[{"text":"A single invasive species can disrupt an ecosystem by competing with native plants for sunlight and water.","translationZh":"單一入侵物種可能與原生植物爭奪陽光和水，擾亂生態系。","source":"self-authored","grammar":"A single invasive species 為單數主詞；can 後接原形動詞 disrupt；by competing 是 by + V-ing，說明干擾方式。","writingTip":"寫入侵物種影響時，說明它與原生植物競爭陽光和水的機制。","topic":"wildlife"},{"text":"Several endangered species depend on the wetland, so protecting this area is a matter of urgency.","translationZh":"數種瀕危物種依賴這片濕地，因此保護此地刻不容緩。","source":"self-authored","grammar":"Several endangered species 為複數主詞，搭配 depend；so 連接結果分句；protecting this area 為 V-ing 主詞。","writingTip":"保育倡議可先指出物種依賴濕地，再帶出保護的急迫性。","topic":"environment"}],"usageNote":"species 的單數和複數拼字相同；a species is，several species are。"},"spot":{"senses":[{"pos":"n.","meaning":"地點；斑點","usage":""},{"pos":"v.","meaning":"發現；認出","usage":""}],"collocations":[{"en":"spot a mistake","zh":"發現錯誤","note":""},{"en":"a quiet spot","zh":"安靜的地方","note":""},{"en":"on the spot","zh":"當場；立即","note":""},{"en":"a parking spot","zh":"停車位","note":""}],"synonyms":[{"en":"notice","zh":"注意到","note":"不一定經刻意尋找"},{"en":"location","zh":"地點","note":"較正式，不表斑點"}],"idioms":[],"family":[{"word":"spotless","pos":"adj.","meaning":"一塵不染的"},{"word":"spotted","pos":"adj.","meaning":"有斑點的"},{"word":"spotting","pos":"n.","meaning":"發現；點狀出血"}],"usageNote":"spot 動詞有 spotting/spotted 的雙寫；on the spot 可表當場，需看上下文。","examples":[{"text":"A classmate spotted a mistake in our chart before the presentation, giving us enough time to check the data and correct it.","translationZh":"同學在簡報前發現圖表錯誤，讓我們有足夠時間查核資料並修正。","source":"self-authored","grammar":"spotted + 錯誤；giving 補充發現及時的結果。","writingTip":"描述同儕查核如何讓團隊及時修正。","topic":"簡報查核"},{"text":"We found a quiet spot under a tree where we could discuss the project without disturbing other students in the library.","translationZh":"我們找到樹下的安靜地點，可以討論專題，也不會打擾圖書館內其他學生。","source":"self-authored","grammar":"where 引導地點的用途；without + V-ing 表避免打擾。","writingTip":"可說明選擇空間時兼顾合作與他人需求。","topic":"討論空間"}]},"stable":{"senses":[{"pos":"adj.","meaning":"穩定的","usage":"狀況不易變動"},{"pos":"n.","meaning":"馬廄","usage":"可數"}],"collocations":[{"en":"a stable income","zh":"穩定收入","note":"生活保障"},{"en":"stable temperatures","zh":"穩定氣溫","note":"科學與環境"},{"en":"remain stable","zh":"維持穩定","note":"remain + 形容詞"},{"en":"a horse stable","zh":"馬廄","note":"名詞熟詞偏義"}],"synonyms":[{"en":"steady","zh":"穩定的","note":"強調持續而不突然改變"},{"en":"secure","zh":"有保障的","note":"對應工作或收入，非所有物理穩定義"}],"idioms":[],"family":[{"word":"stability","pos":"n.","meaning":"穩定"},{"word":"stabilize","pos":"vt./vi.","meaning":"使穩定；變穩定"},{"word":"unstable","pos":"adj.","meaning":"不穩定的"}],"examples":[{"text":"A stable income allows families to plan for future expenses instead of worrying about daily survival.","translationZh":"穩定收入讓家庭能規劃未來支出，而不必擔心每天的生計。","source":"self-authored","grammar":"allow 人 to V；instead of + V-ing","writingTip":"可討論經濟保障的作用。","topic":"work"},{"text":"Water temperatures must remain stable because sudden changes can harm the fish kept in the aquarium.","translationZh":"水溫必須保持穩定，因為突然變化可能傷害水族箱裡的魚。","source":"self-authored","grammar":"remain + 形容詞；kept 修飾 fish","writingTip":"可用於照顧動物或科學閱讀。","topic":"wildlife"}],"usageNote":"stable 多作形容詞表示穩定；名詞 a stable 可指馬廄。"},"state":{"senses":[{"pos":"n.","meaning":"狀態；州；國家","usage":""},{"pos":"v.","meaning":"陳述","usage":""}],"collocations":[{"en":"state one's opinion clearly","zh":"清楚陳述意見","note":""},{"en":"a state of emergency","zh":"緊急狀態","note":""},{"en":"the current state of affairs","zh":"目前的事態","note":""},{"en":"a neighboring state","zh":"鄰近的州","note":""}],"synonyms":[{"en":"condition","zh":"狀態","note":"多指人事物狀況"},{"en":"declare","zh":"宣告","note":"比 state 更強烈或正式"}],"idioms":[],"family":[{"word":"statement","pos":"n.","meaning":"陳述；聲明"},{"word":"stated","pos":"adj.","meaning":"明訂的"},{"word":"stateless","pos":"adj.","meaning":"無國籍的"}],"usageNote":"state that + 子句或 state + 受詞；state 也可指美國的州，非 city。","examples":[{"text":"The notice clearly stated that visitors must remain on marked paths to protect fragile plants and avoid disturbing nesting birds.","translationZh":"公告清楚說明遊客必須留在標示道路上，以保護脆弱植物並避免干擾築巢鳥類。","source":"self-authored","grammar":"stated that + 子句；to protect/avoid 為平行目的不定詞。","writingTip":"用公告內容具體說明遊客應遵守的行為。","topic":"保育公告"},{"text":"After the earthquake, the government declared a state of emergency and asked residents to follow official updates about roads and shelter locations.","translationZh":"地震後，政府宣布進入緊急狀態，請居民留意道路和避難地點的官方更新。","source":"self-authored","grammar":"declared a state of emergency；asked + 人 + to follow。","writingTip":"描寫緊急狀態下應依循官方資訊的理由。","topic":"地震應變"}]},"stress":{"senses":[{"pos":"n.","meaning":"壓力；重音；強調","usage":"須依心理、發音或論述語境辨義。"},{"pos":"vt.","meaning":"強調；使受壓","usage":"常接重點或 that 子句。"}],"collocations":[{"en":"deal with stress","zh":"處理壓力","note":""},{"en":"under stress","zh":"承受壓力","note":""},{"en":"stress the importance of","zh":"強調……的重要性","note":""},{"en":"place stress on a syllable","zh":"把重音放在某音節","note":""}],"synonyms":[{"en":"strain","zh":"壓力；負擔","note":"常強調持續作用造成的負荷。"},{"en":"emphasize","zh":"強調","note":"只對應動詞的強調義。"}],"idioms":[],"family":[{"word":"stressful","pos":"adj.","meaning":"令人有壓力的"},{"word":"stressed","pos":"adj.","meaning":"感到壓力的"},{"word":"stress-free","pos":"adj.","meaning":"無壓力的"}],"examples":[{"text":"Taking short walks helped me deal with stress when exam preparation began to affect my sleep.","translationZh":"當準備考試開始影響睡眠時，短暫散步幫我處理壓力。","grammar":"deal with stress，when 引導具體情境。","writingTip":"可寫有助身心的紓壓方法。","topic":"升學與健康","source":"self-authored"},{"text":"The guide stressed the importance of staying on marked paths to protect fragile plants near the trail.","translationZh":"導覽員強調沿著標示步道行走的重要性，以保護步道附近脆弱的植物。","grammar":"stress the importance of V-ing，to V 表目的。","writingTip":"適合描述負責任的戶外活動。","topic":"生態與旅遊","source":"self-authored"}],"usageNote":"stress 作動詞在說明文常指強調；stressed 是感到壓力，stressful 是令人有壓力。"},"strike":{"senses":[{"pos":"v.","meaning":"擊打；突然想到；使深受觸動","usage":""},{"pos":"n.","meaning":"罷工","usage":""}],"collocations":[{"en":"strike a balance","zh":"取得平衡","note":""},{"en":"go on strike","zh":"發起罷工","note":""},{"en":"be struck by an idea","zh":"突然想到一個想法","note":""},{"en":"strike someone as unusual","zh":"使某人覺得不尋常","note":""}],"synonyms":[{"en":"hit","zh":"擊中","note":"範圍廣，非所有比喻可替代"},{"en":"impress","zh":"使印象深刻","note":"對應某些 struck by 語境"}],"idioms":[{"en":"strike a balance","zh":"取得平衡","note":"常接 between A and B"}],"family":[{"word":"striking","pos":"adj.","meaning":"顯著的；引人注目的"},{"word":"striker","pos":"n.","meaning":"罷工者；前鋒"}],"usageNote":"不規則變化 strike–struck–struck；striking 是引人注目的，不一定正在擊打。","examples":[{"text":"Students need to strike a balance between preparing for exams and maintaining habits that support their physical and mental health.","translationZh":"學生需要在準備考試與維持支持身心健康的習慣之間取得平衡。","source":"self-authored","grammar":"strike a balance between A and B；that support 修飾 habits。","writingTip":"議論時間分配時可兼顧考試和健康習慣。","topic":"身心與考試"},{"text":"I was struck by how calmly the volunteer handled the frightened dog, speaking softly and giving it enough space to relax.","translationZh":"我對志工安撫受驚狗隻的冷靜方式印象深刻；他輕聲說話，也給狗足夠空間放鬆。","source":"self-authored","grammar":"was struck by how + 子句；speaking/giving 補充志工的動作。","writingTip":"描述令人印象深刻的人物時，補上聲音與空間的細節。","topic":"動物照護觀察"}]},"struggle":{"senses":[{"pos":"vi.","meaning":"努力；掙扎","usage":"struggle to V 表努力但困難，with 表面臨問題。"},{"pos":"n.","meaning":"奮鬥；艱難過程","usage":"常用 a struggle to V 或 struggle for。"}],"collocations":[{"en":"struggle to concentrate","zh":"難以專心","note":""},{"en":"struggle with a problem","zh":"努力處理難題","note":""},{"en":"struggle for survival","zh":"為生存奮鬥","note":""},{"en":"a financial struggle","zh":"財務上的艱困處境","note":""}],"synonyms":[{"en":"strive","zh":"努力","note":"強調積極追求，不一定有明顯困難。"},{"en":"battle","zh":"奮戰","note":"語氣較強，可比喻對抗嚴重問題。"}],"idioms":[],"family":[{"word":"struggling","pos":"adj.","meaning":"苦苦支撐的"},{"word":"struggler","pos":"n.","meaning":"奮鬥者；掙扎中的人"}],"examples":[{"text":"I struggled to concentrate in the noisy library until I found a quieter corner away from the entrance.","translationZh":"在吵雜的圖書館裡，我難以專心，直到找到遠離入口的安靜角落。","grammar":"struggle to V，until 表困難持續的界線。","writingTip":"可寫找出環境問題並調整策略。","topic":"學習與環境","source":"self-authored"},{"text":"For families with low incomes, paying for transportation can become a daily struggle that limits access to better opportunities.","translationZh":"對低收入家庭而言，支付交通費可能成為每日難題，限制獲得更好機會的管道。","grammar":"For 指受影響對象，that 引導 struggle 的關係子句。","writingTip":"適合分析經濟負擔與社會機會。","topic":"交通與公平","source":"self-authored"}],"usageNote":"struggle to do 通常含做起來很吃力；struggle for 指努力爭取某目標。"},"subject":{"senses":[{"pos":"n.","meaning":"主題；學科；主詞","usage":""},{"pos":"adj.","meaning":"受制於的","usage":""},{"pos":"v.","meaning":"使經受","usage":""}],"collocations":[{"en":"a school subject","zh":"學校科目","note":""},{"en":"the subject of a discussion","zh":"討論主題","note":""},{"en":"be subject to change","zh":"可能變更","note":""},{"en":"subject someone to pressure","zh":"使某人承受壓力","note":""}],"synonyms":[{"en":"topic","zh":"主題","note":"對應討論內容"},{"en":"expose","zh":"使遭受","note":"expose A to B 可近似 subject A to B 的負面遭遇義"}],"idioms":[],"family":[{"word":"subjective","pos":"adj.","meaning":"主觀的"},{"word":"subjectivity","pos":"n.","meaning":"主觀性"},{"word":"subjection","pos":"n.","meaning":"被征服；受制"}],"usageNote":"be subject to + 名詞，表示可能受某條件影響；不是 be subjective to。","examples":[{"text":"The schedule is subject to change if heavy rain prevents the outdoor activities from taking place safely at the planned location.","translationZh":"若大雨使戶外活動無法在預定地點安全舉辦，行程可能變更。","source":"self-authored","grammar":"subject to + change；prevent + 活動 + from V-ing。","writingTip":"說明活動計畫必須依安全條件調整。","topic":"天候與行程"},{"text":"The article became the subject of a lively discussion because it challenged several assumptions students had made about keeping pets.","translationZh":"文章因挑戰學生對飼養寵物的幾項假設，成為熱烈討論的主題。","source":"self-authored","grammar":"the subject of + discussion；assumptions students had made 省略關係代名詞。","writingTip":"可描述文章如何挑戰讀者原有想法。","topic":"寵物議題閱讀"}]},"succeed":{"senses":[{"pos":"vi.","meaning":"成功","usage":"succeed in 後接名詞或動名詞。"},{"pos":"vt.","meaning":"接替；繼任","usage":"可直接接前任人物作受詞。"}],"collocations":[{"en":"succeed in solving a problem","zh":"成功解決問題","note":""},{"en":"succeed as a leader","zh":"成功勝任領導者","note":""},{"en":"succeed someone as chairperson","zh":"接替某人擔任主席","note":""},{"en":"succeed to the throne","zh":"繼承王位","note":"此義使用 to。"}],"synonyms":[{"en":"achieve one's aim","zh":"達成目標","note":"須改成不同句型，achieve 是及物動詞。"},{"en":"replace","zh":"取代","note":"只對應接替義，不一定正式繼任。"}],"idioms":[],"family":[{"word":"success","pos":"n.","meaning":"成功"},{"word":"successful","pos":"adj.","meaning":"成功的"},{"word":"successfully","pos":"adv.","meaning":"成功地"},{"word":"successor","pos":"n.","meaning":"繼任者"}],"examples":[{"text":"Our team succeeded in reducing food waste after we measured leftovers and adjusted the amount prepared each day.","translationZh":"我們測量剩食並調整每日備餐量後，成功減少了食物浪費。","grammar":"succeed in V-ing，prepared 為過去分詞修飾 amount。","writingTip":"可寫用數據改善具體問題。","topic":"飲食與永續","source":"self-authored"},{"text":"The new principal succeeded a longtime leader and promised to listen carefully before changing school policies.","translationZh":"新校長接替了長期任職的前任，承諾改變校務政策前先仔細聆聽。","grammar":"succeed someone 為接替義，before V-ing。","writingTip":"適合描述組織接班與領導方式。","topic":"校園與領導","source":"self-authored"}],"usageNote":"succeed in doing 不寫 succeed to do；successor 是繼任者，並非成功人士。"},"suit":{"senses":[{"pos":"n.","meaning":"西裝；一套衣服","usage":""},{"pos":"v.","meaning":"適合；符合需要","usage":""}],"collocations":[{"en":"wear a suit","zh":"穿西裝","note":""},{"en":"suit one's needs","zh":"符合某人的需求","note":""},{"en":"suit one's schedule","zh":"配合某人的時間","note":""},{"en":"follow suit","zh":"跟進；仿效","note":""}],"synonyms":[{"en":"fit","zh":"合身","note":"fit 常指尺寸，suit 常指風格或需要"},{"en":"match","zh":"相配","note":"強調搭配一致"}],"idioms":[{"en":"follow suit","zh":"仿效；跟進","note":"常指他人採同樣做法"}],"family":[{"word":"suitable","pos":"adj.","meaning":"合適的"},{"word":"suitability","pos":"n.","meaning":"合適性"},{"word":"unsuitable","pos":"adj.","meaning":"不合適的"}],"usageNote":"suit + 受詞；be suitable for + 名詞。follow suit 的 suit 不是衣服。","examples":[{"text":"No single study method suits everyone's needs, so students should test different approaches and adjust them according to their progress.","translationZh":"沒有一種讀書方法能符合每個人的需求，因此學生應測試不同方式並依進度調整。","source":"self-authored","grammar":"suits everyone's needs；according to + 名詞表調整依據。","writingTip":"以測試和進度回饋說明適合自己的方法。","topic":"個別讀書方法"},{"text":"After one class began bringing reusable containers, several others followed suit and helped reduce the amount of waste after lunch.","translationZh":"一班開始帶環保餐盒後，其他幾班跟進，協助減少午餐後的垃圾量。","source":"self-authored","grammar":"followed suit 表跟進；after 引導同儕仿效的時序。","writingTip":"可從一班的行動延伸到其他班的参與。","topic":"環保行為擴散"}]},"support":{"senses":[{"pos":"vt.","meaning":"支持；支撐；供養","usage":"可指情感、論證、物理或經濟上的支援。"},{"pos":"n.","meaning":"支持；支援","usage":"通常不可數。"}],"collocations":[{"en":"support an argument with evidence","zh":"以證據支持論點","note":""},{"en":"provide emotional support","zh":"提供情感支持","note":""},{"en":"support one's family","zh":"養家","note":""},{"en":"support a local business","zh":"支持在地商家","note":""}],"synonyms":[{"en":"back","zh":"支持","note":"較口語，可指支持人或計畫。"},{"en":"sustain","zh":"維持；支撐","note":"常強調使某事持續存在。"}],"idioms":[],"family":[{"word":"supportive","pos":"adj.","meaning":"給予支持的"},{"word":"supporter","pos":"n.","meaning":"支持者"},{"word":"supporting","pos":"adj.","meaning":"輔助的；支持性的"}],"examples":[{"text":"A friend who offers support listens without judging and helps us recognize options when a problem feels overwhelming.","translationZh":"支持我們的朋友會不帶批判地傾聽，並在問題令人不知所措時幫助我們看見選擇。","grammar":"who 引導關係子句，without V-ing，when 引導情緒情境。","writingTip":"可描述良好友誼的具體行為。","topic":"友誼與心理","source":"self-authored"},{"text":"Writers should support their arguments with reliable evidence rather than expect readers to accept personal opinions as facts.","translationZh":"作者應以可靠證據支持論點，而不是期待讀者把個人意見當作事實接受。","grammar":"support A with B，expect someone to V。","writingTip":"適合說明議論寫作與資訊判斷。","topic":"寫作與思辨","source":"self-authored"}],"usageNote":"support 作動詞不加 for：support a plan；名詞可寫 support for a plan。"},"survive":{"senses":[{"pos":"vi.","meaning":"存活；撐過","usage":"survive on 表靠有限資源維生。"},{"pos":"vt.","meaning":"挺過；比……活得久","usage":"可直接接災難或被超過壽命的人。"}],"collocations":[{"en":"survive an earthquake","zh":"挺過地震","note":""},{"en":"survive on limited income","zh":"靠有限收入維生","note":""},{"en":"survive in harsh conditions","zh":"在惡劣環境中存活","note":""},{"en":"survive a difficult period","zh":"撐過艱難時期","note":""}],"synonyms":[{"en":"endure","zh":"忍受；持續","note":"不必涉及生死或能否存續。"},{"en":"outlive","zh":"比……活得久","note":"只對應壽命較長的意思。"}],"idioms":[],"family":[{"word":"survival","pos":"n.","meaning":"存活"},{"word":"survivor","pos":"n.","meaning":"倖存者"},{"word":"surviving","pos":"adj.","meaning":"倖存的；仍存的"}],"examples":[{"text":"Some plants survive in dry environments by storing water and reducing the amount lost through their leaves.","translationZh":"有些植物透過儲水並減少葉片水分流失，在乾燥環境中存活。","grammar":"by 後接並列動名詞，lost 為分詞修飾 amount。","writingTip":"可敘述生物適應環境的機制。","topic":"生態與適應","source":"self-authored"},{"text":"Small shops may struggle to survive when rising rents force owners to increase prices beyond what customers can afford.","translationZh":"租金上漲迫使店主把價格提高到顧客負擔不起時，小店可能難以生存。","grammar":"force someone to V，what 引導名詞子句。","writingTip":"適合分析地方商家面對的壓力。","topic":"經濟與社區","source":"self-authored"}],"usageNote":"survive a disaster 是及物用法，不必加 from；survive on 少量資源指靠其維生。"},"sustainable":{"senses":[{"pos":"adj.","meaning":"可長期持續的","usage":"不耗盡資源或造成不可承受的負擔"}],"collocations":[{"en":"sustainable development","zh":"永續發展","note":"環境與經濟"},{"en":"sustainable agriculture","zh":"永續農業","note":"耕作方式"},{"en":"a sustainable lifestyle","zh":"永續的生活方式","note":"日常選擇"},{"en":"financially sustainable","zh":"財務上可持續的","note":"成本與收入"}],"synonyms":[{"en":"viable in the long term","zh":"長期可行的","note":"強調能持續維持"},{"en":"resource-conscious","zh":"重視資源的","note":"較偏環境行為，未必完全等義"}],"idioms":[],"family":[{"word":"sustain","pos":"vt.","meaning":"維持；支持"},{"word":"sustainability","pos":"n.","meaning":"永續性"},{"word":"sustainably","pos":"adv.","meaning":"以可持續方式"}],"examples":[{"text":"A sustainable lifestyle includes buying only what we need and using products for as long as possible.","translationZh":"永續的生活方式包括只買所需，並盡可能延長物品的使用時間。","source":"self-authored","grammar":"includes 後接 buying 與 using 兩個 V-ing 片語；what we need 是 buying 的名詞子句受詞。","writingTip":"描述永續生活時，可將購買需求與延長使用年限並列成實際做法。","topic":"sustainability"},{"text":"The project must be financially sustainable if the community wants to keep it running for many years.","translationZh":"若社區想讓計畫運作多年，它就必須在財務上能長期維持。","source":"self-authored","grammar":"if 條件子句；keep + 受詞 + V-ing","writingTip":"可討論公共計畫的持續條件。","topic":"community"}],"usageNote":"sustainable 不只用於環保，也可指財務、制度或計畫能長期維持。"},"sympathy":{"senses":[{"pos":"n.","meaning":"同情；慰問；認同","usage":"對人或處境常用 for，with 可表支持某種看法。"}],"collocations":[{"en":"feel sympathy for someone","zh":"同情某人","note":""},{"en":"express sympathy","zh":"表達同情或慰問","note":""},{"en":"extend one's sympathy to","zh":"向……表達慰問","note":""},{"en":"be in sympathy with an idea","zh":"認同某個想法","note":""}],"synonyms":[{"en":"compassion","zh":"憐憫；關懷","note":"常包含希望減輕他人痛苦的心意。"},{"en":"empathy","zh":"同理心","note":"著重理解或感受他人處境，與 sympathy 不完全相同。"}],"idioms":[],"family":[{"word":"sympathetic","pos":"adj.","meaning":"同情的；贊同的"},{"word":"sympathetically","pos":"adv.","meaning":"同情地"},{"word":"sympathize","pos":"vi.","meaning":"同情；認同"}],"examples":[{"text":"After hearing the family's story, students expressed sympathy and organized a sale to help cover medical expenses.","translationZh":"聽過這家人的故事後，學生表達同情，並舉辦義賣協助支付醫療費。","grammar":"help cover 使用原形，to help 表活動目的。","writingTip":"可寫把同情轉為實際協助。","topic":"關懷與行動","source":"self-authored"},{"text":"Feeling sympathy for someone is valuable, but asking what support they actually need can make our help more effective.","translationZh":"同情他人很有價值，但詢問對方真正需要什麼支持，能讓幫助更有效。","grammar":"what 引導名詞子句，make 受詞 adjective。","writingTip":"適合討論同理、尊重與有效服務。","topic":"服務與同理","source":"self-authored"}],"usageNote":"sympathy 可指同情或認同；sympathy for a person 與 in sympathy with a policy 需依語境分辨。"},"target":{"senses":[{"pos":"n.","meaning":"目標；對象","usage":""},{"pos":"v.","meaning":"以……為目標","usage":""}],"collocations":[{"en":"set a target","zh":"設定目標","note":""},{"en":"reach a target","zh":"達成目標","note":""},{"en":"target a specific audience","zh":"鎖定特定受眾","note":""},{"en":"be on target","zh":"符合預期進度","note":""}],"synonyms":[{"en":"goal","zh":"目標","note":"target 常具具體數字或特定對象"},{"en":"aim at","zh":"針對","note":"可表示面向某群體"}],"idioms":[],"family":[{"word":"targeted","pos":"adj.","meaning":"有針對性的"},{"word":"targeting","pos":"n.","meaning":"鎖定目標"}],"usageNote":"target 作動詞直接接受詞；be targeted at + 對象。清楚區分目標數值與目標人群。","examples":[{"text":"Our class set a realistic target for collecting used books, then checked progress each week and adjusted the plan when necessary.","translationZh":"我們班設定實際的舊書募集目標，每週檢視進度，必要時調整計畫。","source":"self-authored","grammar":"set a realistic target；when necessary 為省略式條件說明。","writingTip":"設定目標後補上固定檢查與調整的步骤。","topic":"舊書募集"},{"text":"The campaign targeted young commuters by explaining how riding a bicycle could save money and reduce emissions on short daily trips.","translationZh":"活動針對年輕通勤族，說明在日常短程出行時騎自行車如何省錢並減少排放。","source":"self-authored","grammar":"targeted + 對象；by explaining 表接觸受眾的方法。","writingTip":"宣導作文可依目標群體的實際需求說明好處。","topic":"自行車宣導"}]},"technology":{"senses":[{"pos":"n.","meaning":"科技","usage":"通常不可數"},{"pos":"n.","meaning":"技術","usage":"複數 technologies 指不同技術"}],"collocations":[{"en":"digital technology","zh":"數位科技","note":"教育與工作"},{"en":"assistive technology","zh":"輔助科技","note":"身心障礙支援"},{"en":"advances in technology","zh":"科技進展","note":"in 指領域"},{"en":"adopt new technologies","zh":"採用新技術","note":"複數指多種技術"}],"synonyms":[{"en":"technical innovation","zh":"技術創新","note":"指技術上的新改進"},{"en":"tools","zh":"工具","note":"僅在應用語境近義，不等同科技整體"}],"idioms":[],"family":[{"word":"technological","pos":"adj.","meaning":"科技的"},{"word":"technologically","pos":"adv.","meaning":"在科技方面"}],"examples":[{"text":"Assistive technology can help students with disabilities participate more fully in classroom activities.","translationZh":"輔助科技能幫助身心障礙學生更充分參與課堂活動。","source":"self-authored","grammar":"help 人 + 原形動詞；participate in","writingTip":"可連結科技與教育平等。","topic":"inclusion"},{"text":"Technology makes communication faster, but meaningful relationships still require attention, patience, and genuine interest.","translationZh":"科技讓溝通更快，但有意義的關係仍需要關注、耐心與真誠的興趣。","source":"self-authored","grammar":"makes communication faster 使用 make + 受詞 + 形容詞比較級；but 連接對照分句；require 後接三個並列名詞。","writingTip":"人際作文可先肯定溝通速度，再強調關注、耐心與真誠的重要性。","topic":"relationships"}],"usageNote":"technology 指科技整體時通常不可數；technologies 可指不同種類的技術。"},"tend":{"senses":[{"pos":"vi.","meaning":"往往會；傾向於","usage":"tend to V 表一般趨勢。"},{"pos":"vt./vi.","meaning":"照料","usage":"tend a garden 或 tend to a patient。"}],"collocations":[{"en":"tend to forget","zh":"往往會忘記","note":""},{"en":"tend a garden","zh":"照料花園","note":""},{"en":"tend to a patient","zh":"照護病人","note":""},{"en":"tend toward optimism","zh":"傾向樂觀","note":""}],"synonyms":[{"en":"be inclined to","zh":"傾向於","note":"常可替換 tend to V，語氣較正式。"},{"en":"care for","zh":"照顧","note":"只對應照料義，不表示一般趨勢。"}],"idioms":[],"family":[{"word":"tendency","pos":"n.","meaning":"傾向"}],"examples":[{"text":"People tend to remember dramatic stories more easily than ordinary facts, even when the stories are misleading.","translationZh":"人們往往比記住平凡事實更容易記住戲劇化故事，即使那些故事會誤導人。","grammar":"tend to V 表常見傾向，more easily than 為比較。","writingTip":"可分析聳動資訊如何吸引注意。","topic":"媒體與心理","source":"self-authored"},{"text":"During the summer, volunteers tended the community garden and shared the vegetables with families living nearby.","translationZh":"暑假期間，志工照料社區菜園，並與住在附近的家庭分享蔬菜。","grammar":"tend 直接接 garden，living 為分詞修飾 families。","writingTip":"適合寫共享種植與社區合作。","topic":"飲食與社區","source":"self-authored"}],"usageNote":"tend to do 的 to 引出不定詞；tend to a patient 的 to 是介系詞，意義是照料。"},"tight":{"senses":[{"pos":"adj.","meaning":"緊的；牢固的","usage":""},{"pos":"adj.","meaning":"時間或金錢有限而吃緊的","usage":""},{"pos":"adj.","meaning":"嚴格的","usage":""}],"collocations":[{"en":"a tight schedule","zh":"緊湊的行程","note":""},{"en":"a tight budget","zh":"吃緊的預算","note":""},{"en":"tight security","zh":"嚴密的保安","note":""},{"en":"a tight grip","zh":"緊握","note":""}],"synonyms":[{"en":"packed","zh":"排滿的","note":"packed schedule 指行程塞滿"},{"en":"strict","zh":"嚴格的","note":"strict rules 說明規定，不表示尺寸緊"}],"idioms":[],"family":[{"word":"tighten","pos":"v.","meaning":"使變緊；加強"},{"word":"tightly","pos":"adv.","meaning":"緊緊地"},{"word":"tightness","pos":"n.","meaning":"緊繃程度"}],"usageNote":"tight schedule 強調可用時間很少；tight clothes 才是衣服過緊。","examples":[{"text":"With a tight schedule before the school festival, our team divided the work and checked its progress every afternoon.","translationZh":"校慶前行程緊湊，我們小組分工，並在每天下午檢查進度。","source":"self-authored","grammar":"with a tight schedule 交代時間限制；divided/checked 為兩個並列動作。","writingTip":"寫時間管理時，可把分工當作面對行程緊湊的措施。","topic":"校慶準備"},{"text":"Although our budget was tight, we found an affordable way to provide lunch for every volunteer at the shelter.","translationZh":"雖然預算吃緊，我們仍找到負擔得起的方法，為收容所的每位志工提供午餐。","source":"self-authored","grammar":"although 引導讓步；to provide 表示方案的目的。","writingTip":"先交代預算限制，再說明如何提供具體服務。","topic":"收容所預算"}]},"tolerate":{"senses":[{"pos":"vt.","meaning":"容忍；耐受","usage":"直接接事物或動名詞，也用於生物對環境的耐受度。"}],"collocations":[{"en":"tolerate different opinions","zh":"容忍不同意見","note":""},{"en":"tolerate high temperatures","zh":"耐受高溫","note":""},{"en":"refuse to tolerate bullying","zh":"拒絕容忍霸凌","note":""},{"en":"tolerate being criticized","zh":"能忍受被批評","note":""}],"synonyms":[{"en":"put up with","zh":"忍受","note":"較口語，常含不情願。"},{"en":"accept","zh":"接受","note":"可能是同意或接納，比單純容忍更積極。"}],"idioms":[],"family":[{"word":"tolerance","pos":"n.","meaning":"容忍；耐受度"},{"word":"tolerant","pos":"adj.","meaning":"寬容的；耐受的"},{"word":"intolerant","pos":"adj.","meaning":"不寬容的；不耐受的"}],"examples":[{"text":"A respectful classroom allows disagreement, but it should never tolerate bullying or personal attacks against other students.","translationZh":"尊重彼此的教室允許意見不同，但絕不應容忍霸凌或針對其他學生的人身攻擊。","grammar":"allow disagreement 與 tolerate bullying 對照不同界線。","writingTip":"可寫包容不等於接受傷害。","topic":"校園與尊重","source":"self-authored"},{"text":"Researchers are studying crops that can tolerate higher temperatures while still producing enough food for a growing population.","translationZh":"研究人員正研究能耐受較高溫度、又能為增加的人口生產足夠食物的作物。","grammar":"that 引導 crops 的關係子句，while V-ing 表同時。","writingTip":"適合描述氣候調適與糧食需求。","topic":"氣候與農業","source":"self-authored"}],"usageNote":"tolerate 後接動名詞，不接 to V；耐受高溫與容忍別人是不同語境下的延伸義。"},"track":{"senses":[{"pos":"n.","meaning":"軌道；跑道；蹤跡","usage":""},{"pos":"v.","meaning":"追蹤","usage":""}],"collocations":[{"en":"keep track of spending","zh":"掌握花費","note":""},{"en":"track changes over time","zh":"追蹤隨時間的變化","note":""},{"en":"a running track","zh":"跑道","note":""},{"en":"be on the right track","zh":"方向正確","note":""}],"synonyms":[{"en":"monitor","zh":"監測","note":"強調持續觀察，track 也可追尋位置"},{"en":"follow","zh":"追蹤","note":"可指跟隨人或脈絡"}],"idioms":[{"en":"on the right track","zh":"朝正確方向前進","note":"可描述計畫進度或思考方向"}],"family":[{"word":"tracking","pos":"n.","meaning":"追蹤"},{"word":"tracker","pos":"n.","meaning":"追蹤器；追蹤者"},{"word":"trackable","pos":"adj.","meaning":"可追蹤的"}],"usageNote":"keep track of + 名詞；lose track of 表忘記或無法繼續掌握。","examples":[{"text":"Keeping track of my screen time helped me notice that short breaks often turned into long periods of scrolling through videos.","translationZh":"掌握螢幕使用時間，讓我注意到短暫休息常變成長時間滑影片。","source":"self-authored","grammar":"keeping track of + 名詞作主詞；that 引導觀察的內容。","writingTip":"可描寫紀錄習惯如何暴露時間流失。","topic":"螢幕時間"},{"text":"Scientists tracked changes in the river for several months to learn whether the new factory affected water quality downstream.","translationZh":"科學家連續數月追蹤河流變化，了解新工廠是否影響下游水質。","source":"self-authored","grammar":"tracked changes in + 地點；whether 引導監測問題。","writingTip":"用持續追蹤而非單次觀察支持環境評估。","topic":"水質監測"}]},"transform":{"senses":[{"pos":"vt./vi.","meaning":"大幅轉變","usage":"transform A into B"}],"collocations":[{"en":"transform an empty lot into a garden","zh":"把空地變成花園","note":"into 指結果"},{"en":"transform daily life","zh":"改變日常生活","note":"重大影響"},{"en":"undergo a transformation","zh":"經歷轉變","note":"名詞搭配"},{"en":"transform the way people work","zh":"改變人們工作的方式","note":"way 後接子句"}],"synonyms":[{"en":"convert","zh":"轉換","note":"常指用途或形式的具體改變"},{"en":"reshape","zh":"重塑","note":"強調結構或方式改變"}],"idioms":[],"family":[{"word":"transformation","pos":"n.","meaning":"轉變"},{"word":"transformative","pos":"adj.","meaning":"帶來重大轉變的"},{"word":"transformer","pos":"n.","meaning":"變壓器"}],"examples":[{"text":"Local residents transformed an empty lot into a garden where children could learn about plants.","translationZh":"當地居民把一塊空地變成花園，讓孩子能在那裡認識植物。","source":"self-authored","grammar":"transform A into B；where 引導關係子句","writingTip":"可寫社區共同改善空間。","topic":"community"},{"text":"Working with younger students transformed the way I understood patience and responsibility as a volunteer.","translationZh":"與年幼學生合作，改變了我身為志工對耐心與責任的理解。","source":"self-authored","grammar":"Working with younger students 為 V-ing 主詞；the way I understood... 是 transformed 的受詞，子句說明哪種理解方式改變。","writingTip":"志工經驗作文可把參與活動連結到自己對耐心與責任的新理解。","topic":"personal experience"}],"usageNote":"transform 通常暗示明顯或根本的變化，比一般 change 語氣強。"},"treat":{"senses":[{"pos":"v.","meaning":"對待；治療；請客","usage":""},{"pos":"n.","meaning":"令人愉快的事物","usage":""}],"collocations":[{"en":"treat someone with respect","zh":"尊重地對待某人","note":""},{"en":"treat an illness","zh":"治療疾病","note":""},{"en":"treat someone to lunch","zh":"請某人吃午餐","note":""},{"en":"a special treat","zh":"特別享受","note":""}],"synonyms":[{"en":"handle","zh":"對待；處理","note":"handle a situation 不等於治病"},{"en":"cure","zh":"治癒","note":"treat 不保證治癒"}],"idioms":[],"family":[{"word":"treatment","pos":"n.","meaning":"治療；待遇"},{"word":"treatable","pos":"adj.","meaning":"可治療的"},{"word":"untreated","pos":"adj.","meaning":"未治療的"}],"usageNote":"treat A with + 態度；treat A to + 食物活動。treat illness 與 cure illness 不等同。","examples":[{"text":"We should treat service workers with respect, even when a delay or mistake makes us frustrated with the situation.","translationZh":"即使延誤或錯誤讓我們對情況感到挫折，也應尊重地對待服務人員。","source":"self-authored","grammar":"treat + 人 + with + 尊重；even when 表讓步情境。","writingTip":"說明尊重不應只在事情順利時才成立。","topic":"服務人員尊重"},{"text":"To celebrate the completion of our project, our teacher treated the team to lunch and thanked us for helping one another.","translationZh":"為慶祝專題完成，老師請小組吃午餐，並感謝我們彼此協助。","source":"self-authored","grammar":"treated + 人 + to + 午餐；thanked + 人 + for V-ing。","writingTip":"以請客與感謝呈現對团隊互助的肯定。","topic":"專題慶祝"}]},"trust":{"senses":[{"pos":"n.","meaning":"信任；信託","usage":"一般信任不可數，法律上的信託可數。"},{"pos":"vt.","meaning":"信任；相信","usage":"可接人或 that 子句。"}],"collocations":[{"en":"earn someone's trust","zh":"贏得某人的信任","note":""},{"en":"trust someone with a secret","zh":"放心把秘密告訴某人","note":""},{"en":"trust someone to do the right thing","zh":"相信某人會做正確的事","note":""},{"en":"a charitable trust","zh":"慈善信託","note":"法律與財務用法。"}],"synonyms":[{"en":"rely on","zh":"依靠","note":"重點在需要對方支持，不必完全相信其判斷。"},{"en":"believe","zh":"相信","note":"可指相信陳述為真，trust 更常涉及可靠性。"}],"idioms":[],"family":[{"word":"trustworthy","pos":"adj.","meaning":"值得信任的"},{"word":"trusting","pos":"adj.","meaning":"容易相信人的"},{"word":"distrust","pos":"n./vt.","meaning":"不信任"},{"word":"trusted","pos":"adj.","meaning":"受信任的"}],"examples":[{"text":"Trust develops slowly when people keep their promises and admit mistakes instead of hiding them.","translationZh":"當人們遵守承諾並承認錯誤，而不是隱瞞時，信任才會慢慢建立。","grammar":"instead of V-ing，when 表建立信任的情境。","writingTip":"可寫人際信任如何由行動累積。","topic":"人際與誠信","source":"self-authored"},{"text":"Before trusting advice online, readers should check who created it and whether the author has relevant expertise.","translationZh":"相信網路建議前，讀者應確認由誰提供，以及作者是否具備相關專業。","grammar":"before V-ing，who 與 whether 引導並列名詞子句。","writingTip":"適合寫判斷資訊可信度的方法。","topic":"網路與資訊","source":"self-authored"}],"usageNote":"trust someone 是相信其可靠；believe someone 常是相信其話語，兩者有重疊但重點不同。"},"turn":{"senses":[{"pos":"v.","meaning":"轉動；轉變","usage":""},{"pos":"n.","meaning":"輪次；轉彎","usage":""}],"collocations":[{"en":"take turns doing something","zh":"輪流做某事","note":""},{"en":"turn to someone for help","zh":"向某人求助","note":""},{"en":"turn down an offer","zh":"拒絕提議","note":""},{"en":"turn out to be useful","zh":"結果證明有用","note":""}],"synonyms":[{"en":"rotate","zh":"轉動","note":"限旋轉或輪替義"},{"en":"become","zh":"變成","note":"對應 turn + 形容詞，不涵蓋片語義"}],"idioms":[{"en":"turn over a new leaf","zh":"改過自新","note":"強調改善舊習慣或行為"}],"family":[{"word":"turning point","pos":"n.","meaning":"轉折點"},{"word":"turnover","pos":"n.","meaning":"營業額；人員流動"},{"word":"turnout","pos":"n.","meaning":"出席人數"}],"usageNote":"turn out to be + 名詞／形容詞表結果；turn to + 人表求助，turn down + 提議表拒絕。","examples":[{"text":"When I could not understand the instructions, I turned to a classmate for help instead of pretending that everything was clear.","translationZh":"不懂說明時，我向同學求助，而不是假裝一切都清楚。","source":"self-authored","grammar":"turned to + 人 + for help；instead of + V-ing。","writingTip":"用主動求助取代假裝理解，表達學習態度。","topic":"課堂求助"},{"text":"We took turns caring for the injured bird until a wildlife specialist arrived and explained how to transport it safely.","translationZh":"野生動物專家抵達並說明如何安全運送前，我們輪流照顧受傷的鳥。","source":"self-authored","grammar":"took turns + V-ing；until 引導專家抵達的時間。","writingTip":"具體敘述輪流照護與等待專业協助的過程。","topic":"受傷鳥照護"}]},"valid":{"senses":[{"pos":"adj.","meaning":"有效的；仍可使用的","usage":"如期限內的票券或證件。"},{"pos":"adj.","meaning":"有根據的；合乎邏輯的","usage":"形容理由、批評或論證，須看使用標準。"}],"collocations":[{"en":"a valid ticket","zh":"有效票券","note":""},{"en":"a valid reason for concern","zh":"值得擔憂的充分理由","note":""},{"en":"remain valid for one year","zh":"一年內持續有效","note":""},{"en":"a valid argument","zh":"有效或有根據的論證","note":"邏輯效力與前提是否真實仍需區分。"}],"synonyms":[{"en":"legitimate","zh":"正當的；合法的","note":"著重正當性，未必指票券效期或邏輯效力。"},{"en":"well-founded","zh":"有根據的","note":"對應理由或擔憂有依據，不用於票券效期。"}],"idioms":[],"family":[{"word":"validity","pos":"n.","meaning":"有效性；效度"},{"word":"validate","pos":"vt.","meaning":"確認有效；驗證"},{"word":"invalid","pos":"adj.","meaning":"無效的；不成立的"}],"usageNote":"valid for + 有效期間；valid until + 截止點。邏輯上 valid 指結論由前提推出，並不保證前提為真。","examples":[{"text":"The ticket remains valid for thirty days, but passengers must reserve a seat before boarding the train on busy weekends.","translationZh":"票券三十天內有效，但忙碌週末搭車前，乘客必須先訂位。","grammar":"valid for + 期間；must reserve 表另外需要滿足的條件。","writingTip":"說明服務規則時，區分基本效期與使用限制。","topic":"交通規則","source":"self-authored"},{"text":"Her concern about safety was valid, so the group changed the route instead of dismissing her as overly cautious.","translationZh":"她對安全的擔憂有根據，因此團隊改變路線，而沒有認為她過度小心就不予理會。","grammar":"valid 形容 concern 有根據；dismiss A as B 表以某標籤忽視。","writingTip":"團體經驗可描寫對合理疑慮作出具體回應。","topic":"風險與溝通","source":"self-authored"}]},"value":{"senses":[{"pos":"n.","meaning":"價值；價額","usage":""},{"pos":"v.","meaning":"珍視；估價","usage":""}],"collocations":[{"en":"value someone's opinion","zh":"重視某人的意見","note":""},{"en":"the value of education","zh":"教育的價值","note":""},{"en":"good value for money","zh":"物有所值","note":""},{"en":"shared values","zh":"共同價值觀","note":""}],"synonyms":[{"en":"cherish","zh":"珍惜","note":"強調情感珍重"},{"en":"worth","zh":"價值","note":"worth 常作形容詞或名詞，句型不同"}],"idioms":[],"family":[{"word":"valuable","pos":"adj.","meaning":"有價值的"},{"word":"valuation","pos":"n.","meaning":"估價"},{"word":"invaluable","pos":"adj.","meaning":"極珍貴的"}],"usageNote":"values 複數常指價值觀；invaluable 不是沒有價值，而是非常有價值。","examples":[{"text":"I learned to value my classmates' different opinions because they often revealed possibilities I would not have considered on my own.","translationZh":"我學會重視同學不同的意見，因為那些意見常揭示我獨自不會考慮的可能性。","source":"self-authored","grammar":"value + 他人意見；would not have considered 表假設中未做的事。","writingTip":"說明不同意見如何揭示自己忽略的可能性。","topic":"多元觀點"},{"text":"The cheapest product is not always good value for money if it breaks quickly and needs to be replaced several times.","translationZh":"若產品很快壞掉而需多次更換，最便宜的產品不一定物有所值。","source":"self-authored","grammar":"not always 表並非總是；needs to be replaced 為被動不定詞。","writingTip":"可反思低價不一定代表長期物有所值。","topic":"長期消費成本"}]},"vary":{"senses":[{"pos":"vi.","meaning":"不同；有所差異","usage":"vary from person to person"},{"pos":"vi.","meaning":"變動","usage":"vary with + 條件"},{"pos":"vt.","meaning":"改變；使多樣化","usage":"vary a routine"}],"collocations":[{"en":"vary from person to person","zh":"因人而異","note":"from...to..."},{"en":"vary in size","zh":"大小不同","note":"in 指差異項目"},{"en":"vary with the season","zh":"隨季節變動","note":"with 指條件"},{"en":"vary one's routine","zh":"改變日常作息","note":"及物用法"}],"synonyms":[{"en":"differ","zh":"不同","note":"對應差異，常接 from 或 in"},{"en":"change","zh":"改變","note":"對應數值變動或做法改變"}],"idioms":[],"family":[{"word":"variation","pos":"n.","meaning":"差異；變化"},{"word":"variety","pos":"n.","meaning":"多樣性；種類"},{"word":"various","pos":"adj.","meaning":"各種的"},{"word":"variable","pos":"adj./n.","meaning":"可變的；變數"}],"examples":[{"text":"The amount of water plants need varies with the season and the temperature of their surroundings.","translationZh":"植物所需的水量，會隨季節和周遭溫度而變。","source":"self-authored","grammar":"The amount of water 是單數主詞，搭配 varies；plants need 為修飾 water 的關係子句，省略關係代名詞；vary with 引出變動條件。","writingTip":"寫自然現象時，可用季節與溫度說明需水量為何變動。","topic":"science"},{"text":"Learning preferences vary from person to person, so one method may not work equally well for everyone.","translationZh":"學習偏好因人而異，因此同一方法不一定對每個人都同樣有效。","source":"self-authored","grammar":"vary from person to person 表因人而異；so 連接結果分句；may not work 保留方法效果的不確定性。","writingTip":"評估學習策略時，指出個別差異，避免宣稱一種方法適合所有人。","topic":"education"}],"usageNote":"vary 是動詞；various 是各種的，variable 是可變的，variety 是多樣性或種類。"},"voice":{"senses":[{"pos":"n.","meaning":"聲音；表達意見的權利","usage":""},{"pos":"v.","meaning":"表達","usage":""}],"collocations":[{"en":"voice a concern","zh":"表達疑慮","note":""},{"en":"give students a voice","zh":"讓學生有發言機會","note":""},{"en":"raise one's voice","zh":"提高音量","note":""},{"en":"lose one's voice","zh":"失聲","note":""}],"synonyms":[{"en":"express","zh":"表達","note":"對應 voice an opinion"},{"en":"say","zh":"說","note":"say 通常接內容子句，不一定強調公開意見"}],"idioms":[],"family":[{"word":"voiced","pos":"adj.","meaning":"已表達的；有聲的"},{"word":"voiceless","pos":"adj.","meaning":"無發言權的；無聲的"},{"word":"voiceover","pos":"n.","meaning":"旁白"}],"usageNote":"voice 作動詞常搭配 concerns/opinions；give someone a voice 常指參與或發言權。","examples":[{"text":"Giving students a voice in school decisions can make them more willing to follow rules they understand and have helped shape.","translationZh":"讓學生在校務決策中有發言機會，能使他們更願意遵守了解且参與制定的規則。","source":"self-authored","grammar":"giving + 人 + a voice 作主詞；make + 人 + 形容詞。","writingTip":"把参與決策連結到理解與遵守規則。","topic":"學生參與"},{"text":"Several residents voiced concerns about noise, so the organizers changed the concert's ending time and shared the updated plan with neighbors.","translationZh":"幾位居民表達噪音疑慮，因此主辦方更改音樂會結束時間，並向鄰居分享更新計畫。","source":"self-authored","grammar":"voiced concerns about + 問題；so 引出主辦方調整。","writingTip":"說明聽取疑慮後採取哪些具體改善。","topic":"活動與居民"}]},"volunteer":{"senses":[{"pos":"n.","meaning":"志工；自願者","usage":"指主動提供服務的人。"},{"pos":"vi.","meaning":"自願做","usage":"常接 to V 或 for 加工作。"},{"pos":"vt.","meaning":"主動提供","usage":"可接資訊或服務。"}],"collocations":[{"en":"volunteer to help","zh":"自願幫忙","note":""},{"en":"volunteer for a task","zh":"自願承擔任務","note":""},{"en":"work as a volunteer","zh":"擔任志工","note":""},{"en":"volunteer information","zh":"主動提供資訊","note":""}],"synonyms":[{"en":"offer to help","zh":"主動表示願意幫忙","note":"對應動詞自願義，句型不同。"},{"en":"helper","zh":"幫手","note":"未必自願或不領薪資，不完全等同 volunteer。"}],"idioms":[],"family":[{"word":"voluntary","pos":"adj.","meaning":"自願的"},{"word":"voluntarily","pos":"adv.","meaning":"自願地"},{"word":"volunteering","pos":"n.","meaning":"志工服務"}],"examples":[{"text":"I volunteered to read stories to children at the library and discovered how much preparation a short session required.","translationZh":"我自願到圖書館讀故事給孩子聽，也發現短短一場活動需要很多準備。","grammar":"volunteer to V，how much 引導名詞子句。","writingTip":"可寫志工經驗帶來的新理解。","topic":"服務與閱讀","source":"self-authored"},{"text":"Experienced volunteers trained newcomers to listen respectfully instead of assuming they already knew what the community needed.","translationZh":"有經驗的志工訓練新進人員尊重地傾聽，而不是認定自己早已知道社區需要什麼。","grammar":"train someone to V，instead of assuming that 省略 that。","writingTip":"適合討論服務時的態度與準備。","topic":"服務與同理","source":"self-authored"}],"usageNote":"volunteer 是人或自願的動作；voluntary 是形容詞，不寫 a voluntary 表志工。"},"waste":{"senses":[{"pos":"n.","meaning":"廢棄物；浪費","usage":""},{"pos":"v.","meaning":"浪費","usage":""},{"pos":"adj.","meaning":"廢棄的","usage":""}],"collocations":[{"en":"reduce food waste","zh":"減少食物浪費","note":""},{"en":"a waste of time","zh":"浪費時間","note":""},{"en":"waste money on something","zh":"把錢浪費在某事上","note":""},{"en":"waste time doing something","zh":"浪費時間做某事","note":""}],"synonyms":[{"en":"rubbish","zh":"垃圾","note":"英式用語，不一定「浪費」"},{"en":"squander","zh":"揮霍","note":"較強烈，常指金錢或機會"}],"idioms":[],"family":[{"word":"wasteful","pos":"adj.","meaning":"浪費的"},{"word":"wastefully","pos":"adv.","meaning":"浪費地"},{"word":"wastage","pos":"n.","meaning":"浪費量"}],"usageNote":"waste time V-ing，不用 waste time to V；waste 常不可數，但 a waste of + 名詞是固定結構。","examples":[{"text":"Instead of wasting time searching for the perfect study plan, I started with a simple routine and improved it through experience.","translationZh":"與其浪費時間找完美讀書計畫，我先從簡單作息開始，再透過經驗改善。","source":"self-authored","grammar":"instead of wasting 表取代的做法；through experience 表改善依據。","writingTip":"以先實践再改善回應追求完美而遲遲不行動。","topic":"讀書行動"},{"text":"The lunch survey helped our school reduce food waste by matching portion sizes more closely to what students actually ate.","translationZh":"午餐調查幫助學校使份量更符合學生實際食量，從而減少食物浪費。","source":"self-authored","grammar":"by matching 表減少浪費的方法；what 引導實際食量。","writingTip":"以份量符合需求來提出具體減廢方案。","topic":"午餐浪費"}]},"willing":{"senses":[{"pos":"adj.","meaning":"願意的；樂於幫忙的","usage":"通常用 be willing to V。"}],"collocations":[{"en":"be willing to help","zh":"願意幫忙","note":""},{"en":"a willing volunteer","zh":"樂意服務的志工","note":""},{"en":"willing and able","zh":"願意且有能力","note":""},{"en":"willing to listen","zh":"願意傾聽","note":""}],"synonyms":[{"en":"ready","zh":"願意；準備好的","note":"可能表示已準備妥當，不只意願。"},{"en":"prepared to","zh":"願意；準備好……","note":"依語境可表接受必要行動或後果。"}],"idioms":[],"family":[{"word":"willingness","pos":"n.","meaning":"意願"},{"word":"willingly","pos":"adv.","meaning":"自願地"},{"word":"unwilling","pos":"adj.","meaning":"不願意的"},{"word":"unwillingness","pos":"n.","meaning":"不願意"}],"examples":[{"text":"Being willing to listen to criticism helped me revise my plan without treating every suggestion as a personal attack.","translationZh":"願意聆聽批評，讓我能修改計畫，不把每項建議都當成人身攻擊。","grammar":"be willing to V，treat A as B 表看待方式。","writingTip":"可寫成熟面對不同意見。","topic":"學習與溝通","source":"self-authored"},{"text":"Residents were willing to pay slightly more for local produce if they understood how it supported nearby farmers.","translationZh":"若了解在地農產品如何支持附近農民，居民就願意多付一點錢。","grammar":"willing to V，if 引導條件子句。","writingTip":"適合寫消費選擇與資訊透明。","topic":"飲食與在地經濟","source":"self-authored"}],"usageNote":"willing 表意願，不代表已具備能力；be willing to do 不用 willing of doing。"},"wisdom":{"senses":[{"pos":"n.","meaning":"智慧；明智判斷","usage":"通常不可數，也可指長久流傳的觀念。"}],"collocations":[{"en":"gain wisdom from experience","zh":"從經驗獲得智慧","note":""},{"en":"practical wisdom","zh":"實用智慧","note":""},{"en":"conventional wisdom","zh":"普遍接受的看法","note":""},{"en":"question the wisdom of a decision","zh":"質疑某決定是否明智","note":""}],"synonyms":[{"en":"good judgment","zh":"良好判斷力","note":"與明智作決定相關，未必含人生經驗。"},{"en":"insight","zh":"洞察力","note":"強調深入理解某事，不等同整體智慧。"}],"idioms":[],"family":[{"word":"wise","pos":"adj.","meaning":"明智的"},{"word":"wisely","pos":"adv.","meaning":"明智地"},{"word":"unwise","pos":"adj.","meaning":"不明智的"}],"examples":[{"text":"My grandmother's practical wisdom helped me see that repairing a friendship mattered more than winning an argument.","translationZh":"祖母的實用智慧，讓我明白修復友誼比贏得爭論更重要。","grammar":"see that 接理解內容，more than 比較重要性。","writingTip":"可寫長輩經驗與人際成長。","topic":"家庭與人際","source":"self-authored"},{"text":"Conventional wisdom about career success may need reconsideration as new technologies change the skills that employers value.","translationZh":"隨著新科技改變雇主重視的技能，對職涯成功的普遍看法可能需要重新思考。","grammar":"as 表隨著，that 引導 skills 的關係子句。","writingTip":"適合分析社會變化挑戰既有觀念。","topic":"科技與職涯","source":"self-authored"}],"usageNote":"knowledge 是知識，wisdom 是善用知識與經驗作判斷的智慧；conventional wisdom 未必永遠正確。"},"witness":{"senses":[{"pos":"n.","meaning":"目擊者；見證人","usage":""},{"pos":"v.","meaning":"目睹；見證","usage":""}],"collocations":[{"en":"witness an accident","zh":"目擊事故","note":""},{"en":"an eyewitness account","zh":"目擊者的敘述","note":""},{"en":"bear witness to a change","zh":"見證變化","note":""},{"en":"a witness to history","zh":"歷史的見證人","note":""}],"synonyms":[{"en":"observe","zh":"觀察","note":"witness 常強調親眼見到重要事件"},{"en":"see","zh":"看見","note":"較一般，不含見證意義"}],"idioms":[],"family":[{"word":"eyewitness","pos":"n.","meaning":"目擊者"},{"word":"witness statement","pos":"n.","meaning":"證人陳述"}],"usageNote":"witness 作動詞直接接受詞；a witness to + 事件。目擊者敘述仍可能需要其他證據核對。","examples":[{"text":"After witnessing the accident, I called emergency services and stayed nearby to describe what I had seen when the police arrived.","translationZh":"目擊事故後，我打給急救單位並留在附近，在警方抵達時說明所見。","source":"self-authored","grammar":"after witnessing 表目擊後；what I had seen 為過去完成式子句。","writingTip":"描寫目击者如何通報並提供所見。","topic":"事故通報"},{"text":"The old photographs bear witness to the neighborhood's transformation from a quiet farming village into a busy center of trade.","translationZh":"老照片見證社區從安靜農村轉變為繁忙商業中心的歷程。","source":"self-authored","grammar":"bear witness to + 變化；from A into B 表轉變。","writingTip":"用老照片作為社區變遷的具體證據。","topic":"社區歷史"}]},"worthwhile":{"senses":[{"pos":"adj.","meaning":"值得投入時間或心力的","usage":"可用 worthwhile to V 或 worthwhile V-ing。"}],"collocations":[{"en":"a worthwhile experience","zh":"值得投入的經歷","note":""},{"en":"a worthwhile cause","zh":"值得支持的理念","note":""},{"en":"make an effort worthwhile","zh":"讓努力值得","note":""},{"en":"find it worthwhile to help","zh":"覺得幫忙值得","note":""}],"synonyms":[{"en":"valuable","zh":"有價值的","note":"範圍較廣，可指金錢價值，不必值得投入時間。"},{"en":"rewarding","zh":"有收穫的","note":"強調帶來滿足或成果，語氣較偏感受。"}],"idioms":[],"family":[{"word":"worth","pos":"prep./n.","meaning":"值得；價值"},{"word":"worthiness","pos":"n.","meaning":"值得的程度；價值"},{"word":"worthy","pos":"adj.","meaning":"值得的；值得尊敬的"}],"examples":[{"text":"Helping at the animal shelter was a worthwhile experience because it taught me what responsible pet ownership involves.","translationZh":"在動物收容所幫忙是值得的經歷，因為它教會我負責任飼養寵物包含哪些事。","grammar":"a worthwhile experience，what 引導名詞子句。","writingTip":"可寫服務經驗與寵物責任。","topic":"寵物與服務","source":"self-authored"},{"text":"Although the project required many revisions, seeing younger students enjoy the reading corner made our efforts worthwhile.","translationZh":"雖然專案需要多次修改，看見低年級學生喜歡閱讀角，讓我們的努力都值得了。","grammar":"seeing someone V 作主詞，make 受詞 adjective。","writingTip":"適合描寫付出後的具體回饋。","topic":"校園與服務","source":"self-authored"}],"usageNote":"worth doing、worthy of 名詞或動名詞、worthwhile to do 或 doing 的句型各不相同。"}},"supplemental":[{"word":"belonging","level":6,"partOfSpeech":"n./n. pl.","meaning":"歸屬感；個人物品","pronunciation":"","source":"本站學測延伸詞（非原官方詞表）"},{"word":"companionship","level":6,"partOfSpeech":"n.","meaning":"陪伴；有人相伴的情誼","pronunciation":"","source":"本站學測延伸詞（非原官方詞表）"},{"word":"exacerbate","level":6,"partOfSpeech":"v.","meaning":"使問題、病痛或衝突惡化","pronunciation":"","source":"本站學測延伸詞（非原官方詞表）"},{"word":"integral","level":6,"partOfSpeech":"adj.","meaning":"不可或缺的；構成整體的一部分的","pronunciation":"","source":"本站學測延伸詞（非原官方詞表）"},{"word":"loneliness","level":6,"partOfSpeech":"n.","meaning":"孤獨；寂寞","pronunciation":"","source":"本站學測延伸詞（非原官方詞表）"},{"word":"renewable","level":6,"partOfSpeech":"adj.","meaning":"可再生的；可續期的","pronunciation":"","source":"本站學測延伸詞（非原官方詞表）"},{"word":"responsive","level":6,"partOfSpeech":"adj.","meaning":"對刺激或需求有反應的；願意回應意見的","pronunciation":"","source":"本站學測延伸詞（非原官方詞表）"}],"stats":{"headwords":315,"collocations":1282,"examples":630,"senses":638,"synonyms":630,"idioms":32,"family":786}};
